enum AcceptanceSuite {
    All,
    Hotkey,
    Query,
    GateC,
    GateD,
    GateS,
}

impl AcceptanceSuite {
    fn as_str(self) -> &'static str {
        match self {
            Self::All => "all",
            Self::Hotkey => "hotkey",
            Self::Query => "query",
            Self::GateC => "gate_c",
            Self::GateD => "gate_d",
            Self::GateS => "gate_s",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, serde::Deserialize)]
#[serde(rename_all = "snake_case")]
enum AcceptanceHotkey {
    F11,
    ShiftAltWinEnd,
}

impl AcceptanceHotkey {
    fn as_str(self) -> &'static str {
        match self {
            Self::F11 => ACCEPTANCE_HOTKEY,
            Self::ShiftAltWinEnd => "Shift+Alt+Win+End",
        }
    }
}

fn expected_setup_hotkey_edges(hotkey: AcceptanceHotkey) -> Vec<(u32, bool)> {
    match hotkey {
        AcceptanceHotkey::F11 => vec![(0x7A, true), (0x7A, false)],
        AcceptanceHotkey::ShiftAltWinEnd => vec![
            (0xA0, true),
            (0xA4, true),
            (0x5B, true),
            (0x23, true),
            (0x23, false),
            (0x5B, false),
            (0xA4, false),
            (0xA0, false),
        ],
    }
}

