impl<'de> serde::Deserialize<'de> for HotkeyCaseEvidence {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        let wire = HotkeyCaseEvidenceWire::deserialize(deserializer)?;
        let mut evidence = Self {
            schema_version: wire.schema_version,
            case_id: wire.case_id,
            expected_state: wire.expected_state,
            runner_clock: wire.runner_clock,
            runner_edges: wire.runner_edges,
            candidate_events: wire.candidate_events,
            gestures: wire.gestures,
            standalone_decisions: wire.standalone_decisions,
            follow_on_restorations: wire.follow_on_restorations,
            root_identities: wire.root_identities,
            physical_displays: wire.physical_displays,
            screen_draw_priority: wire.screen_draw_priority,
            candidate_event_count: wire.candidate_event_count,
            candidate_trace_overflow: wire.candidate_trace_overflow,
            capture_segment_overflow: wire.capture_segment_overflow,
            runner_edge_overflow: wire.runner_edge_overflow,
            gesture_overflow: wire.gesture_overflow,
        };
        hydrate_hotkey_command_spans(&mut evidence);
        Ok(evidence)
    }
}

fn hydrate_hotkey_command_spans(packet: &mut HotkeyCaseEvidence) {
    for gesture in &mut packet.gestures {
        if let HotkeyDecisionProof::Applied { root_commands, .. } = &mut gesture.decision {
            for span in root_commands {
                hydrate_hotkey_command_span(&packet.candidate_events, gesture.stream, span);
            }
        }
    }
    for decision in &mut packet.standalone_decisions {
        for span in &mut decision.root_commands {
            hydrate_hotkey_command_span(&packet.candidate_events, decision.stream, span);
        }
    }
    for restore in &mut packet.follow_on_restorations {
        for span in &mut restore.root_commands {
            hydrate_hotkey_command_span(&packet.candidate_events, restore.stream, span);
        }
    }
    if let Some(priority) = &mut packet.screen_draw_priority {
        for restore in &mut priority.restorations {
            for span in &mut restore.root_commands {
                hydrate_hotkey_command_span(&priority.candidate_events, restore.stream, span);
            }
        }
    }
}

fn hydrate_hotkey_command_span(
    events: &[HotkeyCandidateEventEvidence],
    stream: HotkeyCandidateStream,
    span: &mut HotkeyRootCommandSpan,
) {
    let command = events.iter().find(|event| {
        event.stream == stream
            && event.event_ordinal == span.command_event_ordinal
            && event.kind == HotkeyTraceEventKind::RootCommand
    });
    if let Some(command) = command {
        span.visibility_revision = command.visibility_revision.unwrap_or_default();
        span.invocation_id = command.invocation_id;
        span.request_id = command.request_id.unwrap_or_default();
        span.command_elapsed_ms = command.elapsed_ms;
        span.command = command.command.unwrap_or(HotkeyRootCommand::Other);
    }
    let observed = span.observed_snapshot_event_ordinal.and_then(|ordinal| {
        events.iter().find(|event| {
            event.stream == stream
                && event.event_ordinal == ordinal
                && event.kind == HotkeyTraceEventKind::NativeWindowSnapshot
        })
    });
    span.observed_presentation = observed.and_then(|event| {
        Some(HotkeyObservedPresentation {
            elapsed_ms: event.elapsed_ms,
            command_to_observed_ms: span.command_to_observed_ms?,
            visible: event.visible?,
            minimized: event.minimized?,
            bounds: event.bounds?,
        })
    });
}

#[derive(Clone, Debug, Serialize, serde::Deserialize)]
struct ReportOverflowReceipt {
    reason: String,
    omitted_case_evidence: usize,
    omitted_artifact_references: usize,
    affected_case_ids: Vec<String>,
}

const GATE_C_METADATA_OVERFLOW_REASON: &str =
    "serialized report exceeded the bounded output size; excess artifact references were omitted";
const PERSISTENCE_OVERFLOW_CASE_OBSERVED: &str =
    "report evidence overflow prevented complete bounded persistence";

fn hotkey_expected_state(case_id: &str) -> Option<HotkeyExpectedState> {
    Some(match case_id {
        "H01" => HotkeyExpectedState::HiddenRootWakeAndFocus,
        "H02" => HotkeyExpectedState::VisibleRootHideWithoutRestore,
        "H04" => HotkeyExpectedState::HiddenAndVisibleBurstParity,
        "H06" => HotkeyExpectedState::TapDismissesWithoutSelection,
        "H07" => HotkeyExpectedState::TapDismissesThenNextGestureWorks,
        "H08" => HotkeyExpectedState::PreparingRuntimeCancelledBeforeReady,
        "H09" => HotkeyExpectedState::HoldOpensAndReleaseClosesWithoutGridToggle,
        "H10" => HotkeyExpectedState::HoldDismissesHoveredActionWithoutDispatch,
        "H11" => HotkeyExpectedState::DesignerDraftAndForegroundPreserved,
        "H12" => HotkeyExpectedState::DesignerPreviewAndDraftPreserved,
        "H15" => HotkeyExpectedState::RealScreenDrawPriorityAndNextGesture,
        "H16" => HotkeyExpectedState::DirectAndLegacyTriggersPreserved,
        "H17" => HotkeyExpectedState::AlternateHotkeyProfilesIsolated,
        "H18" => HotkeyExpectedState::ParkedRootWakesAndRadialDismisses,
        _ => return None,
    })
}

fn validate_hotkey_evidence_packet(packet: &HotkeyCaseEvidence) -> Result<(), String> {
    validate_hotkey_evidence_packet_with_context(packet, AcceptanceHotkey::F11, 350)
}

// ROOT samples are taken two frames after a request. They identify requested
// work, not an application acknowledgment. Keep the causal rule shared by the
// live wait, proof builder, and persisted oracle.
fn hotkey_paired_toggle_intent<'a>(
    events: &'a [HotkeyCandidateEventEvidence],
    intent: &HotkeyCandidateEventEvidence,
) -> Option<(
    &'a HotkeyCandidateEventEvidence,
    &'a HotkeyCandidateEventEvidence,
    &'a HotkeyCandidateEventEvidence,
)> {
    if intent.kind != HotkeyTraceEventKind::VisibilityIntent
        || intent.visibility_source != Some(HotkeyVisibilitySource::ToggleBatch)
        || intent.input_group_id == 0
        || intent.invocation_id.is_none_or(|id| id == 0)
        || intent
            .visibility_revision
            .is_none_or(|revision| revision == 0)
        || intent.visible.is_none()
    {
        return None;
    }
    let unique = |kind| {
        let mut matching = events.iter().filter(|event| {
            event.stream == intent.stream
                && event.input_group_id == intent.input_group_id
                && event.input_purpose == intent.input_purpose
                && event.invocation_id == intent.invocation_id
                && event.kind == kind
        });
        let event = matching.next()?;
        matching.next().is_none().then_some(event)
    };
    let press = unique(HotkeyTraceEventKind::PrimaryPress)?;
    let release = unique(HotkeyTraceEventKind::PrimaryRelease)?;
    let tap = unique(HotkeyTraceEventKind::ShortTap)?;
    (press.modifiers_match == Some(true)
        && release.modifiers_match.is_some()
        && tap.terminal == Some(true)
        && press.event_ordinal < release.event_ordinal
        && release.event_ordinal < tap.event_ordinal
        && tap.event_ordinal < intent.event_ordinal
        && press.elapsed_ms <= release.elapsed_ms
        && release.elapsed_ms <= tap.elapsed_ms
        && tap.elapsed_ms <= intent.elapsed_ms)
        .then_some((press, release, tap))
}

fn hotkey_command_belongs_to_intent(
    command: &HotkeyCandidateEventEvidence,
    intent: &HotkeyCandidateEventEvidence,
) -> bool {
    command.kind == HotkeyTraceEventKind::RootCommand
        && command.stream == intent.stream
        && command.input_group_id == intent.input_group_id
        && command.input_purpose == intent.input_purpose
        && command.visibility_revision == intent.visibility_revision
        && command.invocation_id == intent.invocation_id
        && command.event_ordinal > intent.event_ordinal
        && command.elapsed_ms >= intent.elapsed_ms
        && command.request_id.is_some_and(|request| request != 0)
        && command.command.is_some()
}

#[derive(Clone, Copy)]
struct HotkeyRootProofContext<'a> {
    candidate_events: &'a [HotkeyCandidateEventEvidence],
    root_identities: &'a [HotkeyRootIdentityEvidence],
    physical_displays: &'a [[i32; 4]],
    follow_on_restorations: &'a [HotkeyFollowOnRestoreEvidence],
}

impl<'a> From<&'a HotkeyCaseEvidence> for HotkeyRootProofContext<'a> {
    fn from(packet: &'a HotkeyCaseEvidence) -> Self {
        Self {
            candidate_events: &packet.candidate_events,
            root_identities: &packet.root_identities,
            physical_displays: &packet.physical_displays,
            follow_on_restorations: &packet.follow_on_restorations,
        }
    }
}

fn hotkey_command_snapshots_are_owned(
    events: &[HotkeyCandidateEventEvidence],
    command: &HotkeyCandidateEventEvidence,
) -> bool {
    events
        .iter()
        .filter(|snapshot| {
            snapshot.stream == command.stream
                && snapshot.kind == HotkeyTraceEventKind::NativeWindowSnapshot
                && snapshot.request_id == command.request_id
        })
        .all(|snapshot| {
            snapshot.input_group_id == command.input_group_id
                && snapshot.input_purpose == command.input_purpose
                && snapshot.invocation_id == command.invocation_id
                && snapshot.visibility_revision == command.visibility_revision
                && snapshot.event_ordinal > command.event_ordinal
                && snapshot.elapsed_ms >= command.elapsed_ms
        })
}

fn hotkey_owned_follow_on_restore_intent<'a>(
    context: HotkeyRootProofContext<'a>,
    restore: &HotkeyFollowOnRestoreEvidence,
) -> Option<&'a HotkeyCandidateEventEvidence> {
    let events = context.candidate_events;
    if restore.input_group_id == 0
        || restore.visibility_revision == 0
        || !restore.visible
        || context
            .follow_on_restorations
            .iter()
            .filter(|owner| {
                owner.stream == restore.stream
                    && owner.visibility_revision == restore.visibility_revision
            })
            .count()
            != 1
    {
        return None;
    }
    let mut intents = events.iter().filter(|event| {
        event.stream == restore.stream
            && event.kind == HotkeyTraceEventKind::VisibilityIntent
            && event.visibility_revision == Some(restore.visibility_revision)
            && event.visibility_source == Some(HotkeyVisibilitySource::ScreenDrawRestore)
    });
    let intent = intents.next()?;
    if intents.next().is_some()
        || intent.input_group_id != restore.input_group_id
        || intent.invocation_id != restore.invocation_id
        || intent.elapsed_ms != restore.intent_elapsed_ms
        || intent.visible != Some(restore.visible)
    {
        return None;
    }
    let mut focuses = events.iter().filter(|event| {
        event.stream == restore.stream
            && event.kind == HotkeyTraceEventKind::ScreenDrawRestoreFocusIntent
            && event.visibility_revision == Some(restore.visibility_revision)
    });
    let focus = focuses.next()?;
    if focuses.next().is_some()
        || focus.input_group_id != intent.input_group_id
        || focus.input_purpose != intent.input_purpose
        || focus.invocation_id != intent.invocation_id
        || focus.focus_intent != Some(restore.focus_intent)
        || focus.event_ordinal <= intent.event_ordinal
        || focus.elapsed_ms < intent.elapsed_ms
    {
        return None;
    }
    match (restore.invocation_id, restore.parent_visibility_revision) {
        (None, None) => {}
        (Some(invocation), Some(parent_revision)) => {
            let mut parents = events.iter().filter(|parent| {
                parent.stream == intent.stream
                    && parent.input_group_id == intent.input_group_id
                    && parent.input_purpose == intent.input_purpose
                    && parent.kind == HotkeyTraceEventKind::VisibilityIntent
                    && parent.visibility_source == Some(HotkeyVisibilitySource::ToggleBatch)
                    && parent.invocation_id == Some(invocation)
                    && parent.visibility_revision == Some(parent_revision)
                    && parent_revision < restore.visibility_revision
                    && parent.event_ordinal < intent.event_ordinal
                    && parent.elapsed_ms <= intent.elapsed_ms
            });
            parents.next()?;
            if parents.next().is_some() {
                return None;
            }
        }
        _ => return None,
    }
    let commands = events
        .iter()
        .filter(|command| {
            command.stream == intent.stream
                && command.kind == HotkeyTraceEventKind::RootCommand
                && command.visibility_revision == intent.visibility_revision
        })
        .collect::<Vec<_>>();
    if commands.is_empty()
        || commands.len() != restore.root_commands.len()
        || commands.iter().any(|command| {
            !hotkey_command_belongs_to_intent(command, intent)
                || command.event_ordinal <= focus.event_ordinal
                || command.elapsed_ms < focus.elapsed_ms
                || !hotkey_command_snapshots_are_owned(events, command)
                || restore
                    .root_commands
                    .iter()
                    .filter(|span| root_command_event_matches_span(command, restore.stream, span))
                    .count()
                    != 1
        })
        || restore.root_commands.iter().any(|span| {
            span.visibility_revision != restore.visibility_revision
                || span.invocation_id != restore.invocation_id
                || span.release_to_root_command_ms.is_some()
                || !root_command_span_matches(context, restore.stream, span)
        })
    {
        return None;
    }
    let root = context
        .root_identities
        .iter()
        .find(|root| root.stream == restore.stream)?;
    let snapshot = hotkey_current_intent_physical_snapshot(context, intent, root)?;
    if !restore.root_commands.iter().any(|span| {
        span.observed_snapshot_event_ordinal == Some(snapshot)
            && span.observed_presentation.as_ref().is_some_and(|observed| {
                presentation_matches(context, restore.stream, span, observed, restore.visible)
            })
    }) {
        return None;
    }
    let activations = events
        .iter()
        .filter(|event| {
            event.stream == restore.stream
                && event.kind == HotkeyTraceEventKind::NativeActivation
                && event.visibility_revision == Some(restore.visibility_revision)
                && event.invocation_id == restore.invocation_id
        })
        .collect::<Vec<_>>();
    match restore.focus_intent {
        HotkeyRootFocusIntent::PreserveForeground => {
            if restore.native_activation.is_some()
                || !activations.is_empty()
                || commands
                    .iter()
                    .any(|command| command.command == Some(HotkeyRootCommand::Focus))
            {
                return None;
            }
        }
        HotkeyRootFocusIntent::ActivateRoot => {
            let span = restore.native_activation.as_ref()?;
            if !native_activation_span_matches(context, restore.stream, restore, span)
                || activations.len() != 2
                || activations.iter().any(|event| {
                    event.input_group_id != intent.input_group_id
                        || event.input_purpose != intent.input_purpose
                        || event.event_ordinal <= focus.event_ordinal
                        || event.elapsed_ms < focus.elapsed_ms
                })
            {
                return None;
            }
            let requested = activations.iter().find(|event| {
                event.activation_edge == Some(HotkeyActivationEdge::RestoreRequested)
            })?;
            let completed = activations.iter().find(|event| {
                event.activation_edge == Some(HotkeyActivationEdge::RestoreCompleted)
            })?;
            if requested.event_ordinal >= completed.event_ordinal
                || requested.elapsed_ms > completed.elapsed_ms
            {
                return None;
            }
        }
    }
    Some(intent)
}

fn hotkey_restore_follows_intent<'a>(
    context: HotkeyRootProofContext<'a>,
    restore: &HotkeyFollowOnRestoreEvidence,
    intent: &HotkeyCandidateEventEvidence,
) -> Option<&'a HotkeyCandidateEventEvidence> {
    if restore.stream != intent.stream
        || restore.input_group_id != intent.input_group_id
        || restore.invocation_id != intent.invocation_id
        || restore.parent_visibility_revision != intent.visibility_revision
    {
        return None;
    }
    let restore_intent = hotkey_owned_follow_on_restore_intent(context, restore)?;
    let root = context
        .root_identities
        .iter()
        .find(|root| root.stream == intent.stream)?;
    hotkey_paired_toggle_intent(context.candidate_events, intent)?;
    // Screen Draw retains its parent invocation, but owns fresh work only
    // after the original request has a physical presentation.
    let parent_snapshot = hotkey_current_intent_physical_snapshot(context, intent, root)?;
    let observed = context
        .candidate_events
        .iter()
        .find(|event| event.stream == intent.stream && event.event_ordinal == parent_snapshot)?;
    (restore_intent.input_purpose == intent.input_purpose
        && observed.event_ordinal < restore_intent.event_ordinal
        && observed.elapsed_ms <= restore_intent.elapsed_ms)
        .then_some(restore_intent)
}

fn hotkey_intent_work_is_owned(
    context: HotkeyRootProofContext<'_>,
    intent: &HotkeyCandidateEventEvidence,
) -> bool {
    let events = context.candidate_events;
    if context.follow_on_restorations.iter().any(|restore| {
        restore.stream == intent.stream
            && ((restore.input_group_id == intent.input_group_id
                && hotkey_owned_follow_on_restore_intent(context, restore).is_none())
                || ((restore.invocation_id == intent.invocation_id
                    || restore.parent_visibility_revision == intent.visibility_revision)
                    && hotkey_restore_follows_intent(context, restore, intent).is_none()))
    }) {
        return false;
    }
    events
        .iter()
        .filter(|event| {
            event.stream == intent.stream
                && event.kind == HotkeyTraceEventKind::RootCommand
                && (event.invocation_id == intent.invocation_id
                    || event.visibility_revision == intent.visibility_revision)
        })
        .all(|command| {
            let separately_owned_restore = || {
                let mut owners = context.follow_on_restorations.iter().filter(|restore| {
                    restore
                        .root_commands
                        .iter()
                        .any(|span| root_command_event_matches_span(command, restore.stream, span))
                });
                let restore = owners.next()?;
                if owners.next().is_some() {
                    return None;
                }
                let restore_intent = hotkey_restore_follows_intent(context, restore, intent)?;
                hotkey_command_belongs_to_intent(command, restore_intent).then_some(())
            };
            (hotkey_command_belongs_to_intent(command, intent)
                || separately_owned_restore().is_some())
                && hotkey_command_snapshots_are_owned(events, command)
        })
}

fn hotkey_intent_physical_snapshot(
    context: HotkeyRootProofContext<'_>,
    intent: &HotkeyCandidateEventEvidence,
    root: &HotkeyRootIdentityEvidence,
) -> Option<u32> {
    hotkey_paired_toggle_intent(context.candidate_events, intent)?;
    if !hotkey_intent_work_is_owned(context, intent) {
        return None;
    }
    hotkey_current_intent_physical_snapshot(context, intent, root)
}

fn hotkey_current_intent_physical_snapshot(
    context: HotkeyRootProofContext<'_>,
    intent: &HotkeyCandidateEventEvidence,
    root: &HotkeyRootIdentityEvidence,
) -> Option<u32> {
    let events = context.candidate_events;
    let displays = context.physical_displays;
    if root.stream != intent.stream
        || root.hwnd == 0
        || root.process_id == 0
        || displays.is_empty()
        || displays
            .iter()
            .any(|display| display[0] >= display[2] || display[1] >= display[3])
    {
        return None;
    }
    // One captured ROOT lifetime owns every native observation in this stream.
    if events.iter().any(|event| {
        event.stream == root.stream
            && event.kind == HotkeyTraceEventKind::NativeWindowSnapshot
            && (event.hwnd != Some(root.hwnd)
                || event.process_id != Some(root.process_id)
                || event.visible.is_none()
                || event.minimized.is_none()
                || event
                    .bounds
                    .is_none_or(|bounds| bounds[0] >= bounds[2] || bounds[1] >= bounds[3]))
    }) {
        return None;
    }
    let commands = events
        .iter()
        .filter(|command| hotkey_command_belongs_to_intent(command, intent))
        .collect::<Vec<_>>();
    if commands
        .iter()
        .any(|command| !hotkey_command_snapshots_are_owned(events, command))
    {
        return None;
    }
    let last_command = commands
        .iter()
        .max_by_key(|command| command.event_ordinal)?;
    let snapshot = events
        .iter()
        .filter(|snapshot| {
            snapshot.kind == HotkeyTraceEventKind::NativeWindowSnapshot
                && snapshot.stream == intent.stream
                && snapshot.input_group_id == intent.input_group_id
                && snapshot.input_purpose == intent.input_purpose
                && snapshot.visibility_revision == intent.visibility_revision
                && snapshot.invocation_id == intent.invocation_id
                && snapshot.event_ordinal > last_command.event_ordinal
                && snapshot.elapsed_ms >= last_command.elapsed_ms
                && commands.iter().any(|command| {
                    command.request_id == snapshot.request_id
                        && command.event_ordinal < snapshot.event_ordinal
                        && command.elapsed_ms <= snapshot.elapsed_ms
                })
                && !events.iter().any(|later| {
                    later.stream == intent.stream
                        && later.event_ordinal > intent.event_ordinal
                        && later.event_ordinal < snapshot.event_ordinal
                        && ((later.kind == HotkeyTraceEventKind::VisibilityIntent
                            && later.visibility_revision.is_some_and(|revision| {
                                revision > intent.visibility_revision.unwrap_or(0)
                            }))
                            || (later.kind == HotkeyTraceEventKind::RootCommand
                                && later.visibility_revision != intent.visibility_revision))
                })
        })
        .max_by_key(|snapshot| snapshot.event_ordinal)?;
    let bounds = snapshot.bounds?;
    let physically_shown = snapshot.visible == Some(true)
        && snapshot.minimized == Some(false)
        && displays.iter().any(|display| {
            bounds[0] < display[2]
                && bounds[2] > display[0]
                && bounds[1] < display[3]
                && bounds[3] > display[1]
        });
    (Some(physically_shown) == intent.visible).then_some(snapshot.event_ordinal)
}

fn hotkey_terminal_successor<'a>(
    context: HotkeyRootProofContext<'a>,
    source: &HotkeyCandidateEventEvidence,
    root: &HotkeyRootIdentityEvidence,
) -> Option<&'a HotkeyCandidateEventEvidence> {
    let events = context.candidate_events;
    let (_, source_release, _) = hotkey_paired_toggle_intent(events, source)?;
    let source_revision = source.visibility_revision?;
    let source_invocation = source.invocation_id?;
    if !hotkey_intent_work_is_owned(context, source) {
        return None;
    }
    if let Some(first_newer) = events
        .iter()
        .filter(|event| {
            event.stream == source.stream
                && event.kind == HotkeyTraceEventKind::VisibilityIntent
                && event
                    .visibility_revision
                    .is_some_and(|revision| revision > source_revision)
                && event.event_ordinal > source.event_ordinal
        })
        .min_by_key(|event| event.event_ordinal)
    {
        if events
            .iter()
            .filter(|command| hotkey_command_belongs_to_intent(command, source))
            .any(|command| {
                command.event_ordinal >= first_newer.event_ordinal
                    || command.elapsed_ms > first_newer.elapsed_ms
            })
        {
            return None;
        }
    }
    let mut successors = events
        .iter()
        .filter(|successor| {
            successor.stream == source.stream
                && successor.input_group_id == source.input_group_id
                && successor.input_purpose == source.input_purpose
                && successor.kind == HotkeyTraceEventKind::VisibilityIntent
                && successor.visibility_source == Some(HotkeyVisibilitySource::ToggleBatch)
                && successor.event_ordinal > source.event_ordinal
                && successor.elapsed_ms >= source.elapsed_ms
                && successor
                    .visibility_revision
                    .is_some_and(|revision| revision > source_revision)
                && successor
                    .invocation_id
                    .is_some_and(|invocation| invocation > source_invocation)
        })
        .collect::<Vec<_>>();
    successors.sort_by_key(|successor| successor.event_ordinal);
    for successor in successors {
        let mut chain = events
            .iter()
            .filter(|event| {
                event.stream == source.stream
                    && event.kind == HotkeyTraceEventKind::VisibilityIntent
                    && event.event_ordinal > source.event_ordinal
                    && event.event_ordinal <= successor.event_ordinal
                    && event.visibility_source != Some(HotkeyVisibilitySource::Queued)
            })
            .collect::<Vec<_>>();
        chain.sort_by_key(|event| event.event_ordinal);
        let mut prior_revision = source_revision;
        let mut prior_invocation = source_invocation;
        let mut prior_release = source_release;
        let mut ordered = true;
        for intent in chain {
            let Some((press, release, _)) = hotkey_paired_toggle_intent(events, intent) else {
                ordered = false;
                break;
            };
            if intent.input_group_id != source.input_group_id
                || intent.input_purpose != source.input_purpose
                || intent
                    .visibility_revision
                    .is_none_or(|revision| revision <= prior_revision)
                || intent
                    .invocation_id
                    .is_none_or(|invocation| invocation <= prior_invocation)
                || press.event_ordinal <= prior_release.event_ordinal
                || press.elapsed_ms < prior_release.elapsed_ms
            {
                ordered = false;
                break;
            }
            prior_revision = intent.visibility_revision?;
            prior_invocation = intent.invocation_id?;
            prior_release = release;
        }
        // Issued source work must precede the newer decision; a stale side
        // effect issued after it cannot acquire a supersession proof.
        if ordered
            && events
                .iter()
                .filter(|command| hotkey_command_belongs_to_intent(command, source))
                .all(|command| {
                    command.event_ordinal < successor.event_ordinal
                        && command.elapsed_ms <= successor.elapsed_ms
                })
            && hotkey_intent_physical_snapshot(context, successor, root).is_some()
        {
            return Some(successor);
        }
    }
    None
}

fn validate_hotkey_evidence_packet_with_context(
    packet: &HotkeyCaseEvidence,
    configured_hotkey: AcceptanceHotkey,
    hold_threshold_ms: u64,
) -> Result<(), String> {
    let encoded_len = serde_json::to_vec(packet)
        .map_err(|error| format!("{} evidence serialization failed: {error}", packet.case_id))?
        .len();
    if encoded_len > MAX_HOTKEY_CASE_EVIDENCE_BYTES {
        return Err(format!(
            "{} evidence packet exceeds its byte bound: bytes={encoded_len}, candidate_events={}, runner_edges={}, gestures={}, standalone_decisions={}, command_spans={}, root_commands={}, snapshots={}",
            packet.case_id,
            packet.candidate_events.len(),
            packet.runner_edges.len(),
            packet.gestures.len(),
            packet.standalone_decisions.len(),
            all_root_command_spans(packet).len(),
            packet
                .candidate_events
                .iter()
                .filter(|event| event.kind == HotkeyTraceEventKind::RootCommand)
                .count(),
            packet
                .candidate_events
                .iter()
                .filter(|event| event.kind == HotkeyTraceEventKind::NativeWindowSnapshot)
                .count(),
        ));
    }
    if packet.schema_version != 4 {
        return Err(format!(
            "{} evidence schema version is unsupported",
            packet.case_id
        ));
    }
    if hotkey_expected_state(&packet.case_id) != Some(packet.expected_state) {
        return Err(format!(
            "{} evidence expected state does not match its case",
            packet.case_id
        ));
    }
    if packet.runner_clock != "runner_monotonic_relative_us" {
        return Err(format!("{} runner clock label is invalid", packet.case_id));
    }
    if packet.candidate_trace_overflow
        || packet.capture_segment_overflow
        || packet.runner_edge_overflow
        || packet.gesture_overflow
        || packet.candidate_event_count != packet.candidate_events.len()
        || packet.candidate_events.len() > MAX_HOTKEY_EVIDENCE_EVENTS
        || packet.runner_edges.len() > MAX_HOTKEY_EVIDENCE_EDGES
        || packet.gestures.len() > MAX_HOTKEY_EVIDENCE_GESTURES
        || packet.standalone_decisions.len() > MAX_HOTKEY_EVIDENCE_GESTURES
    {
        return Err(format!(
            "{} evidence packet is incomplete or over capacity",
            packet.case_id
        ));
    }
    validate_packet_root_identity(packet)?;

    let mut ordinals = std::collections::BTreeSet::new();
    let mut root_request_ids = std::collections::BTreeSet::new();
    let mut snapshot_request_ids = std::collections::BTreeSet::new();
    let mut last_by_stream = std::collections::BTreeMap::new();
    for event in &packet.candidate_events {
        if !ordinals.insert((event.stream as u8, event.event_ordinal)) {
            return Err(format!(
                "{} candidate trace event ordinal is duplicated",
                packet.case_id
            ));
        }
        if event.input_group_id == 0 || event.event_ordinal == 0 {
            return Err(format!(
                "{} candidate event is outside a measured input group",
                packet.case_id
            ));
        }
        if let Some((last_ordinal, last_elapsed)) = last_by_stream.get(&event.stream) {
            if event.event_ordinal <= *last_ordinal || event.elapsed_ms < *last_elapsed {
                return Err(format!(
                    "{} candidate trace order is invalid",
                    packet.case_id
                ));
            }
        }
        last_by_stream.insert(event.stream, (event.event_ordinal, event.elapsed_ms));
        match event.kind {
            HotkeyTraceEventKind::PrimaryPress => {
                if event.invocation_id.is_none()
                    || (event.modifiers_match != Some(true)
                        && !h16_legacy_modifier_mismatch_is_valid(packet, event))
                    || event.provenance != Some(HotkeyInputProvenance::ExternalInjected)
                {
                    return Err(format!(
                        "{} primary press is uncorrelated, mismatched, or not external injected input",
                        packet.case_id
                    ));
                }
            }
            HotkeyTraceEventKind::PrimaryRelease => {
                if event.invocation_id.is_none()
                    || event.modifiers_match.is_none()
                    || event.provenance != Some(HotkeyInputProvenance::ExternalInjected)
                {
                    return Err(format!("{} primary release is malformed", packet.case_id));
                }
            }
            _ => {}
        }
        match event.kind {
            HotkeyTraceEventKind::RootCommand => {
                let Some(request_id) = event.request_id else {
                    return Err(format!(
                        "{} ROOT command has no boundary request ID",
                        packet.case_id
                    ));
                };
                if !root_request_ids.insert((event.stream, request_id)) {
                    return Err(format!(
                        "{} ROOT boundary request ID is duplicated",
                        packet.case_id
                    ));
                }
            }
            HotkeyTraceEventKind::NativeWindowSnapshot => {
                let Some(request_id) = event.request_id else {
                    return Err(format!(
                        "{} ROOT snapshot has no boundary request ID",
                        packet.case_id
                    ));
                };
                if !snapshot_request_ids.insert((event.stream, request_id)) {
                    return Err(format!(
                        "{} ROOT snapshot request ID is duplicated",
                        packet.case_id
                    ));
                }
                if !event_root_identity_matches(packet.into(), event) {
                    return Err(format!(
                        "{} native presentation snapshot is not from the captured ROOT HWND/PID",
                        packet.case_id
                    ));
                }
            }
            _ => {}
        }
    }
    validate_hotkey_candidate_event_coverage(packet)?;

    for gesture in &packet.gestures {
        if gesture.input_group_id == 0 {
            return Err(format!("{} gesture evidence is malformed", packet.case_id));
        }
        if let Some(short_tap_elapsed_ms) = gesture.short_tap_elapsed_ms {
            if short_tap_elapsed_ms < gesture.release_elapsed_ms {
                return Err(format!(
                    "{} short tap precedes its primary release",
                    packet.case_id
                ));
            }
        }
        let release_events = packet
            .candidate_events
            .iter()
            .filter(|event| {
                event.stream == gesture.stream
                    && event.input_group_id == gesture.input_group_id
                    && event.kind == HotkeyTraceEventKind::PrimaryRelease
                    && event.invocation_id == Some(gesture.invocation_id)
                    && event.elapsed_ms == gesture.release_elapsed_ms
                    && event.modifiers_match == Some(gesture.release_modifiers_match)
            })
            .count();
        if release_events != 1 {
            return Err(format!(
                "{} gesture release does not map one-to-one to its trace event",
                packet.case_id
            ));
        }
        if let Some(short_tap_elapsed_ms) = gesture.short_tap_elapsed_ms {
            let short_tap_events = packet
                .candidate_events
                .iter()
                .filter(|event| {
                    event.stream == gesture.stream
                        && event.input_group_id == gesture.input_group_id
                        && event.kind == HotkeyTraceEventKind::ShortTap
                        && event.invocation_id == Some(gesture.invocation_id)
                        && event.elapsed_ms == short_tap_elapsed_ms
                        && event.terminal == Some(true)
                })
                .count();
            if short_tap_events != 1 {
                return Err(format!(
                    "{} short tap does not map one-to-one to its trace event",
                    packet.case_id
                ));
            }
        }
        if let HotkeyDecisionProof::Applied {
            visibility_revision,
            intent_elapsed_ms,
            visible,
            release_to_intent_ms,
            root_commands,
            ..
        } = &gesture.decision
        {
            let Some(short_tap_elapsed_ms) = gesture.short_tap_elapsed_ms else {
                return Err(format!(
                    "{} applied visibility decision has no short tap",
                    packet.case_id
                ));
            };
            if *intent_elapsed_ms < gesture.release_elapsed_ms
                || *intent_elapsed_ms < short_tap_elapsed_ms
                || *release_to_intent_ms
                    != intent_elapsed_ms.saturating_sub(gesture.release_elapsed_ms)
                || root_commands.is_empty()
                || !root_commands
                    .iter()
                    .any(|span| span.observed_presentation.is_some())
                || !packet.candidate_events.iter().any(|event| {
                    event.stream == gesture.stream
                        && event.kind == HotkeyTraceEventKind::VisibilityIntent
                        && event.input_group_id == gesture.input_group_id
                        && event.invocation_id == Some(gesture.invocation_id)
                        && event.visibility_revision == Some(*visibility_revision)
                        && event.elapsed_ms == *intent_elapsed_ms
                        && event.visible == Some(*visible)
                        && event.visibility_source == Some(HotkeyVisibilitySource::ToggleBatch)
                })
            {
                return Err(format!(
                    "{} applied gesture is missing a correlated latency span",
                    packet.case_id
                ));
            }
            for span in root_commands {
                if span.visibility_revision == 0
                    || span.request_id == 0
                    || span.visibility_revision != *visibility_revision
                    || span.invocation_id != Some(gesture.invocation_id)
                    || span.command_elapsed_ms < gesture.release_elapsed_ms
                    || span.release_to_root_command_ms
                        != Some(
                            span.command_elapsed_ms
                                .saturating_sub(gesture.release_elapsed_ms),
                        )
                    || !root_command_span_matches(packet.into(), gesture.stream, span)
                {
                    return Err(format!(
                        "{} ROOT command span has invalid release correlation",
                        packet.case_id
                    ));
                }
                if let Some(observed) = &span.observed_presentation {
                    if observed.elapsed_ms < span.command_elapsed_ms
                        || observed.command_to_observed_ms
                            != observed.elapsed_ms.saturating_sub(span.command_elapsed_ms)
                    {
                        return Err(format!(
                            "{} ROOT presentation latency arithmetic is invalid",
                            packet.case_id
                        ));
                    }
                }
            }
            if !root_commands.iter().any(|span| {
                span.observed_presentation.as_ref().is_some_and(|observed| {
                    presentation_matches(packet.into(), gesture.stream, span, observed, *visible)
                })
            }) {
                return Err(format!(
                    "{} applied gesture lacks a ROOT-owned physical presentation matching its visibility decision",
                    packet.case_id
                ));
            }
            let actual_snapshot = packet
                .candidate_events
                .iter()
                .find(|event| {
                    event.stream == gesture.stream
                        && event.input_group_id == gesture.input_group_id
                        && event.input_purpose == gesture.input_purpose
                        && event.kind == HotkeyTraceEventKind::VisibilityIntent
                        && event.invocation_id == Some(gesture.invocation_id)
                        && event.visibility_revision == Some(*visibility_revision)
                })
                .and_then(|intent| {
                    packet
                        .root_identities
                        .iter()
                        .find(|root| root.stream == gesture.stream)
                        .and_then(|root| {
                            hotkey_intent_physical_snapshot(packet.into(), intent, root)
                        })
                });
            if actual_snapshot.is_none_or(|ordinal| {
                !root_commands
                    .iter()
                    .any(|span| span.observed_snapshot_event_ordinal == Some(ordinal))
            }) {
                return Err(format!(
                    "{} applied decision lacks a current physical observation before supersession",
                    packet.case_id
                ));
            }
        }
        if let HotkeyDecisionProof::Superseded {
            visibility_revision,
            by_revision,
            intent_elapsed_ms,
            release_to_intent_ms,
            visible,
            ..
        } = &gesture.decision
        {
            if gesture.short_tap_elapsed_ms.is_none()
                || *visibility_revision == 0
                || *by_revision <= *visibility_revision
                || *intent_elapsed_ms < gesture.release_elapsed_ms
                || *release_to_intent_ms
                    != intent_elapsed_ms.saturating_sub(gesture.release_elapsed_ms)
            {
                return Err(format!(
                    "{} superseded decision is malformed",
                    packet.case_id
                ));
            }
            let source_intent = packet.candidate_events.iter().find(|event| {
                event.stream == gesture.stream
                    && event.input_group_id == gesture.input_group_id
                    && event.input_purpose == gesture.input_purpose
                    && event.kind == HotkeyTraceEventKind::VisibilityIntent
                    && event.visibility_source == Some(HotkeyVisibilitySource::ToggleBatch)
                    && event.invocation_id == Some(gesture.invocation_id)
                    && event.visibility_revision == Some(*visibility_revision)
                    && event.elapsed_ms == *intent_elapsed_ms
                    && event.visible == Some(*visible)
            });
            let successor_intent = source_intent.and_then(|source| {
                packet
                    .root_identities
                    .iter()
                    .find(|root| root.stream == gesture.stream)
                    .and_then(|root| hotkey_terminal_successor(packet.into(), source, root))
                    .filter(|successor| successor.visibility_revision == Some(*by_revision))
            });
            let successor_gesture = successor_intent.and_then(|successor| {
                packet.gestures.iter().find(|candidate| {
                    candidate.stream == successor.stream
                        && candidate.input_group_id == successor.input_group_id
                        && candidate.input_purpose == successor.input_purpose
                        && Some(candidate.invocation_id) == successor.invocation_id
                        && candidate.short_tap_elapsed_ms.is_some()
                        && matches!(
                            &candidate.decision,
                            HotkeyDecisionProof::Applied {
                                visibility_revision,
                                root_commands,
                                ..
                            } if *visibility_revision == *by_revision
                                && root_commands.iter().any(|span| {
                                    span.observed_presentation.as_ref().is_some_and(|observed| {
                                        presentation_matches(
                                            packet.into(),
                                            candidate.stream,
                                            span,
                                            observed,
                                            successor.visible.unwrap_or(false),
                                        )
                                    })
                                })
                        )
                })
            });
            if successor_gesture.is_none() {
                return Err(format!(
                    "{} superseded decision lacks a later paired gesture with terminal physical presentation",
                    packet.case_id
                ));
            }
        }
        if let HotkeyDecisionProof::NotApplicable { reason } = &gesture.decision {
            let has_toggle_intent = packet.candidate_events.iter().any(|event| {
                event.stream == gesture.stream
                    && event.invocation_id == Some(gesture.invocation_id)
                    && event.kind == HotkeyTraceEventKind::VisibilityIntent
                    && event.visibility_source == Some(HotkeyVisibilitySource::ToggleBatch)
            });
            match reason {
                HotkeyEvidenceNotApplicable::HoldGestureHasNoShortTap
                    if gesture.short_tap_elapsed_ms.is_none() && !has_toggle_intent => {}
                HotkeyEvidenceNotApplicable::LegacyTriggerHasNoInvocationReducerId
                    if gesture.short_tap_elapsed_ms.is_none() && !has_toggle_intent => {}
                _ => {
                    return Err(format!(
                        "{} not-applicable gesture has a tap/toggle or an unsupported reason",
                        packet.case_id
                    ));
                }
            }
        }
    }

    for decision in &packet.standalone_decisions {
        if decision.source != HotkeyVisibilitySource::LegacyTrigger
            || decision.invocation_id.is_some()
            || decision.visibility_revision == 0
            || decision.root_commands.is_empty()
            || !packet.candidate_events.iter().any(|event| {
                event.stream == decision.stream
                    && event.kind == HotkeyTraceEventKind::VisibilityIntent
                    && event.input_group_id == decision.input_group_id
                    && event.visibility_revision == Some(decision.visibility_revision)
                    && event.invocation_id.is_none()
                    && event.elapsed_ms == decision.intent_elapsed_ms
                    && event.visible == Some(decision.visible)
                    && event.visibility_source == Some(HotkeyVisibilitySource::LegacyTrigger)
            })
            || !matches!(
                &decision.decision,
                HotkeyDecisionProof::NotApplicable {
                    reason: HotkeyEvidenceNotApplicable::LegacyTriggerHasNoInvocationReducerId
                }
            )
            || !decision
                .root_commands
                .iter()
                .any(|span| span.observed_presentation.is_some())
            || decision.root_commands.iter().any(|span| {
                span.visibility_revision != decision.visibility_revision
                    || span.invocation_id.is_some()
                    || span.release_to_root_command_ms.is_some()
                    || !root_command_span_matches(packet.into(), decision.stream, span)
            })
            || !decision.root_commands.iter().any(|span| {
                span.observed_presentation.as_ref().is_some_and(|observed| {
                    presentation_matches(
                        packet.into(),
                        decision.stream,
                        span,
                        observed,
                        decision.visible,
                    )
                })
            })
        {
            return Err(format!(
                "{} standalone legacy decision is incomplete",
                packet.case_id
            ));
        }
    }

    let screen_draw_events = packet
        .candidate_events
        .iter()
        .filter(|event| {
            event.kind == HotkeyTraceEventKind::VisibilityIntent
                && event.visibility_source == Some(HotkeyVisibilitySource::ScreenDrawRestore)
        })
        .collect::<Vec<_>>();
    let screen_draw_focus_events = packet
        .candidate_events
        .iter()
        .filter(|event| event.kind == HotkeyTraceEventKind::ScreenDrawRestoreFocusIntent)
        .collect::<Vec<_>>();
    if screen_draw_events.len() != packet.follow_on_restorations.len()
        || screen_draw_focus_events.len() != packet.follow_on_restorations.len()
    {
        return Err(format!(
            "{} Screen Draw restores are missing their focus-intent or follow-on proof records",
            packet.case_id
        ));
    }
    for restore in &packet.follow_on_restorations {
        if hotkey_owned_follow_on_restore_intent(packet.into(), restore).is_none() {
            return Err(format!(
                "{} Screen Draw follow-on lacks a correlated ROOT/native presentation span",
                packet.case_id
            ));
        }
    }

    if packet.case_id == "H11" {
        for intent in packet.candidate_events.iter().filter(|event| {
            event.kind == HotkeyTraceEventKind::VisibilityIntent
                && event.visibility_source == Some(HotkeyVisibilitySource::ToggleBatch)
        }) {
            if packet.candidate_events.iter().any(|event| {
                event.stream == intent.stream
                    && event.kind == HotkeyTraceEventKind::NativeActivation
                    && event.visibility_revision == intent.visibility_revision
                    && event.invocation_id == intent.invocation_id
                    && event.activation_edge == Some(HotkeyActivationEdge::RestoreRequested)
            }) {
                return Err(
                    "H11 PreserveForeground gesture requested native ROOT activation".into(),
                );
            }
        }
    }

    let matrix_taps = packet
        .gestures
        .iter()
        .filter(|gesture| {
            gesture.input_purpose == HotkeyRunnerInputPurpose::MatrixBurst
                && gesture.short_tap_elapsed_ms.is_some()
        })
        .count();
    let readable_taps = packet
        .gestures
        .iter()
        .filter(|gesture| {
            gesture.input_purpose == HotkeyRunnerInputPurpose::ReadableCadence
                && gesture.short_tap_elapsed_ms.is_some()
        })
        .count();
    if packet.case_id == "H04" && (matrix_taps != 86 || readable_taps != 3) {
        return Err("H04 evidence does not contain the complete 86+3 tap matrix".into());
    }
    let required_taps = match packet.case_id.as_str() {
        "H01" | "H02" | "H06" | "H08" | "H15" | "H18" => 1,
        "H07" => 3,
        "H16" => 2,
        "H11" => 5,
        "H17" => 2,
        "H04" | "H09" | "H10" => 0,
        "H12" => 1,
        _ => 0,
    };
    let measured_taps = packet
        .gestures
        .iter()
        .filter(|gesture| gesture.short_tap_elapsed_ms.is_some())
        .count();
    if measured_taps < required_taps {
        return Err(format!(
            "{} evidence has {measured_taps} taps; expected at least {required_taps}",
            packet.case_id
        ));
    }
    let required_holds = match packet.case_id.as_str() {
        "H08" | "H12" | "H18" => 1,
        "H09" | "H10" => 2,
        _ => 0,
    };
    let measured_holds = packet
        .gestures
        .iter()
        .filter(|gesture| {
            gesture_has_tagged_hold(packet, gesture, configured_hotkey, hold_threshold_ms)
        })
        .count();
    if measured_holds < required_holds {
        return Err(format!(
            "{} evidence has {measured_holds} tagged holds; expected at least {required_holds}",
            packet.case_id
        ));
    }
    let visible_decisions = packet
        .gestures
        .iter()
        .filter_map(|gesture| {
            hotkey_decision_visible(&gesture.decision).map(|visible| {
                (
                    gesture.stream,
                    gesture.input_purpose,
                    gesture.input_group_id,
                    gesture.release_elapsed_ms,
                    visible,
                )
            })
        })
        .collect::<Vec<_>>();
    let require_sequence = |stream, purpose, expected: &[bool]| -> Result<(), String> {
        let observed = visible_decisions
            .iter()
            .filter(|(candidate_stream, candidate_purpose, _, _, _)| {
                *candidate_stream == stream && *candidate_purpose == purpose
            })
            .map(|(_, _, _, _, visible)| *visible)
            .collect::<Vec<_>>();
        if observed != expected {
            return Err(format!(
                "{} expected {expected:?} visibility decisions for {purpose:?}, observed {observed:?}",
                packet.case_id
            ));
        }
        Ok(())
    };
    match packet.case_id.as_str() {
        "H01" => require_sequence(
            HotkeyCandidateStream::MainCandidate,
            HotkeyRunnerInputPurpose::LauncherChord,
            &[true],
        )?,
        "H02" => require_sequence(
            HotkeyCandidateStream::MainCandidate,
            HotkeyRunnerInputPurpose::LauncherChord,
            &[false],
        )?,
        "H06" => require_sequence(
            HotkeyCandidateStream::MainCandidate,
            HotkeyRunnerInputPurpose::LauncherChord,
            &[true],
        )?,
        "H07" => require_sequence(
            HotkeyCandidateStream::MainCandidate,
            HotkeyRunnerInputPurpose::LauncherChord,
            &[false, true, false],
        )?,
        "H08" => require_sequence(
            HotkeyCandidateStream::MainCandidate,
            HotkeyRunnerInputPurpose::LauncherChord,
            &[false],
        )?,
        "H11" => require_sequence(
            HotkeyCandidateStream::MainCandidate,
            HotkeyRunnerInputPurpose::LauncherChord,
            &[false, true, false, true, false],
        )?,
        "H12" => require_sequence(
            HotkeyCandidateStream::MainCandidate,
            HotkeyRunnerInputPurpose::LauncherChord,
            &[false],
        )?,
        "H15" => require_sequence(
            HotkeyCandidateStream::MainCandidate,
            HotkeyRunnerInputPurpose::LauncherChord,
            &[false],
        )?,
        "H16" => require_sequence(
            HotkeyCandidateStream::MainCandidate,
            HotkeyRunnerInputPurpose::LauncherChord,
            &[false, true],
        )?,
        "H17" => {
            require_sequence(
                HotkeyCandidateStream::MainCandidate,
                HotkeyRunnerInputPurpose::LauncherChord,
                &[true],
            )?;
            require_sequence(
                HotkeyCandidateStream::AlternateProfileCandidate,
                HotkeyRunnerInputPurpose::LauncherChord,
                &[true],
            )?;
        }
        "H18" => require_sequence(
            HotkeyCandidateStream::MainCandidate,
            HotkeyRunnerInputPurpose::LauncherChord,
            &[true],
        )?,
        "H04" => {
            let matrix_groups = packet
                .gestures
                .iter()
                .filter(|gesture| gesture.input_purpose == HotkeyRunnerInputPurpose::MatrixBurst)
                .fold(
                    std::collections::BTreeMap::<u32, Vec<&HotkeyGestureEvidence>>::new(),
                    |mut groups, gesture| {
                        groups
                            .entry(gesture.input_group_id)
                            .or_default()
                            .push(gesture);
                        groups
                    },
                );
            let expected_taps = [1usize, 2, 5, 10, 25, 1, 2, 5, 10, 25];
            if matrix_groups.len() != expected_taps.len() {
                return Err(
                    "H04 matrix evidence has the wrong number of uninterrupted bursts".into(),
                );
            }
            for (index, (group_id, gestures)) in matrix_groups.iter().enumerate() {
                let mut ordered = gestures.iter().copied().collect::<Vec<_>>();
                ordered.sort_by_key(|gesture| gesture.release_elapsed_ms);
                if *group_id != u32::try_from(index + 1).unwrap_or(u32::MAX)
                    || ordered.len() != expected_taps[index]
                {
                    return Err(format!(
                        "H04 burst group {group_id} has an unexpected identity or {} decisions, expected group {} with {} decisions",
                        ordered.len(),
                        index + 1,
                        expected_taps[index]
                    ));
                }
                let mut group_visible = index >= 5;
                for gesture in ordered {
                    group_visible = !group_visible;
                    if hotkey_decision_visible(&gesture.decision) != Some(group_visible) {
                        return Err(format!(
                            "H04 burst group {group_id} did not alternate visible state per gesture"
                        ));
                    }
                }
            }
            require_sequence(
                HotkeyCandidateStream::MainCandidate,
                HotkeyRunnerInputPurpose::ReadableCadence,
                &[true, false, true],
            )?;
        }
        _ => {}
    }
    if packet.case_id == "H16"
        && !packet.standalone_decisions.iter().any(|decision| {
            decision.stream == HotkeyCandidateStream::LegacyFallbackCandidate
                && decision.source == HotkeyVisibilitySource::LegacyTrigger
        })
    {
        return Err("H16 evidence omitted the supported legacy launcher route".into());
    }
    if packet.case_id == "H17"
        && (!packet
            .gestures
            .iter()
            .any(|gesture| gesture.stream == HotkeyCandidateStream::MainCandidate)
            || !packet
                .gestures
                .iter()
                .any(|gesture| gesture.stream == HotkeyCandidateStream::AlternateProfileCandidate))
    {
        return Err("H17 evidence omitted a profile candidate stream".into());
    }

    validate_runner_edge_groups(packet, configured_hotkey, hold_threshold_ms)?;
    if packet.case_id == "H04" {
        validate_h04_matrix_foreign_edges(packet)?;
    }

    let mut previous_runner_us = None;
    for edge in &packet.runner_edges {
        if edge.input_group_id == 0 || edge.runner_relative_us > 24 * 60 * 60 * 1_000_000 {
            return Err(format!(
                "{} runner edge evidence is malformed",
                packet.case_id
            ));
        }
        if previous_runner_us.is_some_and(|previous| edge.runner_relative_us < previous) {
            return Err(format!(
                "{} runner edge timestamps are out of order",
                packet.case_id
            ));
        }
        previous_runner_us = Some(edge.runner_relative_us);
    }
    validate_screen_draw_priority(packet, configured_hotkey)?;
    Ok(())
}

use multi_launcher::radial::acceptance_trace::{
    ScreenDrawLauncherObservation, ScreenDrawParkingObservation, ScreenDrawParkingState,
    ScreenDrawRootIdentity, ScreenDrawToolbarMode, ScreenDrawToolbarObservation,
    ScreenDrawToolbarRole, ScreenDrawToolbarTarget, ScreenDrawToolbarWidget,
};

#[derive(Clone, Debug, PartialEq, Eq, Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct ScreenDrawToolbarReceipt {
    event_ordinal: u32,
    trace_sequence: u64,
    elapsed_ms: u64,
    observation: ScreenDrawToolbarObservation,
}

/// One contract for live admission and persisted H15 proof. Native client
/// measurement and presentation are independent of the producer's UI frame.
fn validate_screen_draw_toolbar_receipt(
    receipt: &ScreenDrawToolbarReceipt,
    mode: ScreenDrawToolbarMode,
    presentation: &QueryRootPresentationEvidence,
    native_client: [i32; 4],
    displays: &[[i32; 4]],
    after_ordinal: u32,
    through_ordinal: u32,
    prior: Option<&ScreenDrawToolbarReceipt>,
) -> Result<(), String> {
    let frame = &receipt.observation;
    let width = native_client[2].checked_sub(native_client[0]);
    let height = native_client[3].checked_sub(native_client[1]);
    if receipt.event_ordinal <= after_ordinal
        || receipt.event_ordinal > through_ordinal
        || receipt.trace_sequence == 0
        || frame.hwnd == 0
        || frame.process_id == 0
        || frame.generation == 0
        || frame.lifetime == 0
        || frame.frame_nr == 0
        || frame.state != mode
        || frame.runtime_mode != mode
        || !matches!(
            mode,
            ScreenDrawToolbarMode::Drawing | ScreenDrawToolbarMode::Ghost
        )
        || !owned_root_presentation_is_valid(
            presentation,
            displays,
            frame.hwnd,
            frame.process_id,
            true,
        )
        || native_client[0] != 0
        || native_client[1] != 0
        || width != Some(frame.client_size[0])
        || height != Some(frame.client_size[1])
        || frame.client_size.iter().any(|size| *size <= 0)
    {
        return Err("Screen Draw receipt has stale identity, mode, client, or presentation".into());
    }
    if !frame.has_visible_controls_for_mode(mode) {
        return Err(
            "Screen Draw receipt lacks its real visible enabled state-label/Resume responses"
                .into(),
        );
    }
    let owner = &frame.launcher;
    let root = owner
        .root
        .ok_or("Screen Draw receipt omitted the current ROOT identity")?;
    let parking = owner
        .parking
        .ok_or("Screen Draw receipt omitted the current parking transaction")?;
    if owner.visibility_revision == 0
        || owner.invocation_id == Some(0)
        || root.hwnd == 0
        || root.hwnd == frame.hwnd
        || root.process_id != frame.process_id
        || root.generation == 0
        || parking.hwnd != root.hwnd
        || parking.generation != frame.generation
        || parking.cycle == 0
        || (mode == ScreenDrawToolbarMode::Drawing
            && (owner.visible || parking.state != ScreenDrawParkingState::Committed))
        || (mode == ScreenDrawToolbarMode::Ghost
            && (!owner.visible || parking.state != ScreenDrawParkingState::Restored))
    {
        return Err(
            "Screen Draw receipt has incomplete or conflicting current launcher ownership".into(),
        );
    }
    if let Some(prior) = prior {
        let previous = &prior.observation;
        if receipt.event_ordinal <= prior.event_ordinal
            || receipt.trace_sequence <= prior.trace_sequence
            || receipt.elapsed_ms < prior.elapsed_ms
            || frame.frame_nr <= previous.frame_nr
            || frame.hwnd != previous.hwnd
            || frame.process_id != previous.process_id
            || frame.generation != previous.generation
            || frame.lifetime != previous.lifetime
            || frame.label.widget_id != previous.label.widget_id
        {
            return Err(
                "Screen Draw recovery receipt is not a fresh frame of the pinned toolbar lifetime"
                    .into(),
            );
        }
    }
    Ok(())
}

/// The pre-input frame is an observation of the current owners, rather than a
/// historical desired-visibility event or a value inferred from recovery.
fn validate_screen_draw_baseline_receipt(
    baseline: &ScreenDrawToolbarReceipt,
    ready: &ScreenDrawToolbarReceipt,
    tool: &QueryRootPresentationEvidence,
    client: [i32; 4],
    root_hwnd: u64,
    process_id: u32,
    displays: &[[i32; 4]],
    entry_ordinal: u32,
    entry_sequence: u64,
    cursor: u32,
) -> Result<(), String> {
    validate_screen_draw_toolbar_receipt(
        baseline,
        ScreenDrawToolbarMode::Drawing,
        tool,
        client,
        displays,
        entry_ordinal,
        cursor,
        None,
    )?;
    let frame = &baseline.observation;
    let initial = &ready.observation;
    let owner = frame.launcher;
    let root = owner.root.ok_or("H15 baseline ROOT is absent")?;
    if baseline.trace_sequence <= entry_sequence
        || baseline.event_ordinal < ready.event_ordinal
        || baseline.trace_sequence < ready.trace_sequence
        || baseline.elapsed_ms < ready.elapsed_ms
        || (baseline.event_ordinal == ready.event_ordinal && baseline != ready)
        || (baseline.event_ordinal > ready.event_ordinal
            && (baseline.trace_sequence <= ready.trace_sequence
                || frame.frame_nr <= initial.frame_nr))
        || frame.hwnd != initial.hwnd
        || frame.process_id != initial.process_id
        || frame.generation != initial.generation
        || frame.lifetime != initial.lifetime
        || frame.label.widget_id != initial.label.widget_id
        || root.hwnd != root_hwnd
        || root.process_id != process_id
        || owner.root != initial.launcher.root
        || owner.visibility_revision < initial.launcher.visibility_revision
        || (owner.visibility_revision == initial.launcher.visibility_revision
            && (owner.invocation_id != initial.launcher.invocation_id
                || owner.focus_intent != initial.launcher.focus_intent
                || owner.visible != initial.launcher.visible))
        || owner
            .parking
            .map(|parking| (parking.hwnd, parking.generation, parking.cycle))
            != initial
                .launcher
                .parking
                .map(|parking| (parking.hwnd, parking.generation, parking.cycle))
    {
        return Err(
            "H15 baseline is not the current pre-chord frame of the owned entry lifetime".into(),
        );
    }
    Ok(())
}

fn validate_screen_draw_recovery_owner(
    baseline: &ScreenDrawToolbarReceipt,
    recovered: &ScreenDrawToolbarReceipt,
    revision: u64,
    invocation: Option<u64>,
    focus: HotkeyRootFocusIntent,
) -> Result<(), String> {
    let before = baseline.observation.launcher;
    let after = recovered.observation.launcher;
    let expected_focus = match focus {
        HotkeyRootFocusIntent::ActivateRoot => {
            multi_launcher::visibility::RootFocusIntent::ActivateRoot
        }
        HotkeyRootFocusIntent::PreserveForeground => {
            multi_launcher::visibility::RootFocusIntent::PreserveForeground
        }
    };
    if revision <= before.visibility_revision
        || after.visibility_revision != revision
        || before.invocation_id != invocation
        || after.invocation_id != invocation
        || before.focus_intent != expected_focus
        || after.focus_intent != expected_focus
        || after.root != before.root
        || after
            .parking
            .map(|parking| (parking.hwnd, parking.generation, parking.cycle))
            != before
                .parking
                .map(|parking| (parking.hwnd, parking.generation, parking.cycle))
    {
        return Err(
            "H15 recovered frame is not the exact current baseline owner's restoration".into(),
        );
    }
    Ok(())
}

fn validate_screen_draw_priority(
    packet: &HotkeyCaseEvidence,
    hotkey: AcceptanceHotkey,
) -> Result<(), String> {
    if packet.case_id != "H15" {
        return if packet.screen_draw_priority.is_none() {
            Ok(())
        } else {
            Err("Screen Draw priority proof is present outside H15".into())
        };
    }
    let proof = packet
        .screen_draw_priority
        .as_ref()
        .ok_or("H15 omitted real Screen Draw priority proof")?;
    let root = packet
        .root_identities
        .iter()
        .find(|root| root.stream == HotkeyCandidateStream::MainCandidate)
        .ok_or("H15 omitted the owned ROOT identity")?;
    let valid_root = |sample: &QueryRootPresentationEvidence| {
        owned_root_presentation_is_valid(
            sample,
            &packet.physical_displays,
            root.hwnd,
            root.process_id,
            true,
        )
    };
    let valid_tool = |sample: &QueryRootPresentationEvidence| {
        sample.hwnd != root.hwnd
            && owned_root_presentation_is_valid(
                sample,
                &packet.physical_displays,
                sample.hwnd,
                root.process_id,
                true,
            )
    };
    let expected = configured_chord_edges(hotkey, 1);
    let edges = proof
        .runner_edges
        .iter()
        .map(|edge| (edge.virtual_key, edge.down))
        .collect::<Vec<_>>();
    let cursor = u32::try_from(proof.trace_cursor)
        .map_err(|_| "H15 trace cursor exceeds its ordinal bound")?;
    let end =
        u32::try_from(proof.trace_end).map_err(|_| "H15 trace end exceeds its ordinal bound")?;
    validate_screen_draw_toolbar_receipt(
        &proof.ready_observation,
        ScreenDrawToolbarMode::Drawing,
        &proof.ready_tool,
        proof.ready_client_bounds,
        &packet.physical_displays,
        proof.entry_clicked_ordinal,
        cursor,
        None,
    )?;
    validate_screen_draw_baseline_receipt(
        &proof.baseline_observation,
        &proof.ready_observation,
        &proof.baseline_tool,
        proof.baseline_client_bounds,
        root.hwnd,
        root.process_id,
        &packet.physical_displays,
        proof.entry_clicked_ordinal,
        proof.entry_clicked_sequence,
        cursor,
    )?;
    let baseline_owner = proof.baseline_observation.observation.launcher;
    if proof.baseline_visibility_revision != baseline_owner.visibility_revision
        || proof.baseline_invocation_id != baseline_owner.invocation_id
    {
        return Err("H15 baseline scalars do not match its mandatory producer receipt".into());
    }
    let recovery_boundary = proof
        .admissions
        .first()
        .ok_or("H15 lacks its recovery admission")?;
    validate_screen_draw_toolbar_receipt(
        &proof.recovered_observation,
        ScreenDrawToolbarMode::Ghost,
        &proof.recovered_tool,
        proof.recovered_client_bounds,
        &packet.physical_displays,
        recovery_boundary.event_ordinal,
        end,
        Some(&proof.baseline_observation),
    )?;
    if proof.entry_clicked_sequence == 0
        || proof.ready_observation.trace_sequence <= proof.entry_clicked_sequence
        || proof.recovered_observation.elapsed_ms < recovery_boundary.elapsed_ms
        || proof
            .primary_edges
            .first()
            .is_none_or(|edge| proof.baseline_observation.elapsed_ms > edge.elapsed_ms)
        || proof.recovered_observation.elapsed_ms > proof.next_admission.elapsed_ms
    {
        return Err(
            "H15 toolbar observations do not follow actual entry and recovery boundaries".into(),
        );
    }
    if !valid_root(&proof.entry_root)
        || !valid_root(&proof.recovered_root)
        || !valid_tool(&proof.ready_tool)
        || !valid_tool(&proof.baseline_tool)
        || !valid_tool(&proof.recovered_tool)
        || proof.ready_tool.hwnd != proof.recovered_tool.hwnd
        || proof.entry_query_digest
            != query_cell_digest(&format!("app {PRIORITY_SMOKE_ACTION_LABEL}"))
        || proof.entry_label_digest != query_cell_digest(PRIORITY_SMOKE_ACTION_LABEL)
        || proof.entry_action_digest != query_cell_digest("screen_draw:start")
        || proof.tool_title_digest != query_cell_digest(PRIORITY_SMOKE_TOOL_TITLE)
        || proof.entry_control_bounds[2] <= proof.entry_control_bounds[0]
        || proof.entry_control_bounds[3] <= proof.entry_control_bounds[1]
        || proof.entry_control_bounds[0] < proof.entry_root.bounds[0]
        || proof.entry_control_bounds[1] < proof.entry_root.bounds[1]
        || proof.entry_control_bounds[2] > proof.entry_root.bounds[2]
        || proof.entry_control_bounds[3] > proof.entry_root.bounds[3]
        || proof.entry_down_inserted != 1
        || proof.entry_up_inserted != 1
        || proof.entry_clicked_ordinal == 0
        || proof.entry_clicked_ordinal > cursor
        || !proof.drawing_ui_ack
        || !proof.ghost_ui_ack
        || cursor == 0
        || end <= cursor
        || proof.baseline_visibility_revision == 0
        || !(75..=1_000).contains(&proof.quiet_preflight_ms)
        || !proof.observer_default_desktop
        || proof.input_down_inserted != expected.len() / 2
        || proof.input_up_inserted != expected.len() / 2
        || proof.input_down_foreground_hwnd != proof.ready_tool.hwnd
        || proof.input_down_foreground_pid != root.process_id
        || ![root.hwnd, proof.ready_tool.hwnd].contains(&proof.input_up_foreground_hwnd)
        || proof.input_up_foreground_pid != root.process_id
        || !proof.input_down_default_desktop
        || !proof.input_up_default_desktop
        || edges != expected
        || !proof.foreign_edges.is_empty()
        || proof.runner_edges.iter().any(|edge| {
            !edge.injected || !edge.runner_cookie_matched || edge.runner_relative_us > 5_000_000
        })
        || proof
            .runner_edges
            .windows(2)
            .any(|pair| pair[0].runner_relative_us > pair[1].runner_relative_us)
        || proof.primary_edges.len() != 2
        || proof.admissions.len() != 2
        || proof.configured_primary.len() != 1
        || proof.candidate_events.is_empty()
        || proof.candidate_events.len() > 128
        || proof.restorations.len() != 1
        || proof.forbidden_event_count != 0
        || proof.runtime_window_count != 0
        || !proof.keys_released
        || !proof.close_requested
        || !proof.tool_closed
        || proof.close_terminal_cursor < proof.trace_end
        || packet.gestures.len() != 1
        || !packet.standalone_decisions.is_empty()
    {
        return Err("H15 real entry, owned tool, exact input, suppression, or cleanup evidence is incomplete".into());
    }
    for (index, transition) in [HotkeyEdgeTransition::Press, HotkeyEdgeTransition::Release]
        .into_iter()
        .enumerate()
    {
        let primary = &proof.primary_edges[index];
        let admission = &proof.admissions[index];
        if primary.transition != transition
            || admission.transition != transition
            || primary.provenance != HotkeyInputProvenance::ExternalInjected
            || admission.provenance != HotkeyInputProvenance::ExternalInjected
            || primary.event_ordinal <= cursor
            || primary.event_ordinal > end
            || admission.event_ordinal <= primary.event_ordinal
            || admission.event_ordinal > end
            || admission.elapsed_ms < primary.elapsed_ms
            || admission.deadline_scheduled
            || admission.radial_intent
            || (index == 0
                && (primary.foreground_owner != PriorityForegroundOwner::Other
                    || admission.owner != PriorityHookOwner::ScreenDrawRecovery
                    || admission.global_exclusive_owners != 1
                    || !admission.recovery))
            || (index == 1
                && (admission.recovery
                    || admission.owner == PriorityHookOwner::ExclusiveTool
                    || admission.global_exclusive_owners & !1 != 0))
            || (index == 1
                && (primary.event_ordinal <= proof.admissions[0].event_ordinal
                    || primary.elapsed_ms < proof.admissions[0].elapsed_ms))
        {
            return Err("H15 lacks ordered external primary edges and authoritative Screen Draw recovery admission".into());
        }
    }
    // InvocationAdapter records the configured key before deciding who owns
    // it. Recovery drains release before that recording path, so precisely one
    // preadmission Press must bridge the hook edge and recovery admission.
    let configured = &proof.configured_primary[0];
    if configured.transition != HotkeyEdgeTransition::Press
        || configured.provenance != HotkeyInputProvenance::ExternalInjected
        || !configured.modifiers_match
        || configured.invocation_id == 0
        || configured.generation == 0
        || configured.event_ordinal <= proof.primary_edges[0].event_ordinal
        || configured.event_ordinal >= proof.admissions[0].event_ordinal
        || configured.elapsed_ms < proof.primary_edges[0].elapsed_ms
        || configured.elapsed_ms > proof.admissions[0].elapsed_ms
    {
        return Err("H15 configured primary is not the owned preadmission recovery receipt".into());
    }
    let mut recovery_packet = packet.clone();
    recovery_packet.screen_draw_priority = None;
    recovery_packet.candidate_events = proof.candidate_events.clone();
    recovery_packet.gestures.clear();
    recovery_packet.standalone_decisions.clear();
    recovery_packet.follow_on_restorations = proof.restorations.clone();
    validate_hotkey_candidate_event_coverage(&recovery_packet)?;
    let restore = &proof.restorations[0];
    validate_screen_draw_recovery_owner(
        &proof.baseline_observation,
        &proof.recovered_observation,
        restore.visibility_revision,
        restore.invocation_id,
        restore.focus_intent,
    )?;
    let mut last_event = None;
    for event in &proof.candidate_events {
        if event.stream != HotkeyCandidateStream::MainCandidate
            || event.input_group_id != 1
            || event.input_purpose != HotkeyRunnerInputPurpose::LauncherChord
            || event.event_ordinal <= cursor
            || event.event_ordinal > end
            || last_event.is_some_and(|(ordinal, elapsed)| {
                event.event_ordinal <= ordinal || event.elapsed_ms < elapsed
            })
            || matches!(
                event.kind,
                HotkeyTraceEventKind::PrimaryPress
                    | HotkeyTraceEventKind::PrimaryRelease
                    | HotkeyTraceEventKind::ShortTap
                    | HotkeyTraceEventKind::RadialAction
            )
            || event.invocation_id != proof.baseline_invocation_id
            || event.visibility_revision != Some(restore.visibility_revision)
        {
            return Err(
                "H15 suppression interval has stale, admitted, or unrelated candidate events"
                    .into(),
            );
        }
        last_event = Some((event.event_ordinal, event.elapsed_ms));
    }
    let intents = proof
        .candidate_events
        .iter()
        .filter(|event| event.kind == HotkeyTraceEventKind::VisibilityIntent)
        .collect::<Vec<_>>();
    if intents.len() != 1
        || intents[0].visibility_source != Some(HotkeyVisibilitySource::ScreenDrawRestore)
        || intents[0].visible != Some(true)
        || intents[0].event_ordinal <= proof.admissions[0].event_ordinal
        || intents[0].elapsed_ms < proof.admissions[0].elapsed_ms
        || restore.visibility_revision <= proof.baseline_visibility_revision
        || restore.invocation_id != proof.baseline_invocation_id
        || !restore.visible
        || restore.intent_elapsed_ms != intents[0].elapsed_ms
        || restore.stream != HotkeyCandidateStream::MainCandidate
        || restore.input_group_id != 1
        || restore.root_commands.is_empty()
        || !proof.candidate_events.iter().any(|event| {
            event.kind == HotkeyTraceEventKind::ScreenDrawRestoreFocusIntent
                && event.event_ordinal > intents[0].event_ordinal
                && event.focus_intent == Some(restore.focus_intent)
        })
        || !proof.candidate_events.iter().any(|event| {
            event.kind == HotkeyTraceEventKind::NativeWindowSnapshot
                && event.bounds == Some(proof.recovered_root.bounds)
                && event.visible == Some(proof.recovered_root.visible)
                && event.minimized == Some(proof.recovered_root.minimized)
                && event.hwnd == Some(root.hwnd)
                && event.process_id == Some(root.process_id)
        })
        || restore
            .root_commands
            .iter()
            .any(|span| !root_command_span_matches((&recovery_packet).into(), restore.stream, span))
        || !restore.root_commands.iter().any(|span| {
            span.observed_presentation.as_ref().is_some_and(|observed| {
                presentation_matches(
                    (&recovery_packet).into(),
                    restore.stream,
                    span,
                    observed,
                    true,
                )
            })
        })
        || (restore.focus_intent == HotkeyRootFocusIntent::ActivateRoot
            && !restore.native_activation.as_ref().is_some_and(|span| {
                native_activation_span_matches(
                    (&recovery_packet).into(),
                    restore.stream,
                    restore,
                    span,
                )
            }))
    {
        return Err(
            "H15 recovery is stale or lacks correlated Screen Draw ROOT/native presentation".into(),
        );
    }
    let gesture = &packet.gestures[0];
    let press = packet
        .candidate_events
        .iter()
        .find(|event| {
            event.kind == HotkeyTraceEventKind::PrimaryPress
                && event.invocation_id == Some(gesture.invocation_id)
        })
        .ok_or("H15 next gesture omitted its admitted press")?;
    let release = packet
        .candidate_events
        .iter()
        .find(|event| {
            event.kind == HotkeyTraceEventKind::PrimaryRelease
                && event.invocation_id == Some(gesture.invocation_id)
        })
        .ok_or("H15 next gesture omitted its admitted release")?;
    let admission = &proof.next_admission;
    if usize::try_from(press.event_ordinal).unwrap_or(0) <= proof.close_terminal_cursor
        || gesture.invocation_id != configured.invocation_id
        || proof
            .baseline_invocation_id
            .is_some_and(|baseline| gesture.invocation_id <= baseline)
        || admission.event_ordinal <= press.event_ordinal
        || admission.event_ordinal >= release.event_ordinal
        || admission.elapsed_ms < press.elapsed_ms
        || admission.transition != HotkeyEdgeTransition::Press
        || admission.provenance != HotkeyInputProvenance::ExternalInjected
        || admission.owner != PriorityHookOwner::Launcher
        || admission.global_exclusive_owners != 0
        || admission.adapter_exclusive
        || admission.recovery
        || !admission.deadline_scheduled
        || admission.radial_intent
        || admission.elapsed_ms > gesture.release_elapsed_ms
        || hotkey_decision_visible(&gesture.decision) != Some(false)
    {
        return Err(
            "H15 owner cleanup did not precede one usable normal configured gesture".into(),
        );
    }
    Ok(())
}

fn validate_hotkey_candidate_event_coverage(packet: &HotkeyCaseEvidence) -> Result<(), String> {
    for event in &packet.candidate_events {
        match event.kind {
            HotkeyTraceEventKind::VisibilityIntent => {
                if visibility_intent_proof_count(packet, event) != 1 {
                    return Err(format!(
                        "{} visibility intent has no unique matching decision proof",
                        packet.case_id
                    ));
                }
            }
            HotkeyTraceEventKind::RootCommand => {
                if root_command_event_reference_count(packet, event) != 1 {
                    return Err(format!(
                        "{} ROOT command has no unique matching command span",
                        packet.case_id
                    ));
                }
            }
            HotkeyTraceEventKind::RadialAction => {
                return Err(format!(
                    "{} launcher gesture selected or dispatched a radial action ({:?})",
                    packet.case_id, event.radial_action_stage
                ));
            }
            _ => {}
        }
    }

    for gesture in &packet.gestures {
        let (visibility_revision, intent_elapsed_ms, visible) = match &gesture.decision {
            HotkeyDecisionProof::Applied {
                visibility_revision,
                intent_elapsed_ms,
                visible,
                ..
            }
            | HotkeyDecisionProof::Superseded {
                visibility_revision,
                intent_elapsed_ms,
                visible,
                ..
            } => (*visibility_revision, *intent_elapsed_ms, *visible),
            HotkeyDecisionProof::NotApplicable { .. } => continue,
        };
        let intent_count = packet
            .candidate_events
            .iter()
            .filter(|event| {
                event.stream == gesture.stream
                    && event.input_group_id == gesture.input_group_id
                    && event.kind == HotkeyTraceEventKind::VisibilityIntent
                    && event.visibility_source == Some(HotkeyVisibilitySource::ToggleBatch)
                    && event.invocation_id == Some(gesture.invocation_id)
                    && event.visibility_revision == Some(visibility_revision)
                    && event.elapsed_ms == intent_elapsed_ms
                    && event.visible == Some(visible)
            })
            .count();
        if intent_count != 1 {
            return Err(format!(
                "{} gesture decision maps to {intent_count} trace intents instead of one",
                packet.case_id
            ));
        }
    }

    for decision in &packet.standalone_decisions {
        let intent_count = packet
            .candidate_events
            .iter()
            .filter(|event| {
                event.stream == decision.stream
                    && event.input_group_id == decision.input_group_id
                    && event.kind == HotkeyTraceEventKind::VisibilityIntent
                    && event.visibility_source == Some(HotkeyVisibilitySource::LegacyTrigger)
                    && event.invocation_id.is_none()
                    && event.visibility_revision == Some(decision.visibility_revision)
                    && event.elapsed_ms == decision.intent_elapsed_ms
                    && event.visible == Some(decision.visible)
            })
            .count();
        if intent_count != 1 {
            return Err(format!(
                "{} standalone legacy decision maps to {intent_count} trace intents instead of one",
                packet.case_id
            ));
        }
    }

    for restore in &packet.follow_on_restorations {
        let intent_count = packet
            .candidate_events
            .iter()
            .filter(|event| {
                event.stream == restore.stream
                    && event.input_group_id == restore.input_group_id
                    && event.kind == HotkeyTraceEventKind::VisibilityIntent
                    && event.visibility_source == Some(HotkeyVisibilitySource::ScreenDrawRestore)
                    && event.invocation_id == restore.invocation_id
                    && event.visibility_revision == Some(restore.visibility_revision)
                    && event.elapsed_ms == restore.intent_elapsed_ms
                    && event.visible == Some(restore.visible)
            })
            .count();
        if intent_count != 1 {
            return Err(format!(
                "{} Screen Draw follow-on maps to {intent_count} trace intents instead of one",
                packet.case_id
            ));
        }
    }

    let mut snapshot_event_references = std::collections::BTreeSet::new();
    for (stream, span) in all_root_command_spans(packet) {
        let event_count = packet
            .candidate_events
            .iter()
            .filter(|event| root_command_event_matches_span(event, stream, span))
            .count();
        if event_count != 1 || !root_command_span_matches(packet.into(), stream, span) {
            return Err(format!(
                "{} ROOT command event reference is dangling, duplicated, or does not match its source record",
                packet.case_id
            ));
        }
        if let Some(ordinal) = span.observed_snapshot_event_ordinal {
            if !snapshot_event_references.insert((stream, ordinal)) {
                return Err(format!(
                    "{} native presentation event reference is duplicated",
                    packet.case_id
                ));
            }
            let snapshot_count = packet
                .candidate_events
                .iter()
                .filter(|event| event.stream == stream && event.event_ordinal == ordinal)
                .count();
            if snapshot_count != 1
                || !packet.candidate_events.iter().any(|event| {
                    event.stream == stream
                        && event.event_ordinal == ordinal
                        && event.kind == HotkeyTraceEventKind::NativeWindowSnapshot
                })
            {
                return Err(format!(
                    "{} native presentation event reference is dangling or has the wrong type",
                    packet.case_id
                ));
            }
        }
    }

    Ok(())
}

fn visibility_intent_proof_count(
    packet: &HotkeyCaseEvidence,
    event: &HotkeyCandidateEventEvidence,
) -> usize {
    match event.visibility_source {
        Some(HotkeyVisibilitySource::ToggleBatch) => packet
            .gestures
            .iter()
            .filter(|gesture| {
                gesture.stream == event.stream
                    && gesture.input_group_id == event.input_group_id
                    && Some(gesture.invocation_id) == event.invocation_id
                    && matches!(
                        &gesture.decision,
                        HotkeyDecisionProof::Applied {
                            visibility_revision,
                            intent_elapsed_ms,
                            visible,
                            ..
                        }
                        | HotkeyDecisionProof::Superseded {
                            visibility_revision,
                            intent_elapsed_ms,
                            visible,
                            ..
                        } if Some(*visibility_revision) == event.visibility_revision
                            && *intent_elapsed_ms == event.elapsed_ms
                            && Some(*visible) == event.visible
                    )
            })
            .count(),
        Some(HotkeyVisibilitySource::LegacyTrigger) => packet
            .standalone_decisions
            .iter()
            .filter(|decision| {
                decision.stream == event.stream
                    && decision.input_group_id == event.input_group_id
                    && decision.invocation_id.is_none()
                    && Some(decision.visibility_revision) == event.visibility_revision
                    && decision.intent_elapsed_ms == event.elapsed_ms
                    && Some(decision.visible) == event.visible
                    && decision.source == HotkeyVisibilitySource::LegacyTrigger
            })
            .count(),
        Some(HotkeyVisibilitySource::ScreenDrawRestore) => packet
            .follow_on_restorations
            .iter()
            .filter(|restore| {
                restore.stream == event.stream
                    && restore.input_group_id == event.input_group_id
                    && restore.invocation_id == event.invocation_id
                    && Some(restore.visibility_revision) == event.visibility_revision
                    && restore.intent_elapsed_ms == event.elapsed_ms
                    && Some(restore.visible) == event.visible
            })
            .count(),
        Some(HotkeyVisibilitySource::Queued) => {
            let Some(revision) = event.visibility_revision else {
                return 0;
            };
            packet
                .candidate_events
                .iter()
                .filter(|authoritative| {
                    authoritative.stream == event.stream
                        && authoritative.kind == HotkeyTraceEventKind::VisibilityIntent
                        && authoritative.visibility_source.is_some_and(|source| {
                            matches!(
                                source,
                                HotkeyVisibilitySource::ToggleBatch
                                    | HotkeyVisibilitySource::LegacyTrigger
                                    | HotkeyVisibilitySource::ScreenDrawRestore
                            )
                        })
                        && authoritative.visibility_revision == Some(revision)
                        && authoritative.visible == event.visible
                        && authoritative.elapsed_ms <= event.elapsed_ms
                        && event
                            .invocation_id
                            .is_none_or(|id| authoritative.invocation_id == Some(id))
                })
                .count()
        }
        Some(HotkeyVisibilitySource::Other) | None => 0,
    }
}

fn all_root_command_spans<'a>(
    packet: &'a HotkeyCaseEvidence,
) -> Vec<(HotkeyCandidateStream, &'a HotkeyRootCommandSpan)> {
    let mut spans = Vec::new();
    for gesture in &packet.gestures {
        if let HotkeyDecisionProof::Applied { root_commands, .. } = &gesture.decision {
            spans.extend(root_commands.iter().map(|span| (gesture.stream, span)));
        }
    }
    for decision in &packet.standalone_decisions {
        spans.extend(
            decision
                .root_commands
                .iter()
                .map(|span| (decision.stream, span)),
        );
    }
    for restore in &packet.follow_on_restorations {
        spans.extend(
            restore
                .root_commands
                .iter()
                .map(|span| (restore.stream, span)),
        );
    }
    spans
}

fn root_command_event_reference_count(
    packet: &HotkeyCaseEvidence,
    event: &HotkeyCandidateEventEvidence,
) -> usize {
    let applied_references = all_root_command_spans(packet)
        .iter()
        .filter(|(stream, span)| root_command_event_matches_span(event, *stream, span))
        .count();
    // Superseded work stays in the bounded original event inventory. Its typed
    // decision owns those command records directly, without fabricating an
    // Applied span or dropping already-issued requests and late observations.
    let superseded_references = packet
        .gestures
        .iter()
        .filter(|gesture| {
            let HotkeyDecisionProof::Superseded {
                visibility_revision,
                intent_elapsed_ms,
                visible,
                ..
            } = &gesture.decision
            else {
                return false;
            };
            packet.candidate_events.iter().any(|intent| {
                intent.stream == gesture.stream
                    && intent.input_group_id == gesture.input_group_id
                    && intent.input_purpose == gesture.input_purpose
                    && intent.kind == HotkeyTraceEventKind::VisibilityIntent
                    && intent.visibility_source == Some(HotkeyVisibilitySource::ToggleBatch)
                    && intent.invocation_id == Some(gesture.invocation_id)
                    && intent.visibility_revision == Some(*visibility_revision)
                    && intent.elapsed_ms == *intent_elapsed_ms
                    && intent.visible == Some(*visible)
                    && hotkey_command_belongs_to_intent(event, intent)
            })
        })
        .count();
    applied_references + superseded_references
}

fn root_command_event_matches_span(
    event: &HotkeyCandidateEventEvidence,
    stream: HotkeyCandidateStream,
    span: &HotkeyRootCommandSpan,
) -> bool {
    event.stream == stream
        && event.kind == HotkeyTraceEventKind::RootCommand
        && event.event_ordinal == span.command_event_ordinal
        && event.visibility_revision == Some(span.visibility_revision)
        && event.invocation_id == span.invocation_id
        && event.request_id == Some(span.request_id)
        && event.elapsed_ms == span.command_elapsed_ms
        && event.command == Some(span.command)
}

fn root_command_span_matches(
    context: HotkeyRootProofContext<'_>,
    stream: HotkeyCandidateStream,
    span: &HotkeyRootCommandSpan,
) -> bool {
    let command_matches = context
        .candidate_events
        .iter()
        .filter(|event| root_command_event_matches_span(event, stream, span))
        .count();
    if command_matches != 1 {
        return false;
    }
    match span.observed_snapshot_event_ordinal {
        Some(ordinal) => {
            let snapshots = context
                .candidate_events
                .iter()
                .filter(|event| {
                    event.stream == stream
                        && event.kind == HotkeyTraceEventKind::NativeWindowSnapshot
                        && event.event_ordinal == ordinal
                        && event.visibility_revision == Some(span.visibility_revision)
                        && event.invocation_id == span.invocation_id
                        && event.request_id == Some(span.request_id)
                        && event.elapsed_ms >= span.command_elapsed_ms
                        && span.command_to_observed_ms
                            == Some(event.elapsed_ms.saturating_sub(span.command_elapsed_ms))
                        && event_root_identity_matches(context, event)
                })
                .count();
            snapshots == 1
                && span.observed_presentation.as_ref().is_some_and(|observed| {
                    observed.elapsed_ms >= span.command_elapsed_ms
                        && observed.command_to_observed_ms
                            == observed.elapsed_ms.saturating_sub(span.command_elapsed_ms)
                })
        }
        None => span.command_to_observed_ms.is_none() && span.observed_presentation.is_none(),
    }
}

fn validate_packet_root_identity(packet: &HotkeyCaseEvidence) -> Result<(), String> {
    if packet.root_identities.is_empty()
        || packet.root_identities.len() > 3
        || packet.physical_displays.is_empty()
        || packet.physical_displays.len() > 32
        || packet
            .physical_displays
            .iter()
            .any(|bounds| bounds[2] <= bounds[0] || bounds[3] <= bounds[1])
    {
        return Err(format!(
            "{} ROOT identity or physical display evidence is missing or invalid",
            packet.case_id
        ));
    }
    for (index, identity) in packet.root_identities.iter().enumerate() {
        if identity.hwnd == 0
            || identity.process_id == 0
            || packet.root_identities[..index]
                .iter()
                .any(|prior| prior.stream == identity.stream)
        {
            return Err(format!(
                "{} captured ROOT identity is invalid or duplicated",
                packet.case_id
            ));
        }
    }
    for event in packet
        .candidate_events
        .iter()
        .filter(|event| event.kind == HotkeyTraceEventKind::NativeWindowSnapshot)
    {
        if event.hwnd.is_none()
            || event.process_id.is_none()
            || event.visible.is_none()
            || event.minimized.is_none()
            || event.bounds.is_none()
            || !event_root_identity_matches(packet.into(), event)
        {
            return Err(format!(
                "{} qualifying native ROOT snapshot has incomplete or stale HWND/PID evidence",
                packet.case_id
            ));
        }
    }
    Ok(())
}

fn event_root_identity_matches(
    context: HotkeyRootProofContext<'_>,
    event: &HotkeyCandidateEventEvidence,
) -> bool {
    let Some(hwnd) = event.hwnd else {
        return false;
    };
    let Some(process_id) = event.process_id else {
        return false;
    };
    context.root_identities.iter().any(|identity| {
        identity.stream == event.stream
            && identity.hwnd == hwnd
            && identity.process_id == process_id
    })
}

fn presentation_matches(
    context: HotkeyRootProofContext<'_>,
    stream: HotkeyCandidateStream,
    span: &HotkeyRootCommandSpan,
    observed: &HotkeyObservedPresentation,
    expected_visible: bool,
) -> bool {
    let Some(event) = context.candidate_events.iter().find(|event| {
        event.stream == stream
            && event.kind == HotkeyTraceEventKind::NativeWindowSnapshot
            && event.visibility_revision == Some(span.visibility_revision)
            && event.invocation_id == span.invocation_id
            && event.request_id == Some(span.request_id)
            && event.elapsed_ms == observed.elapsed_ms
    }) else {
        return false;
    };
    if !root_command_span_matches(context, stream, span)
        || !event_root_identity_matches(context, event)
    {
        return false;
    }
    let Some(bounds) = event.bounds else {
        return false;
    };
    let on_physical_display = context.physical_displays.iter().any(|display| {
        bounds[0] < display[2]
            && bounds[2] > display[0]
            && bounds[1] < display[3]
            && bounds[3] > display[1]
    });
    let physically_shown =
        event.visible == Some(true) && event.minimized == Some(false) && on_physical_display;
    physically_shown == expected_visible
}

fn native_activation_span_matches(
    context: HotkeyRootProofContext<'_>,
    stream: HotkeyCandidateStream,
    restore: &HotkeyFollowOnRestoreEvidence,
    span: &HotkeyNativeActivationSpan,
) -> bool {
    let Some(identity) = context
        .root_identities
        .iter()
        .find(|identity| identity.stream == stream)
    else {
        return false;
    };
    identity.hwnd == span.hwnd
        && span.request_id > 0
        && span.terminal_edge == Some(HotkeyActivationEdge::RestoreCompleted)
        && span
            .terminal_elapsed_ms
            .is_some_and(|terminal| terminal >= span.requested_elapsed_ms)
        && context.candidate_events.iter().any(|event| {
            event.stream == stream
                && event.kind == HotkeyTraceEventKind::NativeActivation
                && event.activation_edge == Some(HotkeyActivationEdge::RestoreRequested)
                && event.request_id == Some(span.request_id)
                && event.hwnd == Some(span.hwnd)
                && event.visibility_revision == Some(restore.visibility_revision)
                && event.invocation_id == restore.invocation_id
                && event.elapsed_ms == span.requested_elapsed_ms
                && event.elapsed_ms >= restore.intent_elapsed_ms
        })
        && context.candidate_events.iter().any(|event| {
            event.stream == stream
                && event.kind == HotkeyTraceEventKind::NativeActivation
                && event.activation_edge == Some(HotkeyActivationEdge::RestoreCompleted)
                && event.terminal == Some(true)
                && event.request_id == Some(span.request_id)
                && event.hwnd == Some(span.hwnd)
                && event.visibility_revision == Some(restore.visibility_revision)
                && event.invocation_id == restore.invocation_id
                && event.elapsed_ms == span.terminal_elapsed_ms.unwrap_or_default()
        })
}

fn configured_chord_edges(hotkey: AcceptanceHotkey, repeats: usize) -> Vec<(u32, bool)> {
    let per_gesture: &[(u32, bool)] = match hotkey {
        AcceptanceHotkey::F11 => &[(0x7A, true), (0x7A, false)],
        AcceptanceHotkey::ShiftAltWinEnd => &[
            (0xA0, true),
            (0xA4, true),
            (0x5B, true),
            (0x23, true),
            (0x23, false),
            (0x5B, false),
            (0xA4, false),
            (0xA0, false),
        ],
    };
    per_gesture
        .iter()
        .copied()
        .cycle()
        .take(per_gesture.len() * repeats)
        .collect()
}

fn opposite_hotkey(hotkey: AcceptanceHotkey) -> AcceptanceHotkey {
    match hotkey {
        AcceptanceHotkey::F11 => AcceptanceHotkey::ShiftAltWinEnd,
        AcceptanceHotkey::ShiftAltWinEnd => AcceptanceHotkey::F11,
    }
}

fn is_legacy_trigger_without_reducer_id(proof: &HotkeyDecisionProof) -> bool {
    matches!(
        proof,
        HotkeyDecisionProof::NotApplicable {
            reason: HotkeyEvidenceNotApplicable::LegacyTriggerHasNoInvocationReducerId
        }
    )
}

fn is_h16_legacy_trigger_pair_group(
    packet: &HotkeyCaseEvidence,
    stream: HotkeyCandidateStream,
    group_id: u32,
    purpose: HotkeyRunnerInputPurpose,
) -> bool {
    if packet.case_id != "H16"
        || stream != HotkeyCandidateStream::LegacyFallbackCandidate
        || purpose != HotkeyRunnerInputPurpose::LauncherChord
    {
        return false;
    }

    let paired_gestures = packet
        .gestures
        .iter()
        .filter(|gesture| {
            gesture.stream == stream
                && gesture.input_group_id == group_id
                && gesture.input_purpose == purpose
                && gesture.short_tap_elapsed_ms.is_none()
                && is_legacy_trigger_without_reducer_id(&gesture.decision)
        })
        .count();
    let standalone_legacy_triggers = packet
        .standalone_decisions
        .iter()
        .filter(|decision| {
            decision.stream == stream
                && decision.input_group_id == group_id
                && decision.input_purpose == purpose
                && decision.invocation_id.is_none()
                && decision.source == HotkeyVisibilitySource::LegacyTrigger
                && is_legacy_trigger_without_reducer_id(&decision.decision)
        })
        .count();

    paired_gestures == 1 && standalone_legacy_triggers == 1
}

fn h16_legacy_modifier_mismatch_is_valid(
    packet: &HotkeyCaseEvidence,
    press: &HotkeyCandidateEventEvidence,
) -> bool {
    let Some(invocation_id) = press.invocation_id else {
        return false;
    };
    let release = packet.candidate_events.iter().find(|event| {
        event.kind == HotkeyTraceEventKind::PrimaryRelease
            && event.stream == press.stream
            && event.input_group_id == press.input_group_id
            && event.input_purpose == press.input_purpose
            && event.invocation_id == Some(invocation_id)
    });
    let Some(release) = release else {
        return false;
    };
    is_h16_legacy_trigger_pair_group(
        packet,
        press.stream,
        press.input_group_id,
        press.input_purpose,
    ) && h16_legacy_candidate_group_has_exact_complex_chord(
        &packet.case_id,
        &packet.candidate_events,
        &packet.runner_edges,
        press,
        release,
    )
}

fn h16_legacy_candidate_group_has_exact_complex_chord(
    case_id: &str,
    events: &[HotkeyCandidateEventEvidence],
    runner_edges: &[HotkeyRunnerEdgeEvidence],
    press: &HotkeyCandidateEventEvidence,
    release: &HotkeyCandidateEventEvidence,
) -> bool {
    let Some(invocation_id) = press.invocation_id else {
        return false;
    };
    if case_id != "H16"
        || press.stream != HotkeyCandidateStream::LegacyFallbackCandidate
        || press.input_purpose != HotkeyRunnerInputPurpose::LauncherChord
        || press.kind != HotkeyTraceEventKind::PrimaryPress
        || press.modifiers_match != Some(false)
        || press.provenance != Some(HotkeyInputProvenance::ExternalInjected)
        || release.kind != HotkeyTraceEventKind::PrimaryRelease
        || release.stream != press.stream
        || release.input_group_id != press.input_group_id
        || release.input_purpose != press.input_purpose
        || release.invocation_id != Some(invocation_id)
        || release.modifiers_match != Some(false)
        || release.provenance != Some(HotkeyInputProvenance::ExternalInjected)
    {
        return false;
    }

    let group_events = events
        .iter()
        .filter(|event| {
            event.stream == press.stream
                && event.input_group_id == press.input_group_id
                && event.input_purpose == press.input_purpose
        })
        .collect::<Vec<_>>();
    let presses = group_events
        .iter()
        .filter(|event| event.kind == HotkeyTraceEventKind::PrimaryPress)
        .collect::<Vec<_>>();
    let releases = group_events
        .iter()
        .filter(|event| event.kind == HotkeyTraceEventKind::PrimaryRelease)
        .collect::<Vec<_>>();
    let legacy_intents = group_events
        .iter()
        .filter(|event| {
            event.kind == HotkeyTraceEventKind::VisibilityIntent
                && event.visibility_source == Some(HotkeyVisibilitySource::LegacyTrigger)
                && event.invocation_id.is_none()
        })
        .collect::<Vec<_>>();
    if presses.len() != 1
        || releases.len() != 1
        || presses[0].invocation_id != Some(invocation_id)
        || releases[0].invocation_id != Some(invocation_id)
        || legacy_intents.len() != 1
        || legacy_intents[0].elapsed_ms < press.elapsed_ms
        || legacy_intents[0].event_ordinal <= press.event_ordinal
        || group_events.iter().any(|event| {
            (event.kind == HotkeyTraceEventKind::ShortTap
                && event.invocation_id == Some(invocation_id))
                || (event.kind == HotkeyTraceEventKind::VisibilityIntent
                    && event.visibility_source == Some(HotkeyVisibilitySource::ToggleBatch))
        })
    {
        return false;
    }

    let tagged_edges = runner_edges
        .iter()
        .filter(|edge| {
            edge.stream == press.stream
                && edge.input_group_id == press.input_group_id
                && edge.purpose == press.input_purpose
        })
        .collect::<Vec<_>>();
    if tagged_edges
        .iter()
        .any(|edge| edge.runner_cookie_matched && !edge.injected)
    {
        return false;
    }
    let tagged = tagged_edges
        .iter()
        .filter(|edge| edge.injected && edge.runner_cookie_matched)
        .map(|edge| {
            (
                edge.virtual_key,
                edge.transition == HotkeyEdgeTransition::Press,
            )
        })
        .collect::<Vec<_>>();
    tagged == configured_chord_edges(AcceptanceHotkey::ShiftAltWinEnd, 1)
}

fn validate_runner_edge_groups(
    packet: &HotkeyCaseEvidence,
    configured_hotkey: AcceptanceHotkey,
    hold_threshold_ms: u64,
) -> Result<(), String> {
    use std::collections::BTreeMap;

    let mut groups = BTreeMap::<
        (HotkeyCandidateStream, u32, HotkeyRunnerInputPurpose),
        Vec<&HotkeyRunnerEdgeEvidence>,
    >::new();
    for edge in &packet.runner_edges {
        groups
            .entry((edge.stream, edge.input_group_id, edge.purpose))
            .or_default()
            .push(edge);
    }
    if groups.is_empty() {
        return Err(format!(
            "{} has no runner input edge groups",
            packet.case_id
        ));
    }
    for ((stream, group_id, purpose), edges) in groups.iter_mut() {
        edges.sort_by_key(|edge| edge.runner_relative_us);
        let expected_repeats = if *purpose == HotkeyRunnerInputPurpose::DirectTrigger {
            1
        } else {
            let gesture_count = packet
                .gestures
                .iter()
                .filter(|gesture| {
                    gesture.stream == *stream
                        && gesture.input_group_id == *group_id
                        && gesture.input_purpose == *purpose
                })
                .count();
            let standalone_count = packet
                .standalone_decisions
                .iter()
                .filter(|decision| {
                    decision.stream == *stream
                        && decision.input_group_id == *group_id
                        && decision.input_purpose == *purpose
                })
                .count();
            gesture_count + standalone_count
                - usize::from(is_h16_legacy_trigger_pair_group(
                    packet, *stream, *group_id, *purpose,
                ))
        };
        let tagged = edges
            .iter()
            .filter(|edge| edge.injected && edge.runner_cookie_matched)
            .map(|edge| {
                (
                    edge.virtual_key,
                    edge.transition == HotkeyEdgeTransition::Press,
                )
            })
            .collect::<Vec<_>>();
        let group_hotkey = match (*stream, packet.case_id.as_str()) {
            (HotkeyCandidateStream::AlternateProfileCandidate, "H17")
            | (HotkeyCandidateStream::LegacyFallbackCandidate, "H16") => {
                opposite_hotkey(configured_hotkey)
            }
            _ => configured_hotkey,
        };
        let expected = if *purpose == HotkeyRunnerInputPurpose::DirectTrigger {
            let key = if *stream == HotkeyCandidateStream::LegacyFallbackCandidate {
                0x59
            } else {
                0x54
            };
            vec![
                (0xA2, true),
                (0xA4, true),
                (key, true),
                (key, false),
                (0xA4, false),
                (0xA2, false),
            ]
        } else {
            configured_chord_edges(group_hotkey, expected_repeats)
        };
        if expected_repeats == 0 || tagged != expected {
            return Err(format!(
                "{} tagged edge group {group_id} ({stream:?}/{purpose:?}) is partial, duplicated, or has the wrong key sequence",
                packet.case_id
            ));
        }
        if edges
            .iter()
            .any(|edge| edge.runner_cookie_matched && !edge.injected)
        {
            return Err(format!(
                "{} runner cookie is present on a non-injected edge",
                packet.case_id
            ));
        }
        if packet.case_id == "H04" && *purpose == HotkeyRunnerInputPurpose::MatrixBurst {
            let tagged_edges = edges
                .iter()
                .copied()
                .filter(|edge| edge.injected && edge.runner_cookie_matched)
                .collect::<Vec<_>>();
            validate_h04_burst_cadence(&tagged_edges, group_hotkey, expected_repeats, *group_id)?;
        }
    }

    for gesture in &packet.gestures {
        let chord = match (gesture.stream, packet.case_id.as_str()) {
            (HotkeyCandidateStream::AlternateProfileCandidate, "H17")
            | (HotkeyCandidateStream::LegacyFallbackCandidate, "H16") => {
                opposite_hotkey(configured_hotkey)
            }
            _ => configured_hotkey,
        };
        let duration_us = tagged_primary_duration_us(
            packet,
            gesture.stream,
            gesture.input_group_id,
            gesture.input_purpose,
            gesture.release_elapsed_ms,
            chord,
        );
        let Some(duration_us) = duration_us else {
            return Err(format!(
                "{} gesture has no complete tagged primary key down/up pair",
                packet.case_id
            ));
        };
        let threshold_us = hold_threshold_ms.saturating_mul(1_000);
        if gesture.short_tap_elapsed_ms.is_some() && duration_us >= threshold_us {
            return Err(format!(
                "{} short tap exceeded the configured hold threshold",
                packet.case_id
            ));
        }
        if gesture.short_tap_elapsed_ms.is_none() && duration_us < threshold_us {
            let paired_legacy_trigger =
                is_h16_legacy_trigger_pair_group(
                    packet,
                    gesture.stream,
                    gesture.input_group_id,
                    gesture.input_purpose,
                ) && is_legacy_trigger_without_reducer_id(&gesture.decision);
            if !paired_legacy_trigger {
                return Err(format!(
                    "{} no-tap gesture lacks a tagged hold at the configured threshold",
                    packet.case_id
                ));
            }
        }
    }
    Ok(())
}

fn validate_h04_burst_cadence(
    edges: &[&HotkeyRunnerEdgeEvidence],
    hotkey: AcceptanceHotkey,
    taps: usize,
    group_id: u32,
) -> Result<(), String> {
    let edges_per_tap = match hotkey {
        AcceptanceHotkey::F11 => 2,
        AcceptanceHotkey::ShiftAltWinEnd => 8,
    };
    if edges.len() != taps.saturating_mul(edges_per_tap) {
        return Err(format!(
            "H04 matrix burst group {group_id} has incomplete tagged cadence edges"
        ));
    }
    let primary_down_index = match hotkey {
        AcceptanceHotkey::F11 => 0,
        AcceptanceHotkey::ShiftAltWinEnd => 3,
    };
    let mut previous_release_us = None;
    for (tap_index, chunk) in edges.chunks_exact(edges_per_tap).enumerate() {
        let down = chunk[primary_down_index].runner_relative_us;
        let up = chunk[primary_down_index + 1].runner_relative_us;
        let hold_us = up.saturating_sub(down);
        if !(10_000..=100_000).contains(&hold_us) {
            return Err(format!(
                "H04 matrix burst group {group_id} tap {} has an out-of-band hold duration",
                tap_index + 1
            ));
        }
        if let Some(previous_up_us) = previous_release_us {
            let gap_us = down.saturating_sub(previous_up_us);
            if !(10_000..=100_000).contains(&gap_us) {
                return Err(format!(
                    "H04 matrix burst group {group_id} tap {} has an out-of-band released gap",
                    tap_index + 1
                ));
            }
        }
        previous_release_us = Some(up);
    }
    Ok(())
}

fn validate_h04_matrix_foreign_edges(packet: &HotkeyCaseEvidence) -> Result<(), String> {
    use std::collections::BTreeMap;

    let mut groups =
        BTreeMap::<(HotkeyCandidateStream, u32), Vec<&HotkeyRunnerEdgeEvidence>>::new();
    for edge in packet
        .runner_edges
        .iter()
        .filter(|edge| edge.purpose == HotkeyRunnerInputPurpose::MatrixBurst)
    {
        groups
            .entry((edge.stream, edge.input_group_id))
            .or_default()
            .push(edge);
    }
    for ((stream, group_id), edges) in groups {
        let mut ordered_owned = edges
            .iter()
            .copied()
            .filter(|edge| edge.injected && edge.runner_cookie_matched)
            .collect::<Vec<_>>();
        ordered_owned.sort_by_key(|edge| edge.runner_relative_us);
        let spans = owned_gesture_spans(ordered_owned.iter().map(|edge| {
            (
                edge.runner_relative_us,
                edge.virtual_key,
                edge.transition == HotkeyEdgeTransition::Press,
            )
        }));
        let mut foreign_edges = edges
            .iter()
            .copied()
            .filter(|edge| !edge.runner_cookie_matched)
            .collect::<Vec<_>>();
        foreign_edges.sort_by_key(|edge| edge.runner_relative_us);
        let foreign_timeline = foreign_edges
            .iter()
            .map(|edge| {
                (
                    edge.runner_relative_us,
                    edge.virtual_key,
                    edge.transition == HotkeyEdgeTransition::Press,
                )
            })
            .collect::<Vec<_>>();
        if !foreign_edge_indices_interfering_owned_spans(&spans, &foreign_timeline).is_empty() {
            return Err(format!(
                "H04 matrix burst group {group_id} ({stream:?}) contains an interfering foreign matching-key edge"
            ));
        }
    }
    Ok(())
}

fn tagged_primary_duration_us(
    packet: &HotkeyCaseEvidence,
    stream: HotkeyCandidateStream,
    group_id: u32,
    purpose: HotkeyRunnerInputPurpose,
    release_elapsed_ms: u64,
    hotkey: AcceptanceHotkey,
) -> Option<u64> {
    let edges_per_gesture = match hotkey {
        AcceptanceHotkey::F11 => 2,
        AcceptanceHotkey::ShiftAltWinEnd => 8,
    };
    let mut groups = packet
        .gestures
        .iter()
        .filter(|gesture| {
            gesture.stream == stream
                && gesture.input_group_id == group_id
                && gesture.input_purpose == purpose
        })
        .collect::<Vec<_>>();
    groups.sort_by_key(|gesture| gesture.release_elapsed_ms);
    let gesture_index = groups
        .iter()
        .position(|gesture| gesture.release_elapsed_ms == release_elapsed_ms)?;
    let mut edges = packet
        .runner_edges
        .iter()
        .filter(|edge| {
            edge.stream == stream
                && edge.input_group_id == group_id
                && edge.purpose == purpose
                && edge.injected
                && edge.runner_cookie_matched
        })
        .collect::<Vec<_>>();
    edges.sort_by_key(|edge| edge.runner_relative_us);
    let base = gesture_index.checked_mul(edges_per_gesture)?;
    let offset = match hotkey {
        AcceptanceHotkey::F11 => 0,
        AcceptanceHotkey::ShiftAltWinEnd => 3,
    };
    let down = *edges.get(base.checked_add(offset)?)?;
    let up = *edges.get(base.checked_add(offset + 1)?)?;
    if down.transition != HotkeyEdgeTransition::Press
        || up.transition != HotkeyEdgeTransition::Release
        || down.virtual_key != up.virtual_key
    {
        return None;
    }
    up.runner_relative_us.checked_sub(down.runner_relative_us)
}

fn gesture_has_tagged_hold(
    packet: &HotkeyCaseEvidence,
    gesture: &HotkeyGestureEvidence,
    hotkey: AcceptanceHotkey,
    threshold_ms: u64,
) -> bool {
    tagged_primary_duration_us(
        packet,
        gesture.stream,
        gesture.input_group_id,
        gesture.input_purpose,
        gesture.release_elapsed_ms,
        hotkey,
    )
    .is_some_and(|duration| duration >= threshold_ms.saturating_mul(1_000))
}

fn hotkey_decision_visible(decision: &HotkeyDecisionProof) -> Option<bool> {
    match decision {
        HotkeyDecisionProof::Applied { visible, .. }
        | HotkeyDecisionProof::Superseded { visible, .. } => Some(*visible),
        HotkeyDecisionProof::NotApplicable { .. } => None,
    }
}

fn validate_hotkey_evidence_report(report: &AcceptanceReport) -> Result<(), String> {
    if let Some(receipt) = &report.report_overflow {
        if !report.capacity_saturated
            || report.outcome != "failed"
            || (receipt.omitted_case_evidence > 0 && !report.hotkey_evidence.is_empty())
            || receipt.reason.is_empty()
            || receipt.affected_case_ids.len() > MAX_HOTKEY_EVIDENCE_CASES
            || receipt.affected_case_ids.iter().any(|id| {
                hotkey_expected_state(id).is_none()
                    || !report
                        .cases
                        .iter()
                        .any(|case| case.id == *id && matches!(case.status, CaseStatus::Failed))
            })
            || !["R0", "CLEANUP"].iter().all(|id| {
                report
                    .cases
                    .iter()
                    .any(|case| case.id == *id && matches!(case.status, CaseStatus::Failed))
            })
        {
            return Err(
                "report overflow receipt does not preserve failed case identity and cleanup".into(),
            );
        }
        if receipt.omitted_case_evidence > 0 {
            return Ok(());
        }
    }
    if report.hotkey_evidence.len() > MAX_HOTKEY_EVIDENCE_CASES {
        return Err("per-case H evidence packet count exceeds its bound".into());
    }
    for (index, packet) in report.hotkey_evidence.iter().enumerate() {
        if report.hotkey_evidence[..index]
            .iter()
            .any(|previous| previous.case_id == packet.case_id)
        {
            return Err(format!(
                "{} has duplicate H evidence packets",
                packet.case_id
            ));
        }
        validate_hotkey_evidence_packet_with_context(
            packet,
            report.hotkey,
            report.profile.hold_threshold_ms,
        )?;
        if !report.cases.iter().any(|case| case.id == packet.case_id) {
            return Err(format!(
                "{} evidence packet has no case result",
                packet.case_id
            ));
        }
    }
    for case in &report.cases {
        if !matches!(case.status, CaseStatus::Passed) || hotkey_expected_state(&case.id).is_none() {
            continue;
        }
        if report
            .hotkey_evidence
            .iter()
            .filter(|packet| packet.case_id == case.id)
            .count()
            != 1
        {
            return Err(format!(
                "{} passed without exactly one H evidence packet",
                case.id
            ));
        }
    }
    if let Some(case) = report
        .cases
        .iter()
        .find(|case| case.id == "H04" && matches!(case.status, CaseStatus::Passed))
    {
        let reported_foreign_edges = observed_field(&case.observed, "foreign_matching_edges=")
            .and_then(|value| value.parse::<usize>().ok())
            .ok_or_else(|| "H04 report omitted its foreign matching-edge count".to_string())?;
        let packet = report
            .hotkey_evidence
            .iter()
            .find(|packet| packet.case_id == "H04")
            .ok_or_else(|| "H04 report omitted its runner-edge packet".to_string())?;
        let captured_foreign_edges = packet
            .runner_edges
            .iter()
            .filter(|edge| {
                edge.purpose == HotkeyRunnerInputPurpose::MatrixBurst && !edge.runner_cookie_matched
            })
            .count();
        if reported_foreign_edges != captured_foreign_edges {
            return Err(format!(
                "H04 foreign matching-edge summary {reported_foreign_edges} disagrees with the {} captured matrix edges",
                captured_foreign_edges
            ));
        }
    }
    if let Some(case) = report.cases.iter().find(|case| case.id == "H04") {
        validate_h04_contamination_artifacts(report, case)?;
    }
    Ok(())
}

fn validate_query_evidence_report(report: &AcceptanceReport) -> Result<(), String> {
    if report.suite != AcceptanceSuite::Query {
        return if report.query_evidence.is_empty() {
            Ok(())
        } else {
            Err("query evidence is present outside the Query suite".into())
        };
    }
    if report.query_evidence.len() > QUERY_CASE_IDS.len() - 2 {
        return Err("Query evidence packet count exceeds its bound".into());
    }
    let mut total_evidence_bytes = 0usize;
    for (index, evidence) in report.query_evidence.iter().enumerate() {
        if report.query_evidence[..index]
            .iter()
            .any(|previous| previous.case_id == evidence.case_id)
        {
            return Err(format!(
                "{} has duplicate Query evidence packets",
                evidence.case_id
            ));
        }
        if !QUERY_CASE_IDS.contains(&evidence.case_id.as_str())
            || matches!(evidence.case_id.as_str(), "CLEANUP" | "R0")
            || evidence.schema_version != 1
            || evidence.invocations.is_empty()
            || evidence.invocations.len() > 2
            || evidence
                .invocations
                .iter()
                .any(|item| !query_invocation_evidence_is_valid(item, report))
            || evidence
                .invocations
                .iter()
                .enumerate()
                .any(|(index, item)| {
                    evidence.invocations[..index].iter().any(|prior| {
                        prior.invocation_id == item.invocation_id
                            || prior.session_digest == item.session_digest
                    })
                })
            || !report.cases.iter().any(|case| case.id == evidence.case_id)
            || evidence.placement.as_ref().is_some_and(|proof| {
                proof.hotkey != report.hotkey
                    || proof.configured_root.process_id
                        != report.environment.child_process_id.unwrap_or(0)
                    || proof.physical_displays
                        != report
                            .environment
                            .monitors
                            .iter()
                            .map(|monitor| {
                                [
                                    monitor.x,
                                    monitor.y,
                                    monitor.x.saturating_add(monitor.width as i32),
                                    monitor.y.saturating_add(monitor.height as i32),
                                ]
                            })
                            .collect::<Vec<_>>()
            })
        {
            return Err(format!(
                "{} Query evidence identity or bounds are invalid",
                evidence.case_id
            ));
        }
        let packet_bytes = serde_json::to_vec(evidence)
            .map_err(|error| {
                format!(
                    "{} Query evidence could not be serialized: {error}",
                    evidence.case_id
                )
            })?
            .len();
        if packet_bytes > MAX_QUERY_CASE_EVIDENCE_BYTES {
            return Err(format!(
                "{} Query evidence packet exceeds its byte bound",
                evidence.case_id
            ));
        }
        total_evidence_bytes = total_evidence_bytes
            .checked_add(packet_bytes)
            .ok_or_else(|| "Query evidence byte count overflowed".to_string())?;
        if total_evidence_bytes > MAX_QUERY_EVIDENCE_BYTES {
            return Err("Query evidence exceeds its aggregate byte bound".into());
        }
        let case = report
            .cases
            .iter()
            .find(|case| case.id == evidence.case_id)
            .unwrap();
        if matches!(case.status, CaseStatus::Passed) {
            query_case_contract_is_valid(evidence)?;
        }
    }
    for case in &report.cases {
        if !matches!(case.status, CaseStatus::Passed)
            || !QUERY_CASE_IDS.contains(&case.id.as_str())
            || matches!(case.id.as_str(), "CLEANUP" | "R0")
        {
            continue;
        }
        if report
            .query_evidence
            .iter()
            .filter(|evidence| evidence.case_id == case.id)
            .count()
            != 1
        {
            return Err(format!(
                "{} passed without exactly one Query evidence packet",
                case.id
            ));
        }
    }
    Ok(())
}

fn validate_gate_c_evidence_report(report: &AcceptanceReport) -> Result<(), String> {
    if report.suite != AcceptanceSuite::GateC {
        return if report.gate_c_evidence.is_empty() {
            Ok(())
        } else {
            Err("Gate C evidence is present outside the Gate C suite".into())
        };
    }
    if let Some(receipt) = &report.report_overflow {
        if report.gate_c_evidence.is_empty() || receipt.omitted_case_evidence > 0 {
            return validate_gate_c_overflow_report(report, receipt);
        }
        if receipt.affected_case_ids.is_empty() {
            return validate_gate_c_retained_evidence_overflow_report(report, receipt);
        }
    }
    if report.gate_c_evidence.len() != GATE_C_REQUIRED_CASES {
        return Err(format!(
            "Gate C requires exactly {GATE_C_REQUIRED_CASES} typed native evidence packets"
        ));
    }

    let mut fixture_digest = None;
    let expected_fixture_digest = gate_c_fixture_digest(&report.profile);
    for (index, packet) in report.gate_c_evidence.iter().enumerate() {
        let case_status = report
            .cases
            .iter()
            .find(|case| case.id == packet.case_id)
            .map(|case| case.status);
        if report.gate_c_evidence[..index]
            .iter()
            .any(|previous| previous.case_id == packet.case_id)
        {
            return Err(format!(
                "{} has duplicate Gate C evidence packets",
                packet.case_id
            ));
        }
        if !GATE_C_CASE_IDS.contains(&packet.case_id.as_str())
            || matches!(packet.case_id.as_str(), "CLEANUP" | "R0")
            || packet.schema_version != 1
            || !is_sha256(&packet.fixture_digest)
            || packet.fixture_digest != expected_fixture_digest
            || fixture_digest
                .replace(packet.fixture_digest.as_str())
                .is_some_and(|previous| previous != packet.fixture_digest)
            || !gate_c_case_collection_bounds_are_valid(packet)
            || packet.editor_identity.as_ref().is_some_and(|identity| {
                !gate_c_editor_identity_is_valid(identity)
                    || identity.session_id != packet.session_id
                    || identity.draft_generation != packet.draft_generation
                    || packet.editor_surface != Some(identity.surface)
            })
            || packet.controls.iter().any(|control| {
                !gate_c_control_is_valid(control)
                    || !gate_c_control_identity_is_observed(control, packet, case_status)
                    || !gate_c_control_binding_is_correlated(control, packet)
            })
            || packet
                .inspector_text_edits
                .iter()
                .any(|edit| !gate_c_inspector_text_edit_is_valid(edit))
            || packet.ordered_results.iter().any(|row| {
                !gate_c_result_row_is_valid(row) || !gate_c_result_row_is_correlated(row, packet)
            })
            || packet
                .searches
                .iter()
                .any(|search| !gate_c_search_is_valid(search, packet))
            || packet.incomplete_searches.iter().any(|search| {
                !matches!(case_status, Some(CaseStatus::Failed))
                    || !gate_c_incomplete_search_is_valid(search, packet)
            })
            || !gate_c_result_rows_are_unique(&packet.ordered_results)
            || packet.provider_lifecycle.iter().any(|event| {
                event.trace_sequence == 0
                    || !gate_c_editor_identity_is_valid(&event.identity)
                    || !gate_c_provider_identity_is_observed(event, packet)
                    || event.query_digest == 0
                    || event.query_digest != event.identity.query_digest
                    || (event.kind == GateCProviderKind::Search && event.binding_digest != 0)
                    || (event.kind == GateCProviderKind::Test && event.binding_digest == 0)
            })
            || packet
                .authoring_states
                .iter()
                .any(|state| !gate_c_authoring_state_is_valid(state))
            || packet.q14_partial.as_ref().is_some_and(|partial| {
                !matches!(case_status, Some(CaseStatus::Failed))
                    || packet.q14.is_some()
                    || !gate_c_q14_partial_is_valid(packet, partial)
            })
            || (packet.case_id != "Q14" && packet.q14_partial.is_some())
            || !gate_c_observation_boundaries_are_valid(packet)
            || packet.bindings.iter().any(|binding| {
                !gate_c_binding_is_valid(binding)
                    || (packet.case_id == "D04"
                        && matches!(case_status, Some(CaseStatus::Failed))
                        && !gate_c_binding_control_links_are_valid(binding, packet, true))
            })
            || packet
                .insertions
                .iter()
                .any(|insertion| !gate_c_insertion_is_valid(insertion))
            || packet.screenshot_artifacts.iter().any(|artifact| {
                artifact.is_empty()
                    || artifact.len() > MAX_PATH_BYTES
                    || !report.artifacts.iter().any(|reported| reported == artifact)
            })
            || !report.cases.iter().any(|case| case.id == packet.case_id)
        {
            return Err(format!(
                "{} Gate C evidence identity or bounds are invalid",
                packet.case_id
            ));
        }
        gate_c_packet_wire_bytes(packet)?;
        let case = report
            .cases
            .iter()
            .find(|case| case.id == packet.case_id)
            .expect("packet case existence was checked above");
        if matches!(case.status, CaseStatus::Passed) {
            gate_c_case_contract_is_valid(packet)?;
        }
    }
    let aggregate_bytes = serde_json::to_vec(&report.gate_c_evidence)
        .map_err(|error| format!("Gate C evidence serialization failed: {error}"))?
        .len();
    if aggregate_bytes > MAX_GATE_C_EVIDENCE_BYTES {
        return Err(format!(
            "Gate C evidence exceeds its aggregate byte bound ({aggregate_bytes} > {MAX_GATE_C_EVIDENCE_BYTES})"
        ));
    }
    for id in GATE_C_CASE_IDS
        .iter()
        .filter(|id| !matches!(**id, "CLEANUP" | "R0"))
    {
        if !report
            .gate_c_evidence
            .iter()
            .any(|packet| packet.case_id == *id)
        {
            return Err(format!("{id} is missing its Gate C evidence packet"));
        }
    }
    for case in report.cases.iter().filter(|case| {
        matches!(case.status, CaseStatus::Passed)
            && GATE_C_CASE_IDS.contains(&case.id.as_str())
            && !matches!(case.id.as_str(), "CLEANUP" | "R0")
    }) {
        if report
            .gate_c_evidence
            .iter()
            .filter(|packet| packet.case_id == case.id)
            .count()
            != 1
        {
            return Err(format!(
                "{} passed without exactly one Gate C evidence packet",
                case.id
            ));
        }
    }
    Ok(())
}

fn validate_gate_c_overflow_report(
    report: &AcceptanceReport,
    receipt: &ReportOverflowReceipt,
) -> Result<(), String> {
    let affected_case_ids = GATE_C_CASE_IDS
        .iter()
        .filter(|id| !matches!(**id, "CLEANUP" | "R0"))
        .map(|id| (*id).to_owned())
        .collect::<Vec<_>>();
    let all_case_ids_are_retained = report.cases.len() == GATE_C_CASE_IDS.len()
        && GATE_C_CASE_IDS
            .iter()
            .all(|id| report.cases.iter().filter(|case| case.id == *id).count() == 1);
    let all_affected_cases_failed = affected_case_ids.iter().all(|id| {
        report.cases.iter().any(|case| {
            case.id == *id
                && matches!(case.status, CaseStatus::Failed)
                && case.failure_stage.is_some()
        })
    });
    if !report.capacity_saturated
        || report.outcome != "failed"
        || !report.gate_c_evidence.is_empty()
        || receipt.omitted_case_evidence != GATE_C_REQUIRED_CASES
        || receipt.reason.is_empty()
        || receipt.affected_case_ids != affected_case_ids
        || !all_case_ids_are_retained
        || !all_affected_cases_failed
        || !["CLEANUP", "R0"].iter().all(|id| {
            report.cases.iter().any(|case| {
                case.id == *id
                    && matches!(case.status, CaseStatus::Failed)
                    && case.failure_stage.is_some()
            })
        })
    {
        return Err(
            "Gate C evidence overflow did not preserve failed case identity and cleanup".into(),
        );
    }
    Ok(())
}

fn validate_gate_c_retained_evidence_overflow_report(
    report: &AcceptanceReport,
    receipt: &ReportOverflowReceipt,
) -> Result<(), String> {
    let case_ids_are_retained = report.cases.len() == GATE_C_CASE_IDS.len()
        && GATE_C_CASE_IDS
            .iter()
            .all(|id| report.cases.iter().filter(|case| case.id == *id).count() == 1);
    let evidence_ids_are_retained = report.gate_c_evidence.len() == GATE_C_REQUIRED_CASES
        && GATE_C_CASE_IDS
            .iter()
            .filter(|id| !matches!(**id, "CLEANUP" | "R0"))
            .all(|id| {
                report
                    .gate_c_evidence
                    .iter()
                    .filter(|packet| packet.case_id == *id)
                    .count()
                    == 1
            });
    let overflow_case_is_failed = |id: &str| {
        report.cases.iter().any(|case| {
            case.id == id
                && matches!(case.status, CaseStatus::Failed)
                && matches!(case.failure_stage, Some(FailureStage::Environment))
                && case.observed == PERSISTENCE_OVERFLOW_CASE_OBSERVED
        })
    };
    if !report.capacity_saturated
        || report.outcome != "failed"
        || receipt.omitted_case_evidence != 0
        || receipt.omitted_artifact_references > MAX_ARTIFACTS * (MAX_CASES + 1)
        || !receipt.affected_case_ids.is_empty()
        || receipt.reason != GATE_C_METADATA_OVERFLOW_REASON
        || !case_ids_are_retained
        || !evidence_ids_are_retained
        || !overflow_case_is_failed("CLEANUP")
        || !overflow_case_is_failed("R0")
        || !report.artifacts.is_empty()
        || report.cases.iter().any(|case| !case.artifacts.is_empty())
    {
        return Err(
            "Gate C metadata overflow did not retain its typed case evidence and cleanup".into(),
        );
    }
    for packet in &report.gate_c_evidence {
        gate_c_packet_wire_bytes(packet)?;
    }
    Ok(())
}

fn gate_c_packet_wire_bytes(packet: &GateCCaseEvidence) -> Result<usize, String> {
    let bytes = serde_json::to_vec(packet)
        .map_err(|error| {
            format!(
                "{} Gate C evidence serialization failed: {error}",
                packet.case_id
            )
        })?
        .len();
    if bytes > MAX_GATE_C_CASE_EVIDENCE_BYTES {
        return Err(format!(
            "{} Gate C evidence exceeds its per-case byte bound",
            packet.case_id
        ));
    }
    Ok(bytes)
}

fn gate_d_fixture_digest(profile: &ProfileIdentity) -> String {
    sha256_bytes(
        format!(
            "gate-d-fixture-v1\0{}\0{}\0{}",
            profile.settings_sha256, profile.radial_sha256, profile.actions_sha256,
        )
        .as_bytes(),
    )
}

fn validate_gate_d_evidence_report(report: &AcceptanceReport) -> Result<(), String> {
    if report.suite != AcceptanceSuite::GateD {
        return if report.gate_d_evidence.is_empty() {
            Ok(())
        } else {
            Err("Gate D evidence is present outside the Gate D suite".into())
        };
    }
    if report.gate_d_evidence.len() != GATE_D_REQUIRED_CASES {
        return Err(format!(
            "Gate D requires exactly {GATE_D_REQUIRED_CASES} typed evidence packets"
        ));
    }
    let expected_fixture_digest = gate_d_fixture_digest(&report.profile);
    let mut aggregate_bytes = 0usize;
    for (index, packet) in report.gate_d_evidence.iter().enumerate() {
        if packet.case_id != GATE_D_REQUIRED_CASE_IDS[index]
            || packet.schema_version != 2
            || packet.fixture_digest != expected_fixture_digest
            || !GATE_D_REQUIRED_CASE_IDS.contains(&packet.case_id.as_str())
            || packet.steps.len() > MAX_GATE_D_STEPS_PER_CASE
        {
            return Err(format!(
                "{} Gate D evidence has a mismatched identity or exceeds its typed bounds",
                packet.case_id
            ));
        }
        let bytes = serde_json::to_vec(packet)
            .map_err(|error| {
                format!(
                    "{} Gate D evidence serialization failed: {error}",
                    packet.case_id
                )
            })?
            .len();
        if bytes > MAX_GATE_D_CASE_EVIDENCE_BYTES {
            return Err(format!(
                "{} Gate D evidence exceeds its {}-byte case bound",
                packet.case_id, MAX_GATE_D_CASE_EVIDENCE_BYTES
            ));
        }
        aggregate_bytes = aggregate_bytes.saturating_add(bytes);
        let case_status = report
            .cases
            .iter()
            .find(|case| case.id == packet.case_id)
            .map(|case| case.status);
        if matches!(case_status, Some(CaseStatus::Passed))
            && (!gate_d_case_contract_is_valid(packet)
                || packet
                    .hotkey_proof
                    .as_ref()
                    .is_some_and(|proof| proof.configured_hotkey != report.hotkey))
        {
            return Err(format!(
                "{} passed without satisfying its Gate D owner and input evidence contract",
                packet.case_id
            ));
        }
    }
    if aggregate_bytes > MAX_GATE_D_EVIDENCE_BYTES {
        return Err(format!(
            "Gate D evidence exceeds its {}-byte aggregate bound",
            MAX_GATE_D_EVIDENCE_BYTES
        ));
    }
    Ok(())
}

fn gate_d_case_contract_is_valid(packet: &GateDCaseEvidence) -> bool {
    if packet.schema_version != 2
        || packet
            .no_action_proof
            .as_ref()
            .is_none_or(|proof| !gate_d_no_action_proof_is_valid(proof))
        || packet.steps.first().is_none_or(|first| {
            packet.steps.iter().any(|step| {
                step.before.session_id != first.before.session_id
                    || step.after.session_id != first.before.session_id
            })
        })
    {
        return false;
    }
    match packet.case_id.as_str() {
        "D10" => {
            let [plain, toggle, range] = packet.steps.as_slice() else {
                return false;
            };
            let Some(proof) = packet.selection_proof.as_ref() else {
                return false;
            };
            let controls = [
                plain.control.as_ref(),
                toggle.control.as_ref(),
                range.control.as_ref(),
            ];
            let target_ids = proof.clicked_target_digests.as_slice();
            [plain, toggle, range].iter().all(|step| {
                step.result == GateDStepResult::Applied
                    && gate_d_step_input_is_valid(step)
                    && gate_d_same_document_state(&step.before, &step.after)
            }) && plain.operation == GateDOperation::SelectPrimary
                && toggle.operation == GateDOperation::ToggleMember
                && range.operation == GateDOperation::ExtendRange
                && proof.one_menu_digest > 0
                && target_ids.len() == 3
                && target_ids.iter().all(|digest| *digest > 0)
                && proof.inclusive_range_target_digests.len() >= 2
                && proof
                    .inclusive_range_target_digests
                    .iter()
                    .all(|digest| *digest > 0)
                && gate_d_digest_list_is_unique(&proof.inclusive_range_target_digests)
                && proof.inclusive_range_target_digests.first() == target_ids.first()
                && proof.inclusive_range_target_digests.last() == target_ids.last()
                && proof
                    .inclusive_range_target_digests
                    .contains(&target_ids[1])
                && controls.iter().enumerate().all(|(index, control)| {
                    control.is_some_and(|control| {
                        control.target == GateDControlTarget::CanvasCell
                            && control.menu_id_digest == Some(proof.one_menu_digest)
                            && control.authored_target_digest == Some(target_ids[index])
                            && control.ring_index == Some([0, 0, 1][index])
                            && control.slot_index == Some([0, 1, 0][index])
                            && control
                                .menu_cell_ids_digest
                                .is_some_and(|digest| digest > 0)
                            && control.menu_cell_ids_digest
                                == controls[0].and_then(|first| first.menu_cell_ids_digest)
                    })
                })
                && proof.clicked_target_digests
                    == controls
                        .iter()
                        .map(|control| {
                            control
                                .and_then(|control| control.authored_target_digest)
                                .unwrap_or(0)
                        })
                        .collect::<Vec<_>>()
                && toggle.pointer.as_ref().is_some_and(|pointer| {
                    pointer.modifier == Some(GateDModifier::Control)
                        && pointer.button == GateDPointerButton::Primary
                })
                && plain.pointer.as_ref().is_some_and(|pointer| {
                    pointer.modifier.is_none() && pointer.button == GateDPointerButton::Primary
                })
                && toggle
                    .pointer
                    .as_ref()
                    .is_some_and(|pointer| pointer.modifier == Some(GateDModifier::Control))
                && range.pointer.as_ref().is_some_and(|pointer| {
                    pointer.modifier == Some(GateDModifier::Shift)
                        && pointer.button == GateDPointerButton::Primary
                })
                && plain.after.selected_member_count == 1
                && plain.after.selected_member_target_digests == [target_ids[0]]
                && plain.after.primary_target_digest == target_ids[0]
                && plain.after.range_anchor_target_digest == target_ids[0]
                && toggle.after.selected_member_count == 2
                && toggle.after.selected_member_target_digests == target_ids[..2]
                && toggle.after.primary_target_digest == target_ids[0]
                && toggle.after.range_anchor_target_digest == target_ids[0]
                && range.after.selected_member_count == proof.inclusive_range_target_digests.len()
                && range.after.selected_member_target_digests
                    == proof.inclusive_range_target_digests
                && range.after.primary_target_digest == target_ids[2]
                && range.after.range_anchor_target_digest == target_ids[0]
                && plain.after.session_id == toggle.after.session_id
                && toggle.after.session_id == range.after.session_id
                && plain.after.document_digest == toggle.after.document_digest
                && toggle.after.document_digest == range.after.document_digest
                && plain.after.generation == toggle.after.generation
                && toggle.after.generation == range.after.generation
                && gate_d_same_owner_effects(&plain.after, &toggle.after)
                && gate_d_same_owner_effects(&toggle.after, &range.after)
        }
        "D11" => {
            let [apply, undo, redo] = packet.steps.as_slice() else {
                return false;
            };
            let Some(proof) = packet.bulk_label_proof.as_ref() else {
                return false;
            };
            apply.operation == GateDOperation::SetLabel
                && undo.operation == GateDOperation::Undo
                && redo.operation == GateDOperation::Redo
                && [apply, undo, redo].iter().all(|step| {
                    step.result == GateDStepResult::Applied
                        && gate_d_step_input_is_valid(step)
                        && step.before.pending_assets_digest == apply.before.pending_assets_digest
                        && step.after.pending_assets_digest == apply.before.pending_assets_digest
                })
                && apply
                    .control
                    .as_ref()
                    .is_some_and(|control| control.target == GateDControlTarget::BulkSetLabel)
                && apply
                    .related_control
                    .as_ref()
                    .is_some_and(|control| control.target == GateDControlTarget::BulkLabel)
                && proof.target_digests.len() >= 2
                && gate_d_digest_list_is_unique(&proof.target_digests)
                && proof.target_digests.iter().all(|digest| *digest > 0)
                && proof.label_digest == gate_d_label_digest(GATE_D_BULK_LABEL)
                && proof.expected_before_document_digest == apply.before.document_digest
                && proof.expected_after_document_digest == apply.after.document_digest
                && proof.expected_before_document_digest != proof.expected_after_document_digest
                && apply.before.selected_member_target_digests == proof.target_digests
                && apply.after.selected_member_target_digests == proof.target_digests
                && apply.before.document_digest != apply.after.document_digest
                && apply.after.generation == apply.before.generation.saturating_add(1)
                && apply.after.undo_depth == apply.before.undo_depth.saturating_add(1)
                && apply.after.redo_depth == 0
                && !apply.before.draft_dirty
                && apply.after.draft_dirty
                && !apply.after.properties_popup_open
                && gate_d_same_selection(&apply.before, &apply.after)
                && gate_d_same_owner_effects(&apply.before, &apply.after)
                && gate_d_same_document_state(&apply.after, &undo.before)
                && undo.before.document_digest == proof.expected_after_document_digest
                && undo.after.document_digest == proof.expected_before_document_digest
                && undo.after.generation == undo.before.generation.saturating_add(1)
                && undo.after.undo_depth == apply.before.undo_depth
                && undo.after.redo_depth == apply.before.redo_depth.saturating_add(1)
                && !undo.after.draft_dirty
                && gate_d_same_selection(&apply.before, &undo.after)
                && gate_d_same_owner_effects(&undo.before, &undo.after)
                && gate_d_same_document_state(&undo.after, &redo.before)
                && redo.before.document_digest == proof.expected_before_document_digest
                && redo.after.document_digest == proof.expected_after_document_digest
                && redo.after.generation == redo.before.generation.saturating_add(1)
                && redo.after.undo_depth == apply.after.undo_depth
                && redo.after.redo_depth == apply.before.redo_depth
                && redo.after.draft_dirty
                && gate_d_same_selection(&undo.after, &redo.after)
                && gate_d_same_owner_effects(&redo.before, &redo.after)
                && apply.inserted_key_events >= GATE_D_BULK_LABEL.len()
        }
        "D12" => {
            packet.steps.len() == 3
                && packet.selection_proof.is_none()
                && packet.bulk_label_proof.is_none()
                && packet.navigation_proof.is_none()
                && packet.hotkey_proof.is_none()
                && packet.local_ui_proof.is_none()
                && packet.steps.iter().all(|step| {
                    gate_d_observation_is_well_formed(&step.before, true)
                        && step.before == step.after
                        && step.control.is_none()
                        && step.pointer.is_none()
                        && step.related_control.is_none()
                        && step.related_pointer.is_none()
                        && step.inserted_key_events == 0
                })
                && packet.steps[0].operation == GateDOperation::RejectMissingTarget
                && packet.steps[0].result == GateDStepResult::RejectedMissingTarget
                && packet.steps[1].operation == GateDOperation::RejectStaleGeneration
                && packet.steps[1].result == GateDStepResult::RejectedStaleGeneration
                && packet.steps[2].operation == GateDOperation::RejectPolicyIncompatible
                && packet.steps[2].result == GateDStepResult::RejectedPolicyIncompatible
        }
        "D13" => {
            let Some(proof) = packet.navigation_proof.as_ref() else {
                return false;
            };
            if packet.steps.len() != 9
                || proof.breadcrumbs_after_steps.len() != 9
                || proof.root_menu_digest == 0
                || proof.shared_child_menu_digest == 0
                || proof.second_parent_menu_digest == 0
                || proof.direct_child_link_target_digest == 0
                || proof.second_parent_link_target_digest == 0
                || proof.nested_child_link_target_digest == 0
                || proof.direct_child_edge_digest == 0
                || proof.second_parent_edge_digest == 0
                || proof.nested_child_edge_digest == 0
                || proof.search_query_digest != gate_d_label_digest(GATE_D_LONG_LABEL)
                || proof.search_target_ring_digest == 0
                || proof.search_target_cell_digest == 0
                || proof.search_target_digest == 0
                || !gate_d_digest_list_is_unique(&[
                    proof.root_menu_digest,
                    proof.shared_child_menu_digest,
                    proof.second_parent_menu_digest,
                ])
            {
                return false;
            }
            let root = proof.root_menu_digest;
            let shared = proof.shared_child_menu_digest;
            let parent = proof.second_parent_menu_digest;
            let paths = [
                vec![root, shared],
                vec![root],
                vec![root, parent],
                vec![root, parent, shared],
                vec![root, parent],
                vec![root],
                vec![root],
                vec![shared],
                vec![root],
            ];
            let edge_paths = [
                vec![proof.direct_child_edge_digest],
                vec![],
                vec![proof.second_parent_edge_digest],
                vec![
                    proof.second_parent_edge_digest,
                    proof.nested_child_edge_digest,
                ],
                vec![proof.second_parent_edge_digest],
                vec![],
                vec![],
                vec![],
                vec![],
            ];
            let target_by_step = [
                Some(proof.direct_child_link_target_digest),
                None,
                Some(proof.second_parent_link_target_digest),
                Some(proof.nested_child_link_target_digest),
                None,
                None,
                None,
                Some(proof.search_target_digest),
                None,
            ];
            packet.steps.iter().enumerate().all(|(index, step)| {
                let entering = matches!(index, 0 | 2 | 3);
                let current_path = if index == 0 {
                    vec![root]
                } else {
                    paths[index - 1].clone()
                };
                let current_edges = if index == 0 {
                    Vec::new()
                } else {
                    edge_paths[index - 1].clone()
                };
                let input_valid = step.result == GateDStepResult::Applied
                    && gate_d_step_input_is_valid(step)
                    && gate_d_same_document_state(&step.before, &step.after)
                    && step.before.navigation_menu_id_digests == current_path
                    && step.before.navigation_edge_digests == current_edges
                    && step.after.navigation_menu_id_digests == paths[index]
                    && step.after.navigation_edge_digests == edge_paths[index]
                    && step.after.navigation_path_digest > 0
                    && gate_d_breadcrumb_path_is_valid(
                        &proof.breadcrumbs_after_steps[index],
                        &paths[index],
                    );
                if !input_valid {
                    return false;
                }
                if entering {
                    step.operation == GateDOperation::EnterSubmenu
                        && step.control.as_ref().is_some_and(|control| {
                            control.target == GateDControlTarget::CanvasCell
                                && control.authored_target_digest == target_by_step[index]
                                && control.menu_id_digest
                                    == Some(if index == 3 { parent } else { root })
                        })
                        && step.pointer.as_ref().is_some_and(|pointer| {
                            pointer.button == GateDPointerButton::Primary
                                && pointer.modifier.is_none()
                        })
                        && step.related_control == step.control
                        && step.related_pointer.as_ref().is_some_and(|pointer| {
                            pointer.button == GateDPointerButton::Primary
                                && pointer.modifier.is_none()
                        })
                        && step.after.selection_kind == GateDSelectionKind::Menu
                } else if index == 6 {
                    step.operation == GateDOperation::TypeFilter
                        && step
                            .control
                            .as_ref()
                            .is_some_and(|control| control.target == GateDControlTarget::TreeSearch)
                        && step.pointer.as_ref().is_some_and(|pointer| {
                            pointer.button == GateDPointerButton::Primary
                                && pointer.modifier.is_none()
                        })
                        && step.related_control.is_none()
                        && step.related_pointer.is_none()
                        && step.inserted_key_events >= GATE_D_LONG_LABEL.len()
                        && step.before.designer_filter_digest == 0
                        && step.after.designer_filter_digest == proof.search_query_digest
                        && step.after.designer_search_hit_count == 1
                        && step.before.selected_member_target_digests
                            == [proof.second_parent_link_target_digest]
                        && gate_d_same_selection(&step.before, &step.after)
                } else if index == 7 {
                    step.operation == GateDOperation::SearchReveal
                        && step.control.as_ref().is_some_and(|control| {
                            control.target == GateDControlTarget::TreeSearchResult
                                && control.index == Some(0)
                                && control.menu_id_digest == Some(shared)
                                && control.ring_id_digest == Some(proof.search_target_ring_digest)
                                && control.cell_id_digest == Some(proof.search_target_cell_digest)
                                && control.authored_target_digest
                                    == Some(proof.search_target_digest)
                        })
                        && step.pointer.as_ref().is_some_and(|pointer| {
                            pointer.button == GateDPointerButton::Primary
                                && pointer.modifier.is_none()
                        })
                        && step.related_control.is_none()
                        && step.related_pointer.is_none()
                        && step.before.designer_filter_digest == proof.search_query_digest
                        && step.before.designer_search_hit_count == 1
                        && step.after.designer_filter_digest == 0
                        && step.after.designer_search_hit_count == 0
                        && step.after.selection_kind == GateDSelectionKind::Cell
                        && step.after.selected_member_target_digests == [proof.search_target_digest]
                        && step.after.primary_target_digest == proof.search_target_digest
                        && step.after.range_anchor_target_digest == proof.search_target_digest
                } else {
                    step.operation == GateDOperation::Back
                        && step.control.as_ref().is_some_and(|control| {
                            control.target == GateDControlTarget::DesignerBack
                        })
                        && step.pointer.as_ref().is_some_and(|pointer| {
                            pointer.button == GateDPointerButton::Primary
                                && pointer.modifier.is_none()
                        })
                        && step.related_control.is_none()
                        && step.related_pointer.is_none()
                        && (index != 8
                            || (step.after.selection_kind == GateDSelectionKind::Cell
                                && step.after.selected_member_target_digests
                                    == [proof.second_parent_link_target_digest]
                                && step.after.primary_target_digest
                                    == proof.second_parent_link_target_digest
                                && step.after.range_anchor_target_digest
                                    == proof.second_parent_link_target_digest))
                }
            }) && packet.selection_proof.is_none()
                && packet.bulk_label_proof.is_none()
                && packet.hotkey_proof.is_none()
                && packet.local_ui_proof.is_none()
        }
        "D14" => {
            let Some(local) = packet.local_ui_proof.as_ref() else {
                return false;
            };
            let Some(hotkey) = packet.hotkey_proof.as_ref() else {
                return false;
            };
            let Some(checkpoint) = local.text_undo_checkpoint.as_ref() else {
                return false;
            };
            if packet.steps.len() != 11
                || local.compact_client_size[0] <= 0
                || local.compact_client_size[1] <= 0
                || local.compact_client_size[0] > 520
                || local.compact_client_size[1] > 380
                || local.long_label_digest != gate_d_label_digest(GATE_D_LONG_LABEL)
                || local.expected_filter_digest != local.long_label_digest
                || local.undo_restored_filter_digest
                    != gate_d_label_digest(GATE_D_TEXT_ORIGINAL_FILTER)
                || local.escape_cleared_filter_digest != 0
                || local.shared_child_menu_digest == 0
                || local.direct_child_link_target_digest == 0
                || local.direct_child_edge_digest == 0
                || local.popup_source_target_digest == 0
                || local.generated_source_target_digest == 0
                || local.generated_result_index != 0
            {
                return false;
            }
            let operation_order = [
                GateDOperation::EnterSubmenu,
                GateDOperation::TypeFilter,
                GateDOperation::TextSelectAll,
                GateDOperation::TypeFilter,
                GateDOperation::TextUndo,
                GateDOperation::EscapeFilter,
                GateDOperation::OpenPropertiesPopup,
                GateDOperation::EscapePopup,
                GateDOperation::SelectProjectedResult,
                GateDOperation::EditDynamicSource,
                GateDOperation::LauncherChord,
            ];
            if !packet.steps.iter().enumerate().all(|(index, step)| {
                step.operation == operation_order[index]
                    && step.result == GateDStepResult::Applied
                    && gate_d_step_input_is_valid(step)
            }) {
                return false;
            }
            let [
                enter,
                initial_filter,
                select_all,
                long_filter,
                undo,
                escape,
                popup,
                popup_escape,
                projected,
                edit_source,
                chord,
            ] = packet.steps.as_slice()
            else {
                return false;
            };
            let expected_edges = expected_setup_hotkey_edges(hotkey.configured_hotkey);
            let expected_hotkey_digest = gate_d_hotkey_edges_digest(&expected_edges);
            enter.before.navigation_menu_id_digests.len() == 1
                && enter.before.navigation_menu_id_digests[0] != 0
                && enter.after.navigation_menu_id_digests
                    == [
                        enter.before.navigation_menu_id_digests[0],
                        local.shared_child_menu_digest,
                    ]
                && enter.after.navigation_edge_digests == [local.direct_child_edge_digest]
                && enter.control.as_ref().is_some_and(|control| {
                    control.authored_target_digest == Some(local.direct_child_link_target_digest)
                        && control.menu_id_digest
                            == Some(enter.before.navigation_menu_id_digests[0])
                })
                && enter.pointer.as_ref().is_some_and(|pointer| {
                    pointer.button == GateDPointerButton::Primary && pointer.modifier.is_none()
                })
                && enter.related_pointer.as_ref().is_some_and(|pointer| {
                    pointer.button == GateDPointerButton::Primary && pointer.modifier.is_none()
                })
                && gate_d_same_document_state(&enter.before, &enter.after)
                && initial_filter.control.as_ref().is_some_and(|control| {
                    control.target == GateDControlTarget::TreeSearch
                        && control.client_size == local.compact_client_size
                })
                && initial_filter
                    .pointer
                    .as_ref()
                    .is_some_and(|pointer| pointer.button == GateDPointerButton::Primary)
                && initial_filter.inserted_key_events > 0
                && initial_filter.after.designer_filter_digest == local.undo_restored_filter_digest
                && initial_filter.after.designer_search_hit_count > 0
                && gate_d_text_undo_checkpoint_is_valid(
                    checkpoint,
                    initial_filter,
                    select_all,
                    local.compact_client_size,
                )
                && select_all.inserted_key_events == 4
                && select_all.before.designer_filter_digest == local.undo_restored_filter_digest
                && select_all.after.designer_filter_digest == local.undo_restored_filter_digest
                && long_filter.inserted_key_events >= GATE_D_LONG_LABEL.len()
                && long_filter.after.designer_filter_digest == local.expected_filter_digest
                && long_filter.after.designer_search_hit_count == 1
                && gate_d_visible_label_is_valid(&local.visible_long_label)
                && local.visible_long_label.session_id == long_filter.after.session_id
                && local.visible_long_label.generation == long_filter.after.generation
                && local.visible_long_label.trace_sequence > long_filter.before.trace_sequence
                && local.visible_long_label.authored_target_digest
                    == local.popup_source_target_digest
                && local.visible_long_label.client_size == local.compact_client_size
                && undo.inserted_key_events == 4
                && undo.after.designer_filter_digest == local.undo_restored_filter_digest
                && undo.after.designer_search_hit_count > 0
                && escape.inserted_key_events == 2
                && escape.after.designer_filter_digest == 0
                && escape.after.designer_search_hit_count == 0
                && [initial_filter, select_all, long_filter, undo, escape]
                    .iter()
                    .all(|step| {
                        gate_d_same_document_state(&step.before, &step.after)
                            && gate_d_same_selection(&step.before, &step.after)
                    })
                && popup.control.as_ref().is_some_and(|control| {
                    control.target == GateDControlTarget::CanvasCell
                        && control.cell_label_digest == Some(local.long_label_digest)
                        && control.authored_target_digest == Some(local.popup_source_target_digest)
                })
                && popup.pointer.as_ref().is_some_and(|pointer| {
                    pointer.button == GateDPointerButton::Secondary && pointer.modifier.is_none()
                })
                && popup.after.properties_popup_open
                && popup.after.primary_target_digest == local.popup_source_target_digest
                && popup_escape.inserted_key_events == 2
                && popup_escape.before.properties_popup_open
                && !popup_escape.after.properties_popup_open
                && gate_d_same_document_state(&popup.before, &popup.after)
                && gate_d_same_document_state(&popup_escape.before, &popup_escape.after)
                && gate_d_same_selection(&popup_escape.before, &popup_escape.after)
                && projected.control.as_ref().is_some_and(|control| {
                    control.target == GateDControlTarget::ProjectedCell
                        && control.projected_source_target_digest
                            == Some(local.generated_source_target_digest)
                        && control.projected_result_index == Some(local.generated_result_index)
                })
                && gate_d_same_document_state(&projected.before, &projected.after)
                && gate_d_same_selection(&projected.before, &projected.after)
                && edit_source.control.as_ref().is_some_and(|control| {
                    control.target == GateDControlTarget::EditDynamicSource
                        && control.edit_source_target_digest
                            == Some(local.generated_source_target_digest)
                        && control.edit_source_result_index == Some(local.generated_result_index)
                })
                && edit_source.after.selected_member_target_digests
                    == [local.generated_source_target_digest]
                && edit_source.after.primary_target_digest == local.generated_source_target_digest
                && edit_source.after.range_anchor_target_digest
                    == local.generated_source_target_digest
                && edit_source.after.draft_dirty
                && gate_d_same_document_state(&edit_source.before, &edit_source.after)
                && hotkey.input_group_id > 0
                && hotkey.invocation_id > 0
                && hotkey.exact_key_edge_count == expected_edges.len()
                && hotkey.exact_key_edge_digest == expected_hotkey_digest
                && hotkey.exact_key_edge_digest != 0
                && hotkey.designer_hwnd > 0
                && hotkey.designer_process_id > 0
                && hotkey.designer_hwnd_after == hotkey.designer_hwnd
                && hotkey.designer_process_id_after == hotkey.designer_process_id
                && hotkey.session_id == edit_source.after.session_id
                && hotkey.session_id_after == hotkey.session_id
                && hotkey.root_visible_before == chord.before.root_visible
                && hotkey.root_visible_after == chord.after.root_visible
                && hotkey.root_visible_before != hotkey.root_visible_after
                && hotkey.draft_generation == chord.before.generation
                && hotkey.draft_generation_after == chord.after.generation
                && hotkey.document_digest == chord.before.document_digest
                && hotkey.document_digest_after == chord.after.document_digest
                && hotkey.selected_members_digest == chord.before.selected_members_digest
                && hotkey.selected_members_digest_after == chord.after.selected_members_digest
                && hotkey.selection_digest == chord.before.selection_digest
                && hotkey.selection_digest_after == chord.after.selection_digest
                && hotkey.draft_dirty
                && hotkey.draft_dirty_after
                && hotkey.draft_dirty == chord.before.draft_dirty
                && hotkey.draft_dirty_after == chord.after.draft_dirty
                && hotkey.properties_popup_open == chord.before.properties_popup_open
                && hotkey.properties_popup_open_after == chord.after.properties_popup_open
                && !hotkey.properties_popup_open
                && gate_d_same_document_state(&chord.before, &chord.after)
                && gate_d_same_selection(&chord.before, &chord.after)
                && chord.inserted_key_events == hotkey.exact_key_edge_count
                && packet.selection_proof.is_none()
                && packet.bulk_label_proof.is_none()
                && packet.navigation_proof.is_none()
        }
        _ => false,
    }
}

fn gate_d_no_action_proof_is_valid(proof: &GateDNoActionProof) -> bool {
    let state_is_zero = |state: &GateDTraceDispatchState| {
        [
            &state.result_pointer,
            &state.universal_action,
            &state.radial_leaf,
            &state.query,
            &state.radial_dispatch_requested,
        ]
        .iter()
        .all(|event| event.event_count == 0 && event.event_digest == 0)
    };
    proof.trace_before == proof.trace_after
        && state_is_zero(&proof.trace_before)
        && proof.marker_lines_before == 0
        && proof.marker_lines_before == proof.marker_lines_after
        && proof.marker_digest_before > 0
        && proof.marker_digest_before == proof.marker_digest_after
}

fn gate_d_visible_label_is_valid(proof: &GateDVisibleLabelEvidence) -> bool {
    let [left, top, right, bottom] = proof.text_bounds;
    let [control_left, control_top, control_right, control_bottom] = proof.control_bounds;
    let [width, height] = proof.client_size;
    proof.session_id > 0
        && proof.generation > 0
        && proof.trace_sequence > 0
        && proof.authored_target_digest > 0
        && proof.expected_rendered_text_digest > 0
        && proof.rendered_text_digest == proof.expected_rendered_text_digest
        && proof.fully_visible
        && !proof.elided
        && width > 0
        && height > 0
        && control_left >= 0
        && control_top >= 0
        && control_right <= width
        && control_bottom <= height
        && left >= control_left
        && top >= control_top
        && right <= control_right
        && bottom <= control_bottom
        && right > left
        && bottom > top
}

fn gate_d_text_undo_checkpoint_is_valid(
    proof: &GateDTextUndoCheckpointEvidence,
    initial_filter: &GateDStepEvidence,
    select_all: &GateDStepEvidence,
    client_size: [i32; 2],
) -> bool {
    let Some(initial_control) = initial_filter.control.as_ref() else {
        return false;
    };
    let control = &proof.control;
    let [left, top, right, bottom] = control.bounds;
    let [clip_left, clip_top, clip_right, clip_bottom] = proof.clip_bounds;
    let [width, height] = client_size;
    control.target == GateDControlTarget::TreeSearch
        && control.index.is_none()
        && control.enabled
        && !control.clicked
        && proof.focused
        && !proof.in_flux
        && control
            .text_edit_field_digest
            .is_some_and(|digest| digest > 0)
        && control.text_edit_field_digest == initial_control.text_edit_field_digest
        && control.session_id == initial_filter.after.session_id
        && control.session_id == select_all.before.session_id
        && control.generation == initial_filter.after.generation
        && control.generation == select_all.before.generation
        && control.trace_sequence > initial_filter.after.trace_sequence
        && control.trace_sequence <= select_all.before.trace_sequence
        && proof.value_digest == gate_d_label_digest(GATE_D_TEXT_ORIGINAL_FILTER)
        && control.client_size == client_size
        && width > 0
        && height > 0
        && clip_left >= 0
        && clip_top >= 0
        && clip_right <= width
        && clip_bottom <= height
        && clip_right > clip_left
        && clip_bottom > clip_top
        && left >= clip_left
        && top >= clip_top
        && right <= clip_right
        && bottom <= clip_bottom
        && right > left
        && bottom > top
        && gate_d_same_document_state(&initial_filter.after, &select_all.before)
        && gate_d_same_selection(&initial_filter.after, &select_all.before)
        && initial_filter.after.navigation_path_digest == select_all.before.navigation_path_digest
        && initial_filter.after.navigation_menu_id_digests
            == select_all.before.navigation_menu_id_digests
        && initial_filter.after.navigation_edge_digests == select_all.before.navigation_edge_digests
        && initial_filter.after.designer_filter_digest == select_all.before.designer_filter_digest
        && initial_filter.after.designer_search_hit_count
            == select_all.before.designer_search_hit_count
}

fn gate_d_digest_list_is_unique(values: &[u64]) -> bool {
    values.iter().all(|value| *value != 0)
        && values
            .iter()
            .copied()
            .collect::<std::collections::BTreeSet<_>>()
            .len()
            == values.len()
}

fn gate_d_breadcrumb_path_is_valid(
    breadcrumbs: &[GateDBreadcrumbEvidence],
    expected_menu_ids: &[u64],
) -> bool {
    !expected_menu_ids.is_empty()
        && breadcrumbs.len() == expected_menu_ids.len()
        && breadcrumbs.iter().enumerate().all(|(index, breadcrumb)| {
            let [left, top, right, bottom] = breadcrumb.bounds;
            let [width, height] = breadcrumb.client_size;
            breadcrumb.index == index
                && breadcrumb.menu_id_digest == expected_menu_ids[index]
                && breadcrumb.selected == (index + 1 == expected_menu_ids.len())
                && breadcrumb.enabled
                && left >= 0
                && top >= 0
                && right > left
                && bottom > top
                && width > 0
                && height > 0
                && right <= width
                && bottom <= height
        })
}

fn gate_d_step_input_is_valid(step: &GateDStepEvidence) -> bool {
    let related_input_is_valid = match (&step.related_control, &step.related_pointer) {
        (None, None) => true,
        (Some(control), Some(pointer)) => {
            gate_d_control_input_is_valid(control, &step.before)
                && gate_d_pointer_input_is_valid(pointer, control)
        }
        _ => false,
    };
    if !related_input_is_valid {
        return false;
    }
    if !gate_d_observation_is_well_formed(&step.before, false)
        || !gate_d_observation_is_well_formed(&step.after, false)
    {
        return false;
    }
    if step.pointer.is_none() {
        let keyboard_operation = matches!(
            step.operation,
            GateDOperation::TextSelectAll
                | GateDOperation::TypeFilter
                | GateDOperation::TextUndo
                | GateDOperation::EscapeFilter
                | GateDOperation::EscapePopup
                | GateDOperation::LauncherChord
        );
        return keyboard_operation
            && step
                .control
                .as_ref()
                .is_none_or(|control| gate_d_control_input_is_valid(control, &step.before));
    }
    let (Some(control), Some(pointer)) = (&step.control, &step.pointer) else {
        return false;
    };
    gate_d_observation_is_well_formed(&step.before, false)
        && gate_d_observation_is_well_formed(&step.after, false)
        && gate_d_control_input_is_valid(control, &step.before)
        && gate_d_pointer_input_is_valid(pointer, control)
}

fn gate_d_control_input_is_valid(
    control: &GateDControlEvidence,
    before: &GateDObservationEvidence,
) -> bool {
    let scope_is_valid = match control.target {
        GateDControlTarget::CanvasCell => {
            control
                .menu_cell_ids_digest
                .is_some_and(|digest| digest > 0)
                && control.menu_id_digest.is_some_and(|digest| digest > 0)
                && control.ring_id_digest.is_some_and(|digest| digest > 0)
                && control.cell_id_digest.is_some_and(|digest| digest > 0)
                && control
                    .authored_target_digest
                    .is_some_and(|digest| digest > 0)
                && control.ring_index.is_some()
                && control.slot_index.is_some()
        }
        GateDControlTarget::ProjectedCell => {
            control
                .projected_source_target_digest
                .is_some_and(|digest| digest > 0)
                && control.projected_result_index.is_some()
        }
        GateDControlTarget::TreeSearchResult => {
            control.index.is_some()
                && control.menu_id_digest.is_some_and(|digest| digest > 0)
                && control.ring_id_digest.is_some_and(|digest| digest > 0)
                && control.cell_id_digest.is_some_and(|digest| digest > 0)
                && control
                    .authored_target_digest
                    .is_some_and(|digest| digest > 0)
        }
        GateDControlTarget::EditDynamicSource => {
            control
                .edit_source_target_digest
                .is_some_and(|digest| digest > 0)
                && control.edit_source_result_index.is_some()
        }
        GateDControlTarget::DesignerBreadcrumb => {
            control
                .breadcrumb_menu_id_digest
                .is_some_and(|digest| digest > 0)
                && control.index.is_some()
        }
        _ => true,
    };
    scope_is_valid
        && control.clicked
        && control.enabled
        && control.trace_sequence > 0
        && control.session_id == before.session_id
        && control.generation == before.generation
        && control.bounds[2] > control.bounds[0]
        && control.bounds[3] > control.bounds[1]
        && control.client_size[0] > 0
        && control.client_size[1] > 0
        && control.bounds[0] >= 0
        && control.bounds[1] >= 0
        && control.bounds[2] <= control.client_size[0]
        && control.bounds[3] <= control.client_size[1]
}

fn gate_d_pointer_input_is_valid(
    pointer: &GateDPointerEvidence,
    control: &GateDControlEvidence,
) -> bool {
    control.enabled
        && control.trace_sequence > 0
        && control.session_id > 0
        && control.generation > 0
        && control.bounds[2] > control.bounds[0]
        && control.bounds[3] > control.bounds[1]
        && control.client_size[0] > 0
        && control.client_size[1] > 0
        && control.bounds[0] >= 0
        && control.bounds[1] >= 0
        && control.bounds[2] <= control.client_size[0]
        && control.bounds[3] <= control.client_size[1]
        && pointer.target_hwnd > 0
        && pointer.target_process_id > 0
        && pointer.foreground_hwnd == pointer.target_hwnd
        && pointer.nudge_under_cursor_hwnd > 0
        && pointer.nudge_process_id == pointer.target_process_id
        && pointer.under_cursor_hwnd > 0
        && pointer.under_cursor_process_id == pointer.target_process_id
        && pointer.nudge_inserted > 0
        && pointer.movement_inserted > 0
        && pointer.down_inserted > 0
        && pointer.up_inserted > 0
        && pointer.pointer_move_acknowledged
        && pointer.down_acknowledged
        && pointer.up_acknowledged
        && match pointer.modifier {
            Some(_) => pointer.modifier_down_inserted == 1 && pointer.modifier_up_inserted == 1,
            None => pointer.modifier_down_inserted == 0 && pointer.modifier_up_inserted == 0,
        }
}

fn gate_d_observation_is_well_formed(
    state: &GateDObservationEvidence,
    deterministic: bool,
) -> bool {
    let selected_targets_are_valid = state.selected_member_target_digests.len()
        == state.selected_member_count
        && state
            .selection_kind
            .accepts_member_count(state.selected_member_count)
        && if state.selection_kind == GateDSelectionKind::None {
            state.selection_digest == 0
        } else {
            state.selection_digest > 0
        }
        && if state.selected_member_count == 0 {
            state.selected_members_digest == 0
                && state.primary_cell_digest == 0
                && state.range_anchor_digest == 0
                && state.primary_target_digest == 0
                && state.range_anchor_target_digest == 0
        } else {
            state.selected_members_digest > 0
                && state.selection_digest > 0
                && state.primary_cell_digest > 0
                && state.range_anchor_digest > 0
                && state.primary_target_digest > 0
                && state.range_anchor_target_digest > 0
                && gate_d_digest_list_is_unique(&state.selected_member_target_digests)
                && state
                    .selected_member_target_digests
                    .contains(&state.primary_target_digest)
                && state
                    .selected_member_target_digests
                    .contains(&state.range_anchor_target_digest)
        };
    let navigation_is_valid = if deterministic {
        state.navigation_path_digest == 0
            && state.navigation_menu_id_digests.is_empty()
            && state.navigation_edge_digests.is_empty()
    } else {
        state.navigation_path_digest > 0
            && !state.navigation_menu_id_digests.is_empty()
            && state.navigation_menu_id_digests.len() <= 64
            && state.navigation_edge_digests.len() + 1 == state.navigation_menu_id_digests.len()
            && state
                .navigation_menu_id_digests
                .iter()
                .all(|digest| *digest > 0)
            && state
                .navigation_edge_digests
                .iter()
                .all(|digest| *digest > 0)
    };
    state.session_id > 0
        && state.generation > 0
        && state.document_digest > 0
        && state.pending_assets_digest > 0
        && navigation_is_valid
        && state.selected_member_count <= 8_192
        && selected_targets_are_valid
        && (deterministic
            || (state.frame_ordinal > 0
                && state.trace_sequence > 0
                && state.root_history_digest > 0
                && state.root_usage_digest > 0))
}

fn gate_d_no_mutation(before: &GateDObservationEvidence, after: &GateDObservationEvidence) -> bool {
    gate_d_observation_is_well_formed(before, false)
        && gate_d_observation_is_well_formed(after, false)
        && gate_d_same_document_state(before, after)
        && gate_d_same_selection(before, after)
}

fn gate_d_same_document_state(
    left: &GateDObservationEvidence,
    right: &GateDObservationEvidence,
) -> bool {
    left.generation == right.generation
        && left.document_digest == right.document_digest
        && left.undo_depth == right.undo_depth
        && left.redo_depth == right.redo_depth
        && left.pending_assets_digest == right.pending_assets_digest
        && gate_d_same_owner_effects(left, right)
}

fn gate_d_same_selection(
    left: &GateDObservationEvidence,
    right: &GateDObservationEvidence,
) -> bool {
    left.selection_kind == right.selection_kind
        && left.selection_digest == right.selection_digest
        && left.selected_member_count == right.selected_member_count
        && left.selected_members_digest == right.selected_members_digest
        && left.selected_member_target_digests == right.selected_member_target_digests
        && left.primary_cell_digest == right.primary_cell_digest
        && left.range_anchor_digest == right.range_anchor_digest
        && left.primary_target_digest == right.primary_target_digest
        && left.range_anchor_target_digest == right.range_anchor_target_digest
}

fn gate_d_same_owner_effects(
    left: &GateDObservationEvidence,
    right: &GateDObservationEvidence,
) -> bool {
    left.root_history_entries == right.root_history_entries
        && left.root_history_digest == right.root_history_digest
        && left.root_usage_entries == right.root_usage_entries
        && left.root_usage_digest == right.root_usage_digest
}

fn gate_c_case_collection_bounds_are_valid(packet: &GateCCaseEvidence) -> bool {
    packet.controls.len() <= MAX_GATE_C_CONTROLS
        && packet.ordered_results.len() <= MAX_GATE_C_RESULTS
        && packet.inspector_text_edits.len() <= 16
        && packet.provider_lifecycle.len() <= MAX_GATE_C_LIFECYCLE_EDGES
        && packet.searches.len() <= MAX_GATE_C_SEARCHES
        && packet.incomplete_searches.len() <= MAX_GATE_C_SEARCHES
        && packet.searches.len() + packet.incomplete_searches.len() <= MAX_GATE_C_SEARCHES
        && packet.authoring_states.len() <= 4
        && packet
            .q14_partial
            .as_ref()
            .is_none_or(|partial| partial.operations.len() <= MAX_GATE_C_Q14_OPERATIONS)
        && packet.observation_boundaries.len() <= MAX_GATE_C_OBSERVATION_BOUNDARIES
        && packet.designer_controls.len() <= 8
        && packet.designer_closes.len() <= 4
        && packet.initial_snapshots.len() <= 4
        && packet.bindings.len() <= MAX_GATE_C_BINDINGS
        && packet.insertions.len() <= MAX_GATE_C_INSERTIONS
        && packet.screenshot_artifacts.len() <= MAX_GATE_C_SCREENSHOTS
}

fn is_zero_i32_quad(value: &[i32; 4]) -> bool {
    *value == [0; 4]
}

fn is_zero_i32_pair(value: &[i32; 2]) -> bool {
    *value == [0; 2]
}

fn is_false(value: &bool) -> bool {
    !*value
}

fn gate_c_designer_control_is_valid(control: &GateCDesignerControlEvidence) -> bool {
    control.trace_sequence > 0
        && control.session_id > 0
        && control.generation > 0
        && gate_c_rect_is_visible(control.bounds, control.client_size)
        && (!control.clicked || control.enabled)
}

fn gate_c_initial_snapshot_receipt_is_valid(receipt: &GateCInitialSnapshotReceipt) -> bool {
    receipt.request_id > 0
        && receipt.session_id > 0
        && receipt.generation > 0
        && receipt.trace_sequence > 0
        && receipt.terminal
}

fn gate_c_editor_identity_is_valid(identity: &GateCEditorIdentity) -> bool {
    identity.session_id > 0
        && identity.draft_generation > 0
        && identity.stable_target_digest > 0
        && identity.editor_epoch > 0
        && identity.query_digest > 0
        && identity.binding_digest > 0
}

fn gate_c_same_editor_visit(left: &GateCEditorIdentity, right: &GateCEditorIdentity) -> bool {
    left.surface == right.surface
        && left.session_id == right.session_id
        && left.draft_generation == right.draft_generation
        && left.stable_target_digest == right.stable_target_digest
        && left.editor_epoch == right.editor_epoch
        && left.binding_digest == right.binding_digest
}

fn gate_c_same_editor_visit_during_binding_edit(
    candidate: &GateCEditorIdentity,
    stage: &GateCEditorIdentity,
) -> bool {
    candidate.surface == stage.surface
        && candidate.session_id == stage.session_id
        && candidate.draft_generation == stage.draft_generation
        && candidate.stable_target_digest == stage.stable_target_digest
        && candidate.editor_epoch == stage.editor_epoch
        && candidate.query_generation == stage.query_generation
        && candidate.query_request_generation == stage.query_request_generation
        && candidate.search_request_generation == stage.search_request_generation
        && candidate.test_request_generation == stage.test_request_generation
        && candidate.query_digest == stage.query_digest
}

fn gate_c_fixture_digest(profile: &ProfileIdentity) -> String {
    sha256_bytes(
        format!(
            "gate-c-fixture-v2\0{}\0{}\0{}\0{}",
            profile.settings_sha256,
            profile.radial_sha256,
            profile.actions_sha256,
            gate_c_notes_manifest_digest(),
        )
        .as_bytes(),
    )
}

fn gate_c_notes_manifest_digest() -> String {
    sha256_bytes(
        b"radial-acceptance-shared-a.md\0# Shared Acceptance Note\nFirst duplicate-title target for radial authoring.\n\0radial-acceptance-shared-b.md\0# Shared Acceptance Note\nSecond duplicate-title target for radial authoring.\n",
    )
}

fn gate_c_private_digest(bytes: &[u8]) -> u64 {
    bytes.iter().fold(0xcbf29ce484222325, |hash, byte| {
        (hash ^ u64::from(*byte)).wrapping_mul(0x100000001b3)
    })
}

fn gate_d_label_digest(label: &str) -> u64 {
    gate_c_private_digest(label.as_bytes())
}

fn gate_d_hotkey_edges_digest(edges: &[(u32, bool)]) -> u64 {
    let mut bytes = Vec::with_capacity(edges.len().saturating_mul(5));
    for (virtual_key, down) in edges {
        bytes.extend_from_slice(&virtual_key.to_le_bytes());
        bytes.push(u8::from(*down));
    }
    gate_c_private_digest(&bytes)
}

fn gate_c_trace_text_digest(text: &str) -> u64 {
    let mut hash = gate_c_private_digest(text.as_bytes());
    hash = (hash ^ 0).wrapping_mul(0x100000001b3);
    hash
}

fn gate_c_trace_parts_digest(parts: &[&str]) -> u64 {
    let mut hash = 0xcbf29ce484222325;
    for part in parts {
        for byte in part.as_bytes().iter().chain(std::iter::once(&0)) {
            hash = (hash ^ u64::from(*byte)).wrapping_mul(0x100000001b3);
        }
    }
    hash
}

fn gate_c_inspector_text_edit_is_valid(edit: &GateCInspectorTextEvidence) -> bool {
    let [left, top, right, bottom] = edit.bounds;
    let [clip_left, clip_top, clip_right, clip_bottom] = edit.clip_bounds;
    let [client_width, client_height] = edit.client_size;
    edit.target_digest > 0
        && edit.session_id > 0
        && edit.generation > 0
        && edit.value_digest > 0
        && edit.expected_value_digest > 0
        && edit.trace_sequence > 0
        && edit.visible
        && edit.fully_visible
        && left < right
        && top < bottom
        && [left, top, right, bottom] == [clip_left, clip_top, clip_right, clip_bottom]
        && left >= 0
        && top >= 0
        && right <= client_width
        && bottom <= client_height
        && client_width > 0
        && client_height > 0
        && match edit.stage {
            GateCInspectorTextStage::Visible => !edit.changed,
            GateCInspectorTextStage::Focused => edit.focused && edit.clicked && !edit.changed,
            GateCInspectorTextStage::Changed => {
                edit.focused && edit.changed && edit.value_digest == edit.expected_value_digest
            }
        }
}

fn gate_c_inspector_edit_sequence_is_valid(
    edits: &[GateCInspectorTextEvidence],
    session_id: u64,
    target_digest: u64,
    expected_value_digest: u64,
    baseline_trace_sequence: u64,
    baseline_generation: u64,
) -> bool {
    let matching = edits
        .iter()
        .filter(|edit| {
            edit.session_id == session_id
                && edit.target_digest == target_digest
                && gate_c_inspector_text_edit_is_valid(edit)
        })
        .collect::<Vec<_>>();
    matching.iter().any(|visible| {
        visible.stage == GateCInspectorTextStage::Visible
            && visible.value_digest != 0
            && matching.iter().any(|focused| {
                focused.stage == GateCInspectorTextStage::Focused
                    && focused.trace_sequence > visible.trace_sequence
                    && focused.generation == visible.generation
                    && focused.value_digest == visible.value_digest
                    && matching.iter().any(|changed| {
                        changed.stage == GateCInspectorTextStage::Changed
                            && changed.trace_sequence > focused.trace_sequence
                            && changed.trace_sequence < baseline_trace_sequence
                            && changed.generation > focused.generation
                            && changed.generation <= baseline_generation
                            && changed.value_digest == expected_value_digest
                            && changed.expected_value_digest == expected_value_digest
                    })
            })
    })
}

fn gate_c_d09_reopen_selection_is_observed(
    packet: &GateCCaseEvidence,
    receipt: &GateCInitialSnapshotReceipt,
    terminal: &GateCAuthoringStateEvidence,
    evidence: &GateCD09Evidence,
) -> bool {
    let Some(identity) = terminal.action_editor.as_ref() else {
        return false;
    };
    receipt.session_id == terminal.session_id
        && receipt.generation <= terminal.generation
        && receipt.trace_sequence < terminal.trace_sequence
        && terminal.editor_open
        && terminal.session_id > 0
        && evidence.unrelated_cell_selection_digest != 0
        && terminal.selected_cell_digest == evidence.unrelated_cell_selection_digest
        && terminal.selected_target_digest == identity.stable_target_digest
        && identity.surface == GateCSurface::Inspector
        && identity.session_id == terminal.session_id
        && identity.draft_generation == terminal.generation
        && packet.inspector_text_edits.iter().any(|visible| {
            visible.stage == GateCInspectorTextStage::Visible
                && visible.session_id == terminal.session_id
                && visible.generation == terminal.generation
                && visible.target_digest == evidence.unrelated_cell_target_digest
                && visible.trace_sequence > receipt.trace_sequence
                && visible.trace_sequence < terminal.trace_sequence
                && visible.value_digest != evidence.unrelated_label_value_digest
                && visible.value_digest != 0
                && visible.expected_value_digest == visible.value_digest
                && visible.visible
                && visible.fully_visible
                && visible.bounds == visible.clip_bounds
                && gate_c_rect_is_visible(visible.bounds, visible.client_size)
                && packet.controls.iter().any(|control| {
                    control.control == "query_field"
                        && control.identity == *identity
                        && control.trace_sequence > visible.trace_sequence
                        && control.trace_sequence < terminal.trace_sequence
                        && control.visible
                        && control.enabled
                        && control.fully_visible
                        && control.bounds == control.full_bounds
                        && control.client_size[0] > 0
                        && control.client_size[1] > 0
                        && gate_c_rect_is_visible(control.bounds, control.client_size)
                })
                && packet.inspector_text_edits.iter().any(|focused| {
                    focused.stage == GateCInspectorTextStage::Focused
                        && focused.session_id == visible.session_id
                        && focused.generation == visible.generation
                        && focused.target_digest == visible.target_digest
                        && focused.value_digest == visible.value_digest
                        && focused.expected_value_digest == visible.expected_value_digest
                        && focused.trace_sequence > visible.trace_sequence
                        && focused.trace_sequence < terminal.trace_sequence
                        && focused.visible
                        && focused.fully_visible
                        && focused.focused
                        && focused.clicked
                        && focused.bounds == visible.bounds
                        && focused.clip_bounds == visible.clip_bounds
                        && focused.client_size == visible.client_size
                })
        })
}

fn gate_c_inspector_selected_cell_digest(cell_id: &str) -> u64 {
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    std::hash::Hash::hash(
        &multi_launcher::radial::model::CellId::new(cell_id),
        &mut hasher,
    );
    std::hash::Hasher::finish(&hasher)
}

fn gate_c_note_semantic_target_digest(slug: &str) -> u64 {
    let command = format!("note:open:{slug}");
    let disambiguator = format!("slug {slug}");
    gate_c_trace_parts_digest(&[&command, "Shared Acceptance Note", "Note", &disambiguator])
}

fn gate_c_note_reference_digest(slug: &str) -> u64 {
    let reference = PersistableActionTargetRef::Note {
        slug: slug.to_owned(),
    };
    serde_json::to_vec(&reference)
        .ok()
        .map_or(0, |bytes| gate_c_private_digest(&bytes))
}

fn gate_c_note_action_digest() -> u64 {
    gate_c_trace_parts_digest(&[action_ids::NOTE_EDIT.as_str()])
}

fn gate_c_custom_action() -> multi_launcher::actions::Action {
    multi_launcher::actions::Action {
        label: "Radial Acceptance Harmless Action 000".into(),
        desc: "Deterministic native authoring fixture".into(),
        action: "radial_acceptance_harmless_000".into(),
        args: None,
    }
}

fn gate_c_custom_action_target_digest() -> u64 {
    let action = gate_c_custom_action();
    gate_c_trace_parts_digest(&[
        &action.action,
        &action.label,
        "Custom action",
        // Two deterministic marker actions precede this fixture action in the
        // isolated profile's custom-action catalog.
        "custom action 3",
    ])
}

fn gate_c_custom_action_reference_digest() -> u64 {
    let reference = PersistableActionTargetRef::CustomAction {
        action: gate_c_custom_action(),
    };
    serde_json::to_vec(&reference)
        .ok()
        .map_or(0, |bytes| gate_c_private_digest(&bytes))
}

fn gate_c_custom_action_id_digest() -> u64 {
    gate_c_trace_parts_digest(&[action_ids::RESULT_EXECUTE.as_str()])
}

fn gate_c_insertion_fixture_query(layout: GateCResultLayout) -> &'static str {
    match layout {
        GateCResultLayout::List => "note search First duplicate-title target",
        GateCResultLayout::Grid => "app Radial Acceptance Harmless Action 000",
    }
}

fn gate_c_insertion_fixture_binding(layout: GateCResultLayout) -> ActionBinding {
    let (target, action_id) = match layout {
        GateCResultLayout::List => (
            PersistableActionTargetRef::Note {
                slug: "radial-acceptance-shared-a".into(),
            },
            action_ids::NOTE_EDIT,
        ),
        GateCResultLayout::Grid => (
            PersistableActionTargetRef::CustomAction {
                action: gate_c_custom_action(),
            },
            action_ids::RESULT_EXECUTE,
        ),
    };
    ActionBinding::Persisted {
        action: PersistedUniversalActionRef {
            target: Some(target),
            action_id,
        },
    }
}

fn gate_c_insertion_fixture_identity(layout: GateCResultLayout) -> (u64, u64, u64, u64) {
    let (target_digest, action_digest) = match layout {
        GateCResultLayout::List => (
            gate_c_note_semantic_target_digest("radial-acceptance-shared-a"),
            gate_c_note_action_digest(),
        ),
        GateCResultLayout::Grid => (
            gate_c_custom_action_target_digest(),
            gate_c_custom_action_id_digest(),
        ),
    };
    let binding = gate_c_insertion_fixture_binding(layout);
    let binding_digest = serde_json::to_vec(&binding)
        .ok()
        .map_or(0, |bytes| gate_c_private_digest(&bytes));
    let query_digest = gate_c_trace_text_digest(gate_c_insertion_fixture_query(layout));
    (target_digest, action_digest, binding_digest, query_digest)
}

fn gate_c_note_target_reference_matches(binding: &GateCBindingEvidence) -> bool {
    ["radial-acceptance-shared-a", "radial-acceptance-shared-b"]
        .into_iter()
        .any(|slug| {
            binding.target_reference_digest == Some(gate_c_note_reference_digest(slug))
                && binding.semantic_target_digest == gate_c_note_semantic_target_digest(slug)
        })
}

fn gate_c_persisted_binding_identity_matches(binding: &GateCBindingEvidence) -> bool {
    let note_match = binding.action_id_digest == Some(gate_c_note_action_digest())
        && binding.semantic_action_digest == gate_c_note_action_digest()
        && gate_c_note_target_reference_matches(binding);
    let custom_action_match = binding.route == GateCBindingRoute::RadialInsertion
        && binding.action_id_digest == Some(gate_c_custom_action_id_digest())
        && binding.semantic_action_digest == gate_c_custom_action_id_digest()
        && binding.target_reference_digest == Some(gate_c_custom_action_reference_digest())
        && binding.semantic_target_digest == gate_c_custom_action_target_digest();
    note_match || custom_action_match
}

fn gate_c_apply_note_row_identity(row: &mut GateCResultRowEvidence, slug: &str) {
    row.target_digest = gate_c_note_semantic_target_digest(slug);
    row.action_digest = gate_c_note_action_digest();
    if let Some((title, target_type, disambiguator, label)) =
        gate_c_expected_fixture_label_digests(row.target_digest, row.action_digest)
    {
        row.title_digest = title;
        row.type_digest = target_type;
        row.disambiguator_digest = disambiguator;
        row.displayed_text_digest = label;
    }
}

fn gate_c_apply_note_control_identity(control: &mut GateCControlEvidence, slug: &str) {
    control.target_digest = gate_c_note_semantic_target_digest(slug);
    control.action_digest = gate_c_note_action_digest();
    if let Some((title, target_type, disambiguator, label)) =
        gate_c_expected_fixture_label_digests(control.target_digest, control.action_digest)
    {
        control.title_digest = title;
        control.type_digest = target_type;
        control.disambiguator_digest = disambiguator;
        if matches!(
            control.control.as_str(),
            "result" | "result_target" | "contextual_target"
        ) {
            control.displayed_text_digest = label;
            control.readable_text_digest = Some(label);
        } else {
            control.displayed_text_digest = 0;
            control.readable_text_digest = None;
        }
    }
}

fn gate_c_rect_is_visible(bounds: [i32; 4], client_size: [i32; 2]) -> bool {
    bounds[0] >= 0
        && bounds[1] >= 0
        && bounds[2] > bounds[0]
        && bounds[3] > bounds[1]
        && client_size[0] > 0
        && client_size[1] > 0
        && bounds[2] <= client_size[0]
        && bounds[3] <= client_size[1]
}

fn gate_c_control_is_valid(control: &GateCControlEvidence) -> bool {
    const CONTROLS: &[&str] = &[
        "query_tab",
        "query",
        "query_field",
        "search",
        "query_mode",
        "result_count",
        "result",
        "result_target",
        "pin",
        "pin_result",
        "save_query",
        "mode",
        "test_query",
        "test_result",
        "contextual_target",
        "pin_contextual",
        "test_assigned",
        "advanced",
        "advanced_tab",
        "exact_command",
        "arguments",
        "exact_command_field",
        "exact_args_field",
        "use_exact_command",
        "test_exact_command",
        "test",
        "apply",
        "open_inspector",
        "close",
        "save",
        "undo",
        "redo",
        "keep_editing",
        "discard",
        "reopen",
        "add_to_radial",
        "menu",
        "ring",
        "cell",
        "spacer",
        "append",
        "replace",
        "cancel",
        "confirm_close_tree",
    ];
    let row_control = matches!(
        control.control.as_str(),
        "result"
            | "result_target"
            | "pin"
            | "pin_result"
            | "test_result"
            | "contextual_target"
            | "pin_contextual"
    );
    let readable_row_control = matches!(
        control.control.as_str(),
        "result" | "result_target" | "contextual_target"
    );
    let owner_control = matches!(control.control.as_str(), "apply" | "save" | "undo" | "redo");
    let owner_identity_is_valid = match (control.owner_session_id, control.owner_generation) {
        (Some(session_id), Some(generation)) => {
            owner_control
                && control.clicked
                && session_id > 0
                && session_id == control.identity.session_id
                && generation > 0
        }
        (None, None) => !owner_control,
        _ => false,
    };
    CONTROLS.contains(&control.control.as_str())
        && control.trace_sequence > 0
        && gate_c_editor_identity_is_valid(&control.identity)
        && owner_identity_is_valid
        && control.query_digest == control.identity.query_digest
        && if row_control {
            control.title_digest != 0
                && control.type_digest != 0
                && control.disambiguator_digest != 0
        } else {
            control.title_digest == 0
                && control.type_digest == 0
                && control.disambiguator_digest == 0
        }
        && if readable_row_control {
            control.displayed_text_digest != 0
                && control.readable_text_digest == Some(control.displayed_text_digest)
                && control.fully_visible
                && gate_c_rect_is_visible(control.full_bounds, control.client_size)
        } else {
            control.displayed_text_digest == 0 && control.readable_text_digest.is_none()
        }
        && control
            .control_index
            .is_none_or(|index| index < MAX_GATE_C_RESULTS)
        && gate_c_rect_is_visible(control.bounds, control.client_size)
        && control.visible
        && (!control.clicked || control.enabled)
        && match control.control.as_str() {
            "query" | "query_field" => control.value_digest == control.query_digest,
            "exact_command_field" | "exact_args_field" => control.value_digest != 0,
            _ => control.value_digest == 0,
        }
}

fn gate_c_control_binding_is_correlated(
    control: &GateCControlEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    let row_control = matches!(
        control.control.as_str(),
        "result"
            | "result_target"
            | "pin"
            | "pin_result"
            | "test_result"
            | "contextual_target"
            | "pin_contextual"
    );
    if row_control {
        packet.ordered_results.iter().any(|row| {
            let pin_transition_matches = control.control != "pin_result"
                || (control.identity.surface == row.identity.surface
                    && control.identity.session_id == row.identity.session_id
                    && control.identity.draft_generation == row.identity.draft_generation
                    && control.identity.stable_target_digest == row.identity.stable_target_digest
                    && control.identity.editor_epoch == row.identity.editor_epoch
                    && control.identity.query_digest == row.identity.query_digest
                    && control.identity.query_generation == row.identity.query_generation
                    && control.identity.query_request_generation
                        == row.identity.query_request_generation
                    && control.identity.search_request_generation
                        == row.identity.search_request_generation
                    && (control.identity.edit_generation == row.identity.edit_generation
                        || control.identity.edit_generation
                            == row.identity.edit_generation.saturating_add(1))
                    && (control.identity.binding_digest == row.identity.binding_digest
                        || control.identity.binding_digest == row.binding_digest));
            (row.identity == control.identity || pin_transition_matches)
                && control.control_index.and_then(|index| index.checked_add(1)) == Some(row.order)
                && row.target_digest == control.target_digest
                && row.title_digest == control.title_digest
                && row.type_digest == control.type_digest
                && row.disambiguator_digest == control.disambiguator_digest
                && row.action_digest == control.action_digest
                && row.binding_digest == control.binding_digest
                && row.surface == control.identity.surface
                && row.readable
        }) || packet.bindings.iter().any(|binding| {
            binding.semantic_target_digest == control.target_digest
                && binding.semantic_action_digest == control.action_digest
                && binding.expected_binding_digest == control.binding_digest
                && binding.controls.iter().any(|receipt| {
                    receipt.trace_sequence == control.trace_sequence
                        && receipt.surface == control.identity.surface
                })
        })
    } else if control.control == "search" {
        packet.searches.iter().any(|search| {
            search.identity == control.identity
                && search.search_control_sequence == control.trace_sequence
                && search.query_binding_digest == control.binding_digest
        }) || packet.incomplete_searches.iter().any(|search| {
            search.identity == control.identity
                && search.search_control_sequence == control.trace_sequence
                && search.query_binding_digest == control.binding_digest
                && search.query_digest == control.query_digest
        }) || packet.provider_lifecycle.iter().any(|event| {
            event.kind == GateCProviderKind::Search
                && event.edge == GateCProviderEdge::Queued
                && event.identity == control.identity
                && event.query_digest == control.query_digest
                && event.binding_digest == 0
                && control.trace_sequence < event.trace_sequence
        })
    } else {
        control.binding_digest == 0
            || control.binding_digest == control.identity.binding_digest
            || (matches!(
                control.control.as_str(),
                "query"
                    | "query_field"
                    | "mode"
                    | "query_mode"
                    | "save_query"
                    | "test"
                    | "test_query"
                    | "test_result"
                    | "test_exact_command"
                    | "test_assigned"
                    | "advanced"
                    | "exact_command"
                    | "exact_command_field"
                    | "arguments"
                    | "exact_args_field"
                    | "use_exact_command"
                    | "apply"
                    | "save"
                    | "undo"
                    | "redo"
                    | "reopen"
            ) && control.binding_digest != 0)
    }
}

fn gate_c_control_identity_is_observed(
    control: &GateCControlEvidence,
    packet: &GateCCaseEvidence,
    case_status: Option<CaseStatus>,
) -> bool {
    if packet.case_id == "D02"
        && matches!(case_status, Some(CaseStatus::Failed))
        && control.control == "query_field"
        && control.changed
        && control.identity.surface == GateCSurface::Inspector
    {
        return gate_c_failed_inspector_search_edit_is_observed(control, packet);
    }
    packet.editor_identity.as_ref() == Some(&control.identity)
        || packet
            .searches
            .iter()
            .any(|search| search.identity == control.identity)
        || packet
            .incomplete_searches
            .iter()
            .any(|search| search.identity == control.identity)
        || packet
            .ordered_results
            .iter()
            .any(|row| row.identity == control.identity)
        || packet
            .provider_lifecycle
            .iter()
            .any(|event| event.identity == control.identity)
        || packet.q14.as_ref().is_some_and(|evidence| {
            evidence
                .operations
                .iter()
                .any(|operation| operation.identity == control.identity)
                || evidence.baseline.action_editor.as_ref() == Some(&control.identity)
                || evidence.terminal.action_editor.as_ref() == Some(&control.identity)
        })
        || packet.q14_partial.as_ref().is_some_and(|evidence| {
            evidence
                .operations
                .iter()
                .any(|operation| operation.identity == control.identity)
                || evidence.baseline.action_editor.as_ref() == Some(&control.identity)
                || evidence.terminal.as_ref().is_some_and(|terminal| {
                    terminal.action_editor.as_ref() == Some(&control.identity)
                })
        })
        || packet
            .authoring_states
            .iter()
            .any(|state| state.action_editor.as_ref() == Some(&control.identity))
        || packet.bindings.iter().any(|binding| {
            binding
                .controls
                .iter()
                .any(|receipt| receipt.identity == control.identity)
        })
        || (matches!(case_status, Some(CaseStatus::Failed))
            && packet.case_id == "D04"
            && control.control == "query_field"
            && gate_c_d04_failed_completed_query_edit_is_observed(control, packet))
        || (matches!(case_status, Some(CaseStatus::Failed))
            && if gate_c_failed_edit_has_linked_inspector_attempt(control, packet) {
                gate_c_failed_inspector_search_edit_is_observed(control, packet)
            } else {
                gate_c_failed_partial_query_edit_is_observed(control, packet)
            })
        || (packet.case_id == "D04"
            && matches!(case_status, Some(CaseStatus::Failed))
            && gate_c_d04_binding_input_is_observed(control, packet))
        || (packet.case_id == "D04"
            && matches!(case_status, Some(CaseStatus::Passed))
            && packet.bindings.iter().any(|binding| {
                gate_c_d04_exact_command_transition_is_observed(control, binding, packet)
            }))
        || (packet.case_id == "D04"
            && matches!(case_status, Some(CaseStatus::Passed))
            && ((control.control == "query_mode"
                && control.clicked
                && control.changed
                && gate_c_d04_binding_input_is_observed(control, packet))
                || (control.control == "query_tab"
                    && gate_c_d04_query_tab_is_observed(control, packet))))
        || (packet.case_id == "D04"
            && matches!(case_status, Some(CaseStatus::Failed))
            && control.control == "query_tab"
            && gate_c_d04_query_tab_is_observed(control, packet))
        || (matches!(case_status, Some(CaseStatus::Passed))
            && gate_c_passed_query_edit_is_observed(control, packet))
        || (packet.case_id == "D09"
            && matches!(case_status, Some(CaseStatus::Passed))
            && gate_c_d09_held_query_edit_is_observed(control, packet))
}

fn gate_c_d04_failed_completed_query_edit_is_observed(
    edit: &GateCControlEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    if packet.case_id != "D04"
        || edit.control != "query_field"
        || edit.identity.surface != GateCSurface::Properties
        || !edit.changed
        || !edit.visible
        || !edit.enabled
        || edit.trace_sequence == 0
        || edit.value_digest == 0
        || edit.value_digest != edit.query_digest
        || edit.query_digest != edit.identity.query_digest
    {
        return false;
    }

    packet.bindings.iter().any(|binding| {
        if binding.kind != GateCBindingKind::LauncherQuery
            || binding.route != GateCBindingRoute::PropertiesStaged
            || binding.query_mode != Some(GateCQueryMode::ExecuteFirst)
            || binding.query_digest != Some(edit.query_digest)
            || binding.previous_binding_digest == 0
            || binding.previous_binding_digest == binding.expected_binding_digest
            || edit.identity.binding_digest != binding.previous_binding_digest
        {
            return false;
        }
        let Some(stage) = binding
            .controls
            .iter()
            .find(|receipt| receipt.kind == GateCBindingControlKind::Stage)
        else {
            return false;
        };
        if stage.control != "save_query"
            || stage.trace_sequence <= edit.trace_sequence
            || stage.binding_digest != binding.expected_binding_digest
            || stage.identity.binding_digest != binding.previous_binding_digest
            || !packet.controls.iter().any(|observed| observed == edit)
            || !packet.controls.iter().any(|candidate| {
                candidate.control == stage.control
                    && candidate.clicked
                    && candidate.enabled
                    && candidate.visible
                    && candidate.trace_sequence == stage.trace_sequence
                    && candidate.identity == stage.identity
                    && candidate.binding_digest == binding.expected_binding_digest
            })
        {
            return false;
        }

        // Keep this as one witness chain. A different settled search in the
        // same visit must not satisfy the Stage side after another Search has
        // independently satisfied the edit side.
        packet.controls.iter().any(|search_control| {
            gate_c_inspector_edit_matches_later_search(edit, search_control)
                && search_control.identity.binding_digest == binding.previous_binding_digest
                && search_control.binding_digest == binding.previous_binding_digest
                && packet.searches.iter().any(|search| {
                    search.identity == search_control.identity
                        && search.surface == search_control.identity.surface
                        && search.query_digest == edit.query_digest
                        && search.query_binding_digest == binding.previous_binding_digest
                        && search.search_control_sequence == search_control.trace_sequence
                        && search.search_control_sequence > edit.trace_sequence
                        && search.observed_trace_sequence < stage.trace_sequence
                        && search.identity.binding_digest == binding.previous_binding_digest
                        && gate_c_same_editor_visit_during_binding_edit(
                            &search.identity,
                            &stage.identity,
                        )
                        && gate_c_search_is_valid(search, packet)
                })
        })
    })
}

fn gate_c_d04_query_tab_is_observed(
    control: &GateCControlEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    if packet.case_id != "D04"
        || control.control != "query_tab"
        || control.clicked
        || control.trace_sequence == 0
        || !control.visible
        || !control.enabled
    {
        return false;
    }
    let same_visit = |left: &GateCEditorIdentity, right: &GateCEditorIdentity| {
        left.surface == right.surface
            && left.session_id == right.session_id
            && left.draft_generation == right.draft_generation
            && left.stable_target_digest == right.stable_target_digest
            && left.editor_epoch == right.editor_epoch
            && left.binding_digest == right.binding_digest
    };
    let first_input_sequence = packet
        .controls
        .iter()
        .filter(|candidate| {
            same_visit(&control.identity, &candidate.identity)
                && ((candidate.control == "query_field" && candidate.changed)
                    || (candidate.control == "query_mode" && candidate.clicked)
                    || (candidate.control == "advanced_tab" && candidate.clicked)
                    || (candidate.control == "exact_command_field" && candidate.changed)
                    || (candidate.control == "exact_args_field" && candidate.changed)
                    || (candidate.control == "save_query" && candidate.clicked)
                    || (candidate.control == "pin_result" && candidate.clicked))
        })
        .map(|candidate| candidate.trace_sequence)
        .min();
    if first_input_sequence.is_none_or(|sequence| control.trace_sequence >= sequence) {
        return false;
    }

    let query_search_anchor = packet.controls.iter().any(|edit| {
        edit.control == "query_field"
            && edit.changed
            && edit.trace_sequence > control.trace_sequence
            && same_visit(&control.identity, &edit.identity)
            && gate_c_passed_query_edit_is_observed(edit, packet)
    });
    let typed_stage_anchor = packet.bindings.iter().any(|binding| {
        binding.controls.iter().any(|receipt| {
            matches!(
                receipt.kind,
                GateCBindingControlKind::Stage | GateCBindingControlKind::Assign
            ) && receipt.trace_sequence > control.trace_sequence
                && same_visit(&control.identity, &receipt.identity)
                && packet.controls.iter().any(|candidate| {
                    candidate.control == receipt.control
                        && candidate.identity == receipt.identity
                        && candidate.trace_sequence == receipt.trace_sequence
                        && candidate.trace_sequence > control.trace_sequence
                        && candidate.clicked
                        && candidate.enabled
                        && candidate.binding_digest == receipt.binding_digest
                })
        })
    });
    query_search_anchor || typed_stage_anchor
}

fn gate_c_d04_binding_input_is_observed(
    control: &GateCControlEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    packet.bindings.iter().any(|binding| {
        let staged = binding.controls.iter().find(|receipt| {
            matches!(
                receipt.kind,
                GateCBindingControlKind::Stage | GateCBindingControlKind::Assign
            )
        });
        let reopened = binding
            .controls
            .iter()
            .find(|receipt| receipt.kind == GateCBindingControlKind::Reopen);

        let phase_matches = |candidate: &GateCControlEvidence, is_reopened: bool| {
            if is_reopened {
                reopened.is_some_and(|receipt| {
                    candidate.identity == receipt.identity
                        && candidate.trace_sequence >= receipt.trace_sequence
                })
            } else {
                staged.is_some_and(|receipt| {
                    gate_c_same_editor_visit(&candidate.identity, &receipt.identity)
                        && candidate.trace_sequence < receipt.trace_sequence
                })
            }
        };
        let input_matches = |candidate: &GateCControlEvidence, is_reopened: bool| {
            let staged_binding_transition = !is_reopened
                && binding.route == GateCBindingRoute::PropertiesStaged
                && (binding.kind == GateCBindingKind::ExactCommand
                    || (binding.kind == GateCBindingKind::LauncherQuery
                        && binding.query_mode == Some(GateCQueryMode::ExecuteFirst)
                        && candidate.control == "query_mode"));
            if !staged_binding_transition && !phase_matches(candidate, is_reopened) {
                return false;
            }
            match binding.kind {
                GateCBindingKind::PersistedReference => false,
                GateCBindingKind::LauncherQuery => {
                    let query = binding.query_digest.unwrap_or(0);
                    if query == 0 {
                        return false;
                    }
                    match candidate.control.as_str() {
                        "query_field" => {
                            candidate.query_digest == query
                                && candidate.value_digest == query
                                && (!is_reopened
                                    || candidate.binding_digest == binding.expected_binding_digest)
                        }
                        "query_mode" => {
                            if is_reopened {
                                phase_matches(candidate, true)
                                    && candidate.query_digest == query
                                    && candidate.binding_digest == binding.expected_binding_digest
                                    && candidate.selected
                                        == (binding.query_mode
                                            == Some(GateCQueryMode::ExecuteFirst))
                            } else if binding.query_mode == Some(GateCQueryMode::ExecuteFirst) {
                                gate_c_d04_query_mode_stage_transition_is_observed(
                                    candidate, binding, packet,
                                )
                            } else {
                                phase_matches(candidate, false)
                                    && candidate.query_digest == query
                                    && candidate.binding_digest == binding.expected_binding_digest
                                    && candidate.selected
                                        == (binding.query_mode
                                            == Some(GateCQueryMode::ExecuteFirst))
                            }
                        }
                        _ => false,
                    }
                }
                GateCBindingKind::ExactCommand => {
                    if !is_reopened {
                        return gate_c_d04_exact_command_transition_is_observed(
                            candidate, binding, packet,
                        );
                    }
                    if !phase_matches(candidate, is_reopened) {
                        return false;
                    }
                    let expected_value = match candidate.control.as_str() {
                        "exact_command_field" => binding.command_digest.unwrap_or(0),
                        "exact_args_field" => binding.arguments_digest.unwrap_or(0),
                        _ => return false,
                    };
                    expected_value != 0
                        && candidate.value_digest == expected_value
                        && candidate.binding_digest == binding.expected_binding_digest
                }
            }
        };

        [false, true].into_iter().any(|is_reopened| {
            input_matches(control, is_reopened)
                && packet
                    .controls
                    .iter()
                    .filter(|candidate| {
                        candidate.control == control.control
                            && input_matches(candidate, is_reopened)
                    })
                    .max_by_key(|candidate| candidate.trace_sequence)
                    .is_some_and(|latest| latest.trace_sequence == control.trace_sequence)
        })
    })
}

fn gate_c_d04_query_mode_stage_transition_is_observed(
    control: &GateCControlEvidence,
    binding: &GateCBindingEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    let Some(stage) = binding
        .controls
        .iter()
        .find(|receipt| receipt.kind == GateCBindingControlKind::Stage)
    else {
        return false;
    };
    let query = binding.query_digest.unwrap_or(0);
    let previous_binding = binding.previous_binding_digest;
    let expected_binding = binding.expected_binding_digest;
    if packet.case_id != "D04"
        || binding.kind != GateCBindingKind::LauncherQuery
        || binding.route != GateCBindingRoute::PropertiesStaged
        || binding.query_mode.is_none()
        || control.control != "query_mode"
        || !control.clicked
        || !control.changed
        || !control.visible
        || !control.enabled
        || control.trace_sequence == 0
        || control.trace_sequence >= stage.trace_sequence
        || query == 0
        || previous_binding == 0
        || previous_binding == expected_binding
        || expected_binding == 0
        || control.identity.binding_digest != previous_binding
        || control.binding_digest != expected_binding
        || control.identity.query_digest != query
        || control.query_digest != query
        || control.selected != (binding.query_mode == Some(GateCQueryMode::ExecuteFirst))
        || stage.control != "save_query"
        || stage.trace_sequence == 0
        || stage.binding_digest != expected_binding
        || stage.identity.binding_digest != previous_binding
        || control.identity.edit_generation == 0
        || control.identity.edit_generation != stage.identity.edit_generation
        || !gate_c_same_editor_visit_during_binding_edit(&control.identity, &stage.identity)
        || !packet.controls.iter().any(|observed| observed == control)
        || !packet.controls.iter().any(|observed| {
            observed.control == stage.control
                && observed.clicked
                && observed.enabled
                && observed.trace_sequence == stage.trace_sequence
                && observed.identity == stage.identity
                && observed.binding_digest == expected_binding
        })
    {
        return false;
    }

    packet
        .controls
        .iter()
        .filter(|candidate| {
            candidate.control == "query_mode"
                && candidate.clicked
                && candidate.changed
                && candidate.identity.binding_digest == previous_binding
                && candidate.binding_digest == expected_binding
                && candidate.query_digest == query
                && candidate.selected == (binding.query_mode == Some(GateCQueryMode::ExecuteFirst))
                && candidate.trace_sequence < stage.trace_sequence
                && gate_c_same_editor_visit_during_binding_edit(
                    &candidate.identity,
                    &stage.identity,
                )
        })
        .max_by_key(|candidate| candidate.trace_sequence)
        .is_some_and(|latest| latest.trace_sequence == control.trace_sequence)
}

fn gate_c_d04_exact_command_transition_is_observed(
    control: &GateCControlEvidence,
    binding: &GateCBindingEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    if binding.kind != GateCBindingKind::ExactCommand
        || binding.route != GateCBindingRoute::PropertiesStaged
    {
        return false;
    }
    let Some(stage) = binding
        .controls
        .iter()
        .find(|receipt| receipt.kind == GateCBindingControlKind::Stage)
    else {
        return false;
    };
    let expected_binding = binding.expected_binding_digest;
    let previous_binding = binding.previous_binding_digest;
    if previous_binding == 0 || previous_binding == expected_binding {
        return false;
    }
    if stage.control != "use_exact_command"
        || stage.trace_sequence == 0
        || stage.binding_digest != expected_binding
        || stage.identity.binding_digest != previous_binding
        || stage.identity.edit_generation == 0
        || !packet.controls.iter().any(|candidate| {
            candidate.control == "use_exact_command"
                && candidate.clicked
                && candidate.enabled
                && candidate.trace_sequence == stage.trace_sequence
                && candidate.identity == stage.identity
                && candidate.binding_digest == expected_binding
        })
    {
        return false;
    }

    let source_bindings = packet
        .controls
        .iter()
        .filter(|candidate| {
            candidate.control == "advanced_tab"
                && candidate.clicked
                && candidate.selected
                && candidate.enabled
                && candidate.visible
                && candidate.trace_sequence > 0
                && candidate.trace_sequence < stage.trace_sequence
                && candidate.identity.binding_digest == previous_binding
                && candidate.binding_digest == candidate.identity.binding_digest
                && candidate.identity.edit_generation < stage.identity.edit_generation
                && gate_c_same_editor_visit_during_binding_edit(
                    &candidate.identity,
                    &stage.identity,
                )
        })
        .collect::<Vec<_>>();

    let command_digest = binding.command_digest.unwrap_or(0);
    let arguments_digest = binding.arguments_digest.unwrap_or(0);
    if command_digest == 0 || arguments_digest == 0 {
        return false;
    }

    let mut valid_fields = Vec::with_capacity(2);
    for (name, expected_value) in [
        ("exact_command_field", command_digest),
        ("exact_args_field", arguments_digest),
    ] {
        let Some(field) = packet
            .controls
            .iter()
            .filter(|candidate| {
                candidate.control == name
                    && candidate.changed
                    && candidate.enabled
                    && candidate.visible
                    && candidate.value_digest == expected_value
                    && candidate.trace_sequence < stage.trace_sequence
                    && candidate.identity.binding_digest == previous_binding
                    && candidate.binding_digest != 0
                    && candidate.binding_digest != candidate.identity.binding_digest
                    && candidate.identity.edit_generation <= stage.identity.edit_generation
                    && gate_c_same_editor_visit_during_binding_edit(
                        &candidate.identity,
                        &stage.identity,
                    )
            })
            .max_by_key(|candidate| candidate.trace_sequence)
        else {
            return false;
        };
        valid_fields.push(field);
    }

    let [command, arguments] = valid_fields.as_slice() else {
        return false;
    };
    if command.identity.binding_digest != arguments.identity.binding_digest
        // The pre-Stage field event fingerprints the draft binding; the
        // clicked Stage receipt fingerprints the candidate binding. The editor
        // identity itself remains on the previously assigned binding until
        // that click is applied.
        || command.binding_digest == expected_binding
        || arguments.binding_digest != expected_binding
        || !source_bindings.iter().any(|advanced| {
            advanced.identity.binding_digest == command.identity.binding_digest
                && command.identity.binding_digest == arguments.identity.binding_digest
                && advanced.trace_sequence < command.trace_sequence
                && advanced.trace_sequence < arguments.trace_sequence
                && advanced.identity.edit_generation < command.identity.edit_generation
                && advanced.identity.edit_generation < arguments.identity.edit_generation
        })
    {
        return false;
    }

    let mut ordered_fields = [*command, *arguments];
    ordered_fields.sort_by_key(|candidate| candidate.trace_sequence);
    ordered_fields[0].identity.edit_generation <= ordered_fields[1].identity.edit_generation
        && ordered_fields[1].identity.edit_generation == stage.identity.edit_generation
        && match control.control.as_str() {
            "advanced_tab" => source_bindings
                .iter()
                .any(|candidate| **candidate == *control),
            "exact_command_field" => **command == *control,
            "exact_args_field" => **arguments == *control,
            _ => false,
        }
}

fn gate_c_failed_d04_control_is_required(
    control: &GateCControlEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    control.clicked
        || control.changed
        || packet.bindings.iter().any(|binding| {
            binding.controls.iter().any(|receipt| {
                receipt.control == control.control
                    && receipt.trace_sequence == control.trace_sequence
                    && receipt.identity == control.identity
            })
        })
        || packet.searches.iter().any(|search| {
            control.control == "search"
                && search.search_control_sequence == control.trace_sequence
                && search.identity == control.identity
        })
        || packet.ordered_results.iter().any(|row| {
            let sequence_matches = match control.control.as_str() {
                "result_target" => row.observed_trace_sequence == control.trace_sequence,
                "result" | "contextual_target" => {
                    control.trace_sequence < row.observed_trace_sequence
                }
                _ => false,
            };
            sequence_matches
                && row.identity == control.identity
                && gate_c_result_control_index_matches_order(control.control_index, row.order)
                && control.target_digest == row.target_digest
                && control.title_digest == row.title_digest
                && control.type_digest == row.type_digest
                && control.disambiguator_digest == row.disambiguator_digest
                && control.action_digest == row.action_digest
                && control.binding_digest == row.binding_digest
                && control.displayed_text_digest == row.displayed_text_digest
                && control.readable_text_digest == Some(row.displayed_text_digest)
                && control.fully_visible
        })
        || gate_c_d04_binding_input_is_observed(control, packet)
}

fn gate_c_compact_failed_d04_packet(
    packet: &mut GateCCaseEvidence,
    case_status: CaseStatus,
) -> bool {
    if packet.case_id != "D04" || !matches!(case_status, CaseStatus::Failed) {
        return false;
    }

    // A failed D04 can contain several completed transactions before its final
    // Inspector visit fails. Keep the last exact-command Properties transaction
    // and the following InspectorDirect persisted transaction as a coherent
    // tail. Earlier transactions are omitted only from this Failed-only summary.
    let Some(active_identity) = packet.editor_identity.as_ref() else {
        return false;
    };
    let Some((_, direct_binding)) = packet
        .bindings
        .iter()
        .enumerate()
        .filter(|(_, binding)| {
            binding.kind == GateCBindingKind::PersistedReference
                && binding.route == GateCBindingRoute::InspectorDirect
                && binding.controls.iter().any(|receipt| {
                    receipt.kind == GateCBindingControlKind::Reopen
                        && gate_c_same_editor_visit(active_identity, &receipt.identity)
                })
        })
        .max_by_key(|(_, binding)| {
            binding
                .controls
                .iter()
                .find(|receipt| receipt.kind == GateCBindingControlKind::Reopen)
                .map_or(0, |receipt| receipt.trace_sequence)
        })
    else {
        return false;
    };
    let Some(direct_assignment) = direct_binding
        .controls
        .iter()
        .find(|receipt| receipt.kind == GateCBindingControlKind::Assign)
    else {
        return false;
    };
    let Some(direct_reopen) = direct_binding
        .controls
        .iter()
        .find(|receipt| receipt.kind == GateCBindingControlKind::Reopen)
    else {
        return false;
    };
    if !gate_c_same_editor_visit(active_identity, &direct_reopen.identity)
        || direct_assignment.trace_sequence >= direct_reopen.trace_sequence
    {
        return false;
    }
    let same_owner_visit = |left: &GateCEditorIdentity, right: &GateCEditorIdentity| {
        left.surface == right.surface
            && left.session_id == right.session_id
            && left.draft_generation == right.draft_generation
            && left.stable_target_digest == right.stable_target_digest
            && left.editor_epoch == right.editor_epoch
    };
    let Some((_, exact_binding)) = packet
        .bindings
        .iter()
        .enumerate()
        .filter(|(_, binding)| {
            binding.kind == GateCBindingKind::ExactCommand
                && binding.route == GateCBindingRoute::PropertiesStaged
                && binding.controls.iter().any(|reopen| {
                    reopen.kind == GateCBindingControlKind::Reopen
                        && reopen.trace_sequence < direct_assignment.trace_sequence
                        && same_owner_visit(&reopen.identity, &direct_assignment.identity)
                })
        })
        .max_by_key(|(_, binding)| {
            binding
                .controls
                .iter()
                .find(|receipt| receipt.kind == GateCBindingControlKind::Reopen)
                .map_or(0, |receipt| receipt.trace_sequence)
        })
    else {
        return false;
    };
    let Some(exact_reopen) = exact_binding
        .controls
        .iter()
        .find(|receipt| receipt.kind == GateCBindingControlKind::Reopen)
    else {
        return false;
    };
    if exact_reopen.trace_sequence >= direct_assignment.trace_sequence
        || direct_binding.previous_binding_digest != exact_binding.expected_binding_digest
        || exact_reopen.identity.binding_digest != direct_binding.previous_binding_digest
        || !same_owner_visit(&exact_reopen.identity, &direct_assignment.identity)
    {
        return false;
    }

    // Undo/Redo/Save can rebind the Inspector after a document generation
    // change. Every retained transaction receipt owns a required control;
    // select all of those visits before trimming their dependencies.
    let retained_visits = exact_binding
        .controls
        .iter()
        .chain(&direct_binding.controls)
        .map(|receipt| receipt.identity.clone())
        .collect::<Vec<_>>();
    let identity_is_in_tail = |identity: &GateCEditorIdentity| {
        retained_visits.iter().any(|retained| {
            identity.surface == retained.surface
                && identity.session_id == retained.session_id
                && identity.draft_generation == retained.draft_generation
                && identity.stable_target_digest == retained.stable_target_digest
                && identity.editor_epoch == retained.editor_epoch
        })
    };
    let retained_bindings = vec![exact_binding.clone(), direct_binding.clone()];

    packet.bindings = retained_bindings;
    packet
        .searches
        .retain(|search| identity_is_in_tail(&search.identity));
    packet
        .incomplete_searches
        .retain(|search| identity_is_in_tail(&search.identity));
    packet
        .provider_lifecycle
        .retain(|event| identity_is_in_tail(&event.identity));
    packet
        .ordered_results
        .retain(|row| identity_is_in_tail(&row.identity));
    packet.inspector_text_edits.retain(|edit| {
        retained_visits.iter().any(|identity| {
            edit.session_id == identity.session_id
                && edit.target_digest == identity.stable_target_digest
        })
    });
    packet
        .controls
        .retain(|control| identity_is_in_tail(&control.identity));

    let retained_sequences = packet
        .controls
        .iter()
        .filter(|control| gate_c_failed_d04_control_is_required(control, packet))
        .map(|control| control.trace_sequence)
        .collect::<std::collections::BTreeSet<_>>();
    packet
        .controls
        .retain(|control| retained_sequences.contains(&control.trace_sequence));
    true
}

fn gate_c_passed_query_edit_is_observed(
    edit: &GateCControlEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    if edit.control != "query_field"
        || !edit.changed
        || !edit.visible
        || !edit.enabled
        || edit.value_digest == 0
        || edit.value_digest != edit.query_digest
        || edit.query_digest != edit.identity.query_digest
        || edit.binding_digest == 0
    {
        return false;
    }

    packet.controls.iter().any(|search_control| {
        gate_c_inspector_edit_matches_later_search(edit, search_control)
            && packet.searches.iter().any(|search| {
                search.identity == search_control.identity
                    && search.surface == search_control.identity.surface
                    && search.query_digest == edit.query_digest
                    && search.query_binding_digest == search_control.binding_digest
                    && search.search_control_sequence == search_control.trace_sequence
                    && search.search_control_sequence > edit.trace_sequence
                    && gate_c_search_is_valid(search, packet)
            })
    })
}

fn gate_c_d09_held_query_edit_is_observed(
    edit: &GateCControlEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    if packet.case_id != "D09"
        || edit.control != "query_field"
        || !edit.changed
        || !edit.visible
        || !edit.enabled
        || edit.value_digest == 0
        || edit.value_digest != edit.query_digest
        || edit.query_digest != edit.identity.query_digest
        || edit.binding_digest == 0
        || gate_c_case_contract_is_valid(packet).is_err()
    {
        return false;
    }

    // D09 deliberately retires both held Search requests before their results
    // can settle. The pre-Search edit is witnessed by that exact request's
    // complete lifecycle, while the existing D09 contract proves Keep,
    // Discard, reopen, and rejection against the actual authoring boundaries.
    packet.controls.iter().any(|search| {
        if !gate_c_inspector_edit_matches_later_search(edit, search) {
            return false;
        }
        let edges = [
            GateCProviderEdge::Queued,
            GateCProviderEdge::WorkerStarted,
            GateCProviderEdge::Retired,
            GateCProviderEdge::WorkerCompleted,
            GateCProviderEdge::Rejected,
        ]
        .map(|edge| {
            gate_c_provider_request_edge(packet, &search.identity, edit.query_digest, edge)
        });
        let mut previous = search.trace_sequence;
        edges.into_iter().all(|event| {
            event.is_some_and(|event| {
                let ordered = event.trace_sequence > previous;
                previous = event.trace_sequence;
                ordered
            })
        })
    })
}

fn gate_c_failed_edit_has_linked_inspector_attempt(
    control: &GateCControlEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    packet.incomplete_searches.iter().any(|request| {
        request.identity.session_id == control.identity.session_id
            && request.identity.draft_generation == control.identity.draft_generation
            && request.identity.stable_target_digest == control.identity.stable_target_digest
            && request.identity.editor_epoch == control.identity.editor_epoch
            && request.identity.edit_generation == control.identity.edit_generation
            && request.identity.query_generation == control.identity.query_generation
            && request.identity.query_request_generation
                == control.identity.query_request_generation
            && request.identity.test_request_generation == control.identity.test_request_generation
            && request.identity.search_request_generation
                > control.identity.search_request_generation
    }) || (control.identity.surface == GateCSurface::Inspector
        && packet.controls.iter().any(|search| {
            gate_c_inspector_edit_tracks_search_attempt(control, search, true)
                && packet.provider_lifecycle.iter().any(|event| {
                    event.kind == GateCProviderKind::Search
                        && event.edge == GateCProviderEdge::Queued
                        && event.identity == search.identity
                        && event.query_digest == search.query_digest
                        && event.binding_digest == 0
                        && event.trace_sequence > search.trace_sequence
                })
        }))
        || packet.controls.iter().any(|search| {
            search.identity.surface == GateCSurface::Inspector
                && gate_c_inspector_edit_tracks_search_attempt(control, search, false)
                && packet.provider_lifecycle.iter().any(|event| {
                    event.kind == GateCProviderKind::Search
                        && event.edge == GateCProviderEdge::Queued
                        && event.identity == search.identity
                        && event.query_digest == search.query_digest
                        && event.binding_digest == 0
                        && event.trace_sequence > search.trace_sequence
                })
        })
}

fn gate_c_inspector_edit_matches_later_search(
    edit: &GateCControlEvidence,
    search: &GateCControlEvidence,
) -> bool {
    gate_c_inspector_edit_matches_later_search_with_surface(edit, search, true)
}

fn gate_c_inspector_edit_matches_later_search_with_surface(
    edit: &GateCControlEvidence,
    search: &GateCControlEvidence,
    require_same_surface: bool,
) -> bool {
    if edit.control != "query_field"
        || search.control != "search"
        || !edit.changed
        || !search.clicked
        || !search.enabled
        || !search.visible
        || search.trace_sequence <= edit.trace_sequence
        || edit.query_digest == 0
        || search.query_digest != edit.query_digest
        || edit.binding_digest == 0
        || search.binding_digest != edit.binding_digest
    {
        return false;
    }
    let mut expected_request = edit.identity.clone();
    if !require_same_surface {
        expected_request.surface = search.identity.surface;
    }
    expected_request.search_request_generation = search.identity.search_request_generation;
    search.identity == expected_request
        && search.identity.search_request_generation > edit.identity.search_request_generation
}

fn gate_c_inspector_edit_tracks_search_attempt(
    edit: &GateCControlEvidence,
    search: &GateCControlEvidence,
    require_same_surface: bool,
) -> bool {
    if edit.control != "query_field"
        || search.control != "search"
        || !edit.changed
        || !search.clicked
        || !search.enabled
        || !search.visible
        || search.trace_sequence <= edit.trace_sequence
        || edit.query_digest == 0
        || search.query_digest != edit.query_digest
        || edit.binding_digest == 0
        || search.binding_digest != edit.binding_digest
    {
        return false;
    }
    let mut expected_request = edit.identity.clone();
    if !require_same_surface {
        expected_request.surface = search.identity.surface;
    }
    expected_request.search_request_generation = search.identity.search_request_generation;
    search.identity == expected_request
        && search.identity.search_request_generation >= edit.identity.search_request_generation
}

fn gate_c_failed_partial_query_edit_is_observed(
    control: &GateCControlEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    let identity = &control.identity;
    if control.control != "query_field"
        || !control.changed
        || !control.visible
        || !control.enabled
        || control.value_digest == 0
        || control.value_digest != control.query_digest
        || control.query_digest != identity.query_digest
        || control.trace_sequence == 0
    {
        return false;
    }
    let same_owner = |previous: &GateCEditorIdentity| {
        previous.surface == identity.surface
            && previous.session_id == identity.session_id
            && previous.draft_generation == identity.draft_generation
            && previous.stable_target_digest == identity.stable_target_digest
            && previous.editor_epoch == identity.editor_epoch
            && previous.binding_digest == identity.binding_digest
            && previous.edit_generation < identity.edit_generation
            && previous.query_generation < identity.query_generation
            && previous.query_request_generation <= identity.query_request_generation
            && previous.search_request_generation <= identity.search_request_generation
            && previous.test_request_generation <= identity.test_request_generation
            && previous.query_digest != identity.query_digest
    };
    packet.editor_identity.as_ref().is_some_and(same_owner)
        || packet.controls.iter().any(|previous| {
            previous.trace_sequence < control.trace_sequence && same_owner(&previous.identity)
        })
}

fn gate_c_failed_inspector_search_edit_is_observed(
    control: &GateCControlEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    let identity = &control.identity;
    if control.control != "query_field"
        || identity.surface != GateCSurface::Inspector
        || !control.changed
        || !control.visible
        || !control.enabled
        || control.value_digest == 0
        || control.value_digest != control.query_digest
        || control.query_digest != identity.query_digest
        || control.binding_digest == 0
        || control.trace_sequence == 0
    {
        return false;
    }

    let later_search = packet
        .controls
        .iter()
        .find(|search| gate_c_inspector_edit_matches_later_search(control, search));
    let Some(search_control) = later_search else {
        return false;
    };

    let pending_request_is_valid = packet.incomplete_searches.iter().any(|request| {
        if request.reason != GateCSearchIncompleteReason::TimedOutPending
            || request.search_control_sequence != search_control.trace_sequence
            || request.identity != search_control.identity
            || request.query_digest != control.query_digest
            || request.query_binding_digest != search_control.binding_digest
        {
            return false;
        }
        gate_c_incomplete_search_is_valid(request, packet)
    });

    pending_request_is_valid
        || gate_c_failed_completed_inspector_search_is_observed(control, search_control, packet)
}

fn gate_c_failed_completed_inspector_search_is_observed(
    edit: &GateCControlEvidence,
    search_control: &GateCControlEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    if let Some(search) = packet.searches.iter().find(|search| {
        search.identity == search_control.identity
            && search.query_digest == search_control.query_digest
    }) {
        return search.search_control_sequence == search_control.trace_sequence
            && search.query_binding_digest == search_control.binding_digest
            && gate_c_inspector_edit_matches_later_search(edit, search_control)
            && gate_c_passed_query_edit_is_observed(edit, packet);
    }
    let queued = gate_c_provider_request_edge(
        packet,
        &search_control.identity,
        search_control.query_digest,
        GateCProviderEdge::Queued,
    );
    let started = gate_c_provider_request_edge(
        packet,
        &search_control.identity,
        search_control.query_digest,
        GateCProviderEdge::WorkerStarted,
    );
    let completed = gate_c_provider_request_edge(
        packet,
        &search_control.identity,
        search_control.query_digest,
        GateCProviderEdge::WorkerCompleted,
    );
    let applied = gate_c_provider_request_edge(
        packet,
        &search_control.identity,
        search_control.query_digest,
        GateCProviderEdge::Applied,
    );
    matches!((queued, started, completed, applied), (Some(queued), Some(started), Some(completed), Some(applied))
        if gate_c_inspector_edit_matches_later_search(edit, search_control)
            && queued.trace_sequence > search_control.trace_sequence
            && started.trace_sequence > queued.trace_sequence
            && completed.trace_sequence > started.trace_sequence
            && applied.trace_sequence > completed.trace_sequence)
}

fn gate_c_provider_identity_is_observed(
    event: &GateCProviderLifecycleEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    if packet.case_id == "Q14" && event.kind == GateCProviderKind::Search {
        return packet.searches.iter().any(|search| {
            search.identity == event.identity
                && search.query_digest == event.query_digest
                && event.trace_sequence > search.search_control_sequence
        }) || packet.q14.as_ref().is_some_and(|evidence| {
            evidence
                .operations
                .iter()
                .any(|operation| gate_c_q14_search_event_is_observed_by_operation(operation, event))
        }) || packet.q14_partial.as_ref().is_some_and(|evidence| {
            evidence
                .operations
                .iter()
                .any(|operation| gate_c_q14_search_event_is_observed_by_operation(operation, event))
        });
    }

    packet.searches.iter().any(|search| {
        event.kind == GateCProviderKind::Search
            && search.identity == event.identity
            && search.query_digest == event.query_digest
    }) || packet.controls.iter().any(|control| {
        event.kind == GateCProviderKind::Search
            && gate_c_search_control_matches_request(control, &event.identity, event.query_digest)
            && control.trace_sequence < event.trace_sequence
    }) || packet.controls.iter().any(|control| {
        event.kind == GateCProviderKind::Test
            && matches!(control.control.as_str(), "test" | "test_result")
            && control.identity == event.identity
            && control.query_digest == event.query_digest
            && control.binding_digest == event.binding_digest
    }) || packet
        .authoring_states
        .iter()
        .any(|state| state.action_editor.as_ref() == Some(&event.identity))
        || packet.q14.as_ref().is_some_and(|evidence| {
            evidence.operations.iter().any(|operation| {
                operation.identity == event.identity
                    || gate_c_q14_search_event_is_derived_from_operation(operation, event)
            }) || evidence.baseline.action_editor.as_ref() == Some(&event.identity)
                || evidence.terminal.action_editor.as_ref() == Some(&event.identity)
        })
        || packet.q14_partial.as_ref().is_some_and(|evidence| {
            evidence.operations.iter().any(|operation| {
                operation.identity == event.identity
                    || gate_c_q14_search_event_is_derived_from_operation(operation, event)
            }) || evidence.baseline.action_editor.as_ref() == Some(&event.identity)
        })
        || packet.controls.iter().any(|control| {
            control.identity == event.identity
                && control.query_digest == event.query_digest
                && (control.control == "close"
                    || control.control == "keep_editing"
                    || control.control == "discard"
                    || control.control == "reopen")
        })
}

fn gate_c_q14_search_event_is_derived_from_operation(
    operation: &GateCQ14OperationEvidence,
    event: &GateCProviderLifecycleEvidence,
) -> bool {
    event.kind == GateCProviderKind::Search
        && matches!(
            operation.kind,
            GateCQ14OperationKind::QueryEdit | GateCQ14OperationKind::EnterSearch
        )
        && operation.query_digest == event.query_digest
        && event.binding_digest == 0
        && event.trace_sequence > operation.trace_sequence
        && gate_c_q14_search_request_identity_matches(&operation.identity, &event.identity)
}

fn gate_c_q14_search_event_is_observed_by_operation(
    operation: &GateCQ14OperationEvidence,
    event: &GateCProviderLifecycleEvidence,
) -> bool {
    match operation.kind {
        GateCQ14OperationKind::QueryEdit | GateCQ14OperationKind::EnterSearch => {
            gate_c_q14_search_event_is_derived_from_operation(operation, event)
        }
        GateCQ14OperationKind::Search => {
            event.kind == GateCProviderKind::Search
                && operation.identity == event.identity
                && operation.query_digest == event.query_digest
                && event.binding_digest == 0
                && event.trace_sequence > operation.trace_sequence
        }
        GateCQ14OperationKind::InspectorAssignment => {
            gate_c_q14_search_event_is_post_assignment_refresh(operation, event)
        }
        _ => false,
    }
}

fn gate_c_q14_search_event_is_post_assignment_refresh(
    operation: &GateCQ14OperationEvidence,
    event: &GateCProviderLifecycleEvidence,
) -> bool {
    if operation.kind != GateCQ14OperationKind::InspectorAssignment
        || operation.identity.surface != GateCSurface::Inspector
        || operation.query_digest != operation.identity.query_digest
        || event.kind != GateCProviderKind::Search
        || event.query_digest != operation.query_digest
        || event.binding_digest != 0
        || operation.binding_digest == 0
        || operation.binding_digest == operation.identity.binding_digest
        || event.trace_sequence <= operation.trace_sequence
    {
        return false;
    }

    let Some(draft_generation) = operation.identity.draft_generation.checked_add(1) else {
        return false;
    };
    let Some(editor_epoch) = operation.identity.editor_epoch.checked_add(1) else {
        return false;
    };
    let Some(edit_generation) = operation.identity.edit_generation.checked_add(1) else {
        return false;
    };
    let Some(query_request_generation) = operation.identity.query_request_generation.checked_add(1)
    else {
        return false;
    };
    let Some(search_request_generation) =
        operation.identity.search_request_generation.checked_add(2)
    else {
        return false;
    };
    let Some(test_request_generation) = operation.identity.test_request_generation.checked_add(1)
    else {
        return false;
    };

    let mut expected = operation.identity.clone();
    expected.draft_generation = draft_generation;
    expected.editor_epoch = editor_epoch;
    expected.edit_generation = edit_generation;
    // Binding rebind advances Search once; its immediate debounce emission advances it again.
    expected.query_request_generation = query_request_generation;
    expected.search_request_generation = search_request_generation;
    expected.test_request_generation = test_request_generation;
    expected.binding_digest = operation.binding_digest;
    event.identity == expected
}

fn gate_c_provider_request_edge<'a>(
    packet: &'a GateCCaseEvidence,
    identity: &GateCEditorIdentity,
    query_digest: u64,
    edge: GateCProviderEdge,
) -> Option<&'a GateCProviderLifecycleEvidence> {
    packet.provider_lifecycle.iter().find(|event| {
        event.kind == GateCProviderKind::Search
            && event.edge == edge
            && event.identity == *identity
            && event.query_digest == query_digest
            && event.binding_digest == 0
    })
}

fn gate_c_search_control_matches_request(
    control: &GateCControlEvidence,
    identity: &GateCEditorIdentity,
    query_digest: u64,
) -> bool {
    control.control == "search"
        && control.identity == *identity
        && control.query_digest == query_digest
}

fn gate_c_clicked_search_control_precedes_request(
    packet: &GateCCaseEvidence,
    identity: &GateCEditorIdentity,
    query_digest: u64,
    queued_sequence: u64,
) -> bool {
    packet.controls.iter().any(|control| {
        gate_c_search_control_matches_request(control, identity, query_digest)
            && control.clicked
            && control.binding_digest != 0
            && control.trace_sequence < queued_sequence
    })
}

fn gate_c_result_row_is_valid(row: &GateCResultRowEvidence) -> bool {
    gate_c_result_order_is_valid(row.order, MAX_GATE_C_RESULTS)
        && gate_c_editor_identity_is_valid(&row.identity)
        && row.identity.surface == row.surface
        && row.search_completion_sequence > 0
        && row.observed_trace_sequence > row.search_completion_sequence
        && row.identity.query_digest > 0
        && row.target_digest != 0
        && row.title_digest != 0
        && row.type_digest != 0
        && row.disambiguator_digest != 0
        && row.action_digest != 0
        && row.binding_digest != 0
        && gate_c_rect_is_visible(row.bounds, row.client_size)
        && row.displayed_text_digest != 0
        && row.fully_visible
        && gate_c_rect_is_visible(row.full_bounds, row.client_size)
        && row.readable
}

fn gate_c_result_row_is_correlated(
    row: &GateCResultRowEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    let settled_search_matches = packet.searches.iter().any(|search| {
        search.identity == row.identity
            && search.surface == row.surface
            && search.worker_terminal_sequence == row.search_completion_sequence
            && search.observed_trace_sequence >= row.observed_trace_sequence
            && gate_c_result_order_is_valid(row.order, search.result_count)
    });
    let q14_operations = packet
        .q14
        .as_ref()
        .map(|evidence| evidence.operations.as_slice())
        .or_else(|| {
            packet
                .q14_partial
                .as_ref()
                .map(|evidence| evidence.operations.as_slice())
        });
    let q14_entered_search_matches = q14_operations.is_some_and(|operations| {
        let entered = operations.iter().find(|operation| {
            operation.kind == GateCQ14OperationKind::EnterSearch
                && gate_c_q14_search_request_identity_matches(&operation.identity, &row.identity)
                && operation.query_digest == row.identity.query_digest
        });
        let selected = operations.iter().any(|operation| {
            operation.kind == GateCQ14OperationKind::SelectResult
                && operation.identity == row.identity
                && operation.trace_sequence > row.observed_trace_sequence
        });
        let failed_enter_row_prefix = packet.q14.is_none()
            && packet
                .q14_partial
                .as_ref()
                .is_some_and(|partial| partial.terminal.is_none())
            && !operations.iter().any(|operation| {
                operation.kind == GateCQ14OperationKind::SelectResult
                    && operation.identity == row.identity
            });
        let queued = gate_c_provider_request_edge(
            packet,
            &row.identity,
            row.identity.query_digest,
            GateCProviderEdge::Queued,
        );
        let started = gate_c_provider_request_edge(
            packet,
            &row.identity,
            row.identity.query_digest,
            GateCProviderEdge::WorkerStarted,
        );
        let completed = gate_c_provider_request_edge(
            packet,
            &row.identity,
            row.identity.query_digest,
            GateCProviderEdge::WorkerCompleted,
        );
        let applied = gate_c_provider_request_edge(
            packet,
            &row.identity,
            row.identity.query_digest,
            GateCProviderEdge::Applied,
        );
        entered
            .zip(queued)
            .zip(started)
            .zip(completed)
            .zip(applied)
            .is_some_and(|((((entered, queued), started), completed), applied)| {
                (selected || failed_enter_row_prefix)
                    && entered.trace_sequence < queued.trace_sequence
                    && queued.trace_sequence < started.trace_sequence
                    && started.trace_sequence < completed.trace_sequence
                    && completed.trace_sequence == row.search_completion_sequence
                    && completed.trace_sequence < applied.trace_sequence
                    && applied.trace_sequence < row.observed_trace_sequence
            })
    });
    let q14_mode_lineage_matches = q14_operations
        .is_some_and(|operations| gate_c_q14_mode_row_lineage_matches(row, packet, operations));
    let q14_entered_search_matches = q14_entered_search_matches || q14_mode_lineage_matches;
    (settled_search_matches || q14_entered_search_matches)
        && (!matches!(packet.case_id.as_str(), "D01" | "D02" | "Q14")
            || gate_c_fixture_displayed_label_matches(row))
        && packet.controls.iter().any(|control| {
            let control_kind_and_time_match = if q14_entered_search_matches {
                control.control == "result_target"
                    && control.trace_sequence == row.observed_trace_sequence
            } else {
                match control.control.as_str() {
                    "result_target" => control.trace_sequence == row.observed_trace_sequence,
                    "result" | "contextual_target" => {
                        control.trace_sequence < row.observed_trace_sequence
                    }
                    _ => false,
                }
            };
            matches!(
                control.control.as_str(),
                "result" | "result_target" | "contextual_target"
            ) && control.identity == row.identity
                && gate_c_result_control_index_matches_order(control.control_index, row.order)
                && control.target_digest == row.target_digest
                && control.title_digest == row.title_digest
                && control.type_digest == row.type_digest
                && control.disambiguator_digest == row.disambiguator_digest
                && control.action_digest == row.action_digest
                && control.binding_digest == row.binding_digest
                && control.displayed_text_digest == row.displayed_text_digest
                && control.readable_text_digest == Some(row.displayed_text_digest)
                && control.fully_visible
                && control_kind_and_time_match
        })
}

fn gate_c_q14_mode_row_lineage_matches(
    row: &GateCResultRowEvidence,
    packet: &GateCCaseEvidence,
    operations: &[GateCQ14OperationEvidence],
) -> bool {
    let same_row_identity = |first: &GateCEditorIdentity, second: &GateCEditorIdentity| {
        first.surface == second.surface
            && first.session_id == second.session_id
            && first.draft_generation == second.draft_generation
            && first.stable_target_digest == second.stable_target_digest
            && first.editor_epoch == second.editor_epoch
            && first.query_generation == second.query_generation
            && first.query_request_generation == second.query_request_generation
            && first.search_request_generation == second.search_request_generation
            && first.test_request_generation == second.test_request_generation
            && first.query_digest == second.query_digest
            && first.binding_digest == second.binding_digest
            && second.edit_generation > first.edit_generation
    };
    let same_rendered_result = |first: &GateCResultRowEvidence, second: &GateCResultRowEvidence| {
        first.surface == second.surface
            && first.search_completion_sequence == second.search_completion_sequence
            && first.order == second.order
            && first.target_digest == second.target_digest
            && first.title_digest == second.title_digest
            && first.type_digest == second.type_digest
            && first.disambiguator_digest == second.disambiguator_digest
            && first.action_digest == second.action_digest
            && first.binding_digest == second.binding_digest
            && first.displayed_text_digest == second.displayed_text_digest
            && first.enabled == second.enabled
    };

    operations
        .iter()
        .filter(|operation| {
            operation.kind == GateCQ14OperationKind::ModeChange
                && operation.identity == row.identity
                && operation.query_digest == row.identity.query_digest
                && operation.input_method == GateCInputMethod::Toggle
                && operation.trace_sequence < row.observed_trace_sequence
                && gate_c_q14_operation_has_control(packet, operation)
        })
        .any(|mode_change| {
            operations
                .iter()
                .filter(|operation| {
                    operation.kind == GateCQ14OperationKind::SelectResult
                        && operation.trace_sequence < mode_change.trace_sequence
                        && operation.query_digest == row.identity.query_digest
                        && operation.input_method == GateCInputMethod::Pointer
                        && gate_c_q14_operation_has_control(packet, operation)
                })
                .any(|selection| {
                    let Some(selected_row) = packet.ordered_results.iter().find(|candidate| {
                        candidate.identity == selection.identity
                            && same_rendered_result(candidate, row)
                            && candidate.observed_trace_sequence < selection.trace_sequence
                    }) else {
                        return false;
                    };
                    if !same_row_identity(&selected_row.identity, &row.identity) {
                        return false;
                    }
                    if selection.binding_digest != selected_row.binding_digest {
                        return false;
                    }
                    let selected_control = packet.controls.iter().any(|control| {
                        control.control == "result_target"
                            && control.trace_sequence == selection.control_sequence
                            && control.identity == selection.identity
                            && control.clicked
                            && control.enabled
                            && control.query_digest == selection.query_digest
                            && control.binding_digest == selection.binding_digest
                            && gate_c_result_control_index_matches_order(
                                control.control_index,
                                selected_row.order,
                            )
                            && control.target_digest == selected_row.target_digest
                            && control.title_digest == selected_row.title_digest
                            && control.type_digest == selected_row.type_digest
                            && control.disambiguator_digest == selected_row.disambiguator_digest
                            && control.action_digest == selected_row.action_digest
                            && control.displayed_text_digest == selected_row.displayed_text_digest
                            && control.readable_text_digest
                                == Some(selected_row.displayed_text_digest)
                    });
                    let entered = operations.iter().find(|operation| {
                        operation.kind == GateCQ14OperationKind::EnterSearch
                            && operation.query_digest == selection.query_digest
                            && gate_c_q14_search_request_identity_matches(
                                &operation.identity,
                                &selection.identity,
                            )
                    });
                    let queued = gate_c_provider_request_edge(
                        packet,
                        &selected_row.identity,
                        selected_row.identity.query_digest,
                        GateCProviderEdge::Queued,
                    );
                    let started = gate_c_provider_request_edge(
                        packet,
                        &selected_row.identity,
                        selected_row.identity.query_digest,
                        GateCProviderEdge::WorkerStarted,
                    );
                    let completed = gate_c_provider_request_edge(
                        packet,
                        &selected_row.identity,
                        selected_row.identity.query_digest,
                        GateCProviderEdge::WorkerCompleted,
                    );
                    let applied = gate_c_provider_request_edge(
                        packet,
                        &selected_row.identity,
                        selected_row.identity.query_digest,
                        GateCProviderEdge::Applied,
                    );
                    selected_control
                        && entered
                            .zip(queued)
                            .zip(started)
                            .zip(completed)
                            .zip(applied)
                            .is_some_and(|((((entered, queued), started), completed), applied)| {
                                entered.trace_sequence < queued.trace_sequence
                                    && queued.trace_sequence < started.trace_sequence
                                    && started.trace_sequence < completed.trace_sequence
                                    && completed.trace_sequence
                                        == selected_row.search_completion_sequence
                                    && completed.trace_sequence < applied.trace_sequence
                                    && applied.trace_sequence < selected_row.observed_trace_sequence
                                    && selected_row.observed_trace_sequence
                                        < selection.trace_sequence
                                    && selection.trace_sequence < mode_change.trace_sequence
                                    && mode_change.trace_sequence < row.observed_trace_sequence
                            })
                })
        })
}

fn gate_c_fixture_displayed_label_matches(row: &GateCResultRowEvidence) -> bool {
    gate_c_expected_fixture_label_digests(row.target_digest, row.action_digest)
        .is_some_and(|(_, _, _, expected)| expected == row.displayed_text_digest)
}

fn gate_c_expected_fixture_label_digest(target_digest: u64, action_digest: u64) -> Option<u64> {
    gate_c_expected_fixture_label_digests(target_digest, action_digest)
        .map(|(_, _, _, digest)| digest)
}

fn gate_c_expected_fixture_label_digests(
    target_digest: u64,
    action_digest: u64,
) -> Option<(u64, u64, u64, u64)> {
    for slug in ["radial-acceptance-shared-a", "radial-acceptance-shared-b"] {
        let title = "Shared Acceptance Note";
        let target_type = "Note";
        let disambiguator = format!("slug {slug}");
        let note_target_digest = gate_c_trace_parts_digest(&[
            &format!("note:open:{slug}"),
            title,
            target_type,
            &disambiguator,
        ]);
        let note_action_digest = gate_c_trace_parts_digest(&[
            multi_launcher::universal_actions::action_ids::NOTE_EDIT.as_str(),
        ]);
        if target_digest == note_target_digest && action_digest == note_action_digest {
            let label = format!("{title} · {target_type} · {disambiguator} — Edit Note");
            return Some((
                gate_c_trace_text_digest(title),
                gate_c_trace_text_digest(target_type),
                gate_c_trace_text_digest(&disambiguator),
                gate_c_trace_text_digest(&label),
            ));
        }
    }

    for index in 0..32 {
        let (custom_target_digest, custom_action_digest) =
            gate_c_custom_action_semantic_identity(index);
        if target_digest == custom_target_digest && action_digest == custom_action_digest {
            let title = format!("Radial Acceptance Harmless Action {index:03}");
            let target_type = "Custom action";
            let disambiguator = format!("custom action {}", index + 3);
            let label = format!("{title} · {target_type} · {disambiguator} — Execute");
            return Some((
                gate_c_trace_text_digest(&title),
                gate_c_trace_text_digest(target_type),
                gate_c_trace_text_digest(&disambiguator),
                gate_c_trace_text_digest(&label),
            ));
        }
    }
    None
}

fn gate_c_custom_action_semantic_identity(index: usize) -> (u64, u64) {
    let command = format!("radial_acceptance_harmless_{index:03}");
    let title = format!("Radial Acceptance Harmless Action {index:03}");
    let disambiguator = format!("custom action {}", index + 3);
    let target_digest =
        gate_c_trace_parts_digest(&[&command, &title, "Custom action", &disambiguator]);
    let action_digest = gate_c_trace_parts_digest(&[
        multi_launcher::universal_actions::action_ids::RESULT_EXECUTE.as_str(),
    ]);
    (target_digest, action_digest)
}

fn gate_c_result_rows_are_unique(rows: &[GateCResultRowEvidence]) -> bool {
    rows.iter().enumerate().all(|(index, row)| {
        rows[..index].iter().all(|previous| {
            previous.surface != row.surface
                || previous.identity != row.identity
                || (previous.order != row.order
                    && (previous.target_digest != row.target_digest
                        || previous.action_digest != row.action_digest))
        })
    })
}

fn gate_c_record_ordered_result_row(
    packet: &mut GateCCaseEvidence,
    row: GateCResultRowEvidence,
) -> bool {
    let already_recorded = packet.ordered_results.iter().any(|existing| {
        existing.surface == row.surface
            && existing.identity == row.identity
            && existing.search_completion_sequence == row.search_completion_sequence
            && existing.order == row.order
            && existing.target_digest == row.target_digest
            && existing.action_digest == row.action_digest
    });
    if already_recorded {
        false
    } else {
        packet.ordered_results.push(row);
        true
    }
}

fn gate_c_pin_has_fresh_rendered_row(
    packet: &GateCCaseEvidence,
    pin: &GateCControlEvidence,
) -> bool {
    if pin.control != "pin_result" || !pin.clicked || !pin.enabled {
        return false;
    }
    packet.controls.iter().any(|row_control| {
        if row_control.control != "result_target"
            || row_control.trace_sequence >= pin.trace_sequence
            || row_control.control_index != pin.control_index
            || row_control.target_digest != pin.target_digest
            || row_control.action_digest != pin.action_digest
            || row_control.binding_digest == 0
            || row_control.displayed_text_digest == 0
            || row_control.readable_text_digest != Some(row_control.displayed_text_digest)
            || !row_control.visible
            || !row_control.fully_visible
            || row_control.bounds != row_control.full_bounds
            || !gate_c_rect_is_visible(row_control.bounds, row_control.client_size)
        {
            return false;
        }
        let row_identity = &row_control.identity;
        let pin_identity = &pin.identity;
        let same_editor_visit = pin_identity.surface == row_identity.surface
            && pin_identity.session_id == row_identity.session_id
            && pin_identity.draft_generation == row_identity.draft_generation
            && pin_identity.stable_target_digest == row_identity.stable_target_digest
            && pin_identity.editor_epoch == row_identity.editor_epoch
            && pin_identity.query_generation == row_identity.query_generation
            && pin_identity.query_request_generation == row_identity.query_request_generation
            && pin_identity.search_request_generation == row_identity.search_request_generation
            && pin_identity.test_request_generation == row_identity.test_request_generation
            && pin_identity.query_digest == row_identity.query_digest
            && (pin_identity.edit_generation == row_identity.edit_generation
                || pin_identity.edit_generation == row_identity.edit_generation.saturating_add(1))
            && (pin_identity.binding_digest == row_identity.binding_digest
                || pin_identity.binding_digest == row_control.binding_digest);
        same_editor_visit
            && packet.ordered_results.iter().any(|row| {
                row.identity == *row_identity
                    && row_control
                        .control_index
                        .and_then(|index| index.checked_add(1))
                        == Some(row.order)
                    && row.target_digest == row_control.target_digest
                    && row.action_digest == row_control.action_digest
                    && row.binding_digest == row_control.binding_digest
                    && row.displayed_text_digest == row_control.displayed_text_digest
                    && row.observed_trace_sequence < row_control.trace_sequence
                    && row.enabled
                    && row.fully_visible
                    && gate_c_fixture_displayed_label_matches(row)
            })
    })
}

fn gate_c_result_order_is_valid(order: usize, result_count: usize) -> bool {
    order > 0 && order <= result_count && order <= MAX_GATE_C_RESULTS
}

fn gate_c_result_control_index_matches_order(index: Option<usize>, order: usize) -> bool {
    index.and_then(|index| index.checked_add(1)) == Some(order)
}

fn gate_c_packet_session_is_anchored(packet: &GateCCaseEvidence) -> bool {
    let belongs_to_header = |identity: &GateCEditorIdentity| {
        identity.session_id == packet.session_id
            && identity.draft_generation == packet.draft_generation
    };
    packet.session_id > 0
        && packet.draft_generation > 0
        && packet
            .controls
            .iter()
            .all(|control| belongs_to_header(&control.identity))
        && packet
            .searches
            .iter()
            .all(|search| belongs_to_header(&search.identity))
        && packet
            .ordered_results
            .iter()
            .all(|row| belongs_to_header(&row.identity))
        && packet
            .provider_lifecycle
            .iter()
            .all(|event| belongs_to_header(&event.identity))
}

fn gate_c_authoring_state_is_valid(state: &GateCAuthoringStateEvidence) -> bool {
    state.request_id > 0
        && state.frame_ordinal > 0
        && state.trace_sequence > 0
        && state.trace_boundary_sequence > state.trace_sequence
        && state.root_state_digest != 0
        && state.history_digest != 0
        && state.usage_digest != 0
        && if state.editor_open {
            state.document_digest != 0
                && state.session_id > 0
                && state.generation > 0
                && (state.selected_cell_digest == 0 || state.selected_target_digest != 0)
                && !state.initial_snapshot_pending
                && state.action_editor.as_ref().is_none_or(|identity| {
                    gate_c_editor_identity_is_valid(identity)
                        && identity.session_id == state.session_id
                        && identity.draft_generation == state.generation
                        && identity.stable_target_digest == state.selected_target_digest
                        && identity.binding_digest == state.assigned_binding_digest
                })
                && state.action_editor.is_some()
                    == state.action_editor_authored_input_digest.is_some()
                && state
                    .action_editor_authored_input_digest
                    .is_none_or(|digest| digest != 0)
        } else {
            state.session_id == 0
                && state.generation == 0
                && state.selected_target_digest == 0
                && state.selected_cell_digest == 0
                && state.document_digest == 0
                && state.assigned_binding_digest == 0
                && state.properties_staged_digest.is_none()
                && !state.draft_dirty
                && !state.properties_dirty
                && state.undo_depth == 0
                && state.redo_depth == 0
                && !state.initial_snapshot_pending
                && state.action_editor.is_none()
                && state.action_editor_authored_input_digest.is_none()
                && !state.search_pending
                && !state.test_pending
        }
}

fn gate_c_same_authored_editor_state(
    left: &GateCAuthoringStateEvidence,
    right: &GateCAuthoringStateEvidence,
) -> bool {
    left.action_editor_authored_input_digest.is_some()
        && left.action_editor_authored_input_digest == right.action_editor_authored_input_digest
        && left
            .action_editor
            .as_ref()
            .zip(right.action_editor.as_ref())
            .is_some_and(|(left, right)| {
                left.surface == right.surface
                    && left.session_id == right.session_id
                    && left.draft_generation == right.draft_generation
                    && left.stable_target_digest == right.stable_target_digest
                    && left.query_digest == right.query_digest
                    && left.binding_digest == right.binding_digest
            })
}

fn gate_c_observation_boundaries_are_valid(packet: &GateCCaseEvidence) -> bool {
    let mut states = packet.authoring_states.iter().collect::<Vec<_>>();
    if let Some(q14) = packet.q14.as_ref() {
        states.extend([&q14.baseline, &q14.terminal]);
    } else if let Some(q14_partial) = packet.q14_partial.as_ref() {
        states.push(&q14_partial.baseline);
        states.extend(q14_partial.terminal.iter());
    }
    states.len() == packet.observation_boundaries.len()
        && states.iter().all(|state| {
            packet
                .observation_boundaries
                .iter()
                .filter(|boundary| gate_c_observation_pair_is_valid(state, boundary))
                .count()
                == 1
        })
        && packet.observation_boundaries.iter().all(|boundary| {
            boundary.trace_sequence > boundary.captured_trace_sequence
                && boundary.captured_trace_sequence > 0
                && boundary.request_id > 0
                && (boundary.phase == GateCObservationPhase::Baseline
                    && boundary.baseline_request_id.is_none()
                    || boundary.phase == GateCObservationPhase::Terminal
                        && boundary
                            .baseline_request_id
                            .is_some_and(|baseline_id| baseline_id < boundary.request_id))
                && states
                    .iter()
                    .any(|state| gate_c_observation_pair_is_valid(state, boundary))
        })
        && packet.insertions.iter().all(|insertion| {
            gate_c_insertion_observation_receipt_is_valid(&insertion.source_baseline_receipt)
                && gate_c_insertion_observation_receipt_is_valid(&insertion.source_owner_receipt)
                && gate_c_insertion_observation_receipt_is_valid(&insertion.outcome_receipt)
        })
}

fn gate_c_observation_pair_is_valid(
    state: &GateCAuthoringStateEvidence,
    boundary: &GateCObservationBoundaryEvidence,
) -> bool {
    let expected_phase = if state.baseline_request_id.is_some() {
        GateCObservationPhase::Terminal
    } else {
        GateCObservationPhase::Baseline
    };
    gate_c_authoring_state_is_valid(state)
        && boundary.trace_sequence > boundary.captured_trace_sequence
        && boundary.captured_trace_sequence > 0
        && boundary.request_id > 0
        && boundary.phase == expected_phase
        && boundary.request_id == state.request_id
        && boundary.baseline_request_id == state.baseline_request_id
        && boundary.captured_trace_sequence == state.trace_sequence
        && boundary.trace_sequence == state.trace_boundary_sequence
        && (boundary.phase == GateCObservationPhase::Baseline
            && boundary.baseline_request_id.is_none()
            || boundary.phase == GateCObservationPhase::Terminal
                && boundary
                    .baseline_request_id
                    .is_some_and(|baseline_id| baseline_id < boundary.request_id))
}

fn gate_c_insertion_observation_receipt_is_valid(
    receipt: &GateCInsertionObservationReceipt,
) -> bool {
    receipt.state.baseline_request_id.is_none()
        && gate_c_observation_pair_is_valid(&receipt.state, &receipt.boundary)
}

fn gate_c_search_is_valid(search: &GateCSearchEvidence, packet: &GateCCaseEvidence) -> bool {
    let matching_control = packet.controls.iter().any(|control| {
        control.control == "search"
            && control.clicked
            && control.trace_sequence == search.search_control_sequence
            && control.identity == search.identity
            && control.binding_digest == search.query_binding_digest
    });
    let matching_lifecycle = |sequence, edge| {
        packet.provider_lifecycle.iter().any(|event| {
            event.trace_sequence == sequence
                && event.edge == edge
                && event.kind == GateCProviderKind::Search
                && event.identity == search.identity
                && event.query_digest == search.query_digest
                && event.binding_digest == 0
        })
    };
    search.query_digest != 0
        && search.query_binding_digest != 0
        && search.query_digest == search.identity.query_digest
        && search.surface == search.identity.surface
        && search.search_control_sequence < search.queued_sequence
        && search.queued_sequence < search.worker_started_sequence
        && search.worker_started_sequence < search.worker_terminal_sequence
        && search.worker_terminal_sequence < search.observed_trace_sequence
        && search.observed_trace_sequence > 0
        && search.result_count > 0
        && search.result_count <= MAX_GATE_C_RESULTS
        && gate_c_result_order_is_valid(search.result_order, search.result_count)
        && search.target_digest != 0
        && search.action_digest != 0
        && search.settled
        && matching_control
        && matching_lifecycle(search.queued_sequence, GateCProviderEdge::Queued)
        && matching_lifecycle(
            search.worker_started_sequence,
            GateCProviderEdge::WorkerStarted,
        )
        && matching_lifecycle(
            search.worker_terminal_sequence,
            GateCProviderEdge::WorkerCompleted,
        )
        && packet.provider_lifecycle.iter().any(|event| {
            event.trace_sequence > search.worker_terminal_sequence
                && event.trace_sequence < search.observed_trace_sequence
                && event.edge == GateCProviderEdge::Applied
                && event.kind == GateCProviderKind::Search
                && event.identity == search.identity
                && event.query_digest == search.query_digest
                && event.binding_digest == 0
        })
        && packet.ordered_results.iter().any(|row| {
            row.surface == search.surface
                && row.identity == search.identity
                && row.search_completion_sequence == search.worker_terminal_sequence
                && row.observed_trace_sequence <= search.observed_trace_sequence
                && row.order == search.result_order
                && row.target_digest == search.target_digest
                && row.action_digest == search.action_digest
        })
}

fn gate_c_incomplete_search_is_valid(
    search: &GateCIncompleteSearchEvidence,
    packet: &GateCCaseEvidence,
) -> bool {
    let matching_control = packet.controls.iter().any(|control| {
        control.control == "search"
            && control.clicked
            && control.enabled
            && control.visible
            && control.trace_sequence == search.search_control_sequence
            && control.identity == search.identity
            && control.query_digest == search.query_digest
            && control.binding_digest == search.query_binding_digest
    });
    let matching_events = packet
        .provider_lifecycle
        .iter()
        .filter(|event| {
            event.kind == GateCProviderKind::Search
                && event.identity == search.identity
                && event.query_digest == search.query_digest
                && event.binding_digest == 0
        })
        .collect::<Vec<_>>();
    let event_sequences = matching_events
        .iter()
        .map(|event| event.trace_sequence)
        .collect::<Vec<_>>();
    let increasing = event_sequences.windows(2).all(|pair| pair[0] < pair[1]);
    let queued = matching_events
        .iter()
        .filter(|event| event.edge == GateCProviderEdge::Queued)
        .count();
    let retry_queued = matching_events
        .iter()
        .filter(|event| event.edge == GateCProviderEdge::RetryQueued)
        .count();
    let started = matching_events
        .iter()
        .filter(|event| event.edge == GateCProviderEdge::WorkerStarted)
        .count();
    let completed = matching_events
        .iter()
        .filter(|event| {
            matches!(
                event.edge,
                GateCProviderEdge::WorkerCompleted | GateCProviderEdge::WorkerFailed
            )
        })
        .count();
    let applied = matching_events
        .iter()
        .any(|event| event.edge == GateCProviderEdge::Applied);
    let pending_lifecycle_prefix_is_valid = queued == 1
        && retry_queued <= 1
        && started <= 1
        && completed <= 1
        && !applied
        && (retry_queued == 0
            || matching_events
                .iter()
                .find(|event| event.edge == GateCProviderEdge::RetryQueued)
                .zip(
                    matching_events
                        .iter()
                        .find(|event| event.edge == GateCProviderEdge::Queued),
                )
                .is_some_and(|(retry, queued)| queued.trace_sequence < retry.trace_sequence))
        && (started == 0
            || matching_events
                .iter()
                .find(|event| event.edge == GateCProviderEdge::WorkerStarted)
                .zip(
                    matching_events
                        .iter()
                        .find(|event| event.edge == GateCProviderEdge::Queued),
                )
                .is_some_and(|(started, queued)| queued.trace_sequence < started.trace_sequence))
        && (completed == 0
            || matching_events
                .iter()
                .find(|event| {
                    matches!(
                        event.edge,
                        GateCProviderEdge::WorkerCompleted | GateCProviderEdge::WorkerFailed
                    )
                })
                .zip(
                    matching_events
                        .iter()
                        .find(|event| event.edge == GateCProviderEdge::WorkerStarted),
                )
                .is_some_and(|(completed, started)| {
                    started.trace_sequence < completed.trace_sequence
                }));
    let lifecycle_prefix_is_valid = match search.reason {
        GateCSearchIncompleteReason::TimedOutBeforeQueued => matching_events.is_empty(),
        GateCSearchIncompleteReason::TimedOutPending => pending_lifecycle_prefix_is_valid,
    };
    gate_c_editor_identity_is_valid(&search.identity)
        && search.query_digest != 0
        && search.query_digest == search.identity.query_digest
        && search.query_binding_digest != 0
        && search.search_control_sequence > 0
        && search.observed_trace_sequence >= search.search_control_sequence
        && event_sequences == search.observed_edge_sequences
        && event_sequences.iter().all(|sequence| {
            *sequence > search.search_control_sequence
                && *sequence <= search.observed_trace_sequence
        })
        && increasing
        && lifecycle_prefix_is_valid
        && matching_control
}

fn gate_c_binding_is_valid(binding: &GateCBindingEvidence) -> bool {
    let typed_binding = match binding.kind {
        GateCBindingKind::PersistedReference => {
            gate_c_persisted_binding_identity_matches(binding)
                && binding.query_digest.is_none()
                && binding.query_mode.is_none()
                && binding.command_digest.is_none()
                && binding.arguments_digest.is_none()
        }
        GateCBindingKind::LauncherQuery => {
            binding.action_id_digest.is_none()
                && binding.target_reference_digest.is_none()
                && binding.query_digest.is_some_and(|digest| digest != 0)
                && binding.query_mode.is_some()
                && binding.command_digest.is_none()
                && binding.arguments_digest.is_none()
        }
        GateCBindingKind::ExactCommand => {
            binding.action_id_digest.is_none()
                && binding.target_reference_digest.is_none()
                && binding.query_digest.is_none()
                && binding.query_mode.is_none()
                && binding.command_digest.is_some_and(|digest| digest != 0)
                && binding.arguments_digest.is_some_and(|digest| digest != 0)
        }
    };
    let staged_state_matches_route = match binding.route {
        GateCBindingRoute::PropertiesStaged => {
            binding.document_staged_digest == binding.document_before_digest
                && binding.history_staged_digest == binding.history_before_digest
        }
        GateCBindingRoute::InspectorDirect => {
            binding.document_staged_digest == binding.document_applied_digest
                && binding.history_staged_digest == binding.history_applied_digest
        }
        GateCBindingRoute::RadialInsertion => {
            binding.document_staged_digest == binding.document_before_digest
                && binding.history_staged_digest == binding.history_before_digest
        }
    };
    let transaction = binding.destination_cell_digest != 0
        && binding.semantic_target_digest != 0
        && binding.semantic_action_digest != 0
        && binding.expected_binding_digest != 0
        && binding.previous_binding_digest != 0
        && binding.document_before_digest != 0
        && binding.history_before_digest != 0
        && staged_state_matches_route
        && binding.document_applied_digest != binding.document_before_digest
        && binding.history_applied_digest != 0
        && binding.history_applied_digest != binding.history_before_digest
        && binding.radial_save.as_ref().is_some_and(|save| {
            save.revision_before.checked_add(1) == Some(save.revision_after)
                && save.schema_version == multi_launcher::radial::model::CURRENT_SCHEMA_VERSION
                && save.normalized_content_digest == binding.document_applied_digest
                && binding.saved_document_digest != 0
                && binding.reopened_document_digest == binding.saved_document_digest
        })
        && binding.reopened_binding_digest == binding.expected_binding_digest
        && binding.inspector_binding_digest == binding.expected_binding_digest
        && binding.undo_document_digest == binding.document_before_digest
        && binding.redo_document_digest == binding.document_applied_digest
        && binding.undo_depth_before.checked_add(1) == Some(binding.undo_depth_after)
        && binding.mutation_count == 1
        && binding.saved_after_reopen
        && binding.inspector_matches_saved_binding
        && binding.undo_restores_before
        && binding.redo_restores_after;
    let receipt = |kind| binding.controls.iter().find(|control| control.kind == kind);
    let mutation_precedes_undo = match binding.route {
        GateCBindingRoute::PropertiesStaged => receipt(GateCBindingControlKind::Stage)
            .zip(receipt(GateCBindingControlKind::Apply))
            .zip(receipt(GateCBindingControlKind::Undo))
            .is_some_and(|((stage, apply), undo)| {
                stage.trace_sequence < apply.trace_sequence
                    && apply.trace_sequence < undo.trace_sequence
            }),
        GateCBindingRoute::InspectorDirect => receipt(GateCBindingControlKind::Assign)
            .zip(receipt(GateCBindingControlKind::Undo))
            .is_some_and(|(assign, undo)| assign.trace_sequence < undo.trace_sequence),
        GateCBindingRoute::RadialInsertion => true,
    };
    let expected_receipt_count = match binding.route {
        GateCBindingRoute::PropertiesStaged => 6,
        GateCBindingRoute::InspectorDirect => 5,
        GateCBindingRoute::RadialInsertion => 0,
    };
    let receipt_context_is_current = binding.controls.iter().all(|control| {
        let owner_click = matches!(
            control.kind,
            GateCBindingControlKind::Apply
                | GateCBindingControlKind::Undo
                | GateCBindingControlKind::Redo
                | GateCBindingControlKind::Save
        );
        if owner_click {
            control.owner_session_id == Some(control.identity.session_id)
                && control
                    .owner_generation
                    .is_some_and(|generation| generation > 0)
        } else {
            control.owner_session_id.is_none() && control.owner_generation.is_none()
        }
    });
    let reopened_in_fresh_inspector =
        receipt(GateCBindingControlKind::Reopen).is_some_and(|reopen| {
            binding.controls.first().is_some_and(|first| {
                reopen.surface == GateCSurface::Inspector
                    && reopen.identity.surface == GateCSurface::Inspector
                    && reopen.identity.session_id != first.identity.session_id
                    && reopen.identity.stable_target_digest == first.identity.stable_target_digest
            })
        });
    let editor_receipts_are_correlated = binding.controls.len() == expected_receipt_count
        && binding.controls.len() <= 8
        && receipt_context_is_current
        && (binding.route == GateCBindingRoute::RadialInsertion || reopened_in_fresh_inspector)
        && binding.controls.iter().all(|control| {
            binding
                .controls
                .iter()
                .filter(|candidate| candidate.kind == control.kind)
                .count()
                == 1
        })
        && binding.controls.iter().all(|control| {
            control.trace_sequence > 0
                && gate_c_editor_identity_is_valid(&control.identity)
                && control.binding_digest
                    == if control.kind == GateCBindingControlKind::Undo {
                        binding.previous_binding_digest
                    } else {
                        binding.expected_binding_digest
                    }
                && control.document_digest_after != 0
        })
        && binding
            .controls
            .windows(2)
            .all(|pair| pair[0].trace_sequence < pair[1].trace_sequence)
        && match binding.route {
            GateCBindingRoute::PropertiesStaged | GateCBindingRoute::InspectorDirect => {
                receipt(GateCBindingControlKind::Save).is_some_and(|control| {
                    control.document_digest_after == binding.saved_document_digest
                }) && receipt(GateCBindingControlKind::Reopen).is_some_and(|control| {
                    control.document_digest_after == binding.reopened_document_digest
                }) && receipt(GateCBindingControlKind::Undo).is_some_and(|control| {
                    control.document_digest_after == binding.undo_document_digest
                }) && receipt(GateCBindingControlKind::Redo).is_some_and(|control| {
                    control.document_digest_after == binding.redo_document_digest
                }) && receipt(GateCBindingControlKind::Undo)
                    .zip(receipt(GateCBindingControlKind::Redo))
                    .zip(receipt(GateCBindingControlKind::Save))
                    .zip(receipt(GateCBindingControlKind::Reopen))
                    .is_some_and(|(((undo, redo), save), reopen)| {
                        undo.trace_sequence < redo.trace_sequence
                            && redo.trace_sequence < save.trace_sequence
                            && save.trace_sequence < reopen.trace_sequence
                    })
            }
            GateCBindingRoute::RadialInsertion => binding.controls.is_empty(),
        };
    let route_is_correlated = match binding.route {
        GateCBindingRoute::PropertiesStaged => {
            receipt(GateCBindingControlKind::Stage).is_some_and(|control| {
                control.document_digest_after == binding.document_before_digest
            }) && receipt(GateCBindingControlKind::Apply).is_some_and(|control| {
                control.document_digest_after == binding.document_applied_digest
            }) && receipt(GateCBindingControlKind::Assign).is_none()
        }
        GateCBindingRoute::InspectorDirect => {
            receipt(GateCBindingControlKind::Assign).is_some_and(|control| {
                control.document_digest_after == binding.document_applied_digest
            }) && receipt(GateCBindingControlKind::Stage).is_none()
                && receipt(GateCBindingControlKind::Apply).is_none()
        }
        GateCBindingRoute::RadialInsertion => binding.controls.is_empty(),
    };
    transaction
        && typed_binding
        && editor_receipts_are_correlated
        && route_is_correlated
        && mutation_precedes_undo
}

fn gate_c_reused_authoring_state_is_preserved(
    baseline: &GateCAuthoringStateEvidence,
    owner: &GateCAuthoringStateEvidence,
) -> bool {
    baseline.editor_open
        && owner.editor_open
        && baseline.session_id == owner.session_id
        && baseline.generation == owner.generation
        && baseline.selected_target_digest == owner.selected_target_digest
        && baseline.selected_cell_digest == owner.selected_cell_digest
        && baseline.document_digest == owner.document_digest
        && baseline.assigned_binding_digest == owner.assigned_binding_digest
        && baseline.properties_staged_digest == owner.properties_staged_digest
        && baseline.draft_dirty == owner.draft_dirty
        && baseline.properties_dirty == owner.properties_dirty
        && baseline.undo_depth == owner.undo_depth
        && baseline.redo_depth == owner.redo_depth
        && baseline.action_editor_authored_input_digest == owner.action_editor_authored_input_digest
        && baseline.history_entries == owner.history_entries
        && baseline.history_keys == owner.history_keys
        && baseline.history_digest == owner.history_digest
        && baseline.usage_entries == owner.usage_entries
        && baseline.usage_digest == owner.usage_digest
}

fn gate_c_insertion_widget_geometry_is_valid(control: &GateCInsertionControlEvidence) -> bool {
    match control.widget_part {
        GateCInsertionWidgetPart::None => {
            control.bounds == [0; 4]
                && control.full_bounds == [0; 4]
                && control.client_size == [0; 2]
                && !control.visible
                && !control.fully_visible
        }
        part => {
            let control_kind_matches = match part {
                GateCInsertionWidgetPart::None => false,
                GateCInsertionWidgetPart::Selector | GateCInsertionWidgetPart::Option => matches!(
                    control.kind,
                    GateCInsertionControlKind::DestinationMenu
                        | GateCInsertionControlKind::DestinationRing
                        | GateCInsertionControlKind::DestinationCell
                ),
                GateCInsertionWidgetPart::Button => !matches!(
                    control.kind,
                    GateCInsertionControlKind::AddToRadial
                        | GateCInsertionControlKind::DestinationMenu
                        | GateCInsertionControlKind::DestinationRing
                        | GateCInsertionControlKind::DestinationCell
                        | GateCInsertionControlKind::Save
                        | GateCInsertionControlKind::Reopen
                        | GateCInsertionControlKind::Undo
                        | GateCInsertionControlKind::Redo
                ),
            };
            let visible = gate_c_rect_is_visible(control.bounds, control.client_size);
            let full_rect_valid = control.full_bounds[0] >= 0
                && control.full_bounds[1] >= 0
                && control.full_bounds[2] > control.full_bounds[0]
                && control.full_bounds[3] > control.full_bounds[1]
                && control.full_bounds[2] <= control.client_size[0]
                && control.full_bounds[3] <= control.client_size[1];
            control_kind_matches
                && visible == control.visible
                && visible
                && full_rect_valid
                && control.fully_visible == (visible && control.full_bounds == control.bounds)
                && (!control.clicked || (control.enabled && control.fully_visible))
                && match control.kind {
                    GateCInsertionControlKind::DestinationMenu => {
                        control.destination_menu_digest != 0
                            && (control.destination_ring_digest != 0
                                || control.destination_cell_digest == 0)
                            && (control.destination_cell_digest == 0
                                || control.destination_ring_digest != 0)
                    }
                    GateCInsertionControlKind::DestinationRing => {
                        control.destination_menu_digest != 0
                            && control.destination_ring_digest != 0
                            && (control.destination_cell_digest == 0
                                || control.destination_ring_digest != 0)
                    }
                    GateCInsertionControlKind::DestinationCell => {
                        control.destination_menu_digest != 0
                            && control.destination_ring_digest != 0
                            && control.destination_cell_digest != 0
                    }
                    _ => {
                        part == GateCInsertionWidgetPart::Button
                            && control.destination_menu_digest != 0
                            && control.destination_ring_digest != 0
                            && control.destination_cell_digest != 0
                    }
                }
        }
    }
}

fn gate_c_compact_d06_insertion_controls(
    mut controls: Vec<GateCInsertionControlEvidence>,
) -> Vec<GateCInsertionControlEvidence> {
    let final_cell_selection = controls
        .iter()
        .filter(|control| {
            control.kind == GateCInsertionControlKind::DestinationCell
                && control.widget_part == GateCInsertionWidgetPart::None
                && control.clicked
        })
        .map(|control| control.trace_sequence)
        .max();
    let Some(final_cell_selection) = final_cell_selection else {
        return controls;
    };

    controls.retain(|control| {
        if control.clicked || control.trace_sequence >= final_cell_selection {
            return true;
        }
        let redundant_disabled_option =
            control.widget_part == GateCInsertionWidgetPart::Option && !control.enabled;
        let superseded_unselected_policy = matches!(
            control.kind,
            GateCInsertionControlKind::ReplaceToggle
                | GateCInsertionControlKind::ReplaceConfirm
                | GateCInsertionControlKind::AppendToRing
                | GateCInsertionControlKind::Cancel
        ) && !control.clicked;
        !redundant_disabled_option && !superseded_unselected_policy
    });
    controls
}

fn gate_c_insertion_control_identity_matches_parent(
    control: &GateCInsertionControlEvidence,
    insertion: &GateCInsertionEvidence,
) -> bool {
    let inherited = control.request_id == 0
        && control.source_target_digest == 0
        && control.source_action_digest == 0
        && control.source_binding_digest == 0
        && control.source_query_digest == 0;
    let explicit = control.request_id == insertion.request_id
        && control.source_target_digest == insertion.source_target_digest
        && control.source_action_digest == insertion.source_action_digest
        && control.source_binding_digest == insertion.source_binding_digest
        && control.source_query_digest == insertion.source_query_digest;
    inherited || explicit
}

fn gate_c_insertion_widget_click_has_typed_receipt(
    insertion: &GateCInsertionEvidence,
    widget: &GateCInsertionControlEvidence,
) -> bool {
    if !widget.clicked || widget.widget_part == GateCInsertionWidgetPart::None {
        return true;
    }
    if widget.widget_part == GateCInsertionWidgetPart::Selector {
        return true;
    }
    insertion.controls.iter().any(|receipt| {
        if receipt.widget_part != GateCInsertionWidgetPart::None
            || receipt.kind != widget.kind
            || !receipt.clicked
            || !receipt.enabled
            || receipt.trace_sequence <= widget.trace_sequence
            || receipt.request_id != widget.request_id
            || receipt.source_target_digest != widget.source_target_digest
            || receipt.source_action_digest != widget.source_action_digest
            || receipt.source_binding_digest != widget.source_binding_digest
            || receipt.source_query_digest != widget.source_query_digest
            || receipt.session_id != widget.session_id
        {
            return false;
        }
        match widget.kind {
            GateCInsertionControlKind::DestinationMenu => {
                receipt.destination_menu_digest == widget.destination_menu_digest
            }
            GateCInsertionControlKind::DestinationRing => {
                receipt.destination_menu_digest == widget.destination_menu_digest
                    && receipt.destination_ring_digest == widget.destination_ring_digest
            }
            GateCInsertionControlKind::DestinationCell
            | GateCInsertionControlKind::InsertSelectedSpacer
            | GateCInsertionControlKind::AppendToRing
            | GateCInsertionControlKind::ReplaceToggle
            | GateCInsertionControlKind::ReplaceConfirm
            | GateCInsertionControlKind::Cancel
            | GateCInsertionControlKind::CloseTreeConfirm => {
                receipt.destination_menu_digest == widget.destination_menu_digest
                    && receipt.destination_ring_digest == widget.destination_ring_digest
                    && receipt.destination_cell_digest == widget.destination_cell_digest
            }
            _ => false,
        }
    })
}

fn gate_c_insertion_widget_pair_is_valid(
    insertion: &GateCInsertionEvidence,
    kind: GateCInsertionControlKind,
    part: GateCInsertionWidgetPart,
    expected_destination: Option<[u64; 3]>,
    destination_depth: usize,
) -> bool {
    let Some(source) = insertion.controls.iter().find(|control| {
        control.kind == GateCInsertionControlKind::AddToRadial
            && control.widget_part == GateCInsertionWidgetPart::None
    }) else {
        return false;
    };
    let matches = |control: &GateCInsertionControlEvidence, clicked| {
        control.clicked == clicked
            && gate_c_insertion_widget_matches(
                control,
                source,
                insertion.source_owner_session_id,
                insertion.source_owner_generation,
                kind,
                part,
                expected_destination,
                destination_depth,
            )
    };
    insertion.controls.iter().any(|before| {
        matches(before, false)
            && insertion.controls.iter().any(|after| {
                matches(after, true)
                    && before.trace_sequence < after.trace_sequence
                    && before.session_id == after.session_id
                    && before.generation == after.generation
                    && before.destination_menu_digest == after.destination_menu_digest
                    && before.destination_ring_digest == after.destination_ring_digest
                    && before.destination_cell_digest == after.destination_cell_digest
                    && before.bounds == after.bounds
                    && before.full_bounds == after.full_bounds
                    && before.client_size == after.client_size
            })
    })
}

fn gate_c_insertion_widget_matches(
    control: &GateCInsertionControlEvidence,
    source: &GateCInsertionControlEvidence,
    session_id: u64,
    generation: u64,
    kind: GateCInsertionControlKind,
    widget_part: GateCInsertionWidgetPart,
    expected_destination: Option<[u64; 3]>,
    destination_depth: usize,
) -> bool {
    if control.kind != kind
        || control.widget_part != widget_part
        || control.request_id != source.request_id
        || control.source_target_digest != source.source_target_digest
        || control.source_action_digest != source.source_action_digest
        || control.source_binding_digest != source.source_binding_digest
        || control.source_query_digest != source.source_query_digest
        || control.session_id != session_id
        || control.generation != generation
        || !control.enabled
        || !control.visible
        || !control.fully_visible
        || !gate_c_insertion_widget_geometry_is_valid(control)
    {
        return false;
    }
    expected_destination.is_none_or(|expected| {
        (destination_depth < 1 || control.destination_menu_digest == expected[0])
            && (destination_depth < 2 || control.destination_ring_digest == expected[1])
            && (destination_depth < 3 || control.destination_cell_digest == expected[2])
    })
}

fn gate_c_inserted_mutation_kind(
    insertion: &GateCInsertionEvidence,
) -> Option<GateCInsertionControlKind> {
    let mut mutation_kind = None;
    for control in insertion.controls.iter().filter(|control| {
        control.widget_part == GateCInsertionWidgetPart::None
            && control.clicked
            && matches!(
                control.kind,
                GateCInsertionControlKind::InsertSelectedSpacer
                    | GateCInsertionControlKind::AppendToRing
            )
    }) {
        if mutation_kind.replace(control.kind).is_some() {
            return None;
        }
    }
    mutation_kind
}

fn gate_c_inserted_action_button_pair_is_valid(
    insertion: &GateCInsertionEvidence,
    mutation_kind: GateCInsertionControlKind,
) -> bool {
    if !matches!(
        mutation_kind,
        GateCInsertionControlKind::InsertSelectedSpacer | GateCInsertionControlKind::AppendToRing
    ) {
        return false;
    }
    let Some(source) = insertion.controls.iter().find(|control| {
        control.kind == GateCInsertionControlKind::AddToRadial
            && control.widget_part == GateCInsertionWidgetPart::None
    }) else {
        return false;
    };
    let destination = [
        insertion.destination_menu_digest,
        insertion.destination_ring_digest,
        insertion.destination_cell_digest,
    ];
    let Some(committed_click) = insertion.controls.iter().find(|control| {
        control.kind == mutation_kind
            && control.widget_part == GateCInsertionWidgetPart::None
            && control.clicked
            && control.enabled
            && [
                control.destination_menu_digest,
                control.destination_ring_digest,
                control.destination_cell_digest,
            ] == destination
            && control.document_digest_after == insertion.document_after_digest
            && control.binding_digest_after == insertion.source_binding_digest
    }) else {
        return false;
    };
    let matches_widget = |control: &GateCInsertionControlEvidence, clicked| {
        control.clicked == clicked
            && control.document_digest_after == insertion.document_before_digest
            && control.binding_digest_after == insertion.prior_binding_digest
            && gate_c_insertion_widget_matches(
                control,
                source,
                insertion.source_owner_session_id,
                insertion.source_owner_generation,
                mutation_kind,
                GateCInsertionWidgetPart::Button,
                Some(destination),
                3,
            )
    };
    insertion.controls.iter().any(|before| {
        matches_widget(before, false)
            && insertion.controls.iter().any(|after| {
                matches_widget(after, true)
                    && before.trace_sequence < after.trace_sequence
                    && after.trace_sequence < committed_click.trace_sequence
                    && before.request_id == after.request_id
                    && before.session_id == after.session_id
                    && before.generation == after.generation
                    && before.destination_menu_digest == after.destination_menu_digest
                    && before.destination_ring_digest == after.destination_ring_digest
                    && before.destination_cell_digest == after.destination_cell_digest
                    && before.bounds == after.bounds
                    && before.full_bounds == after.full_bounds
                    && before.client_size == after.client_size
            })
    })
}

fn gate_c_inserted_close_tree_confirmation_is_valid(
    insertion: &GateCInsertionEvidence,
    mutation_kind: GateCInsertionControlKind,
) -> bool {
    let Some(source) = insertion.controls.iter().find(|control| {
        control.kind == GateCInsertionControlKind::AddToRadial
            && control.widget_part == GateCInsertionWidgetPart::None
    }) else {
        return false;
    };
    let destination = [
        insertion.destination_menu_digest,
        insertion.destination_ring_digest,
        insertion.destination_cell_digest,
    ];
    let confirmations = insertion
        .controls
        .iter()
        .filter(|control| {
            control.kind == GateCInsertionControlKind::CloseTreeConfirm
                && control.widget_part == GateCInsertionWidgetPart::None
                && control.clicked
        })
        .collect::<Vec<_>>();
    let [confirmation] = confirmations.as_slice() else {
        return false;
    };
    let Some(destination_sequence) = insertion
        .controls
        .iter()
        .filter(|control| {
            control.widget_part == GateCInsertionWidgetPart::None
                && control.clicked
                && matches!(
                    control.kind,
                    GateCInsertionControlKind::DestinationMenu
                        | GateCInsertionControlKind::DestinationRing
                        | GateCInsertionControlKind::DestinationCell
                )
                && [
                    control.destination_menu_digest,
                    control.destination_ring_digest,
                    control.destination_cell_digest,
                ] == destination
        })
        .map(|control| control.trace_sequence)
        .max()
    else {
        return false;
    };
    let Some(committed_click) = insertion.controls.iter().find(|control| {
        control.kind == mutation_kind
            && control.widget_part == GateCInsertionWidgetPart::None
            && control.clicked
            && control.enabled
            && [
                control.destination_menu_digest,
                control.destination_ring_digest,
                control.destination_cell_digest,
            ] == destination
    }) else {
        return false;
    };
    if !matches!(
        mutation_kind,
        GateCInsertionControlKind::InsertSelectedSpacer | GateCInsertionControlKind::AppendToRing
    ) || confirmation.trace_sequence <= destination_sequence
        || confirmation.trace_sequence >= committed_click.trace_sequence
        || !confirmation.enabled
        || !confirmation.selected
        || !gate_c_insertion_control_identity_matches_parent(confirmation, insertion)
        || confirmation.session_id != insertion.source_owner_session_id
        || confirmation.generation != insertion.source_owner_generation
        || [
            confirmation.destination_menu_digest,
            confirmation.destination_ring_digest,
            confirmation.destination_cell_digest,
        ] != destination
        || confirmation.document_digest_after != insertion.document_before_digest
        || confirmation.binding_digest_after != insertion.prior_binding_digest
    {
        return false;
    }

    let matches_button = |control: &GateCInsertionControlEvidence, clicked| {
        control.clicked == clicked
            && control.selected == clicked
            && control.document_digest_after == insertion.document_before_digest
            && control.binding_digest_after == insertion.prior_binding_digest
            && gate_c_insertion_widget_matches(
                control,
                source,
                insertion.source_owner_session_id,
                insertion.source_owner_generation,
                GateCInsertionControlKind::CloseTreeConfirm,
                GateCInsertionWidgetPart::Button,
                Some(destination),
                3,
            )
    };
    let clicked_buttons = insertion
        .controls
        .iter()
        .filter(|control| {
            control.kind == GateCInsertionControlKind::CloseTreeConfirm
                && control.widget_part == GateCInsertionWidgetPart::Button
                && control.clicked
        })
        .count();
    clicked_buttons == 1
        && insertion.controls.iter().any(|before| {
            matches_button(before, false)
                && insertion.controls.iter().any(|after| {
                    matches_button(after, true)
                        && before.trace_sequence < after.trace_sequence
                        && after.trace_sequence < confirmation.trace_sequence
                        && before.request_id == after.request_id
                        && before.session_id == after.session_id
                        && before.generation == after.generation
                        && before.destination_menu_digest == after.destination_menu_digest
                        && before.destination_ring_digest == after.destination_ring_digest
                        && before.destination_cell_digest == after.destination_cell_digest
                        && before.bounds == after.bounds
                        && before.full_bounds == after.full_bounds
                        && before.client_size == after.client_size
                })
        })
}

fn gate_c_insertion_is_valid(insertion: &GateCInsertionEvidence) -> bool {
    gate_c_insertion_validation_failure_stage(insertion).is_none()
}

fn gate_c_insertion_validation_failure_stage(
    insertion: &GateCInsertionEvidence,
) -> Option<&'static str> {
    if insertion.request_id == 0
        || insertion.source_target_digest == 0
        || insertion.source_action_digest == 0
        || insertion.source_binding_digest == 0
        || insertion.source_query_digest == 0
        || insertion.source_root_query_digest != insertion.source_query_digest
        || insertion.source_results_grid_layout != (insertion.layout == GateCResultLayout::Grid)
        || insertion.prior_binding_digest == 0
        || insertion.source_activation_delta != 0
        || insertion.source_dispatch_delta != 0
        || insertion.source_action_execution_delta != 0
        || insertion.source_history_digest_before == 0
        || insertion.source_history_digest_before != insertion.source_history_digest_after
        || insertion.source_usage_digest_before == 0
        || insertion.source_usage_digest_before != insertion.source_usage_digest_after
        || insertion.source_marker_digest_before == 0
        || insertion.source_marker_digest_before != insertion.source_marker_digest_after
        || {
            let (target, action, binding, query) =
                gate_c_insertion_fixture_identity(insertion.layout);
            insertion.source_target_digest != target
                || insertion.source_action_digest != action
                || insertion.source_binding_digest != binding
                || insertion.source_query_digest != query
        }
    {
        return Some("source_fixture_and_effects");
    }
    if !insertion.initial_snapshot_ready
        || insertion.source_baseline_observation_sequence == 0
        || insertion.source_baseline_boundary_sequence
            <= insertion.source_baseline_observation_sequence
        || insertion.initial_snapshot_session_id == 0
        || insertion.initial_snapshot_sequence == 0
        || insertion.source_owner_observation_sequence == 0
        || insertion.source_owner_boundary_sequence <= insertion.source_owner_observation_sequence
        || insertion.outcome_observation_sequence == 0
        || insertion.outcome_boundary_sequence <= insertion.outcome_observation_sequence
        || insertion.outcome_session_id == 0
        || insertion.outcome_generation == 0
        || !gate_c_initial_snapshot_receipt_is_valid(&insertion.initial_snapshot_receipt)
        || insertion.initial_snapshot_receipt.session_id != insertion.initial_snapshot_session_id
        || insertion.initial_snapshot_receipt.trace_sequence != insertion.initial_snapshot_sequence
    {
        return Some("observation_order_and_initial_snapshot");
    }
    let source_baseline = &insertion.source_baseline_receipt.state;
    let source_owner = &insertion.source_owner_receipt.state;
    let outcome_state = &insertion.outcome_receipt.state;
    if !gate_c_insertion_observation_receipt_is_valid(&insertion.source_baseline_receipt)
        || !gate_c_insertion_observation_receipt_is_valid(&insertion.source_owner_receipt)
        || !gate_c_insertion_observation_receipt_is_valid(&insertion.outcome_receipt)
        || source_baseline.trace_sequence != insertion.source_baseline_observation_sequence
        || source_baseline.trace_boundary_sequence != insertion.source_baseline_boundary_sequence
        || source_baseline.session_id != insertion.source_baseline_session_id
        || source_baseline.generation != insertion.source_baseline_generation
        || source_baseline.document_digest != insertion.source_baseline_document_digest
        || source_owner.trace_sequence != insertion.source_owner_observation_sequence
        || source_owner.trace_boundary_sequence != insertion.source_owner_boundary_sequence
        || source_owner.session_id != insertion.source_owner_session_id
        || source_owner.generation != insertion.source_owner_generation
        || source_owner.document_digest != insertion.source_owner_document_digest
        || source_owner.undo_depth != insertion.undo_depth_before
        || source_owner.redo_depth != insertion.redo_depth_before
        || source_owner.draft_dirty != insertion.draft_dirty_before
        || outcome_state.trace_sequence != insertion.outcome_observation_sequence
        || outcome_state.trace_boundary_sequence != insertion.outcome_boundary_sequence
        || outcome_state.session_id != insertion.outcome_session_id
        || outcome_state.generation != insertion.outcome_generation
        || outcome_state.document_digest != insertion.outcome_document_digest
        || outcome_state.undo_depth != insertion.outcome_undo_depth
        || outcome_state.redo_depth != insertion.outcome_redo_depth
        || outcome_state.draft_dirty != insertion.outcome_draft_dirty
    {
        return Some("owner_receipt_field_parity");
    }
    if insertion.outcome_document_digest != insertion.document_after_digest
        || (insertion.outcome == GateCInsertionOutcome::Inserted
            && (insertion.unrelated_cell_target_digest != 0
                || insertion.unrelated_label_value_digest != 0))
        || (insertion.outcome != GateCInsertionOutcome::Inserted
            && (insertion.unrelated_cell_target_digest == 0
                || insertion.unrelated_label_value_digest == 0))
        || insertion.controls.len() > MAX_GATE_C_INSERTION_CONTROLS
        || insertion
            .controls
            .iter()
            .any(|control| !gate_c_insertion_widget_geometry_is_valid(control))
        || insertion.destination_menu_digest == 0
        || insertion.destination_ring_digest == 0
        || insertion.destination_cell_digest == 0
        || insertion.document_before_digest == 0
        || insertion.document_after_digest == 0
        || insertion.radial_history_digest_before == 0
        || insertion.radial_history_digest_after == 0
    {
        return Some("controls_and_document_state");
    }
    if outcome_state.selected_target_digest == 0 || outcome_state.selected_cell_digest == 0 {
        return Some("outcome_selection");
    }
    let has_control = |kind: GateCInsertionControlKind, clicked: bool| {
        insertion.controls.iter().any(|control| {
            control.kind == kind
                && control.widget_part == GateCInsertionWidgetPart::None
                && control.clicked == clicked
                && control.trace_sequence > 0
                && gate_c_insertion_control_identity_matches_parent(control, insertion)
                && (!clicked || control.enabled)
        })
    };
    let destination_controls_match = [
        GateCInsertionControlKind::DestinationMenu,
        GateCInsertionControlKind::DestinationRing,
        GateCInsertionControlKind::DestinationCell,
    ]
    .into_iter()
    .all(|kind| {
        insertion.controls.iter().any(|control| {
            let destination_matches = match kind {
                GateCInsertionControlKind::DestinationMenu => {
                    control.destination_menu_digest == insertion.destination_menu_digest
                }
                GateCInsertionControlKind::DestinationRing => {
                    control.destination_menu_digest == insertion.destination_menu_digest
                        && control.destination_ring_digest == insertion.destination_ring_digest
                }
                GateCInsertionControlKind::DestinationCell => {
                    control.destination_menu_digest == insertion.destination_menu_digest
                        && control.destination_ring_digest == insertion.destination_ring_digest
                        && control.destination_cell_digest == insertion.destination_cell_digest
                }
                _ => false,
            };
            control.kind == kind
                && control.widget_part == GateCInsertionWidgetPart::None
                && control.clicked
                && control.enabled
                && gate_c_insertion_control_identity_matches_parent(control, insertion)
                && destination_matches
        })
    });
    let request_source_identity_matches = insertion.controls.iter().all(|control| {
        if control.widget_part != GateCInsertionWidgetPart::None {
            return gate_c_insertion_control_identity_matches_parent(control, insertion)
                && gate_c_insertion_widget_geometry_is_valid(control);
        }
        let destination_identity_matches = if control.kind == GateCInsertionControlKind::AddToRadial
        {
            control.destination_menu_digest == 0
                && control.destination_ring_digest == 0
                && control.destination_cell_digest == 0
        } else if !control.clicked {
            // The opening frame can still contain controls from the prior
            // destination. Their original destination IDs remain truthful;
            // only clicked controls can claim the final selected destination.
            true
        } else {
            match control.kind {
                GateCInsertionControlKind::AddToRadial => unreachable!(),
                GateCInsertionControlKind::DestinationMenu => {
                    control.destination_menu_digest == insertion.destination_menu_digest
                }
                GateCInsertionControlKind::DestinationRing => {
                    control.destination_menu_digest == insertion.destination_menu_digest
                        && control.destination_ring_digest == insertion.destination_ring_digest
                }
                GateCInsertionControlKind::DestinationCell => {
                    control.destination_menu_digest == insertion.destination_menu_digest
                        && control.destination_ring_digest == insertion.destination_ring_digest
                        && control.destination_cell_digest == insertion.destination_cell_digest
                }
                _ => {
                    control.destination_menu_digest == insertion.destination_menu_digest
                        && control.destination_ring_digest == insertion.destination_ring_digest
                        && control.destination_cell_digest == insertion.destination_cell_digest
                }
            }
        };
        gate_c_insertion_control_identity_matches_parent(control, insertion)
            && destination_identity_matches
    });
    if !has_control(GateCInsertionControlKind::AddToRadial, true)
        || !destination_controls_match
        || !request_source_identity_matches
        || insertion.controls.iter().any(|control| {
            control.widget_part != GateCInsertionWidgetPart::None
                && !gate_c_insertion_widget_click_has_typed_receipt(insertion, control)
        })
    {
        return Some("request_and_control_identity");
    }
    let destination_digests = [
        insertion.destination_menu_digest,
        insertion.destination_ring_digest,
        insertion.destination_cell_digest,
    ];
    if ![
        GateCInsertionControlKind::DestinationMenu,
        GateCInsertionControlKind::DestinationRing,
        GateCInsertionControlKind::DestinationCell,
    ]
    .into_iter()
    .all(|kind| {
        gate_c_insertion_widget_pair_is_valid(
            insertion,
            kind,
            GateCInsertionWidgetPart::Selector,
            None,
            0,
        ) && gate_c_insertion_widget_pair_is_valid(
            insertion,
            kind,
            GateCInsertionWidgetPart::Option,
            Some(destination_digests),
            match kind {
                GateCInsertionControlKind::DestinationMenu => 1,
                GateCInsertionControlKind::DestinationRing => 2,
                GateCInsertionControlKind::DestinationCell => 3,
                _ => 0,
            },
        )
    }) {
        return Some("selector_pair_geometry");
    }
    let button_pair = |kind| {
        gate_c_insertion_widget_pair_is_valid(
            insertion,
            kind,
            GateCInsertionWidgetPart::Button,
            Some(destination_digests),
            3,
        )
    };
    if insertion
        .controls
        .windows(2)
        .any(|pair| pair[0].trace_sequence >= pair[1].trace_sequence)
    {
        return Some("control_trace_order");
    }
    let control_sequence = |kind, clicked| {
        insertion
            .controls
            .iter()
            .find(|control| {
                control.kind == kind
                    && control.widget_part == GateCInsertionWidgetPart::None
                    && control.clicked == clicked
            })
            .map(|control| control.trace_sequence)
    };
    let add_sequence = control_sequence(GateCInsertionControlKind::AddToRadial, true);
    let menu_sequence = control_sequence(GateCInsertionControlKind::DestinationMenu, true);
    let ring_sequence = control_sequence(GateCInsertionControlKind::DestinationRing, true);
    let cell_sequence = control_sequence(GateCInsertionControlKind::DestinationCell, true);
    let source_and_snapshot_are_ordered =
        add_sequence
            .zip(menu_sequence)
            .is_some_and(|(add, menu)| match insertion.session_origin {
                GateCInsertionSessionOrigin::FreshInitialSnapshot => {
                    insertion.source_baseline_session_id == 0
                        && insertion.source_baseline_generation == 0
                        && insertion.source_baseline_document_digest == 0
                        && insertion.source_owner_session_id > 0
                        && insertion.source_owner_generation > 0
                        && insertion.initial_snapshot_session_id
                            == insertion.source_owner_session_id
                        && insertion.initial_snapshot_receipt.session_id
                            == insertion.source_owner_session_id
                        && insertion.initial_snapshot_receipt.generation
                            <= insertion.source_owner_generation
                        && insertion.source_owner_document_digest
                            == insertion.document_before_digest
                        && insertion.source_baseline_boundary_sequence < add
                        && add < insertion.initial_snapshot_sequence
                        && insertion.initial_snapshot_sequence
                            < insertion.source_owner_observation_sequence
                        && insertion.source_owner_observation_sequence
                            < insertion.source_owner_boundary_sequence
                        && insertion.source_owner_boundary_sequence < menu
                }
                GateCInsertionSessionOrigin::ReusedReadySession => {
                    insertion.source_baseline_session_id > 0
                        && insertion.source_baseline_generation > 0
                        && insertion.source_baseline_document_digest > 0
                        && insertion.initial_snapshot_session_id
                            == insertion.source_baseline_session_id
                        && insertion.initial_snapshot_receipt.session_id
                            == insertion.source_baseline_session_id
                        && insertion.initial_snapshot_receipt.generation
                            <= insertion.source_baseline_generation
                        && insertion.source_owner_session_id == insertion.source_baseline_session_id
                        && insertion.source_owner_generation == insertion.source_baseline_generation
                        && insertion.source_owner_document_digest
                            == insertion.source_baseline_document_digest
                        && insertion.source_baseline_document_digest
                            == insertion.document_before_digest
                        && gate_c_reused_authoring_state_is_preserved(source_baseline, source_owner)
                        && insertion.initial_snapshot_sequence
                            < insertion.source_baseline_observation_sequence
                        && insertion.source_baseline_observation_sequence
                            < insertion.source_baseline_boundary_sequence
                        && insertion.source_baseline_boundary_sequence < add
                        && add < insertion.source_owner_observation_sequence
                        && insertion.source_owner_observation_sequence
                            < insertion.source_owner_boundary_sequence
                        && insertion.source_owner_boundary_sequence < menu
                }
            });
    let destination_controls_are_ordered = menu_sequence
        .zip(ring_sequence)
        .zip(cell_sequence)
        .is_some_and(|((menu, ring), cell)| menu < ring && ring < cell);
    if !source_and_snapshot_are_ordered || !destination_controls_are_ordered {
        return Some("session_and_snapshot_order");
    }
    let owner_controls_match_live_session = insertion.controls.iter().all(|control| {
        let is_pre_mutation_owner_control = control.widget_part != GateCInsertionWidgetPart::None
            || matches!(
                control.kind,
                GateCInsertionControlKind::DestinationMenu
                    | GateCInsertionControlKind::DestinationRing
                    | GateCInsertionControlKind::DestinationCell
                    | GateCInsertionControlKind::ReplaceToggle
                    | GateCInsertionControlKind::CloseTreeConfirm
                    | GateCInsertionControlKind::Cancel
            )
            || (control.kind == GateCInsertionControlKind::ReplaceConfirm && !control.clicked);
        !is_pre_mutation_owner_control
            || (control.session_id == source_owner.session_id
                && control.generation == source_owner.generation)
    }) && insertion.controls.iter().all(|control| {
        let is_mutation_receipt = control.widget_part == GateCInsertionWidgetPart::None
            && control.clicked
            && matches!(
                control.kind,
                GateCInsertionControlKind::InsertSelectedSpacer
                    | GateCInsertionControlKind::AppendToRing
                    | GateCInsertionControlKind::ReplaceConfirm
            );
        !is_mutation_receipt
            || (control.session_id == outcome_state.session_id
                && control.generation == outcome_state.generation)
    });
    if !owner_controls_match_live_session {
        return Some("owner_session_generation");
    }
    let destination_sequence = [
        GateCInsertionControlKind::DestinationMenu,
        GateCInsertionControlKind::DestinationRing,
        GateCInsertionControlKind::DestinationCell,
    ]
    .into_iter()
    .filter_map(|kind| control_sequence(kind, true))
    .max();
    let final_destination_control = |kind, clicked, enabled| {
        let destination = [
            insertion.destination_menu_digest,
            insertion.destination_ring_digest,
            insertion.destination_cell_digest,
        ];
        let selected_sequence = destination_sequence?;
        insertion
            .controls
            .iter()
            .filter(|control| {
                control.kind == kind
                    && control.widget_part == GateCInsertionWidgetPart::None
                    && control.clicked == clicked
                    && control.enabled == enabled
                    && control.trace_sequence > selected_sequence
                    && [
                        control.destination_menu_digest,
                        control.destination_ring_digest,
                        control.destination_cell_digest,
                    ] == destination
                    && (kind != GateCInsertionControlKind::ReplaceConfirm
                        || clicked
                        || enabled
                        || (control.document_digest_after == insertion.document_before_digest
                            && control.binding_digest_after == insertion.prior_binding_digest))
            })
            .min_by_key(|control| control.trace_sequence)
    };
    let mutation_sequence = match insertion.outcome {
        GateCInsertionOutcome::Cancelled => {
            control_sequence(GateCInsertionControlKind::Cancel, true)
        }
        GateCInsertionOutcome::Inserted => {
            gate_c_inserted_mutation_kind(insertion).and_then(|kind| control_sequence(kind, true))
        }
        GateCInsertionOutcome::Replaced => {
            control_sequence(GateCInsertionControlKind::ReplaceConfirm, true)
        }
    };
    if mutation_sequence.is_none_or(|sequence| sequence >= insertion.outcome_observation_sequence) {
        return Some("mutation_before_outcome");
    }
    let save_receipts_are_valid = {
        let sequence = |kind| {
            insertion
                .controls
                .iter()
                .filter(|control| {
                    control.kind == kind && control.widget_part == GateCInsertionWidgetPart::None
                })
                .collect::<Vec<_>>()
        };
        let save = sequence(GateCInsertionControlKind::Save);
        let reopen = sequence(GateCInsertionControlKind::Reopen);
        let undo = sequence(GateCInsertionControlKind::Undo);
        let redo = sequence(GateCInsertionControlKind::Redo);
        let reopened_document_matches_typed_save =
            insertion.saved_binding.as_ref().is_some_and(|binding| {
                binding.saved_document_digest > 0
                    && binding.reopened_document_digest == binding.saved_document_digest
                    && reopen.len() == 1
                    && reopen[0].document_digest_after == binding.reopened_document_digest
            });
        save.len() == 1
            && reopen.len() == 1
            && undo.len() == 1
            && redo.len() == 1
            && save[0].clicked
            && reopen[0].clicked
            && undo[0].clicked
            && redo[0].clicked
            && save[0].enabled
            && reopen[0].enabled
            && undo[0].enabled
            && redo[0].enabled
            && save[0].document_digest_after == insertion.document_after_digest
            && reopened_document_matches_typed_save
            && undo[0].document_digest_after == insertion.document_undo_digest
            && redo[0].document_digest_after == insertion.document_redo_digest
            && save[0].binding_digest_after == insertion.source_binding_digest
            && reopen[0].binding_digest_after == insertion.source_binding_digest
            && undo[0].binding_digest_after == insertion.prior_binding_digest
            && redo[0].binding_digest_after == insertion.source_binding_digest
            && [save[0], reopen[0], undo[0], redo[0]]
                .iter()
                .all(|control| {
                    gate_c_insertion_control_identity_matches_parent(control, insertion)
                        && control.destination_menu_digest == insertion.destination_menu_digest
                        && control.destination_ring_digest == insertion.destination_ring_digest
                        && control.destination_cell_digest == insertion.destination_cell_digest
                })
            && add_sequence
                .zip(destination_sequence)
                .zip(mutation_sequence)
                .is_some_and(|((add, destination), mutation)| {
                    add < destination
                        && destination < mutation
                        && mutation < undo[0].trace_sequence
                        && insertion.outcome_observation_sequence
                            < insertion.outcome_boundary_sequence
                        && insertion.outcome_boundary_sequence < undo[0].trace_sequence
                        && undo[0].trace_sequence < redo[0].trace_sequence
                        && redo[0].trace_sequence < save[0].trace_sequence
                        && save[0].trace_sequence < reopen[0].trace_sequence
                })
    };
    let inserted_policy_controls_are_valid = insertion.outcome != GateCInsertionOutcome::Inserted
        || gate_c_inserted_mutation_kind(insertion).is_some_and(|mutation_kind| {
            let replacement_consent_clicked = insertion.controls.iter().any(|control| {
                control.clicked
                    && matches!(
                        control.kind,
                        GateCInsertionControlKind::ReplaceToggle
                            | GateCInsertionControlKind::ReplaceConfirm
                    )
            });
            let close_tree_consent_is_valid = if insertion.policy_confirmation_required {
                gate_c_inserted_close_tree_confirmation_is_valid(insertion, mutation_kind)
            } else {
                !insertion.controls.iter().any(|control| {
                    control.kind == GateCInsertionControlKind::CloseTreeConfirm && control.clicked
                })
            };
            !replacement_consent_clicked
                && close_tree_consent_is_valid
                && gate_c_inserted_action_button_pair_is_valid(insertion, mutation_kind)
        });
    let outcome_is_valid = match insertion.outcome {
        GateCInsertionOutcome::Cancelled => {
            insertion.document_before_digest == insertion.document_after_digest
                && insertion.outcome_session_id == insertion.source_owner_session_id
                && insertion.outcome_generation == insertion.source_owner_generation
                && insertion.outcome_document_digest == insertion.document_before_digest
                && insertion.outcome_undo_depth == insertion.undo_depth_before
                && insertion.outcome_redo_depth == insertion.redo_depth_before
                && insertion.outcome_draft_dirty == insertion.draft_dirty_before
                && insertion.undo_depth_before == insertion.undo_depth_after
                && insertion.redo_depth_before == insertion.redo_depth_after
                && insertion.draft_dirty_before
                && insertion.draft_dirty_after
                && insertion.radial_history_digest_before == insertion.radial_history_digest_after
                && insertion.undo_depth_undo == 0
                && insertion.undo_depth_redo == 0
                && insertion.redo_depth_undo == 0
                && insertion.redo_depth_redo == 0
                && !insertion.draft_dirty_undo
                && !insertion.draft_dirty_redo
                && insertion.radial_history_digest_undo == 0
                && insertion.radial_history_digest_redo == 0
                && insertion.unrelated_dirty_edit_preserved
                && insertion.unrelated_edit_digest_before != 0
                && insertion.unrelated_edit_digest_after == insertion.unrelated_edit_digest_before
                && !insertion.saved_typed_binding_matches
                && insertion.saved_binding.is_none()
                && !insertion.one_undo_restores_before
                && !insertion.one_redo_restores_after
                && !insertion.controls.iter().any(|control| {
                    matches!(
                        control.kind,
                        GateCInsertionControlKind::Save
                            | GateCInsertionControlKind::Reopen
                            | GateCInsertionControlKind::Undo
                            | GateCInsertionControlKind::Redo
                    )
                })
                && final_destination_control(GateCInsertionControlKind::ReplaceToggle, false, true)
                    .zip(final_destination_control(
                        GateCInsertionControlKind::ReplaceConfirm,
                        false,
                        false,
                    ))
                    .zip(control_sequence(GateCInsertionControlKind::Cancel, true))
                    .is_some_and(|((toggle, confirm), cancel)| {
                        toggle.trace_sequence < cancel
                            && confirm.trace_sequence < cancel
                            && !confirm.enabled
                            && !confirm.clicked
                            && confirm.document_digest_after == insertion.document_before_digest
                            && confirm.binding_digest_after == insertion.prior_binding_digest
                    })
                && has_control(GateCInsertionControlKind::Cancel, true)
                && button_pair(GateCInsertionControlKind::Cancel)
                && !has_control(GateCInsertionControlKind::ReplaceToggle, true)
                && !has_control(GateCInsertionControlKind::ReplaceConfirm, true)
                && control_sequence(GateCInsertionControlKind::Cancel, true)
                    .zip(destination_sequence)
                    .is_some_and(|(cancel, destination)| {
                        destination < cancel
                            && insertion.controls.iter().any(|control| {
                                control.kind == GateCInsertionControlKind::Cancel
                                    && control.clicked
                                    && control.document_digest_after
                                        == insertion.document_before_digest
                                    && control.binding_digest_after
                                        == insertion.prior_binding_digest
                            })
                    })
        }
        GateCInsertionOutcome::Inserted | GateCInsertionOutcome::Replaced => {
            insertion.document_before_digest != insertion.document_after_digest
                && insertion.outcome_session_id == insertion.source_owner_session_id
                && insertion.outcome_generation > insertion.source_owner_generation
                && insertion.outcome_document_digest == insertion.document_after_digest
                && insertion.outcome_undo_depth == insertion.undo_depth_after
                && insertion.outcome_redo_depth == insertion.redo_depth_after
                && insertion.outcome_draft_dirty == insertion.draft_dirty_after
                && insertion.undo_depth_before.checked_add(1) == Some(insertion.undo_depth_after)
                && insertion.undo_depth_undo == insertion.undo_depth_before
                && insertion.undo_depth_redo == insertion.undo_depth_after
                && insertion.redo_depth_undo == insertion.redo_depth_after.saturating_add(1)
                && insertion.redo_depth_redo == insertion.redo_depth_after
                && insertion.draft_dirty_undo == insertion.draft_dirty_before
                && insertion.draft_dirty_after
                && insertion.draft_dirty_redo == insertion.draft_dirty_after
                && insertion.radial_history_digest_undo != 0
                && insertion.radial_history_digest_redo != 0
                && (insertion.outcome != GateCInsertionOutcome::Replaced
                    || (insertion.unrelated_dirty_edit_preserved
                        && insertion.unrelated_edit_digest_before != 0
                        && insertion.unrelated_edit_digest_after
                            == insertion.unrelated_edit_digest_before
                        && insertion.unrelated_edit_digest_undo
                            == insertion.unrelated_edit_digest_before
                        && insertion.unrelated_edit_digest_redo
                            == insertion.unrelated_edit_digest_before))
                && insertion.saved_typed_binding_matches
                && insertion.saved_binding.as_ref().is_some_and(|binding| {
                    gate_c_binding_is_valid(binding)
                        && binding.destination_cell_digest == insertion.destination_cell_digest
                        && binding.route == GateCBindingRoute::RadialInsertion
                        && binding.semantic_target_digest == insertion.source_target_digest
                        && binding.semantic_action_digest == insertion.source_action_digest
                        && binding.expected_binding_digest == insertion.source_binding_digest
                        && binding.previous_binding_digest == insertion.prior_binding_digest
                        && (!insertion.policy_confirmation_required
                            || binding.after_action_policy == GateCAfterActionPolicy::CloseTree)
                        && binding.saved_after_reopen
                })
                && insertion.document_undo_digest == insertion.document_before_digest
                && insertion.document_redo_digest == insertion.document_after_digest
                && insertion.one_undo_restores_before
                && insertion.one_redo_restores_after
                && save_receipts_are_valid
                && inserted_policy_controls_are_valid
                && (insertion.outcome != GateCInsertionOutcome::Inserted
                    || ([
                        GateCInsertionControlKind::InsertSelectedSpacer,
                        GateCInsertionControlKind::AppendToRing,
                    ]
                    .into_iter()
                    .filter(|kind| has_control(*kind, true) && button_pair(*kind))
                    .count()
                        == 1))
                && (insertion.outcome != GateCInsertionOutcome::Replaced
                    || (insertion.controls.iter().any(|control| {
                        control.kind == GateCInsertionControlKind::ReplaceToggle
                            && control.enabled
                            && !control.clicked
                    }) && insertion
                        .controls
                        .iter()
                        .filter(|control| {
                            control.kind == GateCInsertionControlKind::ReplaceToggle
                                && control.widget_part == GateCInsertionWidgetPart::None
                                && control.clicked
                        })
                        .count()
                        == 1
                        && insertion
                            .controls
                            .iter()
                            .filter(|control| {
                                control.kind == GateCInsertionControlKind::ReplaceConfirm
                                    && control.widget_part == GateCInsertionWidgetPart::None
                                    && control.clicked
                            })
                            .count()
                            == 1
                        && final_destination_control(
                            GateCInsertionControlKind::ReplaceToggle,
                            false,
                            true,
                        )
                        .zip(final_destination_control(
                            GateCInsertionControlKind::ReplaceConfirm,
                            false,
                            false,
                        ))
                        .zip(final_destination_control(
                            GateCInsertionControlKind::ReplaceToggle,
                            true,
                            true,
                        ))
                        .zip(final_destination_control(
                            GateCInsertionControlKind::ReplaceConfirm,
                            true,
                            true,
                        ))
                        .is_some_and(
                            |(((toggle_before, disabled), toggle), confirm)| {
                                toggle_before.trace_sequence < toggle.trace_sequence
                                    && disabled.trace_sequence < toggle.trace_sequence
                                    && toggle.trace_sequence < confirm.trace_sequence
                            },
                        )
                        && !has_control(GateCInsertionControlKind::Cancel, true)
                        && has_control(GateCInsertionControlKind::ReplaceConfirm, true)
                        && button_pair(GateCInsertionControlKind::ReplaceToggle)
                        && button_pair(GateCInsertionControlKind::ReplaceConfirm)))
                && (if insertion.policy_confirmation_required {
                    control_sequence(GateCInsertionControlKind::CloseTreeConfirm, true)
                        .zip(destination_sequence)
                        .zip(mutation_sequence)
                        .is_some_and(|((confirmation, destination), mutation)| {
                            destination < confirmation && confirmation < mutation
                        })
                        && button_pair(GateCInsertionControlKind::CloseTreeConfirm)
                } else {
                    !has_control(GateCInsertionControlKind::CloseTreeConfirm, true)
                })
        }
    };
    if insertion.outcome != GateCInsertionOutcome::Cancelled && !save_receipts_are_valid {
        Some("save_undo_redo_readback")
    } else if outcome_is_valid {
        None
    } else {
        Some("outcome_state_and_policy")
    }
}

fn gate_c_surface_has_duplicate_action_rows(
    packet: &GateCCaseEvidence,
    surface: GateCSurface,
) -> bool {
    packet
        .ordered_results
        .iter()
        .enumerate()
        .any(|(index, first)| {
            first.surface == surface
                && packet.ordered_results[index + 1..].iter().any(|second| {
                    second.surface == surface
                        && second.title_digest == first.title_digest
                        && second.type_digest == first.type_digest
                        && second.action_digest == first.action_digest
                        && second.target_digest != first.target_digest
                        && second.disambiguator_digest != first.disambiguator_digest
                        && second.identity == first.identity
                        && second.search_completion_sequence == first.search_completion_sequence
                })
        })
}

fn gate_c_search_for(
    packet: &GateCCaseEvidence,
    surface: GateCSurface,
    purpose: GateCSearchPurpose,
) -> Option<&GateCSearchEvidence> {
    packet
        .searches
        .iter()
        .find(|search| search.surface == surface && search.purpose == purpose)
}

fn gate_c_search_pair_is_shared(packet: &GateCCaseEvidence, purpose: GateCSearchPurpose) -> bool {
    let Some(properties) = gate_c_search_for(packet, GateCSurface::Properties, purpose) else {
        return false;
    };
    let Some(inspector) = gate_c_search_for(packet, GateCSurface::Inspector, purpose) else {
        return false;
    };
    properties.query_digest == inspector.query_digest
        && properties.target_digest == inspector.target_digest
        && properties.action_digest == inspector.action_digest
        && properties.result_order == inspector.result_order
        && (purpose != GateCSearchPurpose::BeyondFifty
            || (properties.result_order > 50 && inspector.result_order > 50))
}

fn gate_c_title_token_search_is_valid(packet: &GateCCaseEvidence, surface: GateCSurface) -> bool {
    let Some(search) = gate_c_search_for(packet, surface, GateCSearchPurpose::TitleToken) else {
        return false;
    };
    let expected_query = gate_c_trace_text_digest("note search Shared Acceptance");
    let expected_action = gate_c_note_action_digest();
    let rows = packet
        .ordered_results
        .iter()
        .filter(|row| {
            row.surface == surface
                && row.identity == search.identity
                && row.search_completion_sequence == search.worker_terminal_sequence
        })
        .collect::<Vec<_>>();
    let note_a = gate_c_note_semantic_target_digest("radial-acceptance-shared-a");
    let note_b = gate_c_note_semantic_target_digest("radial-acceptance-shared-b");
    let readable_note = |row: &&GateCResultRowEvidence, slug: &str, target: u64| {
        row.readable
            && row.target_digest == target
            && row.title_digest == gate_c_trace_text_digest("Shared Acceptance Note")
            && row.type_digest == gate_c_trace_text_digest("Note")
            && row.disambiguator_digest == gate_c_trace_text_digest(&format!("slug {slug}"))
            && row.action_digest == expected_action
    };
    let selected_target_is_duplicate = [note_a, note_b].contains(&search.target_digest);
    search.query_digest == expected_query
        && search.identity.query_digest == expected_query
        && search.result_count >= 2
        && selected_target_is_duplicate
        && search.action_digest == expected_action
        && rows.iter().any(|row| {
            row.target_digest == search.target_digest
                && row.action_digest == expected_action
                && row.order == search.result_order
        })
        && rows
            .iter()
            .any(|row| readable_note(row, "radial-acceptance-shared-a", note_a))
        && rows
            .iter()
            .any(|row| readable_note(row, "radial-acceptance-shared-b", note_b))
        && rows.iter().any(|first| {
            readable_note(first, "radial-acceptance-shared-a", note_a)
                && rows.iter().any(|second| {
                    readable_note(second, "radial-acceptance-shared-b", note_b)
                        && first.order != second.order
                        && first.target_digest != second.target_digest
                        && first.disambiguator_digest != second.disambiguator_digest
                })
        })
}

fn gate_c_clicked_control(
    packet: &GateCCaseEvidence,
    name: &str,
    surface: Option<GateCSurface>,
) -> bool {
    packet.controls.iter().any(|control| {
        control.control == name
            && control.clicked
            && surface.is_none_or(|surface| control.identity.surface == surface)
    })
}

fn gate_c_inspector_direct_persisted_pin_is_valid(packet: &GateCCaseEvidence) -> bool {
    packet.bindings.iter().any(|binding| {
        if binding.route != GateCBindingRoute::InspectorDirect
            || binding.kind != GateCBindingKind::PersistedReference
            || !gate_c_binding_is_valid(binding)
        {
            return false;
        }
        let Some(assignment) = binding
            .controls
            .iter()
            .find(|receipt| receipt.kind == GateCBindingControlKind::Assign)
        else {
            return false;
        };
        packet.controls.iter().any(|pin| {
            pin.control == "pin_result"
                && pin.trace_sequence == assignment.trace_sequence
                && pin.identity == assignment.identity
                && pin.identity.surface == GateCSurface::Inspector
                && pin.clicked
                && pin.enabled
                && pin.target_digest == binding.semantic_target_digest
                && pin.action_digest == binding.semantic_action_digest
                && pin.binding_digest == binding.expected_binding_digest
                && gate_c_pin_has_fresh_rendered_row(packet, pin)
        })
    })
}

fn gate_c_binding_control_links_are_valid(
    binding: &GateCBindingEvidence,
    packet: &GateCCaseEvidence,
    allow_d04_binding_transition: bool,
) -> bool {
    let receipt = |kind| binding.controls.iter().find(|receipt| receipt.kind == kind);
    let expected_control = |kind| match kind {
        GateCBindingControlKind::Stage | GateCBindingControlKind::Assign => {
            Some(match binding.kind {
                GateCBindingKind::PersistedReference => "pin_result",
                GateCBindingKind::LauncherQuery => "save_query",
                GateCBindingKind::ExactCommand => "use_exact_command",
            })
        }
        GateCBindingControlKind::Apply => Some("apply"),
        GateCBindingControlKind::Save => Some("save"),
        // Reopen is a readback, not a native button. The current Inspector
        // query field is emitted only after the ordinary reopened session has
        // loaded its assigned binding.
        GateCBindingControlKind::Reopen => {
            Some(if binding.kind == GateCBindingKind::ExactCommand {
                "exact_command_field"
            } else {
                "query_field"
            })
        }
        GateCBindingControlKind::Undo => Some("undo"),
        GateCBindingControlKind::Redo => Some("redo"),
    };
    let receipt_semantics_match = binding
        .controls
        .iter()
        .all(|receipt| expected_control(receipt.kind) == Some(receipt.control.as_str()));
    let control_receipts_match = binding.controls.iter().all(|receipt| {
        packet.controls.iter().any(|control| {
            control.control == receipt.control
                && control.trace_sequence == receipt.trace_sequence
                && control.identity.surface == receipt.surface
                && control.identity == receipt.identity
                && control.owner_session_id == receipt.owner_session_id
                && control.owner_generation == receipt.owner_generation
                && control.enabled
                && if receipt.kind == GateCBindingControlKind::Reopen {
                    let readback_value_matches = match binding.kind {
                        GateCBindingKind::PersistedReference => {
                            control.query_digest != 0
                                && control.value_digest == control.query_digest
                        }
                        GateCBindingKind::LauncherQuery => {
                            let expected_query = binding.query_digest.unwrap_or(0);
                            control.query_digest == expected_query
                                && control.value_digest == expected_query
                        }
                        GateCBindingKind::ExactCommand => {
                            control.value_digest == binding.command_digest.unwrap_or(0)
                        }
                    };
                    let reopen_binding_matches =
                        if binding.kind == GateCBindingKind::PersistedReference {
                            // Query-field controls fingerprint the query text; the
                            // editor identity retains the assigned persisted binding.
                            control.identity.binding_digest == receipt.binding_digest
                        } else {
                            control.binding_digest == receipt.binding_digest
                        };
                    !control.clicked
                        && control.identity.surface == GateCSurface::Inspector
                        && binding.controls.first().is_some_and(|first| {
                            control.identity.session_id != first.identity.session_id
                                && control.identity.stable_target_digest
                                    == first.identity.stable_target_digest
                        })
                        && readback_value_matches
                        && reopen_binding_matches
                } else {
                    control.clicked && control.binding_digest == receipt.binding_digest
                }
        })
    });
    let same_visit = |identity: &GateCEditorIdentity| {
        binding.controls.first().is_some_and(|receipt| {
            receipt.identity.surface == identity.surface
                && receipt.identity.session_id == identity.session_id
                && receipt.identity.draft_generation == identity.draft_generation
                && receipt.identity.stable_target_digest == identity.stable_target_digest
                && receipt.identity.editor_epoch == identity.editor_epoch
        })
    };
    let original_session_id = binding
        .controls
        .first()
        .map(|receipt| receipt.identity.session_id);
    let typed_input_matches = match binding.kind {
        GateCBindingKind::PersistedReference => {
            binding.action_id_digest == Some(binding.semantic_action_digest)
                && packet.controls.iter().any(|control| {
                    control.control == "pin_result"
                        && control.clicked
                        && control.enabled
                        && same_visit(&control.identity)
                        && control.target_digest == binding.semantic_target_digest
                        && control.action_digest == binding.semantic_action_digest
                        && control.binding_digest == binding.expected_binding_digest
                })
        }
        GateCBindingKind::LauncherQuery => {
            let query_digest = binding.query_digest.unwrap_or(0);
            let execute_first = binding.query_mode == Some(GateCQueryMode::ExecuteFirst);
            let reopened = receipt(GateCBindingControlKind::Reopen);
            query_digest != 0
                && packet.controls.iter().any(|control| {
                    control.control == "query_field"
                        && same_visit(&control.identity)
                        && control.query_digest == query_digest
                        && control.value_digest == query_digest
                })
                && packet.controls.iter().any(|control| {
                    control.control == "query_mode"
                        && same_visit(&control.identity)
                        && control.query_digest == query_digest
                        && control.binding_digest == binding.expected_binding_digest
                        && control.selected == execute_first
                })
                && (packet.case_id != "D04"
                    || binding.route != GateCBindingRoute::PropertiesStaged
                    || binding.query_mode != Some(GateCQueryMode::ExecuteFirst)
                    || packet.controls.iter().any(|control| {
                        gate_c_d04_query_mode_stage_transition_is_observed(control, binding, packet)
                    }))
                && packet.controls.iter().any(|control| {
                    control.control == "save_query"
                        && control.clicked
                        && control.enabled
                        && same_visit(&control.identity)
                        && control.query_digest == query_digest
                        && control.binding_digest == binding.expected_binding_digest
                })
                && reopened.is_some_and(|reopen| {
                    packet.controls.iter().any(|control| {
                        control.control == "query_mode"
                            && control.identity == reopen.identity
                            && control.identity.surface == GateCSurface::Inspector
                            && Some(control.identity.session_id) != original_session_id
                            && control.query_digest == query_digest
                            && control.binding_digest == binding.expected_binding_digest
                            && control.selected == execute_first
                    })
                })
        }
        GateCBindingKind::ExactCommand => {
            let command_digest = binding.command_digest.unwrap_or(0);
            let arguments_digest = binding.arguments_digest.unwrap_or(0);
            let reopened = receipt(GateCBindingControlKind::Reopen);
            let source_input_is_correlated = |control: &GateCControlEvidence| {
                if packet.case_id == "D04" && binding.route == GateCBindingRoute::PropertiesStaged {
                    // The final arguments already fingerprint the candidate.
                    // That event digest cannot bypass the ordered pre-accept
                    // identity proof for either D04 source field.
                    allow_d04_binding_transition
                        && gate_c_d04_exact_command_transition_is_observed(control, binding, packet)
                } else {
                    control.binding_digest == binding.expected_binding_digest
                }
            };
            command_digest != 0
                && arguments_digest != 0
                && packet.controls.iter().any(|control| {
                    control.control == "exact_command_field"
                        && same_visit(&control.identity)
                        && control.value_digest == command_digest
                        && source_input_is_correlated(control)
                })
                && packet.controls.iter().any(|control| {
                    control.control == "exact_args_field"
                        && same_visit(&control.identity)
                        && control.value_digest == arguments_digest
                        && source_input_is_correlated(control)
                })
                && packet.controls.iter().any(|control| {
                    control.control == "use_exact_command"
                        && control.clicked
                        && control.enabled
                        && same_visit(&control.identity)
                        && control.binding_digest == binding.expected_binding_digest
                })
                && reopened.is_some_and(|reopen| {
                    [
                        ("exact_command_field", command_digest),
                        ("exact_args_field", arguments_digest),
                    ]
                    .into_iter()
                    .all(|(name, value)| {
                        packet.controls.iter().any(|control| {
                            control.control == name
                                && control.identity == reopen.identity
                                && control.identity.surface == GateCSurface::Inspector
                                && Some(control.identity.session_id) != original_session_id
                                && control.value_digest == value
                                && control.binding_digest == binding.expected_binding_digest
                        })
                    })
                })
        }
    };
    receipt_semantics_match && control_receipts_match && typed_input_matches
}

fn gate_c_cancel_state_matches_next_add_baseline(
    cancelled: &GateCInsertionEvidence,
    replaced: &GateCInsertionEvidence,
) -> bool {
    let after_cancel = &cancelled.outcome_receipt.state;
    let before_replace = &replaced.source_baseline_receipt.state;
    after_cancel.editor_open
        && before_replace.editor_open
        && after_cancel.session_id == before_replace.session_id
        && after_cancel.generation == before_replace.generation
        && after_cancel.selected_target_digest == before_replace.selected_target_digest
        && after_cancel.selected_cell_digest == before_replace.selected_cell_digest
        && after_cancel.document_digest == before_replace.document_digest
        && after_cancel.assigned_binding_digest == before_replace.assigned_binding_digest
        && after_cancel.properties_staged_digest == before_replace.properties_staged_digest
        && after_cancel.action_editor == before_replace.action_editor
        && after_cancel.action_editor_authored_input_digest
            == before_replace.action_editor_authored_input_digest
        && after_cancel.search_pending == before_replace.search_pending
        && after_cancel.test_pending == before_replace.test_pending
        && after_cancel.draft_dirty == before_replace.draft_dirty
        && after_cancel.properties_dirty == before_replace.properties_dirty
        && after_cancel.undo_depth == before_replace.undo_depth
        && after_cancel.redo_depth == before_replace.redo_depth
        && after_cancel.history_entries == before_replace.history_entries
        && after_cancel.history_keys == before_replace.history_keys
        && after_cancel.history_digest == before_replace.history_digest
        && after_cancel.usage_entries == before_replace.usage_entries
        && after_cancel.usage_digest == before_replace.usage_digest
        && cancelled.document_after_digest == replaced.document_before_digest
        && cancelled.prior_binding_digest == replaced.prior_binding_digest
        && cancelled.radial_history_digest_after == replaced.radial_history_digest_before
        && cancelled.undo_depth_after == replaced.undo_depth_before
        && cancelled.redo_depth_after == replaced.redo_depth_before
        && cancelled.draft_dirty_after == replaced.draft_dirty_before
}

fn gate_c_case_contract_is_valid(packet: &GateCCaseEvidence) -> Result<(), String> {
    if packet.q14_partial.is_some() {
        return Err("a partial Q14 observation cannot satisfy a passed Gate C case".into());
    }
    if !packet.incomplete_searches.is_empty() {
        return Err("an incomplete launcher search cannot satisfy a passed Gate C case".into());
    }
    let valid_editor = packet.session_id > 0
        && packet.draft_generation > 0
        && packet.editor_identity.as_ref().is_some_and(|identity| {
            gate_c_editor_identity_is_valid(identity)
                && identity.session_id == packet.session_id
                && identity.draft_generation == packet.draft_generation
                && packet.editor_surface == Some(identity.surface)
        });
    let has_duplicate_both_surfaces = [GateCSurface::Properties, GateCSurface::Inspector]
        .into_iter()
        .all(|surface| gate_c_surface_has_duplicate_action_rows(packet, surface));
    let q14_operations_valid = packet
        .q14
        .as_ref()
        .is_some_and(|q14| gate_c_q14_operations_are_valid(packet, q14));
    let valid = match packet.case_id.as_str() {
        "D01" => {
            valid_editor
                && gate_c_packet_session_is_anchored(packet)
                && has_duplicate_both_surfaces
                && [GateCSurface::Properties, GateCSurface::Inspector]
                    .into_iter()
                    .all(|surface| gate_c_clicked_control(packet, "search", Some(surface)))
                && [GateCSurface::Properties, GateCSurface::Inspector]
                    .into_iter()
                    .all(|surface| {
                        packet.searches.iter().any(|search| {
                            search.surface == surface && search.result_order > 50 && search.settled
                        })
                    })
        }
        "D02" => {
            let separate_title_query = gate_c_search_for(
                packet,
                GateCSurface::Properties,
                GateCSearchPurpose::BeyondFifty,
            )
            .zip(gate_c_search_for(
                packet,
                GateCSurface::Properties,
                GateCSearchPurpose::TitleToken,
            ))
            .is_some_and(|(beyond, title_token)| beyond.query_digest != title_token.query_digest);
            valid_editor
                && gate_c_packet_session_is_anchored(packet)
                && has_duplicate_both_surfaces
                && gate_c_search_pair_is_shared(packet, GateCSearchPurpose::BeyondFifty)
                && gate_c_search_pair_is_shared(packet, GateCSearchPurpose::TitleToken)
                && [GateCSurface::Properties, GateCSurface::Inspector]
                    .into_iter()
                    .all(|surface| gate_c_title_token_search_is_valid(packet, surface))
                && separate_title_query
                && [GateCSurface::Properties, GateCSurface::Inspector]
                    .into_iter()
                    .all(|surface| {
                        packet.controls.iter().any(|control| {
                            matches!(control.control.as_str(), "pin" | "pin_result")
                                && control.clicked
                                && (control.control != "pin_result"
                                    || gate_c_pin_has_fresh_rendered_row(packet, control))
                                && control.identity.surface == surface
                                && packet.ordered_results.iter().any(|row| {
                                    row.surface == surface
                                        && (row.identity == control.identity
                                            || (control.control == "pin_result"
                                                && control.identity.session_id
                                                    == row.identity.session_id
                                                && control.identity.draft_generation
                                                    == row.identity.draft_generation
                                                && control.identity.stable_target_digest
                                                    == row.identity.stable_target_digest
                                                && control.identity.editor_epoch
                                                    == row.identity.editor_epoch
                                                && control.identity.query_digest
                                                    == row.identity.query_digest
                                                && (control.identity.edit_generation
                                                    == row.identity.edit_generation
                                                    || control.identity.edit_generation
                                                        == row
                                                            .identity
                                                            .edit_generation
                                                            .saturating_add(1))
                                                && (control.identity.binding_digest
                                                    == row.identity.binding_digest
                                                    || control.identity.binding_digest
                                                        == row.binding_digest)))
                                        && row.target_digest == control.target_digest
                                        && row.action_digest == control.action_digest
                                        && row.binding_digest == control.binding_digest
                                })
                        })
                    })
        }
        "D04" => {
            let persisted = packet
                .bindings
                .iter()
                .any(|binding| binding.kind == GateCBindingKind::PersistedReference);
            let open_query = packet.bindings.iter().any(|binding| {
                binding.kind == GateCBindingKind::LauncherQuery
                    && binding.query_mode == Some(GateCQueryMode::OpenLauncher)
            });
            let execute_query = packet.bindings.iter().any(|binding| {
                binding.kind == GateCBindingKind::LauncherQuery
                    && binding.query_mode == Some(GateCQueryMode::ExecuteFirst)
            });
            let exact = packet.bindings.iter().any(|binding| {
                binding.kind == GateCBindingKind::ExactCommand && binding.arguments_digest.is_some()
            });
            let properties_routes = packet
                .bindings
                .iter()
                .filter(|binding| binding.route == GateCBindingRoute::PropertiesStaged)
                .count();
            let inspector_routes = packet
                .bindings
                .iter()
                .filter(|binding| binding.route == GateCBindingRoute::InspectorDirect)
                .count();
            valid_editor
                && persisted
                && open_query
                && execute_query
                && exact
                && properties_routes >= 1
                && inspector_routes >= 1
                && packet.bindings.iter().all(|binding| {
                    gate_c_binding_is_valid(binding)
                        && gate_c_binding_control_links_are_valid(binding, packet, true)
                })
                && gate_c_clicked_control(packet, "apply", Some(GateCSurface::Properties))
                && gate_c_inspector_direct_persisted_pin_is_valid(packet)
        }
        "D06" => {
            let inserted_layouts = [GateCResultLayout::List, GateCResultLayout::Grid]
                .into_iter()
                .all(|layout| {
                    packet.insertions.iter().any(|insertion| {
                        insertion.layout == layout
                            && insertion.outcome == GateCInsertionOutcome::Inserted
                            && gate_c_insertion_is_valid(insertion)
                    })
                });
            valid_editor && inserted_layouts
        }
        "D07" => {
            let cancelled = packet
                .insertions
                .iter()
                .filter(|insertion| insertion.outcome == GateCInsertionOutcome::Cancelled)
                .collect::<Vec<_>>();
            let replaced = packet
                .insertions
                .iter()
                .filter(|insertion| insertion.outcome == GateCInsertionOutcome::Replaced)
                .collect::<Vec<_>>();
            cancelled.len() == 1
                && replaced.len() == 1
                && gate_c_insertion_is_valid(cancelled[0])
                && gate_c_insertion_is_valid(replaced[0])
                && cancelled[0].session_origin == GateCInsertionSessionOrigin::ReusedReadySession
                && replaced[0].session_origin == GateCInsertionSessionOrigin::ReusedReadySession
                && cancelled[0].layout == replaced[0].layout
                && cancelled[0].initial_snapshot_session_id
                    == replaced[0].initial_snapshot_session_id
                && cancelled[0].initial_snapshot_sequence == replaced[0].initial_snapshot_sequence
                && cancelled[0].initial_snapshot_receipt == replaced[0].initial_snapshot_receipt
                && cancelled[0].source_baseline_session_id == replaced[0].source_baseline_session_id
                && cancelled[0].source_baseline_generation == replaced[0].source_baseline_generation
                && cancelled[0].source_baseline_document_digest
                    == replaced[0].source_baseline_document_digest
                && cancelled[0].source_owner_session_id == replaced[0].source_owner_session_id
                && cancelled[0].source_owner_generation == replaced[0].source_owner_generation
                && cancelled[0].source_owner_document_digest
                    == replaced[0].source_owner_document_digest
                && cancelled[0].outcome_session_id == replaced[0].source_baseline_session_id
                && replaced[0].request_id > cancelled[0].request_id
                && cancelled[0].outcome_boundary_sequence
                    < replaced[0].source_baseline_observation_sequence
                && cancelled[0].document_before_digest == replaced[0].document_before_digest
                && cancelled[0].document_after_digest == replaced[0].document_before_digest
                && cancelled[0].unrelated_edit_digest_before
                    == replaced[0].unrelated_edit_digest_before
                && cancelled[0].unrelated_cell_target_digest
                    == replaced[0].unrelated_cell_target_digest
                && cancelled[0].unrelated_label_value_digest
                    == replaced[0].unrelated_label_value_digest
                && cancelled[0].source_target_digest == replaced[0].source_target_digest
                && cancelled[0].source_action_digest == replaced[0].source_action_digest
                && cancelled[0].source_binding_digest == replaced[0].source_binding_digest
                && cancelled[0].source_query_digest == replaced[0].source_query_digest
                && cancelled[0].destination_menu_digest == replaced[0].destination_menu_digest
                && cancelled[0].destination_ring_digest == replaced[0].destination_ring_digest
                && cancelled[0].destination_cell_digest == replaced[0].destination_cell_digest
                && replaced[0].saved_binding.as_ref().is_some_and(|binding| {
                    binding.previous_binding_digest == cancelled[0].prior_binding_digest
                })
                && gate_c_inspector_edit_sequence_is_valid(
                    &packet.inspector_text_edits,
                    cancelled[0].source_owner_session_id,
                    cancelled[0].unrelated_cell_target_digest,
                    cancelled[0].unrelated_label_value_digest,
                    cancelled[0].source_baseline_observation_sequence,
                    cancelled[0].source_baseline_generation,
                )
                && packet.inspector_text_edits.iter().any(|edit| {
                    edit.stage == GateCInspectorTextStage::Changed
                        && edit.session_id == cancelled[0].source_owner_session_id
                        && edit.target_digest == cancelled[0].unrelated_cell_target_digest
                        && edit.value_digest == cancelled[0].unrelated_label_value_digest
                        && edit.trace_sequence < cancelled[0].source_baseline_observation_sequence
                })
                && gate_c_cancel_state_matches_next_add_baseline(cancelled[0], replaced[0])
        }
        "D09" => {
            let states = &packet.authoring_states;
            let close_prompts = packet
                .designer_closes
                .iter()
                .filter(|event| event.open && event.close_prompt && event.dirty)
                .collect::<Vec<_>>();
            let keep = packet.designer_controls.iter().find(|control| {
                control.kind == GateCDesignerControlKind::KeepEditing && control.clicked
            });
            let discard = packet.designer_controls.iter().find(|control| {
                control.kind == GateCDesignerControlKind::DiscardDraft && control.clicked
            });
            let reopen = states.get(3).and_then(|state| {
                packet.d09.as_ref().and_then(|evidence| {
                    packet.initial_snapshots.iter().find(|receipt| {
                        gate_c_initial_snapshot_receipt_is_valid(receipt)
                            && gate_c_d09_reopen_selection_is_observed(
                                packet, receipt, state, evidence,
                            )
                    })
                })
            });
            let discarded_document_was_not_persisted =
                packet.d09.as_ref().is_some_and(|evidence| {
                    evidence.persisted_document_digest_before > 0
                        && evidence.persisted_document_digest_before
                            == evidence.persisted_document_digest_after
                        && states.get(3).is_some_and(|state| {
                            state.document_digest == evidence.persisted_document_digest_after
                        })
                });
            let unrelated_label_edit_was_observed = packet.d09.as_ref().is_some_and(|evidence| {
                states.first().is_some_and(|state| {
                    gate_c_inspector_edit_sequence_is_valid(
                        &packet.inspector_text_edits,
                        state.session_id,
                        evidence.unrelated_cell_target_digest,
                        evidence.unrelated_label_value_digest,
                        state.trace_sequence,
                        state.generation,
                    ) && packet.inspector_text_edits.iter().any(|edit| {
                        edit.stage == GateCInspectorTextStage::Changed
                            && edit.session_id == state.session_id
                            && edit.target_digest == evidence.unrelated_cell_target_digest
                            && edit.trace_sequence < state.trace_sequence
                    })
                })
            });
            let states_preserve_then_replace_session = states.len() == 4
                && states[0].editor_open
                && states[1].editor_open
                && states[0].baseline_request_id.is_none()
                && states[1].baseline_request_id == Some(states[0].request_id)
                && states[0].session_id == states[1].session_id
                && states[0].generation == states[1].generation
                && states[0].selected_target_digest == states[1].selected_target_digest
                && states[0].selected_cell_digest == states[1].selected_cell_digest
                && states[0].document_digest == states[1].document_digest
                && states[0].assigned_binding_digest == states[1].assigned_binding_digest
                && states[0].properties_staged_digest == states[1].properties_staged_digest
                && states[0].draft_dirty == states[1].draft_dirty
                && states[0].properties_dirty == states[1].properties_dirty
                && states[0].undo_depth == states[1].undo_depth
                && states[0].redo_depth == states[1].redo_depth
                && states[0].history_digest == states[1].history_digest
                && states[0].history_entries == states[1].history_entries
                && states[0].history_keys == states[1].history_keys
                && states[0].usage_digest == states[1].usage_digest
                && states[0].usage_entries == states[1].usage_entries
                && gate_c_same_authored_editor_state(&states[0], &states[1])
                && !states[2].editor_open
                && states[2].baseline_request_id.is_none()
                && states[2].action_editor.is_none()
                && !states[2].search_pending
                && !states[2].test_pending
                && states[3].editor_open
                && states[3].baseline_request_id == Some(states[2].request_id)
                && states[3].session_id != states[0].session_id
                && packet
                    .editor_identity
                    .as_ref()
                    .is_some_and(|identity| states[3].action_editor.as_ref() == Some(identity));
            let close_prompts_are_ordered = states.len() == 4
                && close_prompts.len() == 2
                && close_prompts[0].session_id == states[0].session_id
                && close_prompts[1].session_id == states[0].session_id
                && close_prompts[0].trace_sequence < close_prompts[1].trace_sequence
                && packet.designer_closes.iter().all(|event| {
                    event.trace_sequence > 0 && event.session_id == states[0].session_id
                });
            let keep_controls_are_ordered = close_prompts_are_ordered
                && keep.is_some_and(|keep| {
                    gate_c_designer_control_is_valid(keep)
                        && keep.session_id == states[0].session_id
                        && keep.generation == states[0].generation
                        && close_prompts[0].trace_sequence < keep.trace_sequence
                        && keep.trace_sequence < states[1].trace_sequence
                })
                && discard.is_some_and(|discard| {
                    gate_c_designer_control_is_valid(discard)
                        && discard.session_id == states[0].session_id
                        && discard.generation == states[1].generation
                        && states[1].trace_sequence < close_prompts[1].trace_sequence
                        && close_prompts[1].trace_sequence < discard.trace_sequence
                        && discard.trace_sequence < states[2].trace_sequence
                })
                && reopen.is_some_and(|receipt| {
                    states[2].trace_boundary_sequence < receipt.trace_sequence
                        && receipt.trace_sequence < states[3].trace_sequence
                });
            let keep_request_retired = packet.provider_lifecycle.iter().any(|started| {
                if states.len() != 4
                    || started.kind != GateCProviderKind::Search
                    || started.edge != GateCProviderEdge::WorkerStarted
                {
                    return false;
                }
                let queued = gate_c_provider_request_edge(
                    packet,
                    &started.identity,
                    started.query_digest,
                    GateCProviderEdge::Queued,
                );
                let retired = gate_c_provider_request_edge(
                    packet,
                    &started.identity,
                    started.query_digest,
                    GateCProviderEdge::Retired,
                );
                queued.is_some_and(|queued| {
                    gate_c_clicked_search_control_precedes_request(
                        packet,
                        &started.identity,
                        started.query_digest,
                        queued.trace_sequence,
                    ) && queued.trace_sequence < started.trace_sequence
                        && close_prompts.first().zip(keep).zip(retired).is_some_and(
                            |((close, keep), retired)| {
                                started.trace_sequence < retired.trace_sequence
                                    && retired.trace_sequence < close.trace_sequence
                                    && close.trace_sequence < keep.trace_sequence
                                    && keep.trace_sequence < states[1].trace_sequence
                            },
                        )
                })
            });
            let keep_late_reply_rejected = packet.provider_lifecycle.iter().any(|started| {
                if states.len() != 4
                    || started.kind != GateCProviderKind::Search
                    || started.edge != GateCProviderEdge::WorkerStarted
                {
                    return false;
                }
                let queued = gate_c_provider_request_edge(
                    packet,
                    &started.identity,
                    started.query_digest,
                    GateCProviderEdge::Queued,
                );
                let retired = gate_c_provider_request_edge(
                    packet,
                    &started.identity,
                    started.query_digest,
                    GateCProviderEdge::Retired,
                );
                let completed = gate_c_provider_request_edge(
                    packet,
                    &started.identity,
                    started.query_digest,
                    GateCProviderEdge::WorkerCompleted,
                );
                let rejected = gate_c_provider_request_edge(
                    packet,
                    &started.identity,
                    started.query_digest,
                    GateCProviderEdge::Rejected,
                );
                queued
                    .zip(retired)
                    .zip(completed)
                    .zip(rejected)
                    .is_some_and(|(((queued, retired), completed), rejected)| {
                        gate_c_clicked_search_control_precedes_request(
                            packet,
                            &started.identity,
                            started.query_digest,
                            queued.trace_sequence,
                        ) && close_prompts
                            .first()
                            .zip(keep)
                            .is_some_and(|(close, keep)| {
                                queued.trace_sequence < started.trace_sequence
                                    && started.trace_sequence < retired.trace_sequence
                                    && retired.trace_sequence < close.trace_sequence
                                    && close.trace_sequence < keep.trace_sequence
                                    && keep.trace_sequence < states[1].trace_sequence
                                    && states[1].trace_sequence < completed.trace_sequence
                                    && completed.trace_sequence < rejected.trace_sequence
                                    && rejected.trace_sequence < states[2].trace_sequence
                                    && !packet.provider_lifecycle.iter().any(|event| {
                                        event.kind == started.kind
                                            && event.identity == started.identity
                                            && event.query_digest == started.query_digest
                                            && event.binding_digest == started.binding_digest
                                            && event.edge == GateCProviderEdge::Applied
                                            && event.trace_sequence > retired.trace_sequence
                                    })
                            })
                    })
            });
            let late_reply_rejected = packet.provider_lifecycle.iter().any(|started| {
                if states.len() != 4
                    || started.kind != GateCProviderKind::Search
                    || started.edge != GateCProviderEdge::WorkerStarted
                    || started.trace_sequence <= states[1].trace_sequence
                    || started.trace_sequence >= states[2].trace_sequence
                    || started.identity.session_id != states[0].session_id
                {
                    return false;
                }
                let queued = gate_c_provider_request_edge(
                    packet,
                    &started.identity,
                    started.query_digest,
                    GateCProviderEdge::Queued,
                );
                let retired = gate_c_provider_request_edge(
                    packet,
                    &started.identity,
                    started.query_digest,
                    GateCProviderEdge::Retired,
                );
                let completed = gate_c_provider_request_edge(
                    packet,
                    &started.identity,
                    started.query_digest,
                    GateCProviderEdge::WorkerCompleted,
                );
                let rejected = gate_c_provider_request_edge(
                    packet,
                    &started.identity,
                    started.query_digest,
                    GateCProviderEdge::Rejected,
                );
                queued
                    .zip(retired)
                    .zip(completed)
                    .zip(rejected)
                    .is_some_and(|(((queued, retired), completed), rejected)| {
                        let reopen = reopen.map_or(0, |receipt| receipt.trace_sequence);
                        gate_c_clicked_search_control_precedes_request(
                            packet,
                            &started.identity,
                            started.query_digest,
                            queued.trace_sequence,
                        ) && close_prompts.get(1).zip(discard).is_some_and(
                            |(second_close, discard)| {
                                queued.trace_sequence < started.trace_sequence
                                    && started.trace_sequence < retired.trace_sequence
                                    && retired.trace_sequence < second_close.trace_sequence
                                    && second_close.trace_sequence < discard.trace_sequence
                                    && discard.trace_sequence < states[2].trace_sequence
                                    && states[2].trace_boundary_sequence < reopen
                                    && reopen < completed.trace_sequence
                                    && completed.trace_sequence < rejected.trace_sequence
                                    && rejected.trace_sequence <= states[3].trace_sequence
                                    && rejected.trace_sequence < states[3].trace_boundary_sequence
                                    && !packet.provider_lifecycle.iter().any(|event| {
                                        event.kind == started.kind
                                            && event.identity == started.identity
                                            && event.query_digest == started.query_digest
                                            && event.binding_digest == started.binding_digest
                                            && event.edge == GateCProviderEdge::Applied
                                            && event.trace_sequence > retired.trace_sequence
                                    })
                            },
                        )
                    })
            });
            valid_editor
                && states.len() == 4
                && gate_c_authoring_state_is_valid(&states[0])
                && gate_c_authoring_state_is_valid(&states[1])
                && gate_c_authoring_state_is_valid(&states[2])
                && gate_c_authoring_state_is_valid(&states[3])
                && keep_late_reply_rejected
                && late_reply_rejected
                && keep_request_retired
                && states_preserve_then_replace_session
                && keep_controls_are_ordered
                && packet.designer_controls.len() == 2
                && packet.designer_closes.len() == 2
                && packet.initial_snapshots.len() == 1
                && discarded_document_was_not_persisted
                && unrelated_label_edit_was_observed
        }
        "Q14" => packet
            .q14
            .as_ref()
            .is_some_and(|evidence| gate_c_q14_is_zero_effect(evidence) && q14_operations_valid),
        _ => false,
    };
    if valid {
        Ok(())
    } else {
        Err(format!(
            "{} Gate C evidence does not prove its native case contract",
            packet.case_id
        ))
    }
}

fn gate_c_q14_is_zero_effect(evidence: &GateCQ14Evidence) -> bool {
    let before = &evidence.baseline;
    let after = &evidence.terminal;
    before.request_id > 0
        && before.baseline_request_id.is_none()
        && after.request_id > before.request_id
        && after.baseline_request_id == Some(before.request_id)
        && after.frame_ordinal > before.frame_ordinal
        && after.trace_sequence > before.trace_sequence
        && gate_c_authoring_state_is_valid(before)
        && gate_c_authoring_state_is_valid(after)
        && before.editor_open
        && after.editor_open
        && before.action_editor.is_some()
        && after.action_editor.is_some()
        && before.history_entries == after.history_entries
        && before.history_keys == after.history_keys
        && before.history_digest == after.history_digest
        && before.usage_entries == after.usage_entries
        && before.usage_digest == after.usage_digest
        && evidence.marker_entries_before == evidence.marker_entries_after
        && evidence.marker_digest_before != 0
        && evidence.marker_digest_before == evidence.marker_digest_after
        && evidence.normal_dispatches == 0
        && evidence.universal_action_dispatches == 0
        && evidence.radial_action_dispatches == 0
        && evidence.authoring_tests == 0
}

fn gate_c_q14_provider_work_is_settled(
    packet: &GateCCaseEvidence,
    evidence: &GateCQ14Evidence,
) -> bool {
    let lower = evidence.baseline.trace_boundary_sequence;
    let upper = evidence.terminal.trace_sequence;
    let in_window = packet
        .provider_lifecycle
        .iter()
        .filter(|event| event.trace_sequence > lower && event.trace_sequence < upper)
        .collect::<Vec<_>>();
    let same_request = |left: &GateCProviderLifecycleEvidence,
                        right: &GateCProviderLifecycleEvidence| {
        left.kind == right.kind
            && left.identity == right.identity
            && left.query_digest == right.query_digest
            && left.binding_digest == right.binding_digest
    };
    let is_queue = |event: &GateCProviderLifecycleEvidence| {
        matches!(
            event.edge,
            GateCProviderEdge::Queued | GateCProviderEdge::RetryQueued
        )
    };
    let each_event_has_window_queue = in_window.iter().copied().all(|event| {
        in_window.iter().copied().any(|queued| {
            is_queue(queued)
                && same_request(queued, event)
                && queued.trace_sequence <= event.trace_sequence
        })
    });
    let mut request_groups: Vec<Vec<&GateCProviderLifecycleEvidence>> = Vec::new();
    for event in &in_window {
        if let Some(group) = request_groups
            .iter_mut()
            .find(|group| same_request(group[0], event))
        {
            group.push(event);
        } else {
            request_groups.push(vec![event]);
        }
    }
    let mut sequences = in_window
        .iter()
        .map(|event| event.trace_sequence)
        .collect::<Vec<_>>();
    sequences.sort_unstable();
    let unique_ordered_sequence = sequences.windows(2).all(|pair| pair[0] < pair[1]);
    let each_request_is_settled = request_groups.iter_mut().all(|group| {
        group.sort_by_key(|event| event.trace_sequence);
        gate_c_q14_request_lifecycle_is_settled(group, upper)
    });
    let no_pending_at_boundaries = [&evidence.baseline, &evidence.terminal]
        .into_iter()
        .all(|state| !state.search_pending && !state.test_pending);
    unique_ordered_sequence
        && each_event_has_window_queue
        && each_request_is_settled
        && no_pending_at_boundaries
}

fn gate_c_q14_request_lifecycle_is_settled(
    events: &[&GateCProviderLifecycleEvidence],
    upper: u64,
) -> bool {
    #[derive(Clone, Copy, PartialEq, Eq)]
    enum State {
        InitialQueue,
        WorkerStart,
        WorkerTerminal,
        Classification,
        AfterRejection,
        Settled,
    }

    if events.is_empty() {
        return false;
    }

    let mut state = State::InitialQueue;
    let mut retired = false;
    for (index, event) in events.iter().enumerate() {
        if event.trace_sequence >= upper {
            return false;
        }
        state = match (state, event.edge) {
            (State::InitialQueue, GateCProviderEdge::Queued) => State::WorkerStart,
            (State::WorkerStart, GateCProviderEdge::WorkerStarted) => State::WorkerTerminal,
            (State::WorkerTerminal, GateCProviderEdge::WorkerCompleted)
            | (State::WorkerTerminal, GateCProviderEdge::WorkerFailed) => State::Classification,
            (State::WorkerStart, GateCProviderEdge::Rejected) => State::Settled,
            (State::Classification, GateCProviderEdge::Applied) => State::Settled,
            (State::Classification, GateCProviderEdge::Rejected) => State::AfterRejection,
            (State::AfterRejection, GateCProviderEdge::RetryQueued) => State::WorkerStart,
            (State::WorkerStart, GateCProviderEdge::Retired)
            | (State::WorkerTerminal, GateCProviderEdge::Retired)
            | (State::Classification, GateCProviderEdge::Retired)
                if !retired =>
            {
                retired = true;
                state
            }
            (State::WorkerStart, GateCProviderEdge::Cancelled)
            | (State::WorkerTerminal, GateCProviderEdge::Cancelled)
            | (State::Classification, GateCProviderEdge::Cancelled) => State::Settled,
            _ => return false,
        };
        if state == State::Settled && index + 1 != events.len() {
            return false;
        }
    }
    matches!(state, State::Settled | State::AfterRejection)
}

fn gate_c_q14_operations_are_valid(
    packet: &GateCCaseEvidence,
    evidence: &GateCQ14Evidence,
) -> bool {
    let before = evidence.baseline.trace_boundary_sequence;
    let after = evidence.terminal.trace_sequence;
    let control_name = |kind| match kind {
        GateCQ14OperationKind::QueryEdit | GateCQ14OperationKind::EnterSearch => "query_field",
        GateCQ14OperationKind::Search => "search",
        GateCQ14OperationKind::SelectResult => "result_target",
        GateCQ14OperationKind::ModeChange => "query_mode",
        GateCQ14OperationKind::Pin | GateCQ14OperationKind::InspectorAssignment => "pin_result",
        GateCQ14OperationKind::SaveQuery => "save_query",
        GateCQ14OperationKind::Advanced => "advanced_tab",
        GateCQ14OperationKind::PropertiesApply => "apply",
        GateCQ14OperationKind::DesignerSave => "save",
        GateCQ14OperationKind::Reopen => "",
    };
    let operation_has_control = |operation: &GateCQ14OperationEvidence| {
        if operation.kind == GateCQ14OperationKind::Reopen {
            return packet.initial_snapshots.iter().any(|receipt| {
                gate_c_initial_snapshot_receipt_is_valid(receipt)
                    && receipt.trace_sequence == operation.control_sequence
                    && receipt.session_id == operation.identity.session_id
                    && receipt.generation <= operation.identity.draft_generation
            });
        }
        packet.controls.iter().any(|control| {
            control.control == control_name(operation.kind)
                && match operation.kind {
                    GateCQ14OperationKind::QueryEdit => control.changed,
                    GateCQ14OperationKind::EnterSearch => control.enter_pressed,
                    _ => control.clicked,
                }
                && control.enabled
                && control.trace_sequence == operation.control_sequence
                && control.trace_sequence == operation.trace_sequence
                && control.identity == operation.identity
                && control.query_digest == operation.query_digest
                && control.binding_digest == operation.binding_digest
                && (!matches!(
                    operation.kind,
                    GateCQ14OperationKind::Pin | GateCQ14OperationKind::InspectorAssignment
                ) || gate_c_pin_has_fresh_rendered_row(packet, control))
        })
    };
    let input_matches = |operation: &GateCQ14OperationEvidence| match operation.kind {
        GateCQ14OperationKind::QueryEdit => operation.input_method == GateCInputMethod::TextInput,
        GateCQ14OperationKind::EnterSearch => {
            operation.input_method == GateCInputMethod::KeyboardEnter
        }
        GateCQ14OperationKind::ModeChange => operation.input_method == GateCInputMethod::Toggle,
        GateCQ14OperationKind::Reopen => operation.input_method == GateCInputMethod::OwnerReply,
        _ => operation.input_method == GateCInputMethod::Pointer,
    };
    let required = [
        GateCQ14OperationKind::QueryEdit,
        GateCQ14OperationKind::Search,
        GateCQ14OperationKind::EnterSearch,
        GateCQ14OperationKind::SelectResult,
        GateCQ14OperationKind::ModeChange,
        GateCQ14OperationKind::Pin,
        GateCQ14OperationKind::SaveQuery,
        GateCQ14OperationKind::Advanced,
        GateCQ14OperationKind::PropertiesApply,
        GateCQ14OperationKind::InspectorAssignment,
        GateCQ14OperationKind::DesignerSave,
        GateCQ14OperationKind::Reopen,
    ];
    let operations = &evidence.operations;
    operations.len() <= MAX_GATE_C_Q14_OPERATIONS
        && operations.len() >= required.len()
        && operations.iter().all(|operation| {
            operation.trace_sequence > before
                && operation.trace_sequence < after
                && operation.trace_sequence == operation.control_sequence
                && gate_c_editor_identity_is_valid(&operation.identity)
                && operation.query_digest == operation.identity.query_digest
                && operation_has_control(operation)
                && input_matches(operation)
        })
        && operations
            .windows(2)
            .all(|pair| pair[0].trace_sequence < pair[1].trace_sequence)
        && required
            .into_iter()
            .all(|kind| operations.iter().any(|operation| operation.kind == kind))
        && operations
            .iter()
            .filter(|operation| operation.kind == GateCQ14OperationKind::Search)
            .all(|operation| {
                packet.searches.iter().any(|search| {
                    search.search_control_sequence == operation.control_sequence
                        && search.identity == operation.identity
                        && search.query_digest == operation.query_digest
                        && search.observed_trace_sequence < after
                })
            })
        && operations
            .iter()
            .filter(|operation| operation.kind == GateCQ14OperationKind::EnterSearch)
            .all(|operation| {
                let same_request = |event: &&GateCProviderLifecycleEvidence| {
                    event.kind == GateCProviderKind::Search
                        && gate_c_q14_search_request_identity_matches(
                            &operation.identity,
                            &event.identity,
                        )
                        && event.query_digest == operation.query_digest
                };
                let queued = packet
                    .provider_lifecycle
                    .iter()
                    .filter(same_request)
                    .find(|event| {
                        matches!(
                            event.edge,
                            GateCProviderEdge::Queued | GateCProviderEdge::RetryQueued
                        )
                    });
                queued.is_some_and(|queued| queued.trace_sequence > operation.trace_sequence)
            })
        && operations
            .iter()
            .filter(|operation| operation.kind == GateCQ14OperationKind::Reopen)
            .all(|reopen| {
                let saved_session = operations
                    .iter()
                    .find(|operation| operation.kind == GateCQ14OperationKind::DesignerSave)
                    .map(|operation| operation.identity.session_id);
                packet.initial_snapshots.iter().any(|receipt| {
                    gate_c_initial_snapshot_receipt_is_valid(receipt)
                        && receipt.trace_sequence == reopen.control_sequence
                        && receipt.session_id == reopen.identity.session_id
                        && receipt.generation <= reopen.identity.draft_generation
                        && saved_session.is_some_and(|session_id| session_id != receipt.session_id)
                })
            })
        && [GateCSurface::Properties, GateCSurface::Inspector]
            .into_iter()
            .all(|surface| {
                operations.iter().any(|operation| {
                    operation.kind == GateCQ14OperationKind::Search
                        && operation.identity.surface == surface
                })
            })
        && operations.iter().any(|operation| {
            operation.kind == GateCQ14OperationKind::InspectorAssignment
                && operation.identity.surface == GateCSurface::Inspector
        })
        && operations.iter().any(|operation| {
            operation.kind == GateCQ14OperationKind::PropertiesApply
                && operation.identity.surface == GateCSurface::Properties
        })
        && evidence
            .baseline
            .action_editor
            .as_ref()
            .is_some_and(|baseline| {
                operations
                    .iter()
                    .find(|operation| operation.kind == GateCQ14OperationKind::QueryEdit)
                    .is_some_and(|query_edit| {
                        gate_c_same_editor_visit(baseline, &query_edit.identity)
                    })
            })
        && evidence
            .terminal
            .action_editor
            .as_ref()
            .is_some_and(|terminal| {
                packet.editor_identity.as_ref() == Some(terminal)
                    && packet.session_id == evidence.terminal.session_id
                    && packet.draft_generation == evidence.terminal.generation
                    && packet.editor_surface == Some(terminal.surface)
                    && operations.last().is_some_and(|operation| {
                        operation.kind == GateCQ14OperationKind::Reopen
                            && operation.identity == *terminal
                    })
            })
        && gate_c_q14_provider_work_is_settled(packet, evidence)
}

fn gate_c_q14_search_request_identity_matches(
    enter_identity: &GateCEditorIdentity,
    request_identity: &GateCEditorIdentity,
) -> bool {
    let mut expected = enter_identity.clone();
    expected.search_request_generation = expected.search_request_generation.wrapping_add(1).max(1);
    &expected == request_identity
}

fn gate_c_q14_operation_control_name(kind: GateCQ14OperationKind) -> &'static str {
    match kind {
        GateCQ14OperationKind::QueryEdit | GateCQ14OperationKind::EnterSearch => "query_field",
        GateCQ14OperationKind::Search => "search",
        GateCQ14OperationKind::SelectResult => "result_target",
        GateCQ14OperationKind::ModeChange => "query_mode",
        GateCQ14OperationKind::Pin | GateCQ14OperationKind::InspectorAssignment => "pin_result",
        GateCQ14OperationKind::SaveQuery => "save_query",
        GateCQ14OperationKind::Advanced => "advanced_tab",
        GateCQ14OperationKind::PropertiesApply => "apply",
        GateCQ14OperationKind::DesignerSave => "save",
        GateCQ14OperationKind::Reopen => "",
    }
}

fn gate_c_q14_operation_has_control(
    packet: &GateCCaseEvidence,
    operation: &GateCQ14OperationEvidence,
) -> bool {
    if operation.kind == GateCQ14OperationKind::Reopen {
        return packet.initial_snapshots.iter().any(|receipt| {
            gate_c_initial_snapshot_receipt_is_valid(receipt)
                && receipt.trace_sequence == operation.control_sequence
                && receipt.session_id == operation.identity.session_id
                && receipt.generation <= operation.identity.draft_generation
                && packet.q14_partial.as_ref().is_some_and(|partial| {
                    partial.terminal.as_ref().is_some_and(|terminal| {
                        terminal.request_id > partial.baseline.request_id
                            && terminal.baseline_request_id == Some(partial.baseline.request_id)
                            && terminal.action_editor.as_ref() == Some(&operation.identity)
                    })
                })
        });
    }
    packet.controls.iter().any(|control| {
        control.control == gate_c_q14_operation_control_name(operation.kind)
            && match operation.kind {
                GateCQ14OperationKind::QueryEdit => control.changed,
                GateCQ14OperationKind::EnterSearch => control.enter_pressed,
                _ => control.clicked,
            }
            && control.enabled
            && control.trace_sequence == operation.control_sequence
            && control.trace_sequence == operation.trace_sequence
            && control.identity == operation.identity
            && control.query_digest == operation.query_digest
            && control.binding_digest == operation.binding_digest
    })
}

fn gate_c_q14_partial_is_valid(
    packet: &GateCCaseEvidence,
    partial: &GateCQ14PartialEvidence,
) -> bool {
    let baseline = &partial.baseline;
    let terminal_sequence = partial
        .terminal
        .as_ref()
        .map(|terminal| terminal.trace_sequence);
    let baseline_is_valid = gate_c_authoring_state_is_valid(baseline)
        && baseline.baseline_request_id.is_none()
        && baseline.trace_boundary_sequence > 0
        && baseline.action_editor.as_ref().is_none_or(|identity| {
            identity.surface == GateCSurface::Properties
                && identity.session_id == baseline.session_id
                && identity.draft_generation == baseline.generation
                && identity.stable_target_digest == baseline.selected_target_digest
                && identity.binding_digest == baseline.assigned_binding_digest
        });
    let terminal_is_valid = partial.terminal.as_ref().is_none_or(|terminal| {
        gate_c_authoring_state_is_valid(terminal)
            && terminal.baseline_request_id == Some(baseline.request_id)
            && terminal.request_id > baseline.request_id
            && terminal.trace_sequence > baseline.trace_boundary_sequence
    });
    let operation_owner_is_valid = partial.operations.iter().all(|operation| {
        if operation.kind == GateCQ14OperationKind::Reopen {
            return partial.terminal.as_ref().is_some_and(|terminal| {
                terminal.session_id == operation.identity.session_id
                    && terminal.generation == operation.identity.draft_generation
                    && terminal.action_editor.as_ref() == Some(&operation.identity)
            });
        }
        baseline.action_editor.is_some()
            && operation.identity.session_id == baseline.session_id
            && operation.identity.draft_generation >= baseline.generation
            && operation.identity.stable_target_digest == baseline.selected_target_digest
            && terminal_sequence.is_none_or(|sequence| sequence > operation.trace_sequence)
    });
    let operations_are_valid = partial.operations.len() <= MAX_GATE_C_Q14_OPERATIONS
        && partial.operations.windows(2).all(|pair| {
            pair[0].trace_sequence < pair[1].trace_sequence
                && (pair[0].kind == GateCQ14OperationKind::Reopen
                    || pair[1].kind == GateCQ14OperationKind::Reopen
                    || pair[1].identity.draft_generation >= pair[0].identity.draft_generation)
        })
        && operation_owner_is_valid
        && partial.operations.iter().all(|operation| {
            operation.trace_sequence > baseline.trace_boundary_sequence
                && terminal_sequence.is_none_or(|sequence| operation.trace_sequence < sequence)
                && operation.trace_sequence == operation.control_sequence
                && gate_c_editor_identity_is_valid(&operation.identity)
                && operation.query_digest == operation.identity.query_digest
                && operation.query_digest != 0
                && gate_c_q14_operation_has_control(packet, operation)
                && match operation.kind {
                    GateCQ14OperationKind::QueryEdit => {
                        operation.input_method == GateCInputMethod::TextInput
                    }
                    GateCQ14OperationKind::EnterSearch => {
                        operation.input_method == GateCInputMethod::KeyboardEnter
                    }
                    GateCQ14OperationKind::ModeChange => {
                        operation.input_method == GateCInputMethod::Toggle
                    }
                    GateCQ14OperationKind::Reopen => {
                        operation.input_method == GateCInputMethod::OwnerReply
                    }
                    _ => operation.input_method == GateCInputMethod::Pointer,
                }
        });
    let derived_search_lifecycle_is_prefix = partial
        .operations
        .iter()
        .filter(|operation| {
            matches!(
                operation.kind,
                GateCQ14OperationKind::QueryEdit | GateCQ14OperationKind::EnterSearch
            )
        })
        .all(|operation| {
            let mut events = packet
                .provider_lifecycle
                .iter()
                .filter(|event| {
                    event.kind == GateCProviderKind::Search
                        && gate_c_q14_search_request_identity_matches(
                            &operation.identity,
                            &event.identity,
                        )
                        && event.query_digest == operation.query_digest
                        && event.binding_digest == 0
                        && event.trace_sequence > operation.trace_sequence
                })
                .collect::<Vec<_>>();
            events.sort_by_key(|event| event.trace_sequence);
            gate_c_q14_request_lifecycle_is_valid_prefix(&events)
        });
    baseline_is_valid
        && terminal_is_valid
        && operations_are_valid
        && derived_search_lifecycle_is_prefix
}

fn gate_c_q14_request_lifecycle_is_valid_prefix(
    events: &[&GateCProviderLifecycleEvidence],
) -> bool {
    #[derive(Clone, Copy, PartialEq, Eq)]
    enum State {
        InitialQueue,
        WorkerStart,
        WorkerTerminal,
        Classification,
        AfterRejection,
        Settled,
    }

    let mut state = State::InitialQueue;
    let mut prior_sequence = 0;
    let mut retired = false;
    for (index, event) in events.iter().enumerate() {
        if event.trace_sequence <= prior_sequence {
            return false;
        }
        prior_sequence = event.trace_sequence;
        state = match (state, event.edge) {
            (State::InitialQueue, GateCProviderEdge::Queued) => State::WorkerStart,
            (State::WorkerStart, GateCProviderEdge::WorkerStarted) => State::WorkerTerminal,
            (State::WorkerTerminal, GateCProviderEdge::WorkerCompleted)
            | (State::WorkerTerminal, GateCProviderEdge::WorkerFailed) => State::Classification,
            (State::WorkerStart, GateCProviderEdge::Rejected) => State::Settled,
            (State::Classification, GateCProviderEdge::Applied) => State::Settled,
            (State::Classification, GateCProviderEdge::Rejected) => State::AfterRejection,
            (State::AfterRejection, GateCProviderEdge::RetryQueued) => State::WorkerStart,
            (State::WorkerStart, GateCProviderEdge::Retired)
            | (State::WorkerTerminal, GateCProviderEdge::Retired)
            | (State::Classification, GateCProviderEdge::Retired)
                if !retired =>
            {
                retired = true;
                state
            }
            (State::WorkerStart, GateCProviderEdge::Cancelled)
            | (State::WorkerTerminal, GateCProviderEdge::Cancelled)
            | (State::Classification, GateCProviderEdge::Cancelled) => State::Settled,
            _ => return false,
        };
        if state == State::Settled && index + 1 != events.len() {
            return false;
        }
    }
    true
}

fn query_invocation_evidence_is_valid(
    invocation: &QueryInvocationEvidence,
    report: &AcceptanceReport,
) -> bool {
    let expected_pid = report.environment.child_process_id.unwrap_or(0);
    !invocation.cell_id.is_empty()
        && invocation.cell_id.len() <= 128
        && invocation
            .cell_id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
        && invocation.cell_digest == query_cell_digest(&invocation.cell_id)
        && invocation.query_digest > 0
        && invocation.cell_digest > 0
        && invocation.session_digest > 0
        && invocation.invocation_id > 0
        && invocation.session_generation > 0
        && invocation.config_revision > 0
        && invocation.preparation_generation > 0
        && ((invocation.mode != QueryEvidenceMode::ExecuteFirst)
            || (invocation.resolution_state == QueryEvidenceState::ManualUi
                || invocation.provider_revision.is_some()))
        && invocation.root_observations.len() >= 2
        && invocation.root_observations.len() <= 16
        && invocation.root_sample_count >= invocation.root_observations.len()
        && invocation.root_sample_count <= 512
        && invocation.root_observations.iter().all(|sample| {
            sample.hwnd > 0
                && sample.process_id == expected_pid
                && sample.bounds[2] > sample.bounds[0]
                && sample.bounds[3] > sample.bounds[1]
                && sample.physically_visible
                    == (sample.visible
                        && !sample.minimized
                        && report.environment.monitors.iter().any(|monitor| {
                            sample.bounds[0] < monitor.x.saturating_add(monitor.width as i32)
                                && monitor.x < sample.bounds[2]
                                && sample.bounds[1]
                                    < monitor.y.saturating_add(monitor.height as i32)
                                && monitor.y < sample.bounds[3]
                        }))
        })
        && invocation
            .root_observations
            .windows(2)
            .all(|pair| pair[0].hwnd == pair[1].hwnd && pair[0].process_id == pair[1].process_id)
        && invocation.root_visible_samples + invocation.root_hidden_samples
            == invocation.root_sample_count
        && invocation
            .root_observations
            .iter()
            .filter(|sample| sample.physically_visible)
            .count()
            <= invocation.root_visible_samples
        && invocation
            .root_observations
            .iter()
            .filter(|sample| !sample.physically_visible)
            .count()
            <= invocation.root_hidden_samples
        && invocation.root_visibility_violation_count == 0
        && invocation.root_identity_violation_count == 0
        && (invocation.resolution_state != QueryEvidenceState::Ready
            || (invocation.result_count > 0
                && invocation.result_digest > 0
                && invocation.selected_digest.is_some_and(|digest| digest > 0)))
        && (invocation.resolution_state != QueryEvidenceState::NoResults
            || (invocation.result_count == 0 && invocation.selected_digest.is_none()))
        && query_setup_visibility_is_valid(&invocation.setup_visibility, report.hotkey)
        && invocation.pointer_click.down_inserted == 1
        && invocation.pointer_click.up_inserted == 1
        && invocation.pointer_click.layout_generation > 0
        && invocation.pointer_click.down_event_ordinal > 0
        && invocation.pointer_click.up_event_ordinal > invocation.pointer_click.down_event_ordinal
        && invocation.pointer_click.release_settle_ms <= 2_000
        && preserved_query_state_is_valid(invocation)
        && invocation.forbidden_root_command_count == 0
}

fn query_setup_visibility_is_valid(
    evidence: &QuerySetupVisibilityEvidence,
    hotkey: AcceptanceHotkey,
) -> bool {
    if evidence.visible_before == evidence.desired_visible {
        return evidence.tap.is_none();
    }
    let Some(tap) = evidence.tap.as_ref() else {
        return false;
    };
    let expected = expected_setup_hotkey_edges(hotkey);
    let observed = tap
        .observed_edges
        .iter()
        .map(|edge| (edge.virtual_key, edge.down))
        .collect::<Vec<_>>();
    let expected_pairs = expected.iter().filter(|(_, down)| *down).count();
    !expected.is_empty()
        && tap.input_down_inserted == expected_pairs
        && tap.input_up_inserted == expected_pairs
        && tap.quiet_preflight_ms >= 75
        && tap.quiet_preflight_ms <= 1_000
        // `wait_for_key_quiet` reports all matching edges observed while it
        // waited, including edges that preceded the final uninterrupted quiet
        // interval. Keep that count as evidence, but require a bounded count and
        // validate the actual settled interval above.
        && tap.quiet_matching_edges <= 256
        && tap.observer_default_desktop
        && observed == expected
        && tap.foreign_edges.is_empty()
        && tap.observed_edges.iter().all(|edge| {
            edge.injected && edge.runner_cookie_matched && edge.runner_relative_us <= 5_000_000
        })
        && tap.trace_cursor > 0
        && tap.invocation_id > 0
        && tap.generation > 0
        && tap.press_event_ordinal > tap.trace_cursor
        && tap.release_event_ordinal > tap.press_event_ordinal
        && tap.short_tap_event_ordinal > tap.release_event_ordinal
        && tap.visibility_event_ordinal > tap.short_tap_event_ordinal
        && tap.visibility_visible == evidence.desired_visible
}

fn preserved_query_state_is_valid(invocation: &QueryInvocationEvidence) -> bool {
    let should_have_snapshot = invocation.root_policy == QueryEvidenceRootPolicy::Preserve
        && invocation.dispatch_outcome == QueryEvidenceOutcome::Executed
        && invocation.selected_digest.is_some();
    if !should_have_snapshot {
        return invocation.source.is_none()
            && invocation.root_state_before.is_none()
            && invocation.root_state_after.is_none()
            && invocation.ordinary_baseline_request_id.is_none()
            && invocation.ordinary_terminal_request_id.is_none()
            && invocation.ordinary_baseline_frame_ordinal.is_none()
            && invocation.ordinary_terminal_frame_ordinal.is_none();
    }
    let (
        Some(source),
        Some(before),
        Some(after),
        Some(selected_digest),
        Some(baseline_request_id),
        Some(terminal_request_id),
        Some(baseline_frame_ordinal),
        Some(terminal_frame_ordinal),
    ) = (
        invocation.source,
        invocation.root_state_before.as_ref(),
        invocation.root_state_after.as_ref(),
        invocation.selected_digest,
        invocation.ordinary_baseline_request_id,
        invocation.ordinary_terminal_request_id,
        invocation.ordinary_baseline_frame_ordinal,
        invocation.ordinary_terminal_frame_ordinal,
    )
    else {
        return false;
    };
    baseline_request_id > 0
        && terminal_request_id > baseline_request_id
        && baseline_frame_ordinal > 0
        && terminal_frame_ordinal > baseline_frame_ordinal
        && before.state_digest > 0
        && before.query_digest > 0
        && before.results_digest > 0
        && before.last_search_query_digest > 0
        && before.suggestions_digest > 0
        && before.query_history_digest > 0
        && before.visibility_revision > 0
        && before.matching_history_count <= before.usage_count as usize
        && before.source_history_count <= before.matching_history_count
        && before.source_history_count <= before.usage_count as usize
        && after.source_history_count <= after.matching_history_count
        && after.source_history_count <= after.usage_count as usize
        && before.state_digest == after.state_digest
        && before.query_digest == after.query_digest
        && before.action_digest == selected_digest
        && after.action_digest == selected_digest
        && before.results_digest == after.results_digest
        && before.results_count == after.results_count
        && before.selected_index == after.selected_index
        && before.grid_layout == after.grid_layout
        && before.visible == after.visible
        && before.restore == after.restore
        && before.visibility_revision == after.visibility_revision
        && before.focus_query == after.focus_query
        && before.move_cursor_end == after.move_cursor_end
        && before.last_results_valid == after.last_results_valid
        && before.last_search_query_digest == after.last_search_query_digest
        && before.suggestions_digest == after.suggestions_digest
        && before.autocomplete_index == after.autocomplete_index
        && before.query_history_digest == after.query_history_digest
        && after.matching_history_count == before.matching_history_count.saturating_add(1)
        && after.source_history_count == before.source_history_count.saturating_add(1)
        && after.usage_count == before.usage_count.saturating_add(1)
        && matches!(
            source,
            QueryEvidenceSource::Click
                | QueryEvidenceSource::RadialRelease
                | QueryEvidenceSource::RadialShortcut
                | QueryEvidenceSource::RadialHotstring
        )
}

fn query_cell_digest(value: &str) -> u64 {
    value.bytes().fold(0xcbf29ce484222325, |hash, byte| {
        (hash ^ u64::from(byte)).wrapping_mul(0x100000001b3)
    })
}

fn owned_root_presentation_is_valid(
    sample: &QueryRootPresentationEvidence,
    displays: &[[i32; 4]],
    hwnd: u64,
    process_id: u32,
    physically_visible: bool,
) -> bool {
    let on_display = displays.iter().any(|display| {
        sample.bounds[0] < display[2]
            && sample.bounds[2] > display[0]
            && sample.bounds[1] < display[3]
            && sample.bounds[3] > display[1]
    });
    hwnd > 0
        && process_id > 0
        && sample.hwnd == hwnd
        && sample.process_id == process_id
        && sample.bounds[2] > sample.bounds[0]
        && sample.bounds[3] > sample.bounds[1]
        && sample.physically_visible == (sample.visible && !sample.minimized && on_display)
        && sample.physically_visible == physically_visible
}

fn query_placement_toggle_is_valid(
    toggle: &QueryPlacementToggleEvidence,
    hotkey: AcceptanceHotkey,
    displays: &[[i32; 4]],
    hwnd: u64,
    process_id: u32,
    visible: bool,
) -> bool {
    let Some(tap) = toggle.input.tap.as_ref() else {
        return false;
    };
    let command = &toggle.command;
    let snapshot = &toggle.snapshot;
    query_setup_visibility_is_valid(&toggle.input, hotkey)
        && tap
            .observed_edges
            .windows(2)
            .all(|edges| edges[0].runner_relative_us <= edges[1].runner_relative_us)
        && toggle.input.visible_before != visible
        && toggle.input.desired_visible == visible
        && toggle.visibility_revision > 0
        && command.stream == HotkeyCandidateStream::MainCandidate
        && command.input_purpose == HotkeyRunnerInputPurpose::LauncherChord
        && command.input_group_id > 0
        && command.kind == HotkeyTraceEventKind::RootCommand
        && command.visibility_revision == Some(toggle.visibility_revision)
        && command.invocation_id == Some(tap.invocation_id)
        && command.request_id.is_some_and(|id| id > 0)
        && usize::try_from(command.event_ordinal).unwrap_or(0) > tap.visibility_event_ordinal
        && matches!(
            command.command,
            Some(
                HotkeyRootCommand::Show
                    | HotkeyRootCommand::Minimize
                    | HotkeyRootCommand::Position
                    | HotkeyRootCommand::ParkingBoundary
            )
        )
        && snapshot.stream == command.stream
        && snapshot.input_group_id == command.input_group_id
        && snapshot.input_purpose == command.input_purpose
        && snapshot.kind == HotkeyTraceEventKind::NativeWindowSnapshot
        && snapshot.request_id == command.request_id
        && snapshot.visibility_revision == command.visibility_revision
        && snapshot.invocation_id == command.invocation_id
        && snapshot.event_ordinal > command.event_ordinal
        && snapshot.elapsed_ms >= command.elapsed_ms
        && snapshot.hwnd == Some(hwnd)
        && snapshot.process_id == Some(process_id)
        && snapshot.bounds == Some(toggle.presentation.bounds)
        && snapshot.visible == Some(toggle.presentation.visible)
        && snapshot.minimized == Some(toggle.presentation.minimized)
        && owned_root_presentation_is_valid(
            &toggle.presentation,
            displays,
            hwnd,
            process_id,
            visible,
        )
}

fn query_placement_is_valid(
    proof: &QueryPlacementEvidence,
    invocation: &QueryInvocationEvidence,
) -> bool {
    let baseline = &proof.configured_root;
    let displays = &proof.physical_displays;
    let scale = f64::from(proof.dpi) / 96.0;
    let scaled = |value: i32| (f64::from(value) * scale).round() as i32;
    let Some(width) = baseline.bounds[2]
        .checked_sub(baseline.bounds[0])
        .filter(|width| *width > 0)
    else {
        return false;
    };
    let Some(height) = baseline.bounds[3]
        .checked_sub(baseline.bounds[1])
        .filter(|height| *height > 0)
    else {
        return false;
    };
    let client = proof.configured_client_bounds;
    let Some(hide_tap) = proof.hide.input.tap.as_ref() else {
        return false;
    };
    let Some(show_tap) = proof.show.input.tap.as_ref() else {
        return false;
    };
    (48..=1536).contains(&proof.dpi)
        && !displays.is_empty()
        && displays.len() <= 32
        && displays
            .iter()
            .all(|display| display[2] > display[0] && display[3] > display[1])
        && proof.configured_logical_position == QUERY_CONFIGURED_ROOT_POSITION
        && proof.configured_logical_client_size == QUERY_CONFIGURED_ROOT_CLIENT_SIZE
        && baseline.bounds[0] == scaled(QUERY_CONFIGURED_ROOT_POSITION[0])
        && baseline.bounds[1] == scaled(QUERY_CONFIGURED_ROOT_POSITION[1])
        && client
            == [
                0,
                0,
                scaled(QUERY_CONFIGURED_ROOT_CLIENT_SIZE[0]),
                scaled(QUERY_CONFIGURED_ROOT_CLIENT_SIZE[1]),
            ]
        && width >= client[2]
        && height >= client[3]
        && owned_root_presentation_is_valid(
            baseline,
            displays,
            baseline.hwnd,
            baseline.process_id,
            true,
        )
        && owned_root_presentation_is_valid(
            &proof.moved_root,
            displays,
            baseline.hwnd,
            baseline.process_id,
            true,
        )
        && proof.moved_root.bounds != baseline.bounds
        && proof.moved_root.bounds[2].checked_sub(proof.moved_root.bounds[0]) == Some(width)
        && proof.moved_root.bounds[3].checked_sub(proof.moved_root.bounds[1]) == Some(height)
        && displays.iter().any(|display| {
            proof.moved_root.bounds[0] >= display[0]
                && proof.moved_root.bounds[1] >= display[1]
                && proof.moved_root.bounds[2] <= display[2]
                && proof.moved_root.bounds[3] <= display[3]
        })
        && proof.moved_client_bounds == client
        && proof.restored_client_bounds == client
        && proof.restored_root == proof.moved_root
        && invocation.root_observations.len() >= 2
        && invocation
            .root_observations
            .iter()
            .all(|sample| sample == &proof.moved_root)
        && invocation.root_geometry_change_count == 0
        && invocation.root_hidden_samples == 0
        && invocation.root_visible_samples == invocation.root_sample_count
        && invocation.root_identity_violation_count == 0
        && invocation.root_visibility_violation_count == 0
        && proof.handoff_terminal_cursor > invocation.pointer_click.up_event_ordinal
        && hide_tap.trace_cursor >= proof.handoff_terminal_cursor
        && hide_tap.invocation_id > invocation.invocation_id
        && show_tap.trace_cursor
            >= usize::try_from(proof.hide.snapshot.event_ordinal).unwrap_or(usize::MAX)
        && show_tap.invocation_id > hide_tap.invocation_id
        && proof.show.visibility_revision > proof.hide.visibility_revision
        && query_placement_toggle_is_valid(
            &proof.hide,
            proof.hotkey,
            displays,
            baseline.hwnd,
            baseline.process_id,
            false,
        )
        && query_placement_toggle_is_valid(
            &proof.show,
            proof.hotkey,
            displays,
            baseline.hwnd,
            baseline.process_id,
            true,
        )
        && proof.show.presentation == proof.configured_root
        && proof.shown_client_bounds == client
        && proof.note_absent_before
        && proof.note_closed_after
}

fn query_case_contract_is_valid(evidence: &QueryCaseEvidence) -> Result<(), String> {
    if evidence.case_id != "L08" && evidence.placement.is_some() {
        return Err("ROOT placement evidence is present outside L08".into());
    }
    let visible = |item: &QueryInvocationEvidence| {
        item.root_visible_samples > 0
            && item
                .root_observations
                .iter()
                .any(|sample| sample.physically_visible)
    };
    let hidden = |item: &QueryInvocationEvidence| {
        item.root_sample_count >= 2
            && item.root_visible_samples == 0
            && item
                .root_observations
                .iter()
                .all(|sample| !sample.physically_visible)
    };
    let stably_visible = |item: &QueryInvocationEvidence| {
        item.root_sample_count >= 2
            && item.root_visible_samples == item.root_sample_count
            && item.root_hidden_samples == 0
            && item
                .root_observations
                .iter()
                .all(|sample| sample.physically_visible)
    };
    let one = evidence.invocations.first();
    let has_cell = |item: &QueryInvocationEvidence, expected: &str| {
        item.cell_id == expected && item.cell_digest == query_cell_digest(expected)
    };
    let pass = match evidence.case_id.as_str() {
        "Q02" => one.is_some_and(|item| {
            item.mode == QueryEvidenceMode::OpenLauncher
                && item.resolution_state == QueryEvidenceState::ManualUi
                && item.requirement == QueryEvidenceRequirement::LauncherUi
                && item.dispatch_outcome == QueryEvidenceOutcome::Executed
                && item.root_policy == QueryEvidenceRootPolicy::Legacy
                && item.effect_count == 0
                && item.ui_ack == QueryEvidenceUiAck::LauncherQuery
                && has_cell(item, "qa-open")
                && visible(item)
                && evidence.invocations.len() == 1
        }),
        "Q03" => one.is_some_and(|item| {
            item.mode == QueryEvidenceMode::ExecuteFirst
                && item.resolution_state == QueryEvidenceState::Ready
                && item.requirement == QueryEvidenceRequirement::External
                && item.dispatch_outcome == QueryEvidenceOutcome::Executed
                && item.root_policy == QueryEvidenceRootPolicy::Preserve
                && item.result_count >= 1
                && item.selected_digest.is_some_and(|digest| digest != 0)
                && item.effect_count == 1
                && hidden(item)
                && item.ui_ack == QueryEvidenceUiAck::None
                && has_cell(item, "qa-hidden-first")
                && evidence.invocations.len() == 1
        }),
        "Q05" => one.is_some_and(|item| {
            item.mode == QueryEvidenceMode::PinnedAction
                && item.resolution_state == QueryEvidenceState::Ready
                && item.requirement == QueryEvidenceRequirement::External
                && item.dispatch_outcome == QueryEvidenceOutcome::Executed
                && item.root_policy == QueryEvidenceRootPolicy::Preserve
                && item.effect_count == 1
                && hidden(item)
                && item.ui_ack == QueryEvidenceUiAck::None
                && has_cell(item, "qa-pinned-second")
                && evidence.invocations.len() == 1
        }),
        "Q07" => one.is_some_and(|item| {
            item.mode == QueryEvidenceMode::ExecuteFirst
                && item.resolution_state == QueryEvidenceState::NoResults
                && item.result_count == 0
                && item.selected_digest.is_none()
                && item.dispatch_outcome == QueryEvidenceOutcome::Executed
                && item.requirement == QueryEvidenceRequirement::LauncherUi
                && item.root_policy == QueryEvidenceRootPolicy::Legacy
                && item.effect_count == 0
                && item.ui_ack == QueryEvidenceUiAck::LauncherQuery
                && has_cell(item, "qa-no-results")
                && visible(item)
                && evidence.invocations.len() == 1
        }),
        "Q10" => {
            evidence.invocations.len() == 2
                && evidence.invocations.iter().all(|item| {
                    item.mode == QueryEvidenceMode::ExecuteFirst
                        && item.resolution_state == QueryEvidenceState::Ready
                        && item.requirement == QueryEvidenceRequirement::External
                        && item.dispatch_outcome == QueryEvidenceOutcome::Executed
                        && item.root_policy == QueryEvidenceRootPolicy::Preserve
                        && item.result_count >= 1
                        && item.selected_digest.is_some_and(|digest| digest != 0)
                        && item.effect_count == 1
                        && item.ui_ack == QueryEvidenceUiAck::None
                        && has_cell(item, "qa-visible-first")
                })
                && hidden(&evidence.invocations[0])
                && stably_visible(&evidence.invocations[1])
                && evidence.invocations[1].root_geometry_change_count == 0
        }
        "Q11" => one.is_some_and(|item| {
            item.mode == QueryEvidenceMode::ExactCommand
                && item.dispatch_outcome == QueryEvidenceOutcome::Executed
                && item.requirement == QueryEvidenceRequirement::LauncherUi
                && item.root_policy == QueryEvidenceRootPolicy::Legacy
                && item.effect_count == 1
                && item.ui_ack == QueryEvidenceUiAck::NoteEditor
                && has_cell(item, "qa-note-new")
                && visible(item)
                && evidence.invocations.len() == 1
        }),
        "L08" => one.is_some_and(|item| {
            item.mode == QueryEvidenceMode::ExactCommand
                && item.resolution_state == QueryEvidenceState::Ready
                && item.setup_visibility.visible_before
                && item.setup_visibility.desired_visible
                && item.setup_visibility.tap.is_none()
                && item.dispatch_outcome == QueryEvidenceOutcome::Executed
                && item.requirement == QueryEvidenceRequirement::LauncherUi
                && item.root_policy == QueryEvidenceRootPolicy::Legacy
                && item.effect_count == 1
                && item.cancelled_confirmation_count == 0
                && item.ui_ack == QueryEvidenceUiAck::NoteEditor
                && has_cell(item, "qa-note-new")
                && stably_visible(item)
                && evidence.invocations.len() == 1
                && evidence
                    .placement
                    .as_ref()
                    .is_some_and(|proof| query_placement_is_valid(proof, item))
        }),
        "Q12" => one.is_some_and(|item| {
            item.mode == QueryEvidenceMode::ExactCommand
                && item.dispatch_outcome == QueryEvidenceOutcome::Executed
                && item.requirement == QueryEvidenceRequirement::LauncherUi
                && item.root_policy == QueryEvidenceRootPolicy::Legacy
                && item.effect_count == 1
                && item.ui_ack == QueryEvidenceUiAck::LauncherQuery
                && has_cell(item, "qa-launcher-show")
                && visible(item)
                && evidence.invocations.len() == 1
        }),
        "Q13" => {
            evidence.invocations.len() == 2
                && evidence.invocations[0].mode == QueryEvidenceMode::ExactCommand
                && evidence.invocations[0].requirement == QueryEvidenceRequirement::Confirmation
                && evidence.invocations[0].dispatch_outcome
                    == QueryEvidenceOutcome::ConfirmationRequired
                && evidence.invocations[0].effect_count == 0
                && evidence.invocations[0].cancelled_confirmation_count == 1
                && evidence.invocations[0].ui_ack == QueryEvidenceUiAck::Cancelled
                && has_cell(&evidence.invocations[0], "qa-note-remove")
                && visible(&evidence.invocations[0])
                && evidence.invocations[1].mode == QueryEvidenceMode::ExactCommand
                && evidence.invocations[1].requirement == QueryEvidenceRequirement::Confirmation
                && evidence.invocations[1].dispatch_outcome
                    == QueryEvidenceOutcome::ConfirmationRequired
                && evidence.invocations[1].effect_count == 1
                && evidence.invocations[1].cancelled_confirmation_count == 0
                && evidence.invocations[1].ui_ack == QueryEvidenceUiAck::Confirmed
                && has_cell(&evidence.invocations[1], "qa-note-remove")
                && visible(&evidence.invocations[1])
        }
        "Q15" => one.is_some_and(|item| {
            item.mode == QueryEvidenceMode::ExactCommand
                && item.dispatch_outcome == QueryEvidenceOutcome::Executed
                && item.requirement == QueryEvidenceRequirement::External
                && item.root_policy == QueryEvidenceRootPolicy::Preserve
                && item.effect_count == 1
                && hidden(item)
                && item.ui_ack == QueryEvidenceUiAck::None
                && has_cell(item, "qa-exact-marker")
                && evidence.invocations.len() == 1
        }),
        _ => false,
    };
    if pass {
        Ok(())
    } else {
        Err(format!(
            "{} Query evidence does not prove its case contract",
            evidence.case_id
        ))
    }
}

fn validate_h04_contamination_artifacts(
    report: &AcceptanceReport,
    case: &AcceptanceCaseResult,
) -> Result<(), String> {
    let observed = &case.observed;
    let (attempts, contamination_count, names) = h04_retry_ledger(case.status, observed)?;

    let mut artifact_attempts = Vec::new();
    for name in names {
        if name.len() > 96
            || !name.starts_with("case-H04-attempt-")
            || !name.ends_with("-contamination.json")
            || !name
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || b"-_.".contains(&byte))
        {
            return Err("H04 retry ledger contains an invalid contamination artifact name".into());
        }
        let case_paths = case
            .artifacts
            .iter()
            .filter(|path| {
                Path::new(path).file_name().and_then(|value| value.to_str()) == Some(name)
            })
            .collect::<Vec<_>>();
        let report_paths = report
            .artifacts
            .iter()
            .filter(|path| {
                Path::new(path.as_str())
                    .file_name()
                    .and_then(|value| value.to_str())
                    == Some(name)
            })
            .collect::<Vec<_>>();
        if case_paths.len() != 1 || report_paths.len() != 1 {
            return Err(format!(
                "H04 contamination artifact {name} is not linked exactly once from both case and report"
            ));
        }
        if case_paths[0] != report_paths[0] {
            return Err(format!(
                "H04 contamination artifact {name} has different case/report paths"
            ));
        }
        let path = Path::new(case_paths[0]);
        let bytes = fs::read(path)
            .map_err(|error| format!("read H04 contamination artifact {name}: {error}"))?;
        if bytes.is_empty() || bytes.len() > MAX_HOTKEY_CASE_EVIDENCE_BYTES {
            return Err(format!(
                "H04 contamination artifact {name} is empty or exceeds its byte bound"
            ));
        }
        let artifact: H04InputContaminationArtifact = serde_json::from_slice(&bytes)
            .map_err(|error| format!("decode H04 contamination artifact {name}: {error}"))?;
        validate_h04_contamination_artifact(&artifact, report.hotkey)?;
        let expected_name = format!("case-H04-attempt-{}-contamination.json", artifact.attempt);
        if name != expected_name {
            return Err(format!(
                "H04 contamination artifact {name} disagrees with its attempt identity"
            ));
        }
        artifact_attempts.push(artifact.attempt);
    }
    artifact_attempts.sort_unstable();
    let expected_attempts = (1..=contamination_count).collect::<Vec<_>>();
    if artifact_attempts != expected_attempts || attempts > 2 {
        return Err(
            "H04 retry artifacts do not identify every contaminated attempt in order".into(),
        );
    }
    Ok(())
}

fn validate_h04_contamination_artifact(
    artifact: &H04InputContaminationArtifact,
    report_hotkey: AcceptanceHotkey,
) -> Result<(), String> {
    let expected_vks: &[u32] = match report_hotkey {
        AcceptanceHotkey::F11 => &[0x7A],
        AcceptanceHotkey::ShiftAltWinEnd => &[0xA0, 0xA4, 0x5B, 0x23],
    };
    if artifact.schema_version != 1
        || artifact.case_id != "H04"
        || !(1..=2).contains(&artifact.attempt)
        || artifact.hotkey != report_hotkey
        || artifact.failure_stage != "InputInjection"
        || artifact.failure.is_empty()
        || artifact.failure.len() > MAX_RESULT_BYTES
        || artifact.declared_initial_state
        || !(1..=10).contains(&artifact.next_matrix_burst_index)
        || artifact.completed_bursts.len() + 1 != usize::from(artifact.next_matrix_burst_index)
        || artifact.input_group_id == 0
        || artifact.input_group_id != u32::from(artifact.next_matrix_burst_index)
        || artifact.root_identity.hwnd == 0
        || artifact.root_identity.process_id == 0
        || artifact.root_identity.stream != artifact.stream
        || artifact.prior_group_ids.is_empty()
        || artifact.prior_group_ids.len() > 13
        || artifact.prior_group_ids.iter().any(|group| *group == 0)
        || artifact
            .prior_group_ids
            .windows(2)
            .any(|pair| pair[0] >= pair[1])
        || !artifact.prior_group_ids.contains(&artifact.input_group_id)
        || artifact.prior_group_ids.len() != usize::from(artifact.next_matrix_burst_index)
        || artifact
            .prior_group_ids
            .iter()
            .enumerate()
            .any(|(index, group)| *group != u32::try_from(index + 1).unwrap_or(u32::MAX))
    {
        return Err("H04 contamination artifact identity or bounds are invalid".into());
    }
    let required_lengths = [1usize, 2, 5, 10, 25];
    let mut completed_invocations = std::collections::BTreeSet::new();
    for (index, burst) in artifact.completed_bursts.iter().enumerate() {
        let expected_initial = index >= required_lengths.len();
        let taps = required_lengths[index % required_lengths.len()];
        let expected_final = expected_initial ^ (taps % 2 == 1);
        let valid_cadence = (10..=100).contains(&burst.hold_min_ms)
            && (10..=100).contains(&burst.hold_max_ms)
            && burst.hold_min_ms <= burst.hold_max_ms
            && if taps == 1 {
                burst.gap_min_ms == 0 && burst.gap_max_ms == 0
            } else {
                (10..=100).contains(&burst.gap_min_ms)
                    && (10..=100).contains(&burst.gap_max_ms)
                    && burst.gap_min_ms <= burst.gap_max_ms
            };
        if burst.matrix_burst_index != u8::try_from(index + 1).unwrap_or(u8::MAX)
            || burst.input_group_id != u32::try_from(index + 1).unwrap_or(u32::MAX)
            || burst.initial_visible != expected_initial
            || usize::from(burst.requested_taps) != taps
            || burst.final_visible != expected_final
            || burst.invocation_ids.len() != taps
            || burst
                .invocation_ids
                .iter()
                .any(|id| *id == 0 || !completed_invocations.insert(*id))
            || burst.trace_probe_id == 0
            || !valid_cadence
        {
            return Err("H04 contamination artifact has an invalid completed-burst prefix".into());
        }
    }
    let group_edges = artifact
        .owned_edges
        .iter()
        .filter(|edge| {
            edge.input_group_id == artifact.input_group_id && edge.stream == artifact.stream
        })
        .collect::<Vec<_>>();
    let group_foreign_edges = artifact
        .foreign_edges
        .iter()
        .filter(|edge| {
            edge.input_group_id == artifact.input_group_id && edge.stream == artifact.stream
        })
        .collect::<Vec<_>>();
    if group_edges.len() != artifact.owned_edges.len()
        || group_foreign_edges.len() != artifact.foreign_edges.len()
        || group_edges.is_empty()
        || group_edges.iter().any(|edge| {
            edge.purpose != HotkeyRunnerInputPurpose::MatrixBurst
                || !edge.runner_cookie_matched
                || !edge.injected
                || !expected_vks.contains(&edge.virtual_key)
        })
        || group_foreign_edges.is_empty()
        || group_foreign_edges.iter().any(|edge| {
            edge.purpose != HotkeyRunnerInputPurpose::MatrixBurst
                || edge.runner_cookie_matched
                || !expected_vks.contains(&edge.virtual_key)
        })
    {
        return Err(
            "H04 contamination artifact does not preserve owned and foreign chord edges".into(),
        );
    }
    let edges_per_tap = if report_hotkey == AcceptanceHotkey::F11 {
        2
    } else {
        8
    };
    let taps = group_edges.len() / edges_per_tap;
    let expected_taps = [1usize, 2, 5, 10, 25];
    if group_edges.len() != taps.saturating_mul(edges_per_tap) || !expected_taps.contains(&taps) {
        return Err("H04 contamination artifact has an invalid measured-burst length".into());
    }
    let expected_edges = (0..taps)
        .flat_map(|_| match report_hotkey {
            AcceptanceHotkey::F11 => vec![
                (0x7A, HotkeyEdgeTransition::Press),
                (0x7A, HotkeyEdgeTransition::Release),
            ],
            AcceptanceHotkey::ShiftAltWinEnd => vec![
                (0xA0, HotkeyEdgeTransition::Press),
                (0xA4, HotkeyEdgeTransition::Press),
                (0x5B, HotkeyEdgeTransition::Press),
                (0x23, HotkeyEdgeTransition::Press),
                (0x23, HotkeyEdgeTransition::Release),
                (0x5B, HotkeyEdgeTransition::Release),
                (0xA4, HotkeyEdgeTransition::Release),
                (0xA0, HotkeyEdgeTransition::Release),
            ],
        })
        .collect::<Vec<_>>();
    if group_edges
        .iter()
        .zip(expected_edges)
        .any(|(edge, (vk, transition))| edge.virtual_key != vk || edge.transition != transition)
    {
        return Err(
            "H04 contamination artifact does not preserve the complete tagged chord sequence"
                .into(),
        );
    }
    let spans = owned_gesture_spans(group_edges.iter().map(|edge| {
        (
            edge.runner_relative_us,
            edge.virtual_key,
            edge.transition == HotkeyEdgeTransition::Press,
        )
    }));
    let foreign_timeline = group_foreign_edges
        .iter()
        .map(|edge| {
            (
                edge.runner_relative_us,
                edge.virtual_key,
                edge.transition == HotkeyEdgeTransition::Press,
            )
        })
        .collect::<Vec<_>>();
    let interfering_edges = foreign_edge_indices_interfering_owned_spans(&spans, &foreign_timeline);
    if interfering_edges.is_empty() {
        return Err(
            "H04 contamination artifact has no foreign edge inside an owned gesture or held across its boundary".into(),
        );
    }
    if artifact.candidate_events.iter().any(|event| {
        event.stream != artifact.stream || event.input_group_id != artifact.input_group_id
    }) {
        return Err("H04 contamination artifact contains unrelated candidate events".into());
    }
    Ok(())
}

fn owned_gesture_spans<T>(edges: impl IntoIterator<Item = (T, u32, bool)>) -> Vec<(T, T)>
where
    T: Copy + Ord,
{
    let mut edges = edges.into_iter().collect::<Vec<_>>();
    edges.sort_by_key(|(at, _, _)| *at);
    let mut active = std::collections::BTreeMap::<u32, usize>::new();
    let mut gesture_start = None;
    let mut spans = Vec::new();

    for (at, virtual_key, down) in &edges {
        if *down {
            if active.is_empty() {
                gesture_start = Some(*at);
            }
            *active.entry(*virtual_key).or_default() += 1;
            continue;
        }
        let Some(count) = active.get_mut(virtual_key) else {
            continue;
        };
        *count -= 1;
        if *count == 0 {
            active.remove(virtual_key);
        }
        if active.is_empty()
            && let Some(start) = gesture_start.take()
        {
            spans.push((start, *at));
        }
    }

    if !active.is_empty()
        && let (Some(start), Some((end, _, _))) = (gesture_start, edges.last())
    {
        spans.push((start, *end));
    }
    spans
}

fn foreign_edge_indices_interfering_owned_spans<T>(
    spans: &[(T, T)],
    foreign_edges: &[(T, u32, bool)],
) -> Vec<usize>
where
    T: Copy + Ord,
{
    if spans.is_empty() || foreign_edges.is_empty() {
        return Vec::new();
    }
    let mut ordered_indices = (0..foreign_edges.len()).collect::<Vec<_>>();
    ordered_indices.sort_by_key(|index| foreign_edges[*index].0);
    let mut edge_cursor = 0usize;
    let mut held = std::collections::BTreeMap::<u32, Vec<usize>>::new();
    let mut interfering = std::collections::BTreeSet::new();

    let apply_edge = |index: usize,
                      held: &mut std::collections::BTreeMap<u32, Vec<usize>>,
                      interfering: &mut std::collections::BTreeSet<usize>| {
        let (_, virtual_key, down) = foreign_edges[index];
        if down {
            held.entry(virtual_key).or_default().push(index);
        } else if let Some(indices) = held.get_mut(&virtual_key) {
            indices.pop();
            if indices.is_empty() {
                held.remove(&virtual_key);
            }
        } else {
            // A release without a captured matching down cannot be part of a
            // balanced pair in the released gap; it may have cleared a key
            // state needed by the next owned gesture.
            interfering.insert(index);
        }
    };
    let mark_held = |held: &std::collections::BTreeMap<u32, Vec<usize>>,
                     interfering: &mut std::collections::BTreeSet<usize>| {
        interfering.extend(held.values().flatten().copied());
    };

    for (start, end) in spans {
        if end < start {
            continue;
        }
        while edge_cursor < ordered_indices.len()
            && foreign_edges[ordered_indices[edge_cursor]].0 < *start
        {
            apply_edge(ordered_indices[edge_cursor], &mut held, &mut interfering);
            edge_cursor += 1;
        }
        mark_held(&held, &mut interfering);
        while edge_cursor < ordered_indices.len()
            && foreign_edges[ordered_indices[edge_cursor]].0 <= *end
        {
            let index = ordered_indices[edge_cursor];
            interfering.insert(index);
            apply_edge(index, &mut held, &mut interfering);
            edge_cursor += 1;
        }
    }

    while edge_cursor < ordered_indices.len() {
        apply_edge(ordered_indices[edge_cursor], &mut held, &mut interfering);
        edge_cursor += 1;
    }
    mark_held(&held, &mut interfering);
    interfering.into_iter().collect()
}

#[derive(Clone, Debug, Default, Serialize, serde::Deserialize)]
struct CleanupResult {
    child_closed_normally: bool,
    child_terminated_after_timeout: bool,
    child_owned_windows_closed: bool,
    profile_removed: bool,
    foreground_restore_captured: bool,
    foreground_restore_attempted: bool,
    foreground_restored: bool,
    cursor_restored: bool,
    input_desktop_released: bool,
}

#[cfg(any(windows, test))]
mod foreground_cursor_cleanup {
    use super::CleanupResult;
    use std::io::Write;

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    struct ForegroundOwner {
        hwnd: usize,
        process_id: u32,
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum AnchorFocus {
        NotRetained,
        Validated,
    }

    trait CleanupBackend {
        fn focus_retained_anchor(&mut self) -> Result<AnchorFocus, String>;
        fn cursor_position(&mut self) -> Result<[i32; 2], String>;
        fn restore_cursor(&mut self, point: [i32; 2]) -> Result<(), String>;
        fn restore_foreground(&mut self, owner: ForegroundOwner) -> Result<(), String>;
        fn validate_foreground(&mut self, owner: ForegroundOwner) -> Result<(), String>;
    }

    fn cursor_matches(current: [i32; 2], expected: [i32; 2]) -> bool {
        current[0].abs_diff(expected[0]) <= 1 && current[1].abs_diff(expected[1]) <= 1
    }

    fn restore(
        backend: &mut impl CleanupBackend,
        before_foreground: Option<ForegroundOwner>,
        before_cursor: Result<[i32; 2], String>,
        cleanup: &mut CleanupResult,
        log: &mut impl Write,
    ) {
        cleanup.foreground_restore_captured = before_foreground.is_some();
        cleanup.foreground_restore_attempted = false;
        cleanup.foreground_restored = false;
        cleanup.cursor_restored = false;

        // Anchor acquisition may require its checked activation click. Complete
        // that input before observing or restoring the final cursor position.
        // Without a captured cursor, that activation cannot be undone.
        let anchor_acquired = before_cursor.is_ok()
            && match backend.focus_retained_anchor() {
                Ok(AnchorFocus::NotRetained) => {
                    let _ = writeln!(
                        log,
                        "cursor/foreground cleanup has no retained runner anchor"
                    );
                    true
                }
                Ok(AnchorFocus::Validated) => true,
                Err(error) => {
                    let _ = writeln!(
                        log,
                        "retained runner anchor acquisition failed; cursor restoration is unverified: {error}"
                    );
                    false
                }
            };
        let cursor_acknowledged = match &before_cursor {
            Ok(point) if anchor_acquired => {
                if backend
                    .cursor_position()
                    .is_ok_and(|current| cursor_matches(current, *point))
                {
                    true
                } else {
                    match backend.restore_cursor(*point) {
                        Ok(()) => true,
                        Err(error) => {
                            let _ = writeln!(log, "cursor restoration failed: {error}");
                            false
                        }
                    }
                }
            }
            Ok(_) => false,
            Err(error) => {
                let _ = writeln!(
                    log,
                    "cursor position capture failed; restoration is unverified: {error}"
                );
                false
            }
        };

        if let Some(owner) = before_foreground {
            cleanup.foreground_restore_attempted = true;
            let restored = match backend.restore_foreground(owner) {
                Ok(()) => true,
                Err(error) => {
                    let _ = writeln!(
                        log,
                        "foreground restoration failed for captured HWND={} PID={}: {error}",
                        owner.hwnd, owner.process_id
                    );
                    false
                }
            };
            let validated = match backend.validate_foreground(owner) {
                Ok(()) => true,
                Err(error) => {
                    let _ = writeln!(log, "final foreground verification failed: {error}");
                    false
                }
            };
            cleanup.foreground_restored = restored && validated;
        } else {
            let _ = writeln!(
                log,
                "foreground restoration skipped: no foreground HWND was captured"
            );
        }

        // Restoring the original foreground must not reactivate the anchor or
        // insert corrective pointer input. The last observation proves whether
        // the acknowledged restoration survived the foreground transition.
        if let Ok(point) = before_cursor {
            match backend.cursor_position() {
                Ok(current) => {
                    cleanup.cursor_restored = cursor_acknowledged && cursor_matches(current, point);
                    if !cleanup.cursor_restored {
                        let _ = writeln!(
                            log,
                            "final cursor restoration is unverified: expected=({},{}), observed=({},{}), acknowledged={cursor_acknowledged}",
                            point[0], point[1], current[0], current[1]
                        );
                    }
                }
                Err(error) => {
                    let _ = writeln!(log, "final cursor verification failed: {error}");
                }
            }
        }
    }

    #[cfg(windows)]
    struct NativeCleanupBackend<'a> {
        anchor: Option<&'a super::native::FocusAnchor>,
    }

    #[cfg(windows)]
    impl CleanupBackend for NativeCleanupBackend<'_> {
        fn focus_retained_anchor(&mut self) -> Result<AnchorFocus, String> {
            let Some(anchor) = self.anchor else {
                return Ok(AnchorFocus::NotRetained);
            };
            anchor.focus()?;
            super::native::focus_is_validated(anchor.hwnd(), anchor.process_id())?;
            Ok(AnchorFocus::Validated)
        }

        fn cursor_position(&mut self) -> Result<[i32; 2], String> {
            super::native::cursor_position().map(|point| [point.x, point.y])
        }

        fn restore_cursor(&mut self, point: [i32; 2]) -> Result<(), String> {
            super::native::set_cursor_position(windows::Win32::Foundation::POINT {
                x: point[0],
                y: point[1],
            })
        }

        fn restore_foreground(&mut self, owner: ForegroundOwner) -> Result<(), String> {
            super::native::restore_foreground(
                windows::Win32::Foundation::HWND(owner.hwnd as *mut std::ffi::c_void),
                owner.process_id,
            )
        }

        fn validate_foreground(&mut self, owner: ForegroundOwner) -> Result<(), String> {
            super::native::focus_is_validated(
                windows::Win32::Foundation::HWND(owner.hwnd as *mut std::ffi::c_void),
                owner.process_id,
            )
        }
    }

    #[cfg(windows)]
    pub(super) fn restore_native(
        before_foreground: (windows::Win32::Foundation::HWND, u32),
        before_cursor: Result<windows::Win32::Foundation::POINT, String>,
        anchor: Option<&super::native::FocusAnchor>,
        cleanup: &mut CleanupResult,
        log: &mut impl Write,
    ) {
        let before_foreground = (!before_foreground.0.is_invalid()).then_some(ForegroundOwner {
            hwnd: before_foreground.0.0 as usize,
            process_id: before_foreground.1,
        });
        restore(
            &mut NativeCleanupBackend { anchor },
            before_foreground,
            before_cursor.map(|point| [point.x, point.y]),
            cleanup,
            log,
        );
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        const ORIGINAL_CURSOR: [i32; 2] = [1194, 978];
        const ACTIVATION_CURSOR: [i32; 2] = [1194, 887];
        const ORIGINAL_FOREGROUND: ForegroundOwner = ForegroundOwner {
            hwnd: 101,
            process_id: 17,
        };
        const ANCHOR: ForegroundOwner = ForegroundOwner {
            hwnd: 202,
            process_id: 31,
        };

        #[derive(Debug, PartialEq, Eq)]
        enum Operation {
            AcquireAnchor,
            ObserveCursor,
            RestoreCursor([i32; 2]),
            RestoreForeground(ForegroundOwner),
            ValidateForeground(ForegroundOwner),
        }

        struct Backend {
            operations: Vec<Operation>,
            anchor_focus: Result<AnchorFocus, String>,
            activation_cursor: Option<[i32; 2]>,
            cursor: [i32; 2],
            foreground: Option<ForegroundOwner>,
            cursor_restore: Result<(), String>,
            apply_cursor_restore: bool,
            foreground_restore: Result<(), String>,
            apply_foreground_restore: bool,
            cursor_after_foreground: Option<[i32; 2]>,
            cursor_reads: usize,
            cursor_error_on_read: Option<usize>,
        }

        impl Default for Backend {
            fn default() -> Self {
                Self {
                    operations: Vec::new(),
                    anchor_focus: Ok(AnchorFocus::Validated),
                    activation_cursor: Some(ACTIVATION_CURSOR),
                    cursor: ORIGINAL_CURSOR,
                    foreground: Some(ORIGINAL_FOREGROUND),
                    cursor_restore: Ok(()),
                    apply_cursor_restore: true,
                    foreground_restore: Ok(()),
                    apply_foreground_restore: true,
                    cursor_after_foreground: None,
                    cursor_reads: 0,
                    cursor_error_on_read: None,
                }
            }
        }

        impl CleanupBackend for Backend {
            fn focus_retained_anchor(&mut self) -> Result<AnchorFocus, String> {
                self.operations.push(Operation::AcquireAnchor);
                if let Some(point) = self.activation_cursor {
                    self.cursor = point;
                    self.foreground = Some(ANCHOR);
                }
                self.anchor_focus.clone()
            }

            fn cursor_position(&mut self) -> Result<[i32; 2], String> {
                self.operations.push(Operation::ObserveCursor);
                self.cursor_reads += 1;
                if self.cursor_error_on_read == Some(self.cursor_reads) {
                    Err("actual cursor read failed".into())
                } else {
                    Ok(self.cursor)
                }
            }

            fn restore_cursor(&mut self, point: [i32; 2]) -> Result<(), String> {
                self.operations.push(Operation::RestoreCursor(point));
                if self.apply_cursor_restore {
                    self.cursor = point;
                }
                self.cursor_restore.clone()
            }

            fn restore_foreground(&mut self, owner: ForegroundOwner) -> Result<(), String> {
                self.operations.push(Operation::RestoreForeground(owner));
                if self.apply_foreground_restore {
                    self.foreground = Some(owner);
                }
                if let Some(point) = self.cursor_after_foreground {
                    self.cursor = point;
                }
                self.foreground_restore.clone()
            }

            fn validate_foreground(&mut self, owner: ForegroundOwner) -> Result<(), String> {
                self.operations.push(Operation::ValidateForeground(owner));
                if self.foreground == Some(owner) {
                    Ok(())
                } else {
                    Err("actual foreground HWND/PID differs from captured owner".into())
                }
            }
        }

        fn run(backend: &mut Backend) -> (CleanupResult, String) {
            let mut cleanup = CleanupResult::default();
            let mut log = Vec::new();
            restore(
                backend,
                Some(ORIGINAL_FOREGROUND),
                Ok(ORIGINAL_CURSOR),
                &mut cleanup,
                &mut log,
            );
            (cleanup, String::from_utf8(log).unwrap())
        }

        fn pointer_restores(backend: &Backend) -> usize {
            backend
                .operations
                .iter()
                .filter(|operation| matches!(operation, Operation::RestoreCursor(_)))
                .count()
        }

        #[test]
        fn anchor_activation_finishes_before_cursor_restoration_and_foreground_return() {
            let mut backend = Backend::default();
            let (cleanup, _) = run(&mut backend);
            assert_eq!(
                backend.operations,
                vec![
                    Operation::AcquireAnchor,
                    Operation::ObserveCursor,
                    Operation::RestoreCursor(ORIGINAL_CURSOR),
                    Operation::RestoreForeground(ORIGINAL_FOREGROUND),
                    Operation::ValidateForeground(ORIGINAL_FOREGROUND),
                    Operation::ObserveCursor,
                ]
            );
            assert_eq!(backend.cursor, ORIGINAL_CURSOR);
            assert_eq!(backend.foreground, Some(ORIGINAL_FOREGROUND));
            assert!(cleanup.foreground_restore_captured);
            assert!(cleanup.foreground_restore_attempted);
            assert!(cleanup.foreground_restored);
            assert!(cleanup.cursor_restored);
        }

        #[test]
        fn no_anchor_already_matching_cursor_needs_no_pointer_input() {
            let mut backend = Backend {
                anchor_focus: Ok(AnchorFocus::NotRetained),
                activation_cursor: None,
                cursor: [ORIGINAL_CURSOR[0] + 1, ORIGINAL_CURSOR[1] - 1],
                ..Backend::default()
            };
            let (cleanup, log) = run(&mut backend);
            assert!(cleanup.cursor_restored);
            assert!(cleanup.foreground_restored);
            assert_eq!(pointer_restores(&backend), 0);
            assert!(log.contains("no retained runner anchor"));
            assert_eq!(backend.operations.len(), 5);
        }

        #[test]
        fn no_anchor_cursor_restoration_still_requires_actual_final_position() {
            for apply_cursor_restore in [true, false] {
                let mut backend = Backend {
                    anchor_focus: Ok(AnchorFocus::NotRetained),
                    activation_cursor: None,
                    cursor: ACTIVATION_CURSOR,
                    apply_cursor_restore,
                    ..Backend::default()
                };
                let (cleanup, _) = run(&mut backend);
                assert_eq!(cleanup.cursor_restored, apply_cursor_restore);
                assert!(cleanup.foreground_restored);
                assert_eq!(pointer_restores(&backend), 1);
            }
        }

        #[test]
        fn failed_anchor_acquisition_refuses_pointer_restore_but_recovers_foreground() {
            for activation_cursor in [Some(ACTIVATION_CURSOR), None] {
                let mut backend = Backend {
                    anchor_focus: Err("retained anchor owner could not be acquired".into()),
                    activation_cursor,
                    ..Backend::default()
                };
                let (cleanup, log) = run(&mut backend);
                assert!(!cleanup.cursor_restored);
                assert!(cleanup.foreground_restored);
                assert_eq!(pointer_restores(&backend), 0);
                assert_eq!(backend.cursor, activation_cursor.unwrap_or(ORIGINAL_CURSOR));
                assert_eq!(backend.foreground, Some(ORIGINAL_FOREGROUND));
                assert_eq!(
                    backend.operations,
                    vec![
                        Operation::AcquireAnchor,
                        Operation::RestoreForeground(ORIGINAL_FOREGROUND),
                        Operation::ValidateForeground(ORIGINAL_FOREGROUND),
                        Operation::ObserveCursor,
                    ]
                );
                assert!(log.contains("anchor acquisition failed"));
            }
        }

        #[test]
        fn cursor_ack_failure_remains_failed_even_when_final_coordinates_match() {
            let mut backend = Backend {
                cursor_restore: Err("native cursor restoration did not acknowledge".into()),
                ..Backend::default()
            };
            let (cleanup, log) = run(&mut backend);
            assert_eq!(backend.cursor, ORIGINAL_CURSOR);
            assert!(!cleanup.cursor_restored);
            assert!(cleanup.foreground_restored);
            assert_eq!(pointer_restores(&backend), 1);
            assert!(log.contains("did not acknowledge"));
        }

        #[test]
        fn final_cursor_mismatch_or_read_failure_never_inserts_post_foreground_input() {
            for (point, read_error) in [
                (Some(ACTIVATION_CURSOR), None),
                (Some([ORIGINAL_CURSOR[0] + 2, ORIGINAL_CURSOR[1]]), None),
                (None, Some(2)),
            ] {
                let mut backend = Backend {
                    cursor_after_foreground: point,
                    cursor_error_on_read: read_error,
                    ..Backend::default()
                };
                let (cleanup, log) = run(&mut backend);
                assert!(!cleanup.cursor_restored);
                assert!(cleanup.foreground_restored);
                assert_eq!(pointer_restores(&backend), 1);
                let returned = backend
                    .operations
                    .iter()
                    .position(|operation| {
                        *operation == Operation::RestoreForeground(ORIGINAL_FOREGROUND)
                    })
                    .unwrap();
                assert!(backend.operations[returned + 1..].iter().all(|operation| {
                    matches!(
                        operation,
                        Operation::ValidateForeground(_) | Operation::ObserveCursor
                    )
                }));
                assert!(log.contains("final cursor"));
            }
        }

        #[test]
        fn foreground_success_requires_both_restoration_ack_and_exact_final_owner() {
            for (foreground_restore, apply_foreground_restore) in [
                (
                    Err("foreground restoration acknowledgment failed".into()),
                    true,
                ),
                (Ok(()), false),
            ] {
                let mut backend = Backend {
                    foreground_restore,
                    apply_foreground_restore,
                    ..Backend::default()
                };
                let (cleanup, log) = run(&mut backend);
                assert!(!cleanup.foreground_restored);
                assert!(cleanup.foreground_restore_captured);
                assert!(cleanup.foreground_restore_attempted);
                assert!(cleanup.cursor_restored);
                assert!(log.contains("foreground"));
            }
            let mut backend = Backend {
                anchor_focus: Ok(AnchorFocus::NotRetained),
                activation_cursor: None,
                foreground: Some(ForegroundOwner {
                    process_id: ORIGINAL_FOREGROUND.process_id + 1,
                    ..ORIGINAL_FOREGROUND
                }),
                apply_foreground_restore: false,
                ..Backend::default()
            };
            let (cleanup, log) = run(&mut backend);
            assert!(!cleanup.foreground_restored);
            assert!(cleanup.cursor_restored);
            assert!(log.contains("HWND/PID differs"));
        }

        #[test]
        fn missing_captures_stay_unverified_and_other_cleanup_facts_are_preserved() {
            let mut backend = Backend::default();
            let original_cursor = backend.cursor;
            let original_foreground = backend.foreground;
            let mut cleanup = CleanupResult {
                child_closed_normally: true,
                child_terminated_after_timeout: true,
                child_owned_windows_closed: true,
                profile_removed: true,
                foreground_restore_captured: true,
                foreground_restore_attempted: true,
                foreground_restored: true,
                cursor_restored: true,
                input_desktop_released: true,
            };
            let mut log = Vec::new();
            restore(
                &mut backend,
                None,
                Err("baseline cursor capture failed".into()),
                &mut cleanup,
                &mut log,
            );
            assert!(backend.operations.is_empty());
            assert_eq!(backend.cursor, original_cursor);
            assert_eq!(backend.foreground, original_foreground);
            assert!(!cleanup.foreground_restore_captured);
            assert!(!cleanup.foreground_restore_attempted);
            assert!(!cleanup.foreground_restored);
            assert!(!cleanup.cursor_restored);
            assert!(cleanup.child_closed_normally);
            assert!(cleanup.child_terminated_after_timeout);
            assert!(cleanup.child_owned_windows_closed);
            assert!(cleanup.profile_removed);
            assert!(cleanup.input_desktop_released);
            let log = String::from_utf8(log).unwrap();
            assert!(log.contains("baseline cursor capture failed"));
            assert!(log.contains("no foreground HWND was captured"));

            backend.foreground = Some(ANCHOR);
            let mut log = Vec::new();
            restore(
                &mut backend,
                Some(ORIGINAL_FOREGROUND),
                Err("baseline cursor capture failed".into()),
                &mut cleanup,
                &mut log,
            );
            assert_eq!(
                backend.operations,
                vec![
                    Operation::RestoreForeground(ORIGINAL_FOREGROUND),
                    Operation::ValidateForeground(ORIGINAL_FOREGROUND),
                ]
            );
            assert_eq!(backend.cursor, original_cursor);
            assert_eq!(backend.foreground, Some(ORIGINAL_FOREGROUND));
            assert!(cleanup.foreground_restore_captured);
            assert!(cleanup.foreground_restore_attempted);
            assert!(cleanup.foreground_restored);
            assert!(!cleanup.cursor_restored);
            assert!(cleanup.child_closed_normally);
            assert!(cleanup.child_terminated_after_timeout);
            assert!(cleanup.child_owned_windows_closed);
            assert!(cleanup.profile_removed);
            assert!(cleanup.input_desktop_released);
            assert!(
                String::from_utf8(log)
                    .unwrap()
                    .contains("baseline cursor capture failed")
            );
        }
    }
}

