#[cfg(windows)]
fn push_final_case(
    report: &mut AcceptanceReport,
    id: &str,
    status: CaseStatus,
    observed: &str,
    failure_stage: Option<FailureStage>,
    artifacts: Vec<String>,
    run_started: Instant,
) {
    report.push_case(AcceptanceCaseResult {
        id: id.into(),
        status,
        elapsed_ms: u64::try_from(run_started.elapsed().as_millis()).unwrap_or(u64::MAX),
        expected: expected_final_case(id).into(),
        observed: bounded_text(observed, MAX_RESULT_BYTES),
        failure_stage,
        artifacts,
    });
}

fn expected_final_case(id: &str) -> &'static str {
    match id {
        "D01" => {
            "Properties and Inspector expose readable, correlated target-first results beyond the first 50 entries"
        }
        "D02" => {
            "duplicate-title targets remain distinguishable and the same secondary action is reachable on both surfaces"
        }
        "D04" => {
            "pin, both query modes, and separate exact command arguments persist through Apply/Save/reopen with one-step history proof"
        }
        "D06" => {
            "list and grid source results insert through the ordinary Designer lifecycle without activating the source result"
        }
        "D07" => {
            "occupied-cell Cancel is inert and explicit Replace preserves dirty state with one undoable mutation"
        }
        "D09" => {
            "a real pending provider request is observed and its late completion is rejected across Keep Editing and Discard/reopen"
        }
        "Q14" => {
            "authoring browse and assignment leave the full marker ledger, live history, usage, and execution dispatches unchanged"
        }
        "R0" => {
            "valid bounded JSON and text reports identify source, profile, hashes, elapsed time, and evidence"
        }
        "R1" => {
            "controlled harness failure writes bounded privacy-safe trace and owned screenshot evidence"
        }
        "CP_R1" => {
            "copied-profile diagnostic evidence validates; failing bundles persist outside the copied profile"
        }
        "R2" => "child process, HWNDs, temp profile, and native input state are cleaned up",
        _ => "required native acceptance case is recorded",
    }
}

#[cfg(windows)]
fn prepare_output_directory(arguments: &Arguments) -> Result<PathBuf, String> {
    if let Some(report) = &arguments.report_file {
        let parent = report
            .parent()
            .filter(|parent| !parent.as_os_str().is_empty())
            .unwrap_or(Path::new("."));
        if !parent.is_dir() {
            return Err("--report parent directory must already exist".into());
        }
        return parent
            .canonicalize()
            .map_err(|error| format!("resolve report parent: {error}"));
    }
    let output = arguments
        .output
        .as_deref()
        .ok_or_else(|| "--output is required".to_string())?;
    fs::create_dir_all(output).map_err(|error| format!("create output directory: {error}"))?;
    let output = output
        .canonicalize()
        .map_err(|error| format!("resolve output directory: {error}"))?;
    let mut entries =
        fs::read_dir(&output).map_err(|error| format!("inspect output directory: {error}"))?;
    if entries.next().is_some() {
        return Err("output directory must be empty so run artifacts are never overwritten".into());
    }
    Ok(output)
}

fn deterministic_fixture(
    log_path: &Path,
    mouse_gesture_mode: MouseGestureMode,
) -> Result<DeterministicFixture, String> {
    deterministic_fixture_for_hotkey(log_path, mouse_gesture_mode, AcceptanceHotkey::F11)
}

fn deterministic_fixture_for_hotkey(
    log_path: &Path,
    mouse_gesture_mode: MouseGestureMode,
    hotkey: AcceptanceHotkey,
) -> Result<DeterministicFixture, String> {
    let mut settings = Settings::default();
    settings.hotkey = Some(hotkey.as_str().to_string());
    settings.help_hotkey = None;
    settings.quit_hotkey = None;
    settings.debug_logging = true;
    settings.log_file = Some(LogFile::Path(log_path.to_string_lossy().to_string()));
    settings.follow_mouse = false;
    settings.static_location_enabled = true;
    settings.static_pos = Some((240, 180));
    settings.static_size = Some((900, 650));
    settings.window_size = Some((900, 650));
    settings.radial.enabled = true;
    settings.radial.shared_tap_hold = true;
    if mouse_gesture_mode == MouseGestureMode::DisabledDiagnostic {
        settings.plugin_settings.insert(
            "mouse_gestures".into(),
            serde_json::json!({ "enabled": false }),
        );
    }
    let mut document = RadialDocument::starter();
    let actions = (0..ACCEPTANCE_ACTION_COUNT)
        .map(|index| multi_launcher::actions::Action {
            label: format!("Radial Acceptance Harmless Action {index:03}"),
            desc: "Deterministic native authoring fixture".into(),
            action: format!("radial_acceptance_harmless_{index:03}"),
            args: None,
        })
        .collect::<Vec<_>>();
    bind_hotkey_hover_probe_action(
        &mut document,
        actions.first().ok_or_else(|| {
            "the deterministic fixture has no harmless hover-probe action".to_string()
        })?,
    )?;
    validate_radial_document(&document)
        .map_err(|error| format!("starter radial document is invalid: {error:?}"))?;
    let reserved = [("launcher", settings.hotkey.as_deref())]
        .into_iter()
        .filter_map(|(owner, chord)| chord.map(|chord| (owner.to_string(), chord.to_string())))
        .collect::<Vec<_>>();
    let issues = radial_settings::validate(&settings.radial, &document, &reserved);
    if !issues.is_empty() {
        return Err(format!("radial settings are invalid: {issues:?}"));
    }
    multi_launcher::hotkey::parse_hotkey(hotkey.as_str()).ok_or_else(|| {
        format!(
            "the deterministic {} acceptance chord is unsupported",
            hotkey.as_str()
        )
    })?;

    Ok(DeterministicFixture {
        settings_json: serde_json::to_vec_pretty(&settings)
            .map_err(|error| format!("serialize settings: {error}"))?,
        radial_json: serde_json::to_vec_pretty(&document)
            .map_err(|error| format!("serialize radial document: {error}"))?,
        actions_json: serde_json::to_vec_pretty(&actions)
            .map_err(|error| format!("serialize custom action fixture: {error}"))?,
        hold_threshold_ms: settings.radial.hold_threshold_ms,
    })
}

fn deterministic_all_fixture_for_hotkey(
    log_path: &Path,
    mouse_gesture_mode: MouseGestureMode,
    hotkey: AcceptanceHotkey,
) -> Result<DeterministicFixture, String> {
    let mut fixture = deterministic_fixture_for_hotkey(log_path, mouse_gesture_mode, hotkey)?;
    let mut document: RadialDocument = serde_json::from_slice(&fixture.radial_json)
        .map_err(|error| format!("decode All acceptance radial document: {error}"))?;
    // All's fixed A5/A6/A7/D6 sequence starts enabled, then saves the disabled value.
    let skin = document
        .skins
        .first_mut()
        .ok_or_else(|| "All acceptance fixture has no exercised skin".to_string())?;
    skin.style.values.effects.glow_enabled = multi_launcher::radial::model::Override::Value(true);
    validate_radial_document(&document)
        .map_err(|error| format!("All acceptance radial document is invalid: {error:?}"))?;
    fixture.radial_json = serde_json::to_vec_pretty(&document)
        .map_err(|error| format!("serialize All acceptance radial document: {error}"))?;
    Ok(fixture)
}

fn deterministic_query_fixture(
    log_path: &Path,
    mouse_gesture_mode: MouseGestureMode,
    hotkey: AcceptanceHotkey,
    marker_path: &Path,
    runner_path: &Path,
) -> Result<DeterministicFixture, String> {
    let profile_root = marker_path
        .parent()
        .ok_or_else(|| "Query marker ledger has no profile parent".to_string())?;
    let notes_directory = profile_root.join("notes");
    fs::create_dir_all(&notes_directory)
        .map_err(|error| format!("create isolated Query notes directory: {error}"))?;
    write_new(
        &notes_directory.join("radial-acceptance-q13.md"),
        b"# Query acceptance fixture note\nThis note may be deleted only after the explicit confirmation case.\n",
    )?;
    let mut fixture = deterministic_fixture_for_hotkey(log_path, mouse_gesture_mode, hotkey)?;
    let mut settings: Settings = serde_json::from_slice(&fixture.settings_json)
        .map_err(|error| format!("decode Query acceptance settings: {error}"))?;
    settings.radial.safety_policy =
        multi_launcher::radial::model::RadialSafetyPolicy::AlwaysConfirmDestructive;
    settings.note.default_view_mode = multi_launcher::settings::NoteViewMode::Edit;
    settings.note_save_on_close = false;
    let mut document: RadialDocument = serde_json::from_slice(&fixture.radial_json)
        .map_err(|error| format!("decode Query acceptance radial document: {error}"))?;

    let marker_target = multi_launcher::actions::Action {
        label: "QMarker Alpha".into(),
        desc: "Harmless marker action used only by isolated acceptance profiles".into(),
        action: runner_path.to_string_lossy().into_owned(),
        args: Some(marker_arguments(marker_path, "q-first")?),
    };
    let second_marker_target = multi_launcher::actions::Action {
        label: "QMarker Beta".into(),
        desc: "Second harmless marker action used only to prove selection identity".into(),
        action: runner_path.to_string_lossy().into_owned(),
        args: Some(marker_arguments(marker_path, "q-second")?),
    };

    let query_binding = |query: &str, mode| ActionBinding::LauncherQuery {
        query: query.to_owned(),
        mode,
    };
    let exact_binding = |command: &str, args: Option<String>| ActionBinding::ExactCommand {
        command: command.to_owned(),
        args,
    };
    let mut bindings = vec![
        (
            "qa-open",
            "Open saved query",
            query_binding(
                "app QMarker",
                multi_launcher::radial::model::QueryRunMode::OpenLauncher,
            ),
        ),
        (
            "qa-hidden-first",
            "Execute first result",
            query_binding(
                "app QMarker",
                multi_launcher::radial::model::QueryRunMode::ExecuteFirst,
            ),
        ),
        (
            "qa-no-results",
            "Open query with no results",
            query_binding(
                "qa-no-such-result-9f42d2",
                multi_launcher::radial::model::QueryRunMode::ExecuteFirst,
            ),
        ),
        (
            "qa-visible-first",
            "Execute first result preserving ROOT",
            query_binding(
                "app QMarker",
                multi_launcher::radial::model::QueryRunMode::ExecuteFirst,
            ),
        ),
        (
            "qa-note-new",
            "Open note editor",
            exact_binding("note:new:radial-acceptance-q11", None),
        ),
        (
            "qa-launcher-show",
            "Explicit launcher show",
            exact_binding("launcher:show", Some("qa-explicit-launcher".into())),
        ),
        (
            "qa-note-remove",
            "Confirm isolated note removal",
            exact_binding("note:remove:radial-acceptance-q13", None),
        ),
        (
            "qa-exact-marker",
            "Execute exact external marker command",
            exact_binding(
                runner_path.to_string_lossy().as_ref(),
                Some(marker_arguments(marker_path, "q-exact")?),
            ),
        ),
    ];
    let menu = document
        .menus
        .iter_mut()
        .find(|menu| menu.id == document.default_menu_id)
        .ok_or_else(|| "Query fixture has no default radial menu".to_string())?;
    let cells = menu
        .rings
        .first_mut()
        .ok_or_else(|| "Query fixture default menu has no radial ring".to_string())?
        .cells
        .as_mut_slice();
    if cells.len() < bindings.len() + 1 {
        return Err("Query fixture has too few cells for its isolated cases".into());
    }
    for (index, (cell_id, label, binding)) in bindings.drain(..).enumerate() {
        let cell = &mut cells[index];
        cell.id = multi_launcher::radial::model::CellId::new(cell_id);
        cell.label = label.into();
        cell.content = CellContent::Action { binding };
        cell.after_action = AfterActionPolicy::CloseTree;
    }
    let pinned = &mut cells[8];
    pinned.id = multi_launcher::radial::model::CellId::new("qa-pinned-second");
    pinned.label = "Pinned non-first result".into();
    pinned.content = CellContent::Action {
        binding: ActionBinding::Persisted {
            action: PersistedUniversalActionRef {
                target: Some(PersistableActionTargetRef::CustomAction {
                    action: second_marker_target.clone(),
                }),
                action_id: action_ids::RESULT_EXECUTE,
            },
        },
    };
    pinned.after_action = AfterActionPolicy::CloseTree;
    document
        .menus
        .iter_mut()
        .find(|menu| menu.id == document.default_menu_id)
        .and_then(|menu| menu.rings.first_mut())
        .and_then(|ring| ring.cells.get_mut(1))
        .map(|cell| {
            if let CellContent::Action {
                binding: ActionBinding::LauncherQuery { .. },
            } = &cell.content
            {
                cell.alternate_clicks
                    .push(multi_launcher::radial::model::ClickBinding {
                        gesture: multi_launcher::radial::model::ClickGesture::ShiftPrimary,
                        action: ActionBinding::Persisted {
                            action: PersistedUniversalActionRef {
                                target: Some(PersistableActionTargetRef::CustomAction {
                                    action: marker_target.clone(),
                                }),
                                action_id: action_ids::RESULT_EXECUTE,
                            },
                        },
                        after_action: AfterActionPolicy::CloseTree,
                    });
            }
        });

    let mut actions = (0..ACCEPTANCE_ACTION_COUNT)
        .map(|index| multi_launcher::actions::Action {
            label: format!("Radial Acceptance Harmless Action {index:03}"),
            desc: "Deterministic native authoring fixture".into(),
            action: format!("radial_acceptance_harmless_{index:03}"),
            args: None,
        })
        .collect::<Vec<_>>();
    actions.insert(0, marker_target);
    actions.insert(1, second_marker_target);

    validate_radial_document(&document)
        .map_err(|error| format!("Query radial fixture is invalid: {error:?}"))?;
    let reserved = [("launcher", settings.hotkey.as_deref())]
        .into_iter()
        .filter_map(|(owner, chord)| chord.map(|chord| (owner.to_string(), chord.to_string())))
        .collect::<Vec<_>>();
    let issues = radial_settings::validate(&settings.radial, &document, &reserved);
    if !issues.is_empty() {
        return Err(format!("Query radial settings are invalid: {issues:?}"));
    }
    fixture.settings_json = serde_json::to_vec_pretty(&settings)
        .map_err(|error| format!("serialize Query settings: {error}"))?;
    fixture.radial_json = serde_json::to_vec_pretty(&document)
        .map_err(|error| format!("serialize Query radial document: {error}"))?;
    fixture.actions_json = serde_json::to_vec_pretty(&actions)
        .map_err(|error| format!("serialize Query actions: {error}"))?;
    Ok(fixture)
}

fn seed_query_note_editor_fixture(profile_root: &Path) -> Result<(), String> {
    write_new(
        &profile_root.join("notes").join("radial-acceptance-q11.md"),
        b"# radial acceptance q11\n\n",
    )
}

fn deterministic_gate_c_fixture(
    log_path: &Path,
    mouse_gesture_mode: MouseGestureMode,
    hotkey: AcceptanceHotkey,
    marker_path: &Path,
    runner_path: &Path,
) -> Result<DeterministicFixture, String> {
    let mut fixture = deterministic_query_fixture(
        log_path,
        mouse_gesture_mode,
        hotkey,
        marker_path,
        runner_path,
    )?;
    let mut settings: Settings = serde_json::from_slice(&fixture.settings_json)
        .map_err(|error| format!("decode Gate C settings: {error}"))?;
    // Gate C exercises a list-only plugin query and a non-prefixed custom
    // action query in grid mode. Capability gating keeps `note` in list mode
    // while the ordinary custom-action query uses the configured grid.
    settings.query_results_layout.enabled = true;
    settings.query_results_layout.respect_plugin_capability = true;
    fixture.settings_json = serde_json::to_vec_pretty(&settings)
        .map_err(|error| format!("serialize Gate C settings: {error}"))?;
    let profile_root = marker_path
        .parent()
        .ok_or_else(|| "Gate C marker ledger has no profile parent".to_string())?;
    let notes_directory = profile_root.join("notes");
    write_new(
        &notes_directory.join("radial-acceptance-shared-a.md"),
        b"# Shared Acceptance Note\nFirst duplicate-title target for radial authoring.\n",
    )?;
    write_new(
        &notes_directory.join("radial-acceptance-shared-b.md"),
        b"# Shared Acceptance Note\nSecond duplicate-title target for radial authoring.\n",
    )?;

    let mut document: RadialDocument = serde_json::from_slice(&fixture.radial_json)
        .map_err(|error| format!("decode Gate C radial fixture: {error}"))?;
    let default_menu_id = document.default_menu_id.clone();
    let default_menu = document
        .menus
        .iter_mut()
        .find(|menu| menu.id == default_menu_id)
        .ok_or_else(|| "Gate C fixture has no default menu".to_string())?;
    let insertion_cell = default_menu
        .rings
        .first_mut()
        .and_then(|ring| ring.cells.get_mut(7))
        .ok_or_else(|| "Gate C fixture has no root insertion spacer".to_string())?;
    insertion_cell.id = multi_launcher::radial::model::CellId::new("gate-c-insertion-spacer");
    insertion_cell.label = "Gate C insertion spacer".into();
    insertion_cell.content = CellContent::Spacer;
    insertion_cell.after_action = AfterActionPolicy::CloseTree;
    insertion_cell.alternate_clicks.clear();

    let grid_insertion_cell = default_menu
        .rings
        .first_mut()
        .and_then(|ring| ring.cells.get_mut(6))
        .ok_or_else(|| "Gate C fixture has no grid insertion spacer".to_string())?;
    grid_insertion_cell.id =
        multi_launcher::radial::model::CellId::new("gate-c-grid-insertion-spacer");
    grid_insertion_cell.label = "Gate C grid insertion spacer".into();
    grid_insertion_cell.content = CellContent::Spacer;
    grid_insertion_cell.after_action = AfterActionPolicy::CloseTree;
    grid_insertion_cell.alternate_clicks.clear();

    // Keep a deterministic, bounded >50-result target query for the shared
    // editor without overflowing the native report's 96-row evidence cap.
    // The isolated profile still contains all 64 harmless custom actions; the
    // first 32 share the queried title and the remainder remain distinct.
    let mut actions: Vec<multi_launcher::actions::Action> =
        serde_json::from_slice(&fixture.actions_json)
            .map_err(|error| format!("decode Gate C custom action fixture: {error}"))?;
    for (index, action) in actions.iter_mut().enumerate().skip(34) {
        action.label = format!("Radial Acceptance Secondary Action {:03}", index - 2);
    }

    validate_radial_document(&document)
        .map_err(|error| format!("Gate C radial fixture is invalid: {error:?}"))?;
    Ok(DeterministicFixture {
        settings_json: fixture.settings_json,
        radial_json: serde_json::to_vec_pretty(&document)
            .map_err(|error| format!("serialize Gate C radial fixture: {error}"))?,
        actions_json: serde_json::to_vec_pretty(&actions)
            .map_err(|error| format!("serialize Gate C custom action fixture: {error}"))?,
        hold_threshold_ms: fixture.hold_threshold_ms,
    })
}

fn deterministic_gate_d_fixture(
    log_path: &Path,
    mouse_gesture_mode: MouseGestureMode,
    hotkey: AcceptanceHotkey,
    marker_path: &Path,
    runner_path: &Path,
) -> Result<DeterministicFixture, String> {
    let fixture = deterministic_gate_c_fixture(
        log_path,
        mouse_gesture_mode,
        hotkey,
        marker_path,
        runner_path,
    )?;
    let mut document: RadialDocument = serde_json::from_slice(&fixture.radial_json)
        .map_err(|error| format!("decode Gate D radial fixture: {error}"))?;
    let root_index = document
        .menus
        .iter()
        .position(|menu| menu.id == document.default_menu_id)
        .ok_or_else(|| "Gate D fixture has no default menu".to_string())?;
    let shared_child = multi_launcher::radial::model::MenuId::new("starter-favorites");
    let second_parent_id = multi_launcher::radial::model::MenuId::new("gate-d-second-parent");

    {
        let shared_menu = document
            .menus
            .iter_mut()
            .find(|menu| menu.id == shared_child)
            .ok_or_else(|| "Gate D fixture has no starter-favorites shared child".to_string())?;
        let dynamic_source = shared_menu
            .rings
            .iter_mut()
            .flat_map(|ring| &mut ring.cells)
            .find(|cell| matches!(&cell.content, CellContent::Dynamic { .. }))
            .ok_or_else(|| "Gate D shared child has no authored dynamic source".to_string())?;
        dynamic_source.label = "Gate D generated query source".into();
        dynamic_source.content = CellContent::Dynamic {
            source: multi_launcher::radial::model::DynamicSource::LauncherQuery {
                query: "app QMarker".into(),
                max_items: 8,
            },
        };
        let dynamic_source_id = dynamic_source.id.clone();
        let long_label_cell = shared_menu
            .rings
            .iter_mut()
            .flat_map(|ring| &mut ring.cells)
            .find(|cell| {
                cell.id != dynamic_source_id
                    && !matches!(&cell.content, CellContent::Dynamic { .. })
            })
            .ok_or_else(|| {
                "Gate D shared child has no non-dynamic cell for its long-label fixture".to_string()
            })?;
        long_label_cell.label = GATE_D_LONG_LABEL.into();
    }

    let mut second_parent = document.menus[root_index].clone();
    second_parent.id = second_parent_id.clone();
    second_parent.name = "Gate D second parent".into();
    second_parent.rings.truncate(1);
    let parent_ring = second_parent
        .rings
        .first_mut()
        .ok_or_else(|| "Gate D fixture root has no ring to form a second parent".to_string())?;
    parent_ring.id = multi_launcher::radial::model::RingId::new("gate-d-second-parent-ring");
    parent_ring.cells.truncate(1);
    let parent_link = parent_ring
        .cells
        .first_mut()
        .ok_or_else(|| "Gate D second parent could not allocate its shared link".to_string())?;
    parent_link.id = multi_launcher::radial::model::CellId::new("gate-d-shared-child-link");
    parent_link.label = "Gate D shared child link".into();
    parent_link.content = CellContent::Submenu {
        menu_id: shared_child.clone(),
    };

    let root = &mut document.menus[root_index];
    let mut range_ring =
        root.rings.first().cloned().ok_or_else(|| {
            "Gate D fixture root has no ring for cross-ring selection".to_string()
        })?;
    range_ring.id = multi_launcher::radial::model::RingId::new("gate-d-range-ring");
    range_ring.radius += 80.0;
    range_ring.cells.truncate(3);
    for (index, cell) in range_ring.cells.iter_mut().enumerate() {
        cell.id = multi_launcher::radial::model::CellId::new(format!("gate-d-range-{index}"));
        cell.label = format!("Gate D range cell {index}");
    }
    let direct_child_link = range_ring.cells.get_mut(1).ok_or_else(|| {
        "Gate D range ring has no cell for its direct shared-child link".to_string()
    })?;
    direct_child_link.id = multi_launcher::radial::model::CellId::new("gate-d-direct-child-link");
    direct_child_link.label = "Gate D direct shared child link".into();
    direct_child_link.content = CellContent::Submenu {
        menu_id: shared_child.clone(),
    };
    let mut second_parent_link = range_ring
        .cells
        .get(2)
        .cloned()
        .ok_or_else(|| "Gate D range ring has no cell for its parent link".to_string())?;
    second_parent_link.id = multi_launcher::radial::model::CellId::new("gate-d-parent-link");
    second_parent_link.label = "Gate D second parent link".into();
    second_parent_link.content = CellContent::Submenu {
        menu_id: second_parent_id.clone(),
    };
    range_ring.cells.push(second_parent_link);
    root.rings.push(range_ring);
    document.menus.push(second_parent);

    let root = document
        .menus
        .iter()
        .find(|menu| menu.id == document.default_menu_id)
        .ok_or_else(|| "Gate D fixture lost its default menu".to_string())?;
    let direct_links = root
        .rings
        .iter()
        .flat_map(|ring| &ring.cells)
        .filter(|cell| {
            cell.id.as_str() == "gate-d-direct-child-link"
                && matches!(&cell.content, CellContent::Submenu { menu_id } if menu_id == &shared_child)
        })
        .count();
    let second_parent_links = root
        .rings
        .iter()
        .flat_map(|ring| &ring.cells)
        .filter(|cell| {
            cell.id.as_str() == "gate-d-parent-link"
                && matches!(&cell.content, CellContent::Submenu { menu_id } if menu_id == &second_parent_id)
        })
        .count();
    let nested_child_links = document
        .menus
        .iter()
        .find(|menu| menu.id == second_parent_id)
        .into_iter()
        .flat_map(|menu| menu.rings.iter())
        .flat_map(|ring| &ring.cells)
        .filter(|cell| {
            cell.id.as_str() == "gate-d-shared-child-link"
                && matches!(&cell.content, CellContent::Submenu { menu_id } if menu_id == &shared_child)
        })
        .count();
    if direct_links != 1 || second_parent_links != 1 || nested_child_links != 1 {
        return Err(format!(
            "Gate D fixture paths are ambiguous or missing: direct={direct_links}, second_parent={second_parent_links}, nested={nested_child_links}"
        ));
    }

    validate_radial_document(&document)
        .map_err(|error| format!("Gate D radial fixture is invalid: {error:?}"))?;
    Ok(DeterministicFixture {
        settings_json: fixture.settings_json,
        radial_json: serde_json::to_vec_pretty(&document)
            .map_err(|error| format!("serialize Gate D radial fixture: {error}"))?,
        actions_json: fixture.actions_json,
        hold_threshold_ms: fixture.hold_threshold_ms,
    })
}

fn marker_arguments(marker_path: &Path, nonce: &str) -> Result<String, String> {
    let marker_path_text = marker_path.to_string_lossy();
    let marker = shlex::try_quote(&marker_path_text)
        .map_err(|_| "query marker path could not be represented as an argument".to_string())?;
    Ok(format!("--acceptance-marker {marker} {nonce}"))
}

fn bind_hotkey_hover_probe_action(
    document: &mut RadialDocument,
    action: &multi_launcher::actions::Action,
) -> Result<(), String> {
    let default_menu_id = document.default_menu_id.clone();
    let menu = document
        .menus
        .iter_mut()
        .find(|menu| menu.id == default_menu_id)
        .ok_or_else(|| "the starter radial has no default menu for the hover probe".to_string())?;
    let cell = menu
        .rings
        .first_mut()
        .and_then(|ring| ring.cells.first_mut())
        .ok_or_else(|| {
            "the starter default menu has no root cell for the hover probe".to_string()
        })?;
    cell.label = action.label.clone();
    cell.after_action = AfterActionPolicy::CloseTree;
    cell.content = CellContent::Action {
        binding: ActionBinding::Persisted {
            action: PersistedUniversalActionRef {
                target: Some(PersistableActionTargetRef::CustomAction {
                    action: action.clone(),
                }),
                action_id: action_ids::RESULT_EXECUTE,
            },
        },
    };
    Ok(())
}

