    #[test]
    fn oversized_packet_error_reports_bounded_component_counts() {
        let mut packet = h04_matrix_evidence_packet();
        let mut next_ordinal = packet
            .candidate_events
            .last()
            .expect("fixture candidate events")
            .event_ordinal
            + 1;
        let mut next_elapsed = packet
            .candidate_events
            .last()
            .expect("fixture candidate events")
            .elapsed_ms
            + 1;
        let template = packet
            .candidate_events
            .iter()
            .find(|event| event.kind == HotkeyTraceEventKind::NativeWindowSnapshot)
            .expect("fixture physical snapshot")
            .clone();
        while packet.candidate_events.len() < MAX_HOTKEY_EVIDENCE_EVENTS {
            let mut event = template.clone();
            event.event_ordinal = next_ordinal;
            event.elapsed_ms = next_elapsed;
            next_ordinal += 1;
            next_elapsed += 1;
            packet.candidate_events.push(event);
        }
        packet.candidate_event_count = packet.candidate_events.len();

        let edge = packet.runner_edges.last().unwrap().clone();
        while packet.runner_edges.len() < MAX_HOTKEY_EVIDENCE_EDGES {
            let mut edge = edge.clone();
            edge.runner_relative_us = packet
                .runner_edges
                .last()
                .unwrap()
                .runner_relative_us
                .saturating_add(1);
            packet.runner_edges.push(edge);
        }
        let gesture = packet.gestures[1].clone();
        while packet.gestures.len() < MAX_HOTKEY_EVIDENCE_GESTURES {
            packet.gestures.push(gesture.clone());
        }

        // Keep component counts at their bounded maxima while independently
        // exercising the serialized byte guard with a hostile oversized tag.
        packet.runner_clock = "x".repeat(MAX_HOTKEY_CASE_EVIDENCE_BYTES);

        let encoded_len = serde_json::to_vec(&packet).unwrap().len();
        assert!(encoded_len > MAX_HOTKEY_CASE_EVIDENCE_BYTES);
        let error = validate_hotkey_evidence_packet_with_context(
            &packet,
            AcceptanceHotkey::ShiftAltWinEnd,
            350,
        )
        .unwrap_err();
        assert!(error.contains(&format!("bytes={encoded_len}")), "{error}");
        assert!(
            error.contains(&format!("candidate_events={MAX_HOTKEY_EVIDENCE_EVENTS}")),
            "{error}"
        );
        assert!(
            error.contains(&format!("runner_edges={MAX_HOTKEY_EVIDENCE_EDGES}")),
            "{error}"
        );
        assert!(
            error.contains(&format!("gestures={MAX_HOTKEY_EVIDENCE_GESTURES}")),
            "{error}"
        );
        assert!(error.contains("command_spans=") && error.contains("snapshots="));
    }

    #[test]
    fn hotkey_packet_requires_external_primary_edges_and_exact_tagged_chord() {
        let packet = h01_evidence_packet();
        // Release modifier matching is diagnostic; false is valid after the
        // owned chord has been released, while Press must match the chord.
        assert_eq!(packet.candidate_events[1].modifiers_match, Some(false));
        validate_hotkey_evidence_packet(&packet).unwrap();

        let mut press_not_external = packet.clone();
        press_not_external.candidate_events[0].provenance = Some(HotkeyInputProvenance::Owned);
        assert!(validate_hotkey_evidence_packet(&press_not_external).is_err());

        let mut release_not_external = packet.clone();
        release_not_external.candidate_events[1].provenance = Some(HotkeyInputProvenance::Physical);
        assert!(validate_hotkey_evidence_packet(&release_not_external).is_err());

        let mut malformed_release = packet.clone();
        malformed_release.candidate_events[1].modifiers_match = None;
        assert!(validate_hotkey_evidence_packet(&malformed_release).is_err());

        let mut partial = packet.clone();
        partial.runner_edges.pop();
        assert!(validate_hotkey_evidence_packet(&partial).is_err());

        let mut wrong_key = packet.clone();
        wrong_key.runner_edges[0].virtual_key = 0x23;
        assert!(validate_hotkey_evidence_packet(&wrong_key).is_err());

        let mut duplicate = packet.clone();
        duplicate
            .runner_edges
            .push(duplicate.runner_edges[1].clone());
        assert!(validate_hotkey_evidence_packet(&duplicate).is_err());
    }

    #[test]
    fn h16_legacy_gesture_and_standalone_intent_share_one_exact_f11_pair() {
        let packet = h16_legacy_fallback_group_packet(AcceptanceHotkey::ShiftAltWinEnd);
        validate_runner_edge_groups(&packet, AcceptanceHotkey::ShiftAltWinEnd, 350).unwrap();

        let reverse_profile = h16_legacy_fallback_group_packet(AcceptanceHotkey::F11);
        validate_runner_edge_groups(&reverse_profile, AcceptanceHotkey::F11, 350).unwrap();

        let mut missing_release = packet.clone();
        missing_release.runner_edges.pop();
        assert!(
            validate_runner_edge_groups(&missing_release, AcceptanceHotkey::ShiftAltWinEnd, 350)
                .is_err()
        );

        let mut extra_chord = packet.clone();
        extra_chord.runner_edges.extend([
            HotkeyRunnerEdgeEvidence {
                runner_relative_us: 300,
                ..packet.runner_edges[0].clone()
            },
            HotkeyRunnerEdgeEvidence {
                runner_relative_us: 400,
                ..packet.runner_edges[1].clone()
            },
        ]);
        assert!(
            validate_runner_edge_groups(&extra_chord, AcceptanceHotkey::ShiftAltWinEnd, 350)
                .is_err()
        );

        let mut unrelated_intent = packet.clone();
        unrelated_intent.standalone_decisions[0].input_group_id += 1;
        assert!(
            validate_runner_edge_groups(&unrelated_intent, AcceptanceHotkey::ShiftAltWinEnd, 350)
                .is_err()
        );

        let mut wrong_gesture_reason = packet;
        wrong_gesture_reason.gestures[0].decision = HotkeyDecisionProof::NotApplicable {
            reason: HotkeyEvidenceNotApplicable::HoldGestureHasNoShortTap,
        };
        assert!(
            validate_runner_edge_groups(
                &wrong_gesture_reason,
                AcceptanceHotkey::ShiftAltWinEnd,
                350
            )
            .is_err()
        );
    }

    #[test]
    fn h16_untracked_modifier_exception_is_bound_to_the_complex_legacy_group() {
        let packet = h16_legacy_modifier_packet(AcceptanceHotkey::F11);
        let press = &packet.candidate_events[0];
        assert!(h16_legacy_modifier_mismatch_is_valid(&packet, press));
        validate_runner_edge_groups(&packet, AcceptanceHotkey::F11, 350).unwrap();
        let incomplete =
            validate_hotkey_evidence_packet_with_context(&packet, AcceptanceHotkey::F11, 350)
                .unwrap_err();
        assert!(
            incomplete.contains("expected [false, true]") || incomplete.contains("has 0 taps"),
            "the H16 packet should proceed past its valid legacy Press and fail only for the intentionally omitted MainCandidate fixture: {incomplete}"
        );
        assert!(!incomplete.contains("primary press"), "{incomplete}");

        let mut missing_modifier = packet.clone();
        missing_modifier.candidate_events[0].modifiers_match = None;
        assert!(!h16_legacy_modifier_mismatch_is_valid(
            &missing_modifier,
            &missing_modifier.candidate_events[0]
        ));
        assert!(
            validate_hotkey_evidence_packet_with_context(
                &missing_modifier,
                AcceptanceHotkey::F11,
                350
            )
            .unwrap_err()
            .contains("primary press")
        );

        let mut mismatched_release = packet.clone();
        mismatched_release.candidate_events[1].modifiers_match = Some(true);
        assert!(!h16_legacy_modifier_mismatch_is_valid(
            &mismatched_release,
            &mismatched_release.candidate_events[0]
        ));

        let mut wrong_stream = packet.clone();
        wrong_stream.candidate_events[0].stream = HotkeyCandidateStream::MainCandidate;
        assert!(!h16_legacy_modifier_mismatch_is_valid(
            &wrong_stream,
            &wrong_stream.candidate_events[0]
        ));
        assert!(
            validate_hotkey_evidence_packet_with_context(&wrong_stream, AcceptanceHotkey::F11, 350)
                .unwrap_err()
                .contains("primary press")
        );

        let mut wrong_group = packet.clone();
        wrong_group.candidate_events[0].input_group_id += 1;
        assert!(!h16_legacy_modifier_mismatch_is_valid(
            &wrong_group,
            &wrong_group.candidate_events[0]
        ));

        let mut wrong_tag = packet.clone();
        wrong_tag.runner_edges[0].runner_cookie_matched = false;
        assert!(!h16_legacy_modifier_mismatch_is_valid(
            &wrong_tag,
            &wrong_tag.candidate_events[0]
        ));
        assert!(
            validate_hotkey_evidence_packet_with_context(&wrong_tag, AcceptanceHotkey::F11, 350)
                .unwrap_err()
                .contains("primary press")
        );

        let mut missing_tagged_edge = packet.clone();
        missing_tagged_edge.runner_edges.pop();
        assert!(!h16_legacy_modifier_mismatch_is_valid(
            &missing_tagged_edge,
            &missing_tagged_edge.candidate_events[0]
        ));

        let mut duplicate_trigger = packet.clone();
        let mut duplicate = duplicate_trigger.candidate_events[2].clone();
        duplicate.event_ordinal = 6;
        duplicate.elapsed_ms = 27;
        duplicate_trigger.candidate_events.push(duplicate);
        duplicate_trigger.candidate_event_count = duplicate_trigger.candidate_events.len();
        assert!(!h16_legacy_modifier_mismatch_is_valid(
            &duplicate_trigger,
            &duplicate_trigger.candidate_events[0]
        ));

        let mut short_tap = packet.clone();
        let mut tap = short_tap.candidate_events[1].clone();
        tap.event_ordinal = 3;
        tap.elapsed_ms = 21;
        tap.kind = HotkeyTraceEventKind::ShortTap;
        tap.terminal = Some(true);
        tap.modifiers_match = None;
        tap.provenance = None;
        short_tap
            .candidate_events
            .iter_mut()
            .skip(2)
            .for_each(|event| event.event_ordinal += 1);
        short_tap.candidate_events.insert(2, tap);
        short_tap.candidate_event_count = short_tap.candidate_events.len();
        assert!(!h16_legacy_modifier_mismatch_is_valid(
            &short_tap,
            &short_tap.candidate_events[0]
        ));

        let mut reducer_active = packet.clone();
        reducer_active.candidate_events[2].visibility_source =
            Some(HotkeyVisibilitySource::ToggleBatch);
        reducer_active.candidate_events[2].invocation_id = Some(17);
        assert!(!h16_legacy_modifier_mismatch_is_valid(
            &reducer_active,
            &reducer_active.candidate_events[0]
        ));

        let reverse_profile = h16_legacy_modifier_packet(AcceptanceHotkey::ShiftAltWinEnd);
        validate_runner_edge_groups(&reverse_profile, AcceptanceHotkey::ShiftAltWinEnd, 350)
            .unwrap();
        assert!(!h16_legacy_modifier_mismatch_is_valid(
            &reverse_profile,
            &reverse_profile.candidate_events[0]
        ));
        let reverse_error = validate_hotkey_evidence_packet_with_context(
            &reverse_profile,
            AcceptanceHotkey::ShiftAltWinEnd,
            350,
        )
        .unwrap_err();
        assert!(reverse_error.contains("primary press"), "{reverse_error}");
        let mut valid_simple_fallback = reverse_profile.clone();
        valid_simple_fallback.candidate_events[0].modifiers_match = Some(true);
        let simple_packet_error = validate_hotkey_evidence_packet_with_context(
            &valid_simple_fallback,
            AcceptanceHotkey::ShiftAltWinEnd,
            350,
        )
        .unwrap_err();
        assert!(
            !simple_packet_error.contains("primary press"),
            "{simple_packet_error}"
        );
    }

