    fn gate_c_identity(
        surface: GateCSurface,
        session_id: u64,
        draft_generation: u64,
        editor_epoch: u64,
        target_digest: u64,
    ) -> GateCEditorIdentity {
        GateCEditorIdentity {
            surface,
            session_id,
            draft_generation,
            stable_target_digest: target_digest,
            editor_epoch,
            edit_generation: 3,
            query_generation: 2,
            query_request_generation: 2,
            search_request_generation: 2,
            test_request_generation: 1,
            query_digest: 31,
            binding_digest: 41,
        }
    }

    fn gate_c_control_sequence(
        name: &str,
        identity: &GateCEditorIdentity,
        index: Option<usize>,
    ) -> u64 {
        let surface_offset = match identity.surface {
            GateCSurface::Properties => 0,
            GateCSurface::Inspector => 500,
        };
        let control_offset = match name {
            "query" | "query_field" => 1,
            "search" => 2,
            "result" | "result_target" => 3,
            "pin" | "pin_result" => 4,
            "save_query" => 5,
            "mode" | "query_mode" => 6,
            "advanced" | "advanced_tab" => 7,
            "exact_command" | "exact_command_field" => 8,
            "arguments" | "exact_args_field" => 9,
            "use_exact_command" => 10,
            "test" | "test_query" | "test_result" | "test_assigned" => 11,
            "test_exact_command" => 12,
            "apply" => 11,
            "open_inspector" => 12,
            "close" => 13,
            "keep_editing" => 14,
            "discard" => 15,
            "reopen" => 16,
            "save" => 17,
            "undo" => 18,
            "redo" => 19,
            "add_to_radial" => 20,
            "menu" => 21,
            "ring" => 22,
            "cell" => 23,
            "spacer" => 24,
            "append" => 25,
            "replace" => 26,
            "cancel" => 27,
            "confirm_close_tree" => 28,
            _ => 99,
        };
        identity.edit_generation * 10_000
            + identity.query_generation * 100
            + surface_offset
            + control_offset * 2
            + index.unwrap_or(0) as u64
    }

    fn gate_c_control(
        name: &str,
        identity: &GateCEditorIdentity,
        index: Option<usize>,
        target_digest: u64,
        action_digest: u64,
        clicked: bool,
    ) -> GateCControlEvidence {
        GateCControlEvidence {
            control: name.into(),
            trace_sequence: gate_c_control_sequence(name, identity, index),
            identity: identity.clone(),
            owner_session_id: None,
            owner_generation: None,
            control_index: index,
            target_digest,
            title_digest: if matches!(
                name,
                "result"
                    | "result_target"
                    | "pin"
                    | "pin_result"
                    | "test_result"
                    | "contextual_target"
                    | "pin_contextual"
            ) {
                301
            } else {
                0
            },
            type_digest: if matches!(
                name,
                "result"
                    | "result_target"
                    | "pin"
                    | "pin_result"
                    | "test_result"
                    | "contextual_target"
                    | "pin_contextual"
            ) {
                302
            } else {
                0
            },
            disambiguator_digest: if matches!(
                name,
                "result"
                    | "result_target"
                    | "pin"
                    | "pin_result"
                    | "test_result"
                    | "contextual_target"
                    | "pin_contextual"
            ) {
                400 + target_digest
            } else {
                0
            },
            action_digest,
            binding_digest: if matches!(
                name,
                "result"
                    | "result_target"
                    | "pin"
                    | "pin_result"
                    | "test_result"
                    | "contextual_target"
                    | "pin_contextual"
            ) {
                501 + target_digest
            } else {
                identity.binding_digest
            },
            query_digest: identity.query_digest,
            value_digest: if matches!(name, "query" | "query_field") {
                identity.query_digest
            } else {
                0
            },
            displayed_text_digest: if matches!(
                name,
                "result" | "result_target" | "contextual_target"
            ) {
                61
            } else {
                0
            },
            bounds: [10, 10, 80, 36],
            full_bounds: [10, 10, 80, 36],
            fully_visible: true,
            client_size: [800, 600],
            visible: true,
            enabled: true,
            selected: clicked,
            focused: clicked,
            clicked,
            changed: false,
            enter_pressed: false,
            readable_text_digest: if matches!(
                name,
                "result" | "result_target" | "contextual_target"
            ) {
                Some(61)
            } else {
                None
            },
        }
    }

