    fn l08_placement_packet(hotkey: AcceptanceHotkey) -> QueryCaseEvidence {
        let configured = QueryRootPresentationEvidence {
            hwnd: 44,
            process_id: 7,
            bounds: [240, 180, 1156, 869],
            visible: true,
            minimized: false,
            physically_visible: true,
        };
        let moved = QueryRootPresentationEvidence {
            bounds: [320, 260, 1236, 949],
            ..configured.clone()
        };
        let mut invocation = query_invocation_for_test(
            "qa-note-new",
            QueryEvidenceMode::ExactCommand,
            QueryEvidenceState::Ready,
            QueryEvidenceRequirement::LauncherUi,
            QueryEvidenceOutcome::Executed,
            QueryEvidenceRootPolicy::Legacy,
            1,
            0,
            QueryEvidenceUiAck::NoteEditor,
            true,
            120,
        );
        invocation.root_observations = vec![moved.clone(), moved.clone()];
        invocation.setup_visibility = QuerySetupVisibilityEvidence {
            visible_before: true,
            desired_visible: true,
            tap: None,
        };
        let toggle = |visible, cursor: usize, invocation_id, visibility_revision| {
            let mut command = h01_evidence_packet().candidate_events[4].clone();
            command.event_ordinal = (cursor + 5) as u32;
            command.elapsed_ms = (cursor + 5) as u64;
            command.invocation_id = Some(invocation_id);
            command.visibility_revision = Some(visibility_revision);
            command.request_id = Some(visibility_revision);
            command.command = Some(if visible {
                HotkeyRootCommand::Show
            } else {
                HotkeyRootCommand::Position
            });
            let presentation = if visible {
                configured.clone()
            } else {
                QueryRootPresentationEvidence {
                    bounds: [-10_000, -10_000, -9084, -9311],
                    physically_visible: false,
                    ..moved.clone()
                }
            };
            let mut snapshot = command.clone();
            snapshot.kind = HotkeyTraceEventKind::NativeWindowSnapshot;
            snapshot.command = None;
            snapshot.event_ordinal += 1;
            snapshot.elapsed_ms += 1;
            snapshot.hwnd = Some(44);
            snapshot.process_id = Some(7);
            snapshot.bounds = Some(presentation.bounds);
            snapshot.visible = Some(true);
            snapshot.minimized = Some(false);
            QueryPlacementToggleEvidence {
                input: QuerySetupVisibilityEvidence {
                    visible_before: !visible,
                    desired_visible: visible,
                    tap: Some(QuerySetupTapEvidence {
                        input_down_inserted: configured_chord_edges(hotkey, 1).len() / 2,
                        input_up_inserted: configured_chord_edges(hotkey, 1).len() / 2,
                        quiet_preflight_ms: 80,
                        quiet_matching_edges: 0,
                        observer_default_desktop: true,
                        observed_edges: configured_chord_edges(hotkey, 1)
                            .into_iter()
                            .enumerate()
                            .map(|(index, (virtual_key, down))| QuerySetupObservedEdge {
                                runner_relative_us: index as u64 * 100,
                                virtual_key,
                                down,
                                injected: true,
                                runner_cookie_matched: true,
                            })
                            .collect(),
                        foreign_edges: Vec::new(),
                        trace_cursor: cursor,
                        invocation_id,
                        generation: 10,
                        press_event_ordinal: cursor + 1,
                        release_event_ordinal: cursor + 2,
                        short_tap_event_ordinal: cursor + 3,
                        visibility_event_ordinal: cursor + 4,
                        visibility_visible: visible,
                    }),
                },
                visibility_revision,
                command,
                snapshot,
                presentation,
            }
        };
        QueryCaseEvidence {
            schema_version: 1,
            case_id: "L08".into(),
            invocations: vec![invocation],
            placement: Some(QueryPlacementEvidence {
                hotkey,
                physical_displays: vec![[0, 0, 1920, 1080]],
                dpi: 96,
                configured_logical_position: QUERY_CONFIGURED_ROOT_POSITION,
                configured_logical_client_size: QUERY_CONFIGURED_ROOT_CLIENT_SIZE,
                configured_client_bounds: [0, 0, 900, 650],
                configured_root: configured.clone(),
                moved_root: moved.clone(),
                moved_client_bounds: [0, 0, 900, 650],
                handoff_terminal_cursor: 20,
                restored_root: moved.clone(),
                restored_client_bounds: [0, 0, 900, 650],
                hide: toggle(false, 30, 200, 20),
                show: toggle(true, 40, 201, 21),
                shown_client_bounds: [0, 0, 900, 650],
                note_absent_before: true,
                note_closed_after: true,
            }),
        }
    }

    #[test]
    fn l08_placement_proof_requires_real_move_ui_handoff_and_exact_hide_show() {
        for hotkey in [AcceptanceHotkey::F11, AcceptanceHotkey::ShiftAltWinEnd] {
            let packet = l08_placement_packet(hotkey);
            query_case_contract_is_valid(&packet).unwrap();
            let bytes = serde_json::to_vec(&packet).unwrap();
            assert!(bytes.len() < MAX_QUERY_CASE_EVIDENCE_BYTES);
            let decoded: QueryCaseEvidence = serde_json::from_slice(&bytes).unwrap();
            query_case_contract_is_valid(&decoded).unwrap();
            let mut q11 = passing_query_packets_for_test()
                .into_iter()
                .find(|packet| packet.case_id == "Q11")
                .unwrap();
            assert_eq!(q11.invocations.len(), 1);
            assert!(q11.placement.is_none());
            query_case_contract_is_valid(&q11).unwrap();
            q11.placement = packet.placement;
            assert!(query_case_contract_is_valid(&q11).is_err());
        }
    }

    #[test]
    fn l08_placement_geometry_uses_measured_client_dimensions_at_fractional_dpi() {
        for dpi in [120, 144] {
            let mut packet = l08_placement_packet(AcceptanceHotkey::F11);
            let scale = f64::from(dpi) / 96.0;
            let bounds =
                |rect: [i32; 4]| rect.map(|value| (f64::from(value) * scale).round() as i32);
            let proof = packet.placement.as_mut().unwrap();
            proof.dpi = dpi;
            proof.physical_displays = vec![bounds([0, 0, 1920, 1080])];
            proof.configured_root.bounds = bounds(proof.configured_root.bounds);
            proof.moved_root.bounds = bounds(proof.moved_root.bounds);
            proof.restored_root.bounds = proof.moved_root.bounds;
            proof.configured_client_bounds = bounds(proof.configured_client_bounds);
            proof.moved_client_bounds = proof.configured_client_bounds;
            proof.restored_client_bounds = proof.configured_client_bounds;
            proof.shown_client_bounds = proof.configured_client_bounds;
            proof.show.presentation = proof.configured_root.clone();
            proof.show.snapshot.bounds = Some(proof.configured_root.bounds);
            for sample in &mut packet.invocations[0].root_observations {
                *sample = proof.moved_root.clone();
            }
            query_case_contract_is_valid(&packet).unwrap();
            packet.placement.as_mut().unwrap().shown_client_bounds[2] += 1;
            assert!(query_case_contract_is_valid(&packet).is_err());
        }
    }

    #[test]
    fn l08_placement_proof_rejects_geometry_identity_ack_release_order_and_cleanup_mutations() {
        let changes: &[fn(&mut QueryCaseEvidence)] = &[
            |packet| {
                packet.placement.as_mut().unwrap().moved_root =
                    packet.placement.as_ref().unwrap().configured_root.clone()
            },
            |packet| packet.placement.as_mut().unwrap().moved_root.hwnd += 1,
            |packet| packet.placement.as_mut().unwrap().moved_root.process_id += 1,
            |packet| packet.placement.as_mut().unwrap().moved_root.minimized = true,
            |packet| {
                packet.placement.as_mut().unwrap().moved_root.bounds =
                    [-20_000, -20_000, -19_084, -19_311]
            },
            |packet| {
                packet.placement.as_mut().unwrap().configured_root.bounds =
                    [i32::MIN, 0, i32::MAX, 600]
            },
            |packet| packet.placement.as_mut().unwrap().restored_root.bounds[0] += 1,
            |packet| packet.invocations[0].root_observations[0].bounds[1] += 1,
            |packet| packet.invocations[0].root_geometry_change_count = 1,
            |packet| packet.invocations[0].ui_ack = QueryEvidenceUiAck::None,
            |packet| packet.invocations[0].effect_count = 2,
            |packet| packet.invocations[0].setup_visibility.visible_before = false,
            |packet| packet.placement.as_mut().unwrap().hide.input.tap = None,
            |packet| {
                packet
                    .placement
                    .as_mut()
                    .unwrap()
                    .show
                    .input
                    .tap
                    .as_mut()
                    .unwrap()
                    .input_up_inserted = 0
            },
            |packet| {
                packet
                    .placement
                    .as_mut()
                    .unwrap()
                    .hide
                    .input
                    .tap
                    .as_mut()
                    .unwrap()
                    .observed_edges[0]
                    .runner_cookie_matched = false
            },
            |packet| {
                packet
                    .placement
                    .as_mut()
                    .unwrap()
                    .show
                    .input
                    .tap
                    .as_mut()
                    .unwrap()
                    .trace_cursor = 25
            },
            |packet| packet.placement.as_mut().unwrap().show.visibility_revision = 20,
            |packet| packet.placement.as_mut().unwrap().show.command.request_id = Some(99),
            |packet| packet.placement.as_mut().unwrap().show.snapshot.hwnd = Some(99),
            |packet| {
                packet.placement.as_mut().unwrap().show.snapshot.bounds =
                    Some([320, 260, 1236, 949])
            },
            |packet| {
                packet.placement.as_mut().unwrap().show.presentation.bounds = [320, 260, 1236, 949]
            },
            |packet| packet.placement.as_mut().unwrap().shown_client_bounds[2] += 1,
            |packet| packet.placement.as_mut().unwrap().note_closed_after = false,
            |packet| packet.placement.as_mut().unwrap().note_absent_before = false,
        ];
        for (index, change) in changes.iter().enumerate() {
            let mut packet = l08_placement_packet(AcceptanceHotkey::F11);
            change(&mut packet);
            assert!(
                query_case_contract_is_valid(&packet).is_err(),
                "mutation {index} falsely passed"
            );
        }
        let mut packet = l08_placement_packet(AcceptanceHotkey::F11);
        packet.placement = None;
        assert!(query_case_contract_is_valid(&packet).is_err());
    }

    #[test]
    fn query_case_contracts_require_the_exact_hovered_cell() {
        let mut packets = passing_query_packets_for_test();
        assert_eq!(packets.len(), 10);
        for packet in &packets {
            query_case_contract_is_valid(packet).unwrap_or_else(|error| panic!("{error}"));
        }

        let packet = packets
            .iter_mut()
            .find(|packet| packet.case_id == "Q05")
            .unwrap();
        packet.invocations[0].cell_id = "qa-hidden-first".into();
        packet.invocations[0].cell_digest = query_cell_digest("qa-hidden-first");
        assert!(query_case_contract_is_valid(packet).is_err());

        let mut packets = passing_query_packets_for_test();
        let packet = packets
            .iter_mut()
            .find(|packet| packet.case_id == "Q10")
            .unwrap();
        let visible = &mut packet.invocations[1];
        visible.root_observations[0].visible = false;
        visible.root_observations[0].physically_visible = false;
        visible.root_visible_samples = 1;
        visible.root_hidden_samples = 1;
        assert!(
            query_case_contract_is_valid(packet).is_err(),
            "Q10 visible-state proof must reject even one retained hidden ROOT sample"
        );

        let mut report = acceptance_report("native_windows_query");
        report.suite = AcceptanceSuite::Query;
        report.environment.child_process_id = Some(7);
        report.environment.monitors = vec![MonitorIdentity {
            id: 1,
            x: 0,
            y: 0,
            width: 1000,
            height: 1000,
            scale_factor: 1.0,
        }];
        let mut invocation = passing_query_packets_for_test()
            .remove(1)
            .invocations
            .remove(0);
        assert!(query_invocation_evidence_is_valid(&invocation, &report));

        let mut impossible_hidden_sample = invocation.clone();
        impossible_hidden_sample.root_observations[0].visible = true;
        impossible_hidden_sample.root_observations[0].physically_visible = true;
        assert!(
            !query_invocation_evidence_is_valid(&impossible_hidden_sample, &report),
            "retained onscreen samples must be consistent with the hidden counter"
        );

        let mut visible_packet = passing_query_packets_for_test()
            .into_iter()
            .find(|packet| packet.case_id == "Q10")
            .unwrap();
        let visible_invocation = &mut visible_packet.invocations[1];
        visible_invocation.root_observations[1].visible = false;
        visible_invocation.root_observations[1].physically_visible = false;
        visible_invocation.root_visible_samples = 1;
        visible_invocation.root_hidden_samples = 1;
        assert!(query_invocation_evidence_is_valid(
            visible_invocation,
            &report
        ));
        assert!(
            query_case_contract_is_valid(&visible_packet).is_err(),
            "physically consistent counters cannot conceal a hidden retained sample"
        );

        invocation.cell_id = "qa-pinned-second".into();
        assert!(!query_invocation_evidence_is_valid(&invocation, &report));
    }

    #[test]
    fn preserved_state_requires_preclick_baseline_and_postquiet_observation() {
        let mut invocation = query_invocation_for_test(
            "qa-hidden-first",
            QueryEvidenceMode::ExecuteFirst,
            QueryEvidenceState::Ready,
            QueryEvidenceRequirement::External,
            QueryEvidenceOutcome::Executed,
            QueryEvidenceRootPolicy::Preserve,
            1,
            0,
            QueryEvidenceUiAck::None,
            false,
            901,
        );
        assert!(preserved_query_state_is_valid(&invocation));

        let mut missing_baseline = invocation.clone();
        missing_baseline.ordinary_baseline_request_id = None;
        assert!(!preserved_query_state_is_valid(&missing_baseline));

        let mut stale_frame = invocation.clone();
        stale_frame.ordinary_terminal_frame_ordinal = stale_frame.ordinary_baseline_frame_ordinal;
        assert!(!preserved_query_state_is_valid(&stale_frame));

        let mut late_query_mutation = invocation.clone();
        late_query_mutation
            .root_state_after
            .as_mut()
            .unwrap()
            .query_digest += 1;
        assert!(!preserved_query_state_is_valid(&late_query_mutation));

        let mut late_results_mutation = invocation.clone();
        late_results_mutation
            .root_state_after
            .as_mut()
            .unwrap()
            .selected_index = Some(1);
        assert!(!preserved_query_state_is_valid(&late_results_mutation));

        let mut duplicate_history = invocation.clone();
        duplicate_history
            .root_state_after
            .as_mut()
            .unwrap()
            .matching_history_count += 1;
        assert!(!preserved_query_state_is_valid(&duplicate_history));

        let mut duplicate_usage = invocation.clone();
        duplicate_usage
            .root_state_after
            .as_mut()
            .unwrap()
            .usage_count += 1;
        assert!(!preserved_query_state_is_valid(&duplicate_usage));

        invocation.root_state_after.as_mut().unwrap().state_digest += 1;
        assert!(!preserved_query_state_is_valid(&invocation));
    }

    #[test]
    fn query_evidence_packets_fit_bounded_case_and_aggregate_caps() {
        let packets = passing_query_packets_for_test();
        let mut total_bytes = 0usize;
        for packet in &packets {
            let packet_bytes = serde_json::to_vec(packet).unwrap().len();
            assert!(packet_bytes <= MAX_QUERY_CASE_EVIDENCE_BYTES);
            total_bytes += packet_bytes;
        }
        assert!(total_bytes <= MAX_QUERY_EVIDENCE_BYTES);

        let mut report = acceptance_report("native_windows_query");
        report.suite = AcceptanceSuite::Query;
        report.environment.child_process_id = Some(7);
        report.environment.monitors = vec![MonitorIdentity {
            id: 1,
            x: 0,
            y: 0,
            width: 1920,
            height: 1080,
            scale_factor: 1.0,
        }];
        for packet in packets {
            for invocation in &packet.invocations {
                assert!(
                    query_invocation_evidence_is_valid(invocation, &report),
                    "{} invocation failed validation: {invocation:?}",
                    packet.case_id
                );
            }
            report.cases.push(AcceptanceCaseResult {
                id: packet.case_id.clone(),
                status: CaseStatus::Passed,
                elapsed_ms: 1,
                expected: "query proof".into(),
                observed: "query proof".into(),
                failure_stage: None,
                artifacts: Vec::new(),
            });
            report.query_evidence.push(packet);
        }
        for (index, packet) in report.query_evidence.iter().enumerate() {
            assert!(
                QUERY_CASE_IDS.contains(&packet.case_id.as_str()),
                "{} not in query inventory",
                packet.case_id
            );
            assert_eq!(packet.schema_version, 1, "{} schema", packet.case_id);
            assert!(
                report.query_evidence[..index]
                    .iter()
                    .all(|prior| prior.case_id != packet.case_id),
                "{} duplicated packet",
                packet.case_id
            );
            for (item_index, item) in packet.invocations.iter().enumerate() {
                assert!(
                    packet.invocations[..item_index].iter().all(|prior| {
                        prior.invocation_id != item.invocation_id
                            && prior.session_digest != item.session_digest
                    }),
                    "{} duplicated invocation identity: {item:?}",
                    packet.case_id
                );
            }
            assert!(report.cases.iter().any(|case| case.id == packet.case_id));
        }
        validate_query_evidence_report(&report).unwrap();
        let q10_index = report
            .query_evidence
            .iter()
            .position(|packet| packet.case_id == "Q10")
            .unwrap();
        let original = report.query_evidence[q10_index].invocations[1].clone();
        report.query_evidence[q10_index].invocations[1].session_digest =
            report.query_evidence[q10_index].invocations[0].session_digest;
        assert!(validate_query_evidence_report(&report).is_err());
        report.query_evidence[q10_index].invocations[1] = original.clone();
        report.query_evidence[q10_index].invocations[1].invocation_id =
            report.query_evidence[q10_index].invocations[0].invocation_id;
        assert!(validate_query_evidence_report(&report).is_err());
        report.query_evidence[q10_index].invocations[1] = original;
        validate_query_evidence_report(&report).unwrap();
    }

    #[test]
    fn query_setup_visibility_accepts_early_edges_only_after_a_quiet_interval() {
        let no_op = QuerySetupVisibilityEvidence {
            visible_before: false,
            desired_visible: false,
            tap: None,
        };
        assert!(query_setup_visibility_is_valid(
            &no_op,
            AcceptanceHotkey::F11
        ));

        let mut evidence = QuerySetupVisibilityEvidence {
            visible_before: false,
            desired_visible: true,
            tap: Some(QuerySetupTapEvidence {
                input_down_inserted: 1,
                input_up_inserted: 1,
                quiet_preflight_ms: 82,
                quiet_matching_edges: 1,
                observer_default_desktop: true,
                observed_edges: vec![
                    QuerySetupObservedEdge {
                        runner_relative_us: 0,
                        virtual_key: 0x7A,
                        down: true,
                        injected: true,
                        runner_cookie_matched: true,
                    },
                    QuerySetupObservedEdge {
                        runner_relative_us: 25_000,
                        virtual_key: 0x7A,
                        down: false,
                        injected: true,
                        runner_cookie_matched: true,
                    },
                ],
                foreign_edges: Vec::new(),
                trace_cursor: 10,
                invocation_id: 11,
                generation: 4,
                press_event_ordinal: 11,
                release_event_ordinal: 12,
                short_tap_event_ordinal: 13,
                visibility_event_ordinal: 14,
                visibility_visible: true,
            }),
        };

        assert!(query_setup_visibility_is_valid(
            &evidence,
            AcceptanceHotkey::F11
        ));
        evidence.tap.as_mut().unwrap().quiet_preflight_ms = 74;
        assert!(!query_setup_visibility_is_valid(
            &evidence,
            AcceptanceHotkey::F11
        ));
        evidence.tap.as_mut().unwrap().quiet_preflight_ms = 82;
        evidence.tap.as_mut().unwrap().quiet_matching_edges = 257;
        assert!(!query_setup_visibility_is_valid(
            &evidence,
            AcceptanceHotkey::F11
        ));
    }

    fn passing_copied_report() -> AcceptanceReport {
        let mut report = acceptance_report("native_windows_copied_profile");
        report.copied_profile_status = CopiedProfileStatus::Passed;
        let private_summary = private_artifacts::PrivateArtifactSummary {
            status: private_artifacts::PrivateArtifactStatus::Retained,
            artifact_id: Some("multi-launcher-private-evidence-test-1234".into()),
            file_count: 4,
            total_bytes: 64,
            manifest_sha256: Some("f".repeat(64)),
        };
        report.private_artifacts = Some(private_summary.clone());
        for id in COPIED_CASE_IDS {
            report.push_case(AcceptanceCaseResult {
                id: id.into(),
                status: CaseStatus::Passed,
                elapsed_ms: 1,
                expected: "bounded expectation".into(),
                observed: if id == "CP_R1" {
                    private_artifact_evidence(&private_summary)
                } else {
                    "bounded evidence".into()
                },
                failure_stage: None,
                artifacts: Vec::new(),
            });
        }
        report.cleanup.child_closed_normally = true;
        report.cleanup.child_owned_windows_closed = true;
        report.cleanup.profile_removed = true;
        report.cleanup.cursor_restored = true;
        report.cleanup.input_desktop_released = true;
        report
    }

    #[cfg(windows)]
    #[test]
    fn cleanup_only_failure_retains_private_diagnostic_bundle() {
        let mut report = acceptance_report("native_windows_copied_profile");
        report.environment.child_process_id = Some(4242);
        report.cleanup.child_closed_normally = true;
        report.cleanup.child_owned_windows_closed = true;
        report.cleanup.cursor_restored = true;
        report.cleanup.input_desktop_released = true;
        assert!(!copied_failure_requires_retention(&report, true, true));

        // Cursor restoration is the only failed native cleanup signal; all native
        // cases, the isolated profile audit, and the supplied source inventory pass.
        report.cleanup.cursor_restored = false;
        assert!(report.cases.is_empty());
        assert!(copied_failure_requires_retention(&report, true, true));

        let profile = tempfile::tempdir().unwrap();
        let names = [
            "case-R1-trace.log",
            "case-R1-windows.json",
            "case-R1-private.log",
            "case-R1.png",
        ];
        let paths = names
            .into_iter()
            .map(|name| {
                let path = profile.path().join(name);
                fs::write(&path, name.as_bytes()).unwrap();
                path
            })
            .collect::<Vec<_>>();
        let staged = private_artifacts::stage_diagnostics(profile.path(), paths).unwrap();
        let retained = if copied_failure_requires_retention(&report, true, true) {
            Some(staged.retain())
        } else {
            None
        };
        let profile_path = profile.path().to_path_buf();
        profile.close().unwrap();
        assert!(!profile_path.exists());

        let retained = retained.expect("cleanup-only failure must retain its private evidence");
        private_artifacts::verify_retained_artifacts(&retained.directory, &retained.summary)
            .unwrap();
        assert!(retained.directory.join("case-R1.png").is_file());
        fs::remove_dir_all(&retained.directory).unwrap();
    }

